values ('rg_hanseol_1', 'side', '연담·한설', '야시장 감찰', '감찰관 한설이 밤마다 혼자 백등 야시장 등 아래 봉인을 감찰한다. 정청 창고 부적의 결재가 늦어지자, 한설이 처음으로 제 이름으로 조사원에게 정화 부적을 주문한다. 「규정대로 받고, 규정대로 값을 치르겠다.」 영수증은 모서리를 접지 않는다.', 'lantern_market', 27, '{mq_lamp_shadow}'::text[], null, 1600, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_hanseol_1';
delete from public.world_quest_steps where quest_id = 'rg_hanseol_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_1', 1, '등 아래 부적', '등 아래 부적', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "밤이 깊자 백등 야시장 골목마다 등이 내걸렸다. 좌판 사이로 국밥 냄새가 흘렀고, 엿장수 가위 소리가 짤깍짤깍 골목을 건너왔다."}, {"s": null, "t": "흥정하는 사람들 사이로 한 사람만 걸음이 느렸다. 감찰관 한설이 등잔 하나를 들고 등 아래를 하나씩 올려다보며 걷고 있었다."}, {"s": null, "t": "등마다 아래쪽 받침에 누런 부적이 한 장씩 붙어 있었다. 한설은 부적 귀퉁이를 손끝으로 들춰 보고, 품에서 꺼낸 수첩에 무언가를 적었다."}, {"s": null, "t": "한설이 다음 등 앞에서 멈췄다. 부적 한 장이 물에 불어 반쯤 떨어져 있었다. 한설의 손끝에 닿은 종이가 젖은 떡처럼 물컹했다. 한설은 그 부적을 조심스럽게 떼어 내 기름종이에 쌌다."}, {"s": null, "t": "내가 곁으로 다가가자 한설이 고개만 돌렸다. 등잔 불빛이 얼굴 한쪽만 비췄다. 콧등에 밤이슬인지 땀인지 모를 물기가 맺혀 있었다."}, {"s": "night_office:han", "t": "조사원이군. 지나가던 길이면 가던 길을 가라. 감찰 중이니까."}, {"s": null, "t": "내 눈이 한설의 손에 머물자, 한설이 떼어 낸 부적을 싼 기름종이를 들어 보였다."}, {"s": "night_office:han", "t": "등 아래 봉인을 보는 거다. 야시장 등은 밤새 켜 두니까 요기가 꼬이거든. 그래서 받침마다 정화 부적을 붙여 막는다. 이 골목에만 쉰두 장이야."}, {"s": "night_office:han", "t": "그런데 지난 장마에 반이 젖었어. 젖으면 획이 번지고, 획이 번지면 봉인이 안 서."}, {"s": null, "t": "나는 정청 창고에서 새 부적을 내 오면 되지 않느냐고 했다. 한설이 수첩을 덮었다. 덮은 수첩 귀퉁이가 여러 장 반듯하게 접혀 있었다."}, {"s": "night_office:han", "t": "청했지. 사흘 전에. 결재가 아직 안 났을 뿐이다. 창고 부적은 결재 없이는 한 장도 못 꺼내."}, {"s": "night_office:han", "t": "규정이 그래. 예외를 하나 두면 다음 예외가 오거든."}, {"s": null, "t": "한설은 그렇게 말하고도 떼어 낸 부적 자리에서 눈을 떼지 못했다. 빈 받침 위에서 등불이 조금 흔들렸다."}, {"s": "night_office:han", "t": "…그렇다고 사흘을 더 기다리면 이 골목 등 아래가 반은 비어. 그사이 요기라도 꼬이면 다치는 건 장사꾼들이고."}, {"s": null, "t": "한설이 나를 돌아보았다. 무언가를 재는 눈이었다."}, {"s": "night_office:han", "t": "조사원. 너, 정화 부적을 그릴 줄 아나?"}, {"s": null, "t": "나는 그릴 줄 안다고 했다. 한설이 수첩을 다시 펴서 새 쪽에 붓을 댔다."}, {"s": "night_office:han", "t": "그럼 주문하지. 정청 창고 말고 내 이름으로. 두 장. 황지는 백지교 물가에 흔하니까 거기서 구해."}, {"s": "night_office:han", "t": "규정대로 받고, 규정대로 값을 치르겠다. 대신 획 하나라도 어긋나면 돌려보낼 거다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_1', 2, '자로 재는 획', '백지교에서 황지을(를) 모은다, 정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "gather", "items": ["seal_paper"], "r": ["paper_bridge"], "n": 4}, {"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "내가 그려 온 정화 부적 두 장을 내밀자, 한설은 받기 전에 손부터 닦았다. 소매에서 작은 놋쇠 자를 꺼내 부적 위에 댔다."}, {"s": null, "t": "한설은 획 하나하나에 자를 대 보았다. 손끝이 획을 따라 천천히 내려갔다. 등잔 심지가 지직 타들어 가는 동안 한설은 아무 말도 하지 않았다."}, {"s": "night_office:han", "t": "…규정대로다."}, {"s": null, "t": "그 한마디가 끝이었다. 한설은 자를 소매에 도로 넣고, 부적 두 장을 내 손에 다시 쥐여 주었다."}, {"s": null, "t": "나는 부적을 쥔 채 한설을 보았다. 한설이 빈 받침 하나를 올려다보았다."}, {"s": "night_office:han", "t": "아니, 붙이는 자리에서 받겠다는 거다. 붙여서 봉인이 서는 걸 봐야 받은 거지. 그 전까진 네 물건이야."}, {"s": "night_office:han", "t": "한 장은 이 골목 몫, 한 장은 감찰 구역 끝 등 몫이다. 구역 끝이 침수된 구시가지 첫 골목인데, 거기 어귀에 등이 하나 걸려 있거든."}, {"s": null, "t": "한설이 등잔을 들고 골목 끝 어둠 쪽을 보았다. 썩은 수초와 녹슨 쇠가 뒤섞인 물비린내가 그쪽에서 실려 왔다."}, {"s": "night_office:han", "t": "물이 찬 골목은 밤에 둘이 들어가게 돼 있다. …나는 늘 혼자 갔지만. 같이 갈 사람이 없었으니까."}, {"s": null, "t": "한설은 그 말을 하고 나서 입을 다물었다. 제 입으로 규정을 어겨 왔다고 한 것이 마음에 걸리는 얼굴이었다."}, {"s": null, "t": "그런 말을 왜 이제 꺼내는지 알 수 없어 나는 한설을 보았다. 한설이 내 눈을 피해 등잔 불빛을 내려다보았다."}, {"s": "night_office:han", "t": "이제 같이 갈 사람이 생겼으니까. 혼자 갈 때 이런 말을 하면, 그건 그냥 규정 위반 자백이잖나."}, {"s": null, "t": "나는 같이 가겠다고 했다. 한설이 나를 한 번 보고 등잔 심지를 돋웠다."}, {"s": "night_office:han", "t": "그 골목엔 등 줄을 쏠아 먹는 놈들이 많아. 붙이기 전에 어귀를 두어 번 둘러봐야 해. 부적은 네가 들고 와서, 붙이는 자리에서 내 손에 넘겨라."}]'::jsonb, '{"xp": 2289}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_1', 3, '접지 않은 영수증', '침수된 구시가지을(를) 살핀다, 정화 부적을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "search", "r": ["sunken_district"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "구시가지 첫 골목 어귀의 등은 기둥째 물에 잠겨 기울어 있었다. 나는 등잔을 든 한설 대신 기둥을 붙잡았다. 정강이까지 찬 물이 밤새 식어 뼛속이 시렸다. 한설이 정화 부적 한 장을 받침에 꾹 눌러 붙였다."}, {"s": null, "t": "부적의 붉은 획이 등불을 받아 한 번 번쩍였다. 물 위를 맴돌던 검은 기운이 스르르 흩어졌다."}, {"s": null, "t": "야시장으로 돌아오는 길에 하늘이 희부옇게 밝아 왔다. 젖은 바짓단이 걸음마다 철벅거렸고, 야시장 쪽에서 첫 솥에 불 지피는 연기가 맵게 풍겨 왔다. 한설은 골목 빈 받침에 남은 한 장을 붙이고 나서야 걸음을 멈췄다."}, {"s": "night_office:han", "t": "됐다, 두 장 다 받았다. 이제 값을 치르지."}, {"s": null, "t": "한설은 등 아래 평상에 앉아 수첩을 펼쳤다. 맨 뒤 쪽을 반듯하게 찢어 날짜와 물품과 수량과 값을 적고, 맨 끝에 제 이름을 적었다."}, {"s": null, "t": "한설이 엽전과 영수증을 함께 내밀었다. 영수증 네 귀퉁이가 칼로 자른 듯 반듯했다."}, {"s": null, "t": "수첩을 덮던 한설의 손끝이 오늘 감찰한 쪽 귀퉁이를 한 번 접었다. 접힌 귀퉁이가 손가락 두 마디 두께로 쌓여 있었다."}, {"s": null, "t": "나는 영수증도 접어 주느냐고 물었다. 한설이 수첩을 품에 넣으며 고개를 저었다."}, {"s": "night_office:han", "t": "그건 네 영수증이잖나. 남의 종이는 안 접어."}, {"s": null, "t": "김이 오르는 국솥을 지고 좌판을 걷던 국밥집 노인이 평상 앞을 지나며 허리를 굽혔다."}, {"s": "q:sx_md_elder", "t": "감찰관 나리, 오늘은 길동무를 달고 도셨구려. 등이 하나도 안 꺼졌습니다요."}, {"s": null, "t": "한설은 노인에게 고개만 까딱하고, 꺼지지 않은 등 줄을 한동안 올려다보았다."}, {"s": "night_office:han", "t": "…둘이 도니까 금방 끝나는군. 규정에 왜 둘이라고 적어 놨는지 이제야 알겠어."}, {"s": "night_office:han", "t": "정청 창고 결재는 앞으로도 늦을 거야. 그럴 때마다 너한테 주문하겠다. 정식으로, 주문서까지 써서."}, {"s": null, "t": "한설이 수첩을 다시 꺼내 새 쪽 머리에 무언가를 적었다. 「주문처」 아래 내 이름이 적혀 있었다."}, {"s": "night_office:han", "t": "…앞으로도 부탁해도 되겠나?"}, {"s": null, "t": "나는 그러겠다고 했다. 한설이 고개를 한 번 끄덕이고, 그 쪽은 접지 않은 채 수첩을 덮었다."}]'::jsonb, '{"xp": 2289, "gil": 113, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
