insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_hanseol_2', 'side', '연담·한설', '반 푼 어긋난 획', '조사원이 넘긴 부적 한 장의 획이 규정에서 반 푼 어긋난다. 한설은 반려 도장을 들었다가 내려놓고, 야시장 찻집 구석에서 밤새 규정집을 뒤진다. 조사원이 곁에서 등잔 심지를 돋운다. 새벽에 조항을 찾은 한설이 규정집을 베고 잠든다.', 'lantern_market', 27, '{rg_hanseol_1}'::text[], null, 1601, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "hanseol", "stage": 2}'::jsonb where quest_id = 'rg_hanseol_2';
delete from public.world_quest_steps where quest_id = 'rg_hanseol_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_2', 1, '반려 도장', '반려 도장', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "해 질 녘 백등 야시장 찻집 앞 평상에 한설이 앉아 있었다. 무릎 위에 수첩을 펴 놓고 손가락으로 줄을 하나씩 짚어 내려가고 있었다. 찻집 문간에서 보리 볶는 구수한 냄새가 흘러나왔고, 아직 켜지지 않은 등들이 노을을 받아 불그스름했다."}, {"s": "night_office:han", "t": "왔나. 앉아. 마침 네 몫 영수증을 셈하던 참이었다."}, {"s": "night_office:han", "t": "정화 부적 스물넷, 봉인 먹 여섯. 영수증만 서른 장이야. 덕분에 이 골목 등 아래는 한 장도 안 비었다."}, {"s": null, "t": "한설은 셈을 다 읽고 나서 수첩 사이에서 부적 한 장을 꺼냈다. 내가 그린 부적이었다. 한설이 그 위에 놋쇠 자를 댔다."}, {"s": "night_office:han", "t": "그런데 이거. 셋째 획이 반 푼 어긋나. 어제 감찰하다 찾았다."}, {"s": null, "t": "한설이 소매에서 붉은 도장 하나를 꺼냈다. 「반려」 두 글자가 새겨진 도장이었다. 한설은 도장을 부적 위로 들어 올렸다."}, {"s": null, "t": "도장은 부적 바로 위에서 멈췄다. 말라붙은 인주가 등잔 불에 검붉게 비쳤다. 한설은 숨을 두어 번 쉬는 동안 그대로 있다가 도장을 평상 위에 내려놓았다."}, {"s": null, "t": "나는 반려하면 다시 그려 오겠다고 했다. 한설이 고개를 저었다."}, {"s": "night_office:han", "t": "그럴 것까진 없다. 이게 붙은 등이 사흘째 멀쩡하거든. 봉인이 섰다는 얘기지. 반 푼 때문에 멀쩡히 선 봉인을 뗄 수는 없어."}, {"s": "night_office:han", "t": "그런데 반려하지 않을 까닭도 없단 말이다. 규정집에 아무 말이 없으면, 나는 이걸 반려해야 해."}, {"s": null, "t": "한설이 평상 옆에 놓인 두꺼운 책을 끌어당겼다. 귀퉁이가 닳아 둥글어진 규정집이었다."}, {"s": null, "t": "나는 그 두꺼운 책과 한설을 번갈아 보았다. 한설이 규정집 표지를 손바닥으로 눌렀다."}, {"s": "night_office:han", "t": "다 읽을 거다. 오늘 밤 안에 찾아야지. 그러려면 견줄 게 있어야 해. 제대로 그은 부적이 옆에 있어야 어디가 반 푼인지 짚을 수 있으니까."}, {"s": "night_office:han", "t": "한 장만 더 그려 와. 이번엔 일부러, 자로 잰 듯이."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_2', 2, '찻집 구석의 밤', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 1}], "give": {"ward_talisman": 1}}'::jsonb, '[{"s": null, "t": "새로 그린 부적을 내밀자 한설은 두 장을 나란히 놓고 자를 댔다. 반 푼 어긋난 셋째 획 끝에 붓 끝으로 작은 점을 찍었다."}, {"s": "night_office:han", "t": "됐다. 이제 이 점 하나를 두고 규정집을 처음부터 읽는 거다."}, {"s": null, "t": "찻집 주인이 문을 닫으려다 평상의 한설을 보았다. 주인은 말없이 등잔 하나를 내다 주었다. 한설은 찻집 구석 자리로 규정집을 옮겨 앉았다. 찻집 안에는 식은 찻잎 냄새와 숯 화로의 남은 온기가 고여 있었다."}, {"s": null, "t": "나는 그 맞은편에 앉았다. 한설이 고개를 들었다."}, {"s": "night_office:han", "t": "갈 데 있으면 가. 이건 내 일이야."}, {"s": null, "t": "나는 등잔 기름이 다 타기 전에는 갈 생각이 없다고 했다. 한설은 대답하지 않고 규정집 첫 장을 넘겼다."}, {"s": null, "t": "밤이 깊어 갔다. 골목의 흥정 소리가 잦아들자 처마 끝 풍경만 이따금 댕그랑 울렸다. 한설은 한 장을 넘길 때마다 손가락으로 줄을 짚었고, 짚은 줄 아래로 입술만 달싹였다."}, {"s": null, "t": "등잔 심지가 짧아져 불빛이 가물거렸다. 나는 손을 뻗어 심지를 돋웠다. 불빛이 다시 환해지자 한설의 손가락이 잠깐 멈췄다."}, {"s": "night_office:han", "t": "…고맙다."}, {"s": null, "t": "한설은 그 말만 하고 다시 줄을 짚었다. 나는 그 뒤로도 불빛이 가물거릴 때마다 심지를 돋웠다."}, {"s": null, "t": "자정이 지나자 화로 숯이 사그라들어 발밑으로 찬 기운이 스며들었다. 그 무렵 한설이 규정집 한가운데서 손을 멈추고 나를 보았다."}, {"s": "night_office:han", "t": "너는 왜 안 가? 네 부적이 반려될까 봐 그러나."}, {"s": null, "t": "나는 부적 걱정이 아니라 등잔 걱정이라고 했다. 이 등잔은 혼자 두면 금방 꺼질 것 같다고 덧붙였다."}, {"s": null, "t": "한설이 등잔을 한 번 보고 다시 규정집으로 눈을 내렸다. 입가가 아주 조금 움직였다."}, {"s": "night_office:han", "t": "…그럼 끝까지 봐라, 그 등잔. 아직 삼분의 일이나 남았으니까."}]'::jsonb, '{"xp": 2289}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_2', 3, '규정집을 베고', '백등 야시장에서 쉰다', '{"at": ["lantern_market"], "tasks": [{"t": "rest", "r": ["lantern_market"], "n": 1}]}'::jsonb, '[{"s": null, "t": "창호지가 희부옇게 밝아 올 무렵 한설의 손가락이 한 줄 위에서 멈췄다. 한설은 그 줄을 두 번 소리 내어 읽었다."}, {"s": "night_office:han", "t": "「봉인의 효험이 확인된 부적은, 획의 차이를 까닭으로 떼지 아니한다. 다만 그린 자에게 그 차이를 일러 다음 것을 바로잡게 한다.」"}, {"s": "night_office:han", "t": "있다. …있었어. 봉인 공예 편 맨 끝, 덧붙임 조항이야. 열다섯 해를 들여다봤는데 이 줄은 처음 짚었다."}, {"s": null, "t": "한설이 규정집을 내 쪽으로 돌려 그 줄을 짚어 보였다. 손톱 끝이 먹빛 글자 밑에 반듯하게 놓였다."}, {"s": "night_office:han", "t": "봐라, 예외가 아니야. 조항이다. 그러니까 이 부적은 반려하지 않는다."}, {"s": "night_office:han", "t": "대신 조항대로 너한테 일러 줘야 해. 셋째 획은 반 푼 더 길게 그어라. 다음 것부터."}, {"s": null, "t": "나는 다음 것부터는 반 푼 더 길게 긋겠다고 했다. 한설이 고개를 끄덕이고 평상 위의 반려 도장을 소매에 넣었다."}, {"s": null, "t": "한설은 규정집을 덮으려다 말고 그 위에 팔을 얹었다. 팔 위에 이마를 대고 잠깐 눈을 감았다."}, {"s": "night_office:han", "t": "감찰 보고는 아침 종이 울리고 나서니까… 그때까지만…."}, {"s": null, "t": "말이 다 끝나기도 전에 한설의 숨소리가 고르게 바뀌었다. 한설은 규정집을 베고 그대로 잠들었다."}, {"s": null, "t": "나는 겉옷을 벗어 한설의 어깨에 덮었다. 등잔 심지를 낮추자 찻집 구석이 어둑해졌다. 규정집에 눌린 한설의 뺨에 종이 결이 붉게 배어 있었다."}, {"s": null, "t": "찻집 주인이 빗자루를 들고 나왔다가 구석을 보고 발소리를 죽였다. 주인은 손가락을 입술에 대 보이고 문간 쪽으로 빗질을 하러 나갔다. 마당을 쓰는 싸리비 소리가 사각사각 멀어졌다."}, {"s": null, "t": "아침 종이 울리자 한설이 퍼뜩 눈을 떴다. 어깨의 겉옷을 내려다보고, 나를 보고, 다시 겉옷을 보았다."}, {"s": "night_office:han", "t": "…얼마나 잤나."}, {"s": null, "t": "나는 한 시진쯤이라고 했다. 한설은 겉옷을 반듯하게 개어 내게 돌려주었다. 귀 끝이 조금 붉었다."}, {"s": "night_office:han", "t": "근무 중에 졸다니. 보고서엔… 안 적을 거다. 적을 칸이 없거든."}, {"s": null, "t": "한설은 규정집을 옆구리에 끼고 일어섰다. 찻집 문턱에서 한 번 돌아보았다."}, {"s": "night_office:han", "t": "셋째 획은 반 푼이다. 잊지 마라."}]'::jsonb, '{"xp": 2289, "gil": 113, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
