values ('rg_hanseol_3', 'side', '연담·한설', '근무 중의 국수', '「근무 중엔 먹지 않는다」는 한설을 조사원이 국숫집 걸상에 앉힌다. 한설은 자정 종이 울릴 때까지 젓가락을 들지 않는다. 불은 국수를 다 먹고 국숫집 쪽지를 받아 처음으로 그 귀퉁이를 접는다. 까닭은 말하지 않는다.', 'lantern_market', 27, '{rg_hanseol_2}'::text[], null, 1602, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
