delete from public.world_quest_steps where quest_id = 'rg_hanseol_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_3', 1, '굶는 감찰관', '굶는 감찰관', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "저녁 장이 막 서기 시작한 백등 야시장 골목에 숯 연기가 매캐하게 깔렸다. 어느 좌판에선가 숯불에 기름 떨어지는 소리가 지글거렸다. 그 연기 속에서 한설이 등 줄을 올려다보고 있었다. 한설은 나를 보자 수첩부터 꺼냈다."}, {"s": "night_office:han", "t": "마침 잘 왔다. 먹이 또 떨어졌거든."}, {"s": "night_office:han", "t": "오늘 주문은 봉인 먹 둘이다. 야시장 동쪽 끝 귀죽림 어귀에 등이 셋 걸려 있는데, 거기 받침 덧칠이 다 벗겨졌어."}, {"s": null, "t": "한설이 말을 마치기도 전에 약 보따리를 든 노파 하나가 다가왔다. 야시장 약방 할멈 고분이었다. 고분이 한설의 소매를 툭 잡아당겼다."}, {"s": "q:dh_gopun", "t": "감찰관 나리, 오늘도 저녁 거르셨수? 낯빛이 누렇게 떴다우."}, {"s": null, "t": "한설은 수첩에서 눈을 떼지 않은 채 짧게 대답했다."}, {"s": "night_office:han", "t": "근무 중입니다, 할멈."}, {"s": null, "t": "고분이 코웃음을 치며 한설의 소매를 한 번 더 잡아당겼다."}, {"s": "q:dh_gopun", "t": "그 근무가 해 질 녘부터 자정까지 아니우. 우리 대쪽 나리가 저녁 드시는 꼴을 내가 아홉 해째 못 봤수."}, {"s": null, "t": "고분은 혀를 차며 제 좌판으로 돌아갔다. 한설은 아무 일도 없었다는 듯 수첩을 넘겼다."}, {"s": null, "t": "나는 고분이 돌아간 좌판과 한설을 번갈아 보았다. 한설이 수첩에서 눈을 떼지 않은 채 입을 열었다."}, {"s": "night_office:han", "t": "감찰관은 근무 중에 남이 내는 건 안 먹는다. 장사꾼이 내준 국 한 그릇이, 다음엔 눈을 좀 감아 달라는 말이 되거든."}, {"s": "night_office:han", "t": "내 돈을 내고 사 먹는 것도 안 먹어. 감찰관이 어느 집에서 먹었다 하면, 누가 냈는지 따지기도 전에 말부터 돈다."}, {"s": null, "t": "한설은 그렇게 말하고 배를 한 번 눌렀다. 아주 작게 꼬르륵 소리가 났다. 한설은 그 소리를 못 들은 척 귀죽림 쪽을 가리켰다."}, {"s": "night_office:han", "t": "…봉인 먹을 개면 귀죽림 어귀로 와라. 거기 등 줄을 쏠아 대는 원숭이 떼가 있어. 덧칠하기 전에 그놈들부터 쫓아야 한다."}, {"s": null, "t": "나는 봉인 먹을 개어 귀죽림 어귀로 가겠다고 했다. 한설이 고개를 끄덕이고 다시 등 줄을 올려다보았다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_3', 2, '국숫집 걸상', '봉인 먹을(를) 만든다, 귀죽림의 요괴를 물리친다, 봉인 먹을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "craft", "items": ["sealing_ink"], "n": 2}, {"t": "win", "r": ["ghost_bamboo"], "n": 6}], "give": {"sealing_ink": 2}}'::jsonb, '[{"s": null, "t": "귀죽림 어귀 등 셋은 줄이 반쯤 쏠려 있었다. 원숭이 떼를 쫓고 나서 한설이 사다리에 올라 쏠린 등 줄을 새 줄로 갈았다. 나는 아래에서 사다리를 붙잡았다. 대숲은 바람 한 점 없는데도 서걱서걱 울었고, 쏠린 줄 끝에서 원숭이 오줌 지린내가 코를 찔렀다."}, {"s": null, "t": "야시장으로 돌아왔을 때는 저녁 장이 한창이었다. 골목 모퉁이 국숫집에서 멸치 국물 냄새가 훅 끼쳐 왔다. 한설의 걸음이 아주 잠깐 느려졌다."}, {"s": null, "t": "나는 한설의 소매를 잡아 국숫집 걸상에 앉혔다. 한설이 일어서려 하기에 나는 그 앞에 앉아 국수 두 그릇을 시켰다."}, {"s": "night_office:han", "t": "조사원. 말했잖나, 근무 중이라고."}, {"s": null, "t": "나는 국수 값은 각자 제 그릇만큼 내자고 했다. 그러면 남이 낸 것을 먹는 게 아니라고 덧붙였다."}, {"s": null, "t": "한설이 입을 열었다가 다물었다. 규정집 어느 쪽을 떠올리는 얼굴이었다."}, {"s": "night_office:han", "t": "…그래도 먹는 건 장사꾼들이 다 본다고."}, {"s": null, "t": "국숫집 노인이 김이 오르는 그릇 둘을 걸상에 내려놓았다. 국물 위에 파 기름이 동그랗게 떠 있었다. 한설은 젓가락을 집지 않았다. 손을 무릎 위에 반듯하게 얹고 그릇만 내려다보았다."}, {"s": "q:sx_md_elder", "t": "나리, 국수는 붇습니다요. 장사꾼들 눈보다 그게 더 무섭습지요."}, {"s": null, "t": "노인이 껄껄 웃으며 솥 앞으로 돌아갔다. 한설은 그래도 젓가락을 들지 않았다."}, {"s": "night_office:han", "t": "근무는 자정까지다. 자정 종이 치면, 그때 먹지."}, {"s": null, "t": "나는 그럼 자정까지 같이 기다리겠다고 했다. 한설이 나를 보았다."}, {"s": "night_office:han", "t": "너는 먹어. 넌 근무 중도 아니잖나."}, {"s": null, "t": "나는 젓가락을 그릇 옆에 나란히 내려놓았다. 한설이 그것을 말없이 보다가 한숨처럼 숨을 내쉬었다."}, {"s": "night_office:han", "t": "…알았다, 알았어. 봉인 먹은 아직 네 손에 있지? 넘겨 다오. 귀죽림 덧칠은 내일 해 질 녘에 하고, 오늘 근무는 여기 앉아서 자정까지 등 줄을 보는 걸로 채우지."}]'::jsonb, '{"xp": 2289}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_3', 3, '처음 접은 귀퉁이', '백등 야시장에서 쉰다, 봉인 먹을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "rest", "r": ["lantern_market"], "n": 1}], "give": {"sealing_ink": 2}}'::jsonb, '[{"s": null, "t": "국수는 그릇 안에서 천천히 불어 갔다. 그릇 가장자리에 대 본 손등에 미지근한 기운만 남았다. 국물이 국수에 다 배어들 즈음, 정청 쪽에서 자정 종이 울렸다."}, {"s": null, "t": "한설은 종소리가 다 끝나기를 기다렸다. 마지막 울림이 사라지자 그제야 젓가락을 집었다."}, {"s": null, "t": "한설은 불은 국수를 한 젓가락씩 말없이 먹었다. 나도 젓가락을 들었다. 식은 국수가 퉁퉁 불어 젓가락에서 자꾸 끊어졌다."}, {"s": null, "t": "한설은 국물까지 다 비우고 나서야 그릇을 내려놓았다. 빈 그릇 바닥을 한동안 내려다보았다."}, {"s": "night_office:han", "t": "…불은 국수는 처음 먹어 본다. 이거, 생각보다 괜찮군."}, {"s": null, "t": "나는 원래 국수는 불기 전에 먹는 것이라고 했다. 한설이 젓가락을 그릇 위에 나란히 걸쳐 놓았다."}, {"s": "night_office:han", "t": "안다. 다음엔 자정 종에 맞춰서 시키면 되잖나."}, {"s": null, "t": "한설은 「다음」이라고 말하고 나서 잠깐 입을 다물었다. 제 입에서 나온 말을 다시 읽어 보는 얼굴이었다."}, {"s": null, "t": "국숫집 노인이 다가와 두 그릇 값을 따로 적은 쪽지를 내밀었다. 한설은 제 몫 엽전을 정확히 세어 놓고 쪽지를 받았다."}, {"s": "q:sx_md_elder", "t": "아홉 해 만에 나리 국수 값을 받습니다요. 내일도 자정에 불을 땔까요?"}, {"s": null, "t": "한설은 노인에게 대답하지 않았다. 노인도 대답을 기다리지 않고 웃으며 솥 앞으로 돌아갔다."}, {"s": null, "t": "한설이 쪽지를 수첩 사이에 끼우려다 멈췄다. 한설의 손끝이 쪽지 귀퉁이를 반듯하게 한 번 접었다. 감찰한 쪽 귀퉁이를 접던 바로 그 손길이었다."}, {"s": null, "t": "한설은 접은 쪽지를 수첩 맨 뒤에 끼우고 수첩을 덮었다. 나는 그 쪽지는 왜 접느냐고 묻지 않았다. 한설도 말하지 않았다."}, {"s": "night_office:han", "t": "근무가 끝났다. 나는 이제 들어가서 잘 거다. 너도 들어가."}, {"s": null, "t": "자정 넘은 골목에 밤이슬이 내려 걸상 다리가 축축했다. 한설은 걸상에서 일어나 몇 걸음 가다가 돌아섰다. 등불 아래서 한설이 수첩을 넣은 쪽 가슴을 한 번 눌렀다."}, {"s": "night_office:han", "t": "…잘 먹었다."}]'::jsonb, '{"xp": 2289, "gil": 113, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_hanseol_4', 'side', '연담·한설', '아홉 해 만의 쉬는 날', '아홉 해 동안 쓰지 않은 휴가를 정청이 억지로 내준다. 쉬는 날 무엇을 하는지 모르는 한설과 조사원이 백지교 물가에서 낚싯대를 드리우고, 해가 지자 야시장 끝에서 끝까지 걷는다. 등롱 가게 앞에서 한설이 처음으로 웃음 비슷한 것을 짓는다.', 'lantern_market', 27, '{rg_hanseol_3}'::text[], null, 1603, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "hanseol", "stage": 4}'::jsonb where quest_id = 'rg_hanseol_4';
delete from public.world_quest_steps where quest_id = 'rg_hanseol_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_4', 1, '휴가 공문', '휴가 공문', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "한낮의 백등 야시장은 등이 꺼져 있었다. 좌판들은 덮개를 덮었고, 골목에는 밤 장사 채비를 하는 사람들만 오갔다. 볕을 받은 등갓 종이가 바싹 말라 바스락거렸고, 밤새 고인 기름 냄새가 한낮 더위에 들큼하게 피어올랐다."}, {"s": null, "t": "그 골목 한가운데 평상에 한설이 앉아 있었다. 감찰 수첩 대신 종이 한 장을 무릎 위에 펴 놓고 있었다. 늘 입던 관복이 아니라 무명 겉옷 차림이었다."}, {"s": "night_office:han", "t": "…왔나. 앉아. 오늘은 수첩도 안 가져왔다."}, {"s": "night_office:han", "t": "주문도 없어. 오늘은… 내가 감찰관이 아니거든."}, {"s": null, "t": "한설이 무릎 위 종이를 내게 내밀었다. 정청 인사 서리의 도장이 찍힌 휴가 공문이었다."}, {"s": "night_office:han", "t": "감찰관 자리에 앉고 아홉 해 동안 휴가를 한 번도 안 썼다. 그런데 휴가를 세 해 넘게 안 쓰면 억지로라도 내보내라는 조항이 있더군. 인사 서리가 그걸 들고 찾아왔어."}, {"s": "night_office:han", "t": "안 나가면 내가 감찰을 받게 생겼다. 그래서 나왔지."}, {"s": null, "t": "한설은 그렇게 말하고 손을 어디에 둘지 몰라 무릎을 몇 번 쓸었다."}, {"s": null, "t": "나는 쉬는 날 무엇을 할 거냐고 물었다. 한설이 한동안 꺼진 등 줄만 올려다보다가 나를 보았다."}, {"s": "night_office:han", "t": "…모르겠다. 아침부터 여기 이러고 앉아 있었어. 쉬는 날 뭘 하라는 건 아무 데도 안 적혀 있더군."}, {"s": "night_office:han", "t": "너는 쉬는 날에 뭘 하나?"}, {"s": null, "t": "나는 물가에 앉아 낚싯대를 드리운다고 했다. 고기가 안 물어도 그냥 앉아 있다가 온다고 덧붙였다."}, {"s": "night_office:han", "t": "고기가 안 물면… 그건 일을 못 한 거 아닌가?"}, {"s": null, "t": "나는 쉬는 날에는 일을 못 해도 된다고 했다. 한설이 그 말을 적으려는 듯 품을 더듬었다. 수첩을 두고 나온 것을 알고 손을 도로 내렸다."}, {"s": "night_office:han", "t": "…그럼 그걸 하지. 백지교 물가가 가까우니까. 낚싯대는 네가 골라 다오. 난 고를 줄 몰라."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_4', 2, '닳은 귀퉁이', '백지교에서 낚시를 한다', '{"at": ["paper_bridge"], "tasks": [{"t": "fish", "r": ["paper_bridge"], "n": 3}]}'::jsonb, '[{"s": null, "t": "백지교 아래 물가에 나란히 앉았다. 다리 그늘 밑 물은 손을 담그면 손목이 저릿할 만큼 찼고, 물풀 냄새가 풋풋했다. 한설은 낚싯대를 두 손으로 꼭 쥐고 찌만 노려보았다. 어깨가 감찰할 때처럼 꼿꼿했다."}, {"s": null, "t": "내 찌가 몇 번 잠기는 동안 한설의 찌는 한 번도 움직이지 않았다. 한설이 미간을 찌푸렸다."}, {"s": "night_office:han", "t": "…규정대로 던졌는데 왜 안 무나."}, {"s": null, "t": "나는 고기는 규정을 안 읽는다고 했다. 한설이 나를 흘끗 보았다. 쥐고 있던 낚싯대를 아주 조금 느슨하게 쥐었다."}, {"s": null, "t": "해가 기울 무렵 한설의 찌가 처음으로 쏙 잠겼다. 한설이 허둥지둥 낚싯대를 들어 올렸다. 손바닥만 한 물고기 한 마리가 퍼덕퍼덕 물방울을 튀겼다. 비늘이 기우는 해를 받아 은빛으로 번쩍였다."}, {"s": "night_office:han", "t": "…어. 어, 잡았다. 조사원, 봐라, 잡았어!"}, {"s": null, "t": "한설은 물고기를 든 채 나와 물고기를 몇 번이나 번갈아 보았다. 그러다 물고기를 도로 물에 놓아주었다. 물고기가 꼬리를 한 번 치고 사라졌다."}, {"s": null, "t": "나는 물고기가 사라진 물 위를 보다가 한설을 보았다. 한설이 젖은 손을 겉옷에 닦았다."}, {"s": "night_office:han", "t": "쉬는 날 잡은 거잖나. 장부에 적을 데가 없어."}, {"s": null, "t": "한설이 일어서며 겉옷 품에서 두꺼운 책을 꺼냈다. 감찰 수첩은 두고 왔어도 규정집은 품에 넣어 온 것이었다. 귀퉁이가 다 닳아 둥글었고, 표지 끈이 끊어져 있었다."}, {"s": "night_office:han", "t": "버릇이야. 이게 없으면 허리춤이 허전해서."}, {"s": null, "t": "나는 그 규정집을 넣을 책갑 하나를 짜 주겠다고 했다. 한설이 고개를 저었다."}, {"s": "night_office:han", "t": "선물은 안 받는다."}, {"s": null, "t": "나는 그럼 주문으로 하라고 했다. 한설이 규정집을 품에 도로 넣다가 멈췄다."}, {"s": "night_office:han", "t": "…주문이면 받지. 값은 치를 거다. 쉬는 날이라도."}, {"s": null, "t": "한설은 그 말을 하고 나서 제가 무슨 말을 했는지 다시 따져 보는 얼굴이 되었다. 쉬는 날에 주문을 한 셈이었다."}, {"s": "night_office:han", "t": "이건… 휴가 중에 한 사사로운 주문이다. 공문엔 안 적어. 황지는 저 다리 밑에도 있으니까."}]'::jsonb, '{"xp": 2289}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_4', 3, '등롱 가게 앞', '책갑을(를) 만든다, 책갑을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "craft", "items": ["hf_surf_books"], "n": 1}], "give": {"hf_surf_books": 1}}'::jsonb, '[{"s": null, "t": "내가 짜 온 책갑에 규정집을 넣자 꼭 맞았다. 한설은 책갑 뚜껑을 몇 번 여닫아 보고 영수증을 썼다. 이번 영수증도 귀퉁이를 접지 않은 채였다."}, {"s": null, "t": "해가 지고 야시장 등이 하나둘 켜졌다. 불이 붙을 때마다 기름 먹은 심지가 탁 하고 작게 튀었다. 한설이 책갑을 품에 안은 채 일어섰다."}, {"s": "night_office:han", "t": "휴가가 아직 반나절 남았군. …야시장이나 걸어 볼까. 감찰 말고, 그냥."}, {"s": null, "t": "우리는 야시장 어귀에서 끝까지 천천히 걸었다. 한설은 버릇처럼 등 아래 부적을 올려다보다가, 그때마다 고개를 내리고 좌판을 보았다."}, {"s": null, "t": "엿 고는 단내가 국물 김으로, 국물 김이 쌉쌀한 쑥 냄새로 걸음마다 바뀌었다. 우리는 엿장수 좌판과 국숫집을 지나 고분의 약방 앞에 이르렀다. 고분이 약방 문간에서 우리를 보고 눈을 동그랗게 떴다."}, {"s": "q:dh_gopun", "t": "아이고, 우리 대쪽 나리가 관복을 벗으셨네. 오늘 해가 서쪽에서 떴수?"}, {"s": null, "t": "한설은 고분에게 고개를 숙여 인사만 하고 걸음을 옮겼다. 귀 끝이 조금 붉어져 있었다."}, {"s": null, "t": "골목 끝 등롱 가게 앞에서 한설의 걸음이 멎었다. 처마 끝에 갓 만든 등롱들이 줄줄이 매달려 저마다 다른 빛을 내고 있었다."}, {"s": null, "t": "등롱 장인 마일수가 가게 안에서 쇠살을 구부리다가 고개를 들었다. 마일수는 한설에게 고개만 꾸벅하고 다시 쇠살을 구부렸다. 풀 먹인 비단 냄새가 문밖까지 풍겼다. 한설은 처마 끝 등롱들에서 눈을 떼지 못했다."}, {"s": "night_office:han", "t": "정청에 들어오고 열다섯 해 동안 이 골목은 감찰로만 걸었다. 등 아래 부적만 봤지, 등은 본 적이 없어."}, {"s": null, "t": "한설이 등롱 하나를 올려다보았다. 푸른 비단 갓에 흰 매화가 그려진 등롱이었다."}, {"s": "night_office:han", "t": "…허. 등이 이렇게 생긴 거였군."}, {"s": null, "t": "등불이 한설의 얼굴에 내려앉았다. 한설의 입꼬리가 아주 조금 올라갔다가 제자리로 돌아왔다. 웃음이라 하기엔 짧고, 아니라 하기엔 분명한 움직임이었다."}, {"s": null, "t": "나는 방금 웃었느냐고 물었다. 한설이 등롱에서 눈을 떼지 않았다."}, {"s": "night_office:han", "t": "쉬는 날이잖나."}, {"s": "night_office:han", "t": "그러니까 따지지 마. 감찰은 내 일이야."}, {"s": null, "t": "한설이 책갑을 고쳐 안았다. 등롱 가게 앞을 떠나며 한 번 더 뒤를 돌아보았다. 이번에는 등 아래 부적이 아니라 등을 보았다."}]'::jsonb, '{"xp": 2289, "gil": 113, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_hanseol_5', 'side', '연담·한설', '예외 조항', '처음 만난 밤처럼 둘이 침수된 구시가지 첫 골목 등에 부적을 붙이고 돌아온다. 자정 종이 울린 뒤 한설이 감찰 수첩 마지막 쪽을 보여 준다 — 「감찰관은 한 사람에 한하여 예외를 둘 수 있다.」 결재 칸에는 도장 대신 제 손글씨가 있다. 「…규정은 내가 썼다. 그러니 예외도 내가 진다.」', 'lantern_market', 27, '{rg_hanseol_4}'::text[], null, 1604, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "hanseol", "stage": 5}'::jsonb where quest_id = 'rg_hanseol_5';
delete from public.world_quest_steps where quest_id = 'rg_hanseol_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_5', 1, '백 장째 영수증', '백 장째 영수증', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "밤 장이 한창인 백등 야시장 첫 골목 등 아래에 한설이 서 있었다. 감찰 수첩을 펴 놓고 등 아래 부적을 하나씩 올려다보고 있었다. 처음 만난 밤과 같은 자리였다. 밤바람이 소맷부리로 차갑게 파고들었다."}, {"s": "night_office:han", "t": "왔나. 그사이 네가 넘긴 걸 세어 보니 영수증이 백 장을 넘었더군. 이 골목 등 아래 부적은 이제 다 네 획이야."}, {"s": "night_office:han", "t": "셋째 획이 반 푼 짧았던 건 그 한 장뿐이었고."}, {"s": null, "t": "한설이 수첩을 넘기다가 첫 쪽에서 손을 멈췄다. 「주문처」 아래 적힌 내 이름이 보였다. 그 쪽만 귀퉁이가 접혀 있지 않았다."}, {"s": null, "t": "나는 그 쪽은 왜 안 접었느냐고 물었다. 한설이 그 쪽을 손가락으로 한 번 쓸었다."}, {"s": "night_office:han", "t": "접는 건 감찰한 쪽이야. 여기는 감찰한 적이 없어. 주문처를 감찰할 일은 없으니까."}, {"s": null, "t": "한설은 그 말을 하고 다음 쪽으로 넘어가려다 말았다. 손끝이 그 쪽 귀퉁이 위에서 잠깐 머물렀다가 떨어졌다."}, {"s": "night_office:han", "t": "오늘 주문은 정화 부적 둘이다. 침수된 구시가지 첫 골목에 걸린 그 등 몫이야."}, {"s": null, "t": "나는 첫날 함께 붙인 그 등을 떠올렸다. 한설도 같은 등을 떠올렸는지 고개를 끄덕였다."}, {"s": "night_office:han", "t": "그래. 그날 붙인 부적이 벌써 철을 여럿 넘겼어. 그 골목 습기면 지금쯤 획이 다 물러졌을 거다. 갈 때가 됐지. 그 골목은 지금도 밤엔 둘이 들어가야 하고."}, {"s": null, "t": "골목을 지나던 국밥집 노인이 한설을 보고 허리를 굽혔다. 한설은 고개만 까딱했다. 노인이 나를 한 번 보고 빙그레 웃으며 지나갔다."}, {"s": "night_office:han", "t": "…저 노인은 왜 늘 너만 보면 웃지?"}, {"s": null, "t": "나는 모르겠다고 했다. 한설이 미간을 조금 찌푸렸다가 이내 폈다."}, {"s": "night_office:han", "t": "그리고… 오늘은 감찰이 끝나고 할 말이 있다. 근무 중엔 사사로운 말은 안 하니까, 자정까지는 묻지 마라."}, {"s": null, "t": "한설은 그 말을 하고 수첩을 덮었다. 덮는 손이 평소보다 조금 느렸다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_5', 2, '접은 영수증', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "한설은 내가 그려 온 부적 두 장에 놋쇠 자를 댔다. 이번에는 자를 대는 손이 빨랐다. 셋째 획에서만 잠깐 멈췄다가 지나갔다."}, {"s": "night_office:han", "t": "됐다. 흠잡을 데가 없군."}, {"s": null, "t": "한설이 수첩 맨 뒤 쪽을 찢어 영수증을 썼다. 날짜와 물품과 수량과 값을 적고 맨 끝에 제 이름을 적었다. 다 쓰고 나서 한설의 손끝이 영수증 귀퉁이를 반듯하게 한 번 접었다."}, {"s": null, "t": "한설은 접힌 영수증을 그대로 내게 내밀었다. 나는 영수증을 받아 들고 접힌 귀퉁이를 내려다보았다."}, {"s": null, "t": "나는 남의 종이는 접지 않는다고 하지 않았느냐고 물었다. 한설이 수첩을 품에 넣었다."}, {"s": "night_office:han", "t": "접어 둔 쪽은 다시 펼쳐 볼 쪽이야. 감찰한 쪽을 접는 것도 그래서고. 다음 감찰 때 거기서부터 다시 보려고."}, {"s": "night_office:han", "t": "국숫집 쪽지도 그래서 접어 둔 거다. 다시 펼쳐 볼 거라서."}, {"s": null, "t": "한설이 수첩 맨 뒤에 끼운 쪽지를 꺼내 펼쳐 보였다. 접힌 자리가 여러 번 펴졌다 접혀 하얗게 닳아 있었다."}, {"s": "night_office:han", "t": "국수 두 그릇, 각자 한 그릇 값. 이만큼 반듯한 영수증은 또 없어."}, {"s": null, "t": "한설은 쪽지를 도로 접어 넣었다. 접는 손이 아주 천천히 움직였다."}, {"s": null, "t": "나는 손에 든 영수증 귀퉁이를 다시 내려다보았다. 접힌 자리가 손끝에 반듯하게 닿았다. 나는 그 귀퉁이를 펴지 않고 영수증을 품에 넣었다."}, {"s": "night_office:han", "t": "그 영수증은 펴지 마라. 접은 그대로 둬. …감찰관 명령은 아니고."}, {"s": null, "t": "한설은 거기까지 말하고 등잔을 들었다. 침수된 구시가지 쪽 어둠에서 축축한 이끼 냄새와 개구리 울음이 실려 왔다."}, {"s": "night_office:han", "t": "가자. 나머지 얘기는 자정이 넘어서 하지."}]'::jsonb, '{"xp": 2289}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hanseol_5', 3, '마지막 쪽', '침수된 구시가지을(를) 살핀다', '{"at": ["lantern_market"], "tasks": [{"t": "search", "r": ["sunken_district"], "n": 2}]}'::jsonb, '[{"s": null, "t": "구시가지 첫 골목 어귀의 등은 그날처럼 기울어 있었다. 등갓에는 물때가 누렇게 앉아 있었다. 나는 그날처럼 미끈거리는 기둥을 붙잡았고, 한설이 낡은 부적을 떼고 새 부적을 붙였다. 붉은 획이 번쩍이자 물 위의 검은 기운이 스르르 흩어졌다."}, {"s": null, "t": "야시장으로 돌아왔을 때 자정 종이 울렸다. 종소리가 물 건너 골목 벽마다 웅웅 부딪쳤다. 한설은 종소리가 다 끝나기를 기다렸다. 그러고 나서 등 아래 평상에 앉아 수첩을 펼쳤다."}, {"s": "night_office:han", "t": "근무가 끝났다. 지금부터는 사사로운 일이야."}, {"s": null, "t": "한설이 수첩을 맨 마지막 쪽까지 넘겼다. 그 쪽만 종이가 새것이었다. 한설은 그 쪽을 내 앞에 펴 놓았다."}, {"s": null, "t": "정청 공문 서식이었다. 칸을 나눈 줄이 자로 그은 듯 곧았고, 맨 위에 반듯한 글씨로 조항 하나가 적혀 있었다."}, {"s": "night_office:han", "t": "「감찰관은 한 사람에 한하여 예외를 둘 수 있다.」"}, {"s": "night_office:han", "t": "「하나, 그 사람이 넘긴 것은 자를 대지 않고 받는다. 하나, 그 사람과 먹는 밥은 근무 중이라도 먹는다. 하나, 그 사람이 부르면 휴가 공문 없이 나간다.」"}, {"s": null, "t": "조항 아래 결재 칸이 있었다. 도장 자리에 붉은 인주 대신 먹으로 쓴 이름이 있었다. 「한설」 두 글자였다."}, {"s": null, "t": "나는 이런 조항이 규정집에 있느냐고 물었다. 한설이 책갑을 열어 규정집을 꺼내 들었다가 도로 넣었다."}, {"s": "night_office:han", "t": "없어. 열다섯 해를 봤으니 알지. 그래서 내가 새로 적었다."}, {"s": "night_office:han", "t": "…규정은 내가 썼다. 그러니 예외도 내가 진다."}, {"s": null, "t": "한설이 수첩을 덮으려다 말고 그 쪽 귀퉁이를 반듯하게 한 번 접었다. 손끝이 접힌 자리를 한 번 더 눌렀다."}, {"s": "night_office:han", "t": "예외를 하나 두면 다음 예외가 온다고 했지? 그래서 한 사람에 한한다고 적은 거다. 다음 예외는 안 와. 자리가 없거든."}, {"s": "night_office:han", "t": "이 공문은 한 벌 더 써서 족자로 꾸며 주마. 공문은 받는 사람한테도 한 벌 가야 하는 법이거든."}, {"s": null, "t": "등불 아래서 한설이 나를 똑바로 보았다. 감찰할 때의 눈이 아니었다."}, {"s": "night_office:han", "t": "조사원. 오늘부터 너는 감찰관의 예외다. 하나뿐인 예외."}, {"s": null, "t": "한설은 수첩을 품에 넣고 평상에서 일어났다. 국숫집 쪽으로 몇 걸음 걸어가다 돌아섰다."}, {"s": "night_office:han", "t": "국숫집이 자정에 불을 땐다더군. …가자. 조항 둘째 줄이잖나."}]'::jsonb, '{"xp": 2289, "gil": 113, "items": {"spirit_qi_pill": 2, "travel_ration": 2, "hf_rg_hanseol_scroll": 1}, "title": "rg_hanseol"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoul_1', 'side', '연담·여울', '쇠 문패', '반요촌 나무 문패는 섬의 안개에 먹이 번져 이름이 자꾸 지워진다. 여울이 문패를 쇠로 부어 보려 월철을 주문한다. 섬 밖으로 나갈 수 없는 여울 대신 조사원이 구중 봉연 바위틈에서 월철을 캐 오고, 여울이 촌장 묵호의 이름을 쇠에 판다.', 'banyo_village', 30, '{gq_1}'::text[], null, 1605, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_yeoul_1';
delete from public.world_quest_steps where quest_id = 'rg_yeoul_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_1', 1, '번지는 문패', '번지는 문패', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 비늘 지붕 위로 재 같은 안개가 내려앉아 있었다. 집집마다 문간에 매단 나무 문패가 안개에 젖어 거뭇하게 번들거렸다. 숨을 들이쉴 때마다 젖은 재 냄새가 목구멍에 껄끄럽게 걸렸다."}, {"s": null, "t": "마을 어귀 첫 집 문간에서 촌장 묵호가 쪼그려 앉아 문패를 고쳐 달고 있었다. 노인의 굽은 등이 망치질에 맞춰 조금씩 들썩였다."}, {"s": null, "t": "그 곁에 여울이 서 있었다. 여울은 노인의 손이 닿지 않는 문패 위쪽 못을 대신 눌러 주고 있었다. 왼손 소매를 손등까지 끌어내린 채였다."}, {"s": null, "t": "내가 다가가자 여울이 고개를 돌렸다. 소매 끝을 한 번 더 잡아당겼다."}, {"s": "q:g_yeoul", "t": "어, 왔네. 또 왔구나. 다들 한 번 왔다 가면 다신 안 오던데."}, {"s": null, "t": "묵호는 우리 쪽을 돌아보지 않았다. 노인은 문패를 문지르던 엄지를 멈추고 번진 글자 하나를 오래 들여다보았다."}, {"s": null, "t": "여울이 목소리를 낮춰 나를 몇 걸음 떨어진 처마 밑으로 데려갔다."}, {"s": "q:g_yeoul", "t": "저 문패, 지난달에 새로 쓴 거거든. 근데 벌써 첫 글자가 번졌어. 섬은 안개가 늘 축축해서 먹이 못 버텨."}, {"s": "q:g_yeoul", "t": "글자가 지워지면 우리 촌장 할아버지는 그 글자를 더 빨리 잊으셔. 다른 집도 다 그래. 그러니까 다들 날마다 문패를 고쳐 다는 거고."}, {"s": null, "t": "여울이 소매째 손목을 문질렀다. 소매 밑에서 딱딱한 것이 스치는 소리가 사락 났다."}, {"s": "q:g_yeoul", "t": "그래서 생각해 봤는데, 나무 말고 쇠에 새기면 어때? 쇠에 판 글자는 안개도 못 지우잖아."}, {"s": "q:g_yeoul", "t": "근데 섬엔 쇠가 안 나. 구중 봉연 바위틈에 월철 광맥이 드러나 있다던데… 나는 거기 못 가."}, {"s": null, "t": "여울이 선창 쪽 물길 끝을 턱으로 가리켰다. 안개 너머 물 위에 박힌 말뚝 하나가 희미하게 보였다."}, {"s": "q:g_yeoul", "t": "저기 말뚝이 보여? 저기까지가 섬이야. 요기 탄 몸은 저길 못 넘어. 그러니까 말뚝 밖 일은… 너한테 부탁할 수밖에 없어."}, {"s": null, "t": "여울은 부탁이라는 말을 하고 나서 입술을 깨물었다. 바깥 사람에게 무엇을 청해 본 지 오래된 얼굴이었다."}, {"s": "q:g_yeoul", "t": "월철 광석 여섯 덩이만 부탁해. 촌장님 문패 하나를 부어 볼 만큼만. 값은 바깥 전으로 줄게. 마을 사람들이 조금씩 모았거든."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_1', 2, '섬 끝 말뚝', '구중 봉연에서 월철 광석을(를) 모은다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["ore"], "r": ["sealed_abyss"], "n": 6}]}'::jsonb, '[{"s": null, "t": "구중 봉연 바위틈에서 캔 월철 광석 자루를 메고 검은 물길을 거슬러 왔다. 물은 기름처럼 무겁게 출렁였고, 자루 끈이 어깨를 파고들었다. 섬 끝 말뚝 곁에 거룻배 한 척이 떠 있었다."}, {"s": null, "t": "뱃머리에 여울이 등을 들고 서 있었다. 여울은 나를 보자 등을 높이 들어 흔들었다."}, {"s": "q:g_yeoul", "t": "여기, 여기! 판자 가운데를 디뎌. 자루부터 이리 줘."}, {"s": null, "t": "여울이 광석 자루를 받아 배 바닥에 내려놓았다. 자루를 풀어 광석 한 덩이를 집어 등불에 비춰 보았다."}, {"s": "q:g_yeoul", "t": "…와, 결이 곱다. 바깥 쇠가 이런 빛이었구나. 너무 오래돼서 다 잊어버렸어."}, {"s": null, "t": "여울이 광석을 자루에 도로 넣고 노를 쥐었다. 노를 쥔 손으로 배 바닥을 톡톡 두드렸다."}, {"s": "q:g_yeoul", "t": "이 늙은 거룻배 못도 다 바깥 거야. 섬에 올 때 같이 실려 온 거. 하나 빠지면 다른 데서 빼 와서 박아."}, {"s": null, "t": "여울이 노를 저었다. 배가 소리 없이 미끄러졌다. 여울의 노 끝에서 튄 물방울이 내 손등에 차갑게 떨어졌다. 여울은 앞만 보며 말을 이었다."}, {"s": "q:g_yeoul", "t": "나도 예전엔 너처럼 조사원이었어. 쇠붙이도 차고 다녔고. 근데 그게 무슨 쇠였는지, 이젠 생각이 안 나."}, {"s": null, "t": "반요촌 선창에 닿자 비늘 덮인 손등의 사내가 대장간 앞에서 우리를 기다리고 있었다. 반요 대장장이 풀무였다."}, {"s": "q:sx_pulmu", "t": "광석째로는 못 붓네. 주괴로 뽑아 와야 쇳물이 고르지. 숯은 우리 가게에 있고."}, {"s": null, "t": "풀무는 그 말만 하고 화덕 쪽으로 돌아섰다. 여울이 광석 자루를 내게 도로 내밀었다."}, {"s": "q:g_yeoul", "t": "아, 미안. 캐 온 사람한테 또 일을 시키네. 나도 거들게. 숯을 나르는 건 나도 할 줄 알아."}, {"s": null, "t": "여울은 대장간 숯 더미에서 숯을 두 팔 가득 안아 화덕 곁에 내려놓았다. 소매가 걷혀 왼 손목의 푸른 비늘이 잠깐 드러났다. 여울은 숯을 내려놓자마자 소매를 끌어내렸다. 끌어내린 소맷자락에 숯가루가 까맣게 묻어났다."}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_1', 3, '안 번지는 글자', '월철 주괴을(를) 만든다, 월철 주괴을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["iron_ingot"], "n": 2}], "give": {"iron_ingot": 2}}'::jsonb, '[{"s": null, "t": "풀무가 주괴를 녹여 문패 틀에 부었다. 쇳물이 치이익 김을 뿜으며 식어 갔다. 대장간 안에 달군 쇠 냄새가 확 퍼졌다. 틀을 깨자 손바닥 두 개만 한 쇳조각이 나왔다."}, {"s": null, "t": "여울이 쇳조각을 무릎에 올려놓고 끌을 쥐었다. 묵호의 나무 문패를 곁에 세워 두고, 글자를 한 자씩 들여다보며 쇠에 팠다."}, {"s": null, "t": "끌질하는 여울의 손이 반듯했다. 획 하나를 팔 때마다 숨을 멈췄다가 다 파고 나서야 내쉬었다."}, {"s": null, "t": "나는 글씨가 곱다고 했다. 여울이 끌을 멈추지 않았다."}, {"s": "q:g_yeoul", "t": "조사원 시절에 장부를 많이 썼거든. 글씨 하나는 반듯하다는 소리를 들었어. 그게 다 좋은 데 쓰였는지는… 모르겠지만."}, {"s": null, "t": "여울은 마지막 획을 파고 쇳가루를 후 불었다. 쇠 문패 위에 묵호의 이름 두 줄이 떠올랐다. 위쪽 이름 첫 자리만 네모나게 비어 있었다."}, {"s": null, "t": "내가 빈자리를 손끝으로 가리키자 여울이 그 자리를 엄지로 쓸었다."}, {"s": "q:g_yeoul", "t": "나무 문패에서 벌써 지워진 글자야. 모르는 글자는 못 새기잖아. 아는 글자부터 지키자."}, {"s": null, "t": "여울은 쇠 문패를 들고 묵호의 집 문간으로 갔다. 노인은 화로 곁에서 졸고 있었다. 화로의 잔불이 노인의 무릎을 발갛게 비췄다. 여울은 노인을 깨우지 않고 나무 문패 아래에 쇠 문패를 나란히 걸었다."}, {"s": null, "t": "얼마 뒤 문간으로 나온 묵호가 쇠 문패 앞에 섰다. 노인은 아무 말 없이 쇠에 판 글자를 손가락으로 천천히 짚어 내려갔다. 굽은 뒷모습이 오래 움직이지 않았다."}, {"s": null, "t": "여울이 그 뒷모습을 보다가 고개를 돌렸다. 소매째 손목을 문지르는 손이 빨랐다."}, {"s": "q:g_yeoul", "t": "…저것 봐. 봐 봐, 안개에 젖어도 안 번져."}, {"s": "q:g_yeoul", "t": "마을 문패가 쉰 개쯤 되거든. 다 바꾸려면 한참 걸릴 거야. 광석을 한 번에 다 캐 올 수도 없고."}, {"s": null, "t": "여울이 나를 보았다. 짧게 끊어 말하던 목소리가 조금 낮아졌다."}, {"s": "q:g_yeoul", "t": "…앞으로도 부탁해도 될까? 봉연에 갈 때마다 조금씩만. 나는 말뚝까지 배를 타고 마중 나갈게."}, {"s": null, "t": "나는 그러겠다고 했다. 여울이 소매 끝을 쥐었다 놓았다. 웃음 끝이 조금 떨렸다."}, {"s": "q:g_yeoul", "t": "이상하다. 부탁은 내가 했는데 왜 내가 더 고맙지."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoul_2', 'side', '연담·여울', '바깥 국밥', '반요촌 장터 솥 다리를 고칠 생 월철을 주문한 여울이 조사원에게 본부 객사 국밥 맛을 묻는다. 둘이 갈대숲에서 생선을 낚아 섬 재료로 국밥을 흉내 내 끓인다. 맛이 영 다르다고 둘 다 웃고, 틀린 맛 덕에 여울이 맞는 맛을 떠올린다.', 'banyo_village', 30, '{rg_yeoul_1}'::text[], null, 1606, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeoul", "stage": 2}'::jsonb where quest_id = 'rg_yeoul_2';
delete from public.world_quest_steps where quest_id = 'rg_yeoul_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_2', 1, '부러진 솥 다리', '부러진 솥 다리', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 장터 한가운데 큰 무쇠 솥 하나가 한쪽으로 기울어 있었다. 세 다리 가운데 하나가 부러져 돌덩이로 받쳐 놓은 채였다. 솥 바닥에 눌어붙은 누룽지 냄새가 안개 속에 아직 옅게 남아 있었다."}, {"s": null, "t": "여울이 솥 곁에 쪼그려 앉아 부러진 다리를 들여다보고 있었다. 나를 보자 일어나 손에 묻은 재를 털었다."}, {"s": "q:g_yeoul", "t": "왔구나! 네가 봉연에서 지고 온 월철로 문패를 열한 개나 부었어. 촌장님네 옆집, 그 옆집, 우물가 집까지. 이제 안개 낀 아침에도 열한 집은 안 번져."}, {"s": null, "t": "여울이 고개를 돌려 장터 둘레를 보았다. 문간마다 쇠 문패가 하나씩 섞여 걸려 있었다. 쇠 문패가 걸린 집 문간에는 문패를 고치러 나온 사람이 없었다."}, {"s": "q:g_yeoul", "t": "문패를 고치러 나오던 시간에 이제 다들 밥을 짓더라. 그래서 이 배불뚝이 솥이 바빠졌는데… 다리가 똑 부러졌지 뭐야."}, {"s": "q:g_yeoul", "t": "그래서 오늘 주문은 생 월철이야. 풀무 아저씨가 생 월철을 섞어야 솥 다리가 안 튄대. 여섯 덩이면 될 거야."}, {"s": null, "t": "여울은 주문을 다 말하고도 솥 곁을 떠나지 않았다. 기운 솥 안쪽을 들여다보다가 불쑥 물었다."}, {"s": "q:g_yeoul", "t": "저기, 조사원. 본부 객사 국밥 말이야, 아직도 팔아?"}, {"s": null, "t": "나는 판다고 했다. 객사 부엌에서 아침마다 솥을 건다고 했다."}, {"s": "q:g_yeoul", "t": "그렇구나. …나도 먹었었어, 조사원 시절에. 일 끝나고 새벽에 들어가면 찬모 아주머니가 남은 걸 데워 주셨거든."}, {"s": "q:g_yeoul", "t": "근데 무슨 맛이었는지 생각이 안 나. 뜨거웠다는 것만 기억나. 벌써 일곱 해나 지났으니까."}, {"s": null, "t": "여울이 웃으며 솥 테두리를 손가락으로 톡톡 두드렸다. 무쇠가 통, 하고 둔하게 울렸다."}, {"s": "q:g_yeoul", "t": "솥 다리를 고치면 우리 끓여 볼래? 섬 재료로 그 국밥 흉내를 내서. 생선부터 낚자. 갈대숲은 섬이라 나도 갈 수 있어."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_2', 2, '흉내 낸 국밥', '구중 봉연에서 생 월철을(를) 모은다, 잿빛 갈대숲에서 낚시를 한다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["raw_iron"], "r": ["sealed_abyss"], "n": 6}, {"t": "fish", "r": ["ash_reeds"], "n": 2}]}'::jsonb, '[{"s": null, "t": "갈대숲 물가에서 여울은 낚싯대를 쥐는 법부터 잊어버린 채였다. 내가 찌를 달아 주자, 여울은 찌가 잠길 때마다 나보다 먼저 소리를 질렀다. 갈대 사이 물은 거무스름했고, 미끼를 꿴 손끝에서 갯내가 좀처럼 가시지 않았다."}, {"s": null, "t": "생선 두 마리와 생 월철 자루를 들고 장터로 돌아오니 풀무가 솥 다리를 새로 부어 끼워 두었다. 솥이 반듯하게 서 있었다."}, {"s": "q:sx_pulmu", "t": "다리 셋이 다 같은 쇠라 이제 안 기울 걸세. 끓이는 건 자네들 몫이네."}, {"s": null, "t": "풀무가 대장간으로 돌아가자 여울이 솥 앞에서 팔을 걷어붙였다. 왼 소매도 걷었다가, 나를 한 번 보고 도로 내렸다."}, {"s": "q:g_yeoul", "t": "그래서, 객사 국밥엔 뭐가 들어가?"}, {"s": null, "t": "나는 맑은 차를 우려 국물을 내고, 손질한 생선과 건량을 넣는다고 했다."}, {"s": "q:g_yeoul", "t": "차로 국물을 낸다고? 별걸 다 넣네."}, {"s": null, "t": "나는 차를 우리면 비린내가 덜하다고 했다. 여울이 솥 가장자리를 손가락으로 쓸었다. 무언가를 떠올리려는 얼굴이었다."}, {"s": "q:g_yeoul", "t": "아, 그러고 보니 객사 국밥은 비린내가 하나도 안 났어. 그건 기억나."}, {"s": null, "t": "여울이 갈대숲에서 뜯어 온 야령초와 수향 갈대를 내밀었다. 차를 우릴 풀이었다. 나는 생선을 손질하고 차를 우렸다. 여울은 곁에서 불을 지켰다."}, {"s": null, "t": "솥에서 오르는 김에 쌉싸름한 풀 내음과 생선 비린내가 뒤엉켰다. 여울은 솥에서 김이 오를 때마다 고개를 숙여 냄새를 맡았다. 맡고 나서는 고개를 갸웃했다."}, {"s": "q:g_yeoul", "t": "…이 냄새가 아닌 것 같은데. 아닌가? 맞나? 아, 모르겠다."}, {"s": null, "t": "나는 끓여 보면 알 거라고 했다. 여울이 국자를 쥐고 솥을 휘휘 저었다."}, {"s": "q:g_yeoul", "t": "두 그릇만 끓이자. 처음 거니까 우리 둘이 먼저 먹어 봐야지. 맛없으면 마을 사람들한테 창피하잖아."}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_2', 3, '영 다른 맛', '영기 국밥을(를) 만든다, 영기 국밥을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["spirit_gukbap"], "n": 2}], "give": {"spirit_gukbap": 2}}'::jsonb, '[{"s": null, "t": "솥 곁 평상에 국밥 두 그릇을 나란히 놓았다. 여울이 숟가락을 들고 오르는 김만 들여다보았다. 한 숟갈을 떠 입에 넣은 것은 김이 다 걷힌 뒤였다."}, {"s": null, "t": "여울의 얼굴이 천천히 찡그려졌다. 나도 한 숟갈을 먹었다. 갈대숲 생선은 비린 데다 차 맛이 너무 진했다. 객사 국밥과는 영 다른 맛이었다."}, {"s": "q:g_yeoul", "t": "…이거, 국밥 맞아?"}, {"s": null, "t": "나는 국밥은 맞는데 객사 국밥은 아니라고 했다. 여울이 숟가락을 든 채 나를 보았다."}, {"s": null, "t": "여울이 먼저 웃음을 터뜨렸다. 어깨가 들썩일 만큼 크게 웃었다. 나도 따라 웃었다. 장터를 지나던 사람들이 무슨 일인가 하고 평상 쪽을 돌아보았다."}, {"s": "q:g_yeoul", "t": "아이고, 배 아파. 일곱 해 만에 먹는 바깥 국밥이 이 맛이라니, 진짜."}, {"s": null, "t": "여울은 웃음을 다 그치고 나서도 숟가락을 내려놓지 않았다. 찡그리면서도 한 숟갈씩 국밥을 다 비웠다."}, {"s": null, "t": "나는 맛없다면서 다 먹는다고 놀렸다. 여울이 빈 그릇 바닥을 숟가락으로 긁었다."}, {"s": "q:g_yeoul", "t": "맛이 달라서 오히려 생각났어. 객사 국밥은 이것보다 훨씬 순했거든. 국물이 뽀얗고, 파가 동동 떠 있고. 다 먹으면 찬모 아주머니가 그릇에 숭늉을 부어 주셨어."}, {"s": "q:g_yeoul", "t": "틀린 걸 먹어 보니까 맞는 게 생각나네. 이상하지?"}, {"s": null, "t": "여울이 빈 그릇을 두 손으로 감쌌다. 그릇에 남은 온기를 오래 쥐고 있었다."}, {"s": null, "t": "장터 솥 쪽에서 사람들이 하나둘 그릇을 들고 다가왔다. 여울이 솥에 남은 국밥을 그릇마다 조금씩 덜어 주었다. 다들 한 숟갈씩 떠먹어 보고 고개를 갸웃하다가 웃었다."}, {"s": "q:g_yeoul", "t": "다음에 객사에 가거든 그 맛을 잘 기억해 와. 나는 못 가니까, 네가 기억해 와서 말해 줘. 그럼 또 끓여 보자."}, {"s": null, "t": "나는 그러겠다고 했다. 여울이 평상에서 일어나 빈 그릇 둘을 포갰다."}, {"s": "q:g_yeoul", "t": "바깥 맛을 들고 와 주는 사람이 생겼네. …이런 날도 오는구나."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoul_3', 'side', '연담·여울', '비늘 손', '우물 두레박 줄을 꼴 갈대 영사는 갈대숲 물길 건너편에만 난다. 미끄러운 징검돌 앞에서 여울이 늘 소매로 가리던 왼손을 그대로 내밀어 조사원의 손을 잡고 건넌다. 돌아오는 길, 건너고 나서도 한참 손을 놓지 않는다.', 'banyo_village', 30, '{rg_yeoul_2}'::text[], null, 1607, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeoul", "stage": 3}'::jsonb where quest_id = 'rg_yeoul_3';
delete from public.world_quest_steps where quest_id = 'rg_yeoul_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_3', 1, '두레박 쇠고리', '두레박 쇠고리', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 우물가에 여울이 두레박을 들고 서 있었다. 두레박 쇠고리가 녹슬어 반쯤 끊어져 있었다. 우물 돌테에는 물이끼가 미끄덩하게 앉아 있었다."}, {"s": "q:g_yeoul", "t": "어, 마침 잘 왔다. 장터 솥은 이제 넷이나 끓는데, 이번엔 이 늙은 두레박이 말썽이야."}, {"s": null, "t": "여울이 웃으며 두레박을 들어 보였다. 끊어지기 직전인 고리가 덜렁거리며 끼익끼익 울었다."}, {"s": "q:g_yeoul", "t": "오늘은 이거. 우물 두레박 고리가 곧 끊어지게 생겼어. 월철 광석 여섯 덩이면 풀무 아저씨가 새 고리를 부어 준대."}, {"s": null, "t": "여울이 우물 안을 내려다보았다. 깊은 데서 검은 물이 찰랑 소리를 냈다."}, {"s": "q:g_yeoul", "t": "빠지면 건질 사람이 없어. 섬 우물은 깊어서 줄이 안 닿는 데까지 가라앉거든. 작년에도 하나 빠뜨렸어. 그 뒤로는 이 두레박 하나로 온 마을이 다 길어 먹어."}, {"s": null, "t": "우물가 돌테 곁에 물동이를 든 아낙 둘이 줄을 서 있었다. 아낙들은 여울이 두레박을 쥔 것을 보고 동이를 내려놓았다."}, {"s": null, "t": "여울은 아낙들 동이에 물을 길어 주었다. 끊어질 듯한 고리를 손으로 감싸 쥐고 줄을 천천히 당겼다."}, {"s": "q:g_yeoul", "t": "두레박 줄도 갈아야 해. 줄은 갈대 영사로 꼬는데, 쓸 만한 영사는 갈대숲 물길 건너편에만 나. 건너는 길이… 좀 미끄러워."}, {"s": null, "t": "여울이 제 손을 내려다보았다."}, {"s": "q:g_yeoul", "t": "꼬는 건 내가 할게. 장부 글씨처럼 반듯하게. 그건 자신 있어."}, {"s": null, "t": "여울은 그 말끝에 왼 손목을 소매째 쥐었다. 무언가 망설이는 손이었다."}, {"s": "q:g_yeoul", "t": "…근데 거기 셋째 돌이 늘 흔들려. 혼자 가다가 두 번이나 빠졌어. 그 뒤론 영사가 모자라도 안 갔고."}, {"s": null, "t": "나는 영사를 캐러 갈 때 같이 건너자고 했다. 여울이 두레박을 우물 돌테에 내려놓았다."}, {"s": "q:g_yeoul", "t": "응, 그러자. 광석을 캐 오면 같이 가."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_3', 2, '징검돌', '구중 봉연에서 월철 광석을(를) 모은다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["ore"], "r": ["sealed_abyss"], "n": 6}]}'::jsonb, '[{"s": null, "t": "캐 온 월철 광석을 풀무에게 맡기고 여울과 갈대숲으로 걸었다. 잿빛 갈대가 바람도 없이 사락사락 흔들렸다."}, {"s": null, "t": "갈대숲 한가운데로 검은 물길 하나가 가로질러 흘렀다. 물 위로 납작한 징검돌이 띄엄띄엄 박혀 있었다. 돌마다 물이끼가 끼어 번들거렸다. 물길에서 올라오는 냉기에 발목이 시렸다."}, {"s": "q:g_yeoul", "t": "여기야. 건너편 갈대가 실이 질기거든. 섬 사람들은 이 물길은 혼자 안 건너. 둘이 손잡고 건너."}, {"s": null, "t": "여울이 먼저 첫 돌에 올라섰다. 뒤를 돌아 나를 보았다. 오른손을 내밀려다 말았다. 오른손에는 갈대 영사를 담을 망태가 들려 있었다."}, {"s": null, "t": "여울의 손이 허공에서 머뭇거렸다. 여울은 망태를 바꿔 들지 않고 왼손을 내밀었다. 소매를 걷지도 내리지도 않은 손이었다. 손목부터 손등까지 푸른 비늘이 덮여 있었다."}, {"s": "q:g_yeoul", "t": "…이쪽 손밖에 없네. 차가울 거야. 싫으면 말해. 망태를 바꿔 들면 돼."}, {"s": null, "t": "나는 그 손을 잡았다. 비늘이 손바닥에 매끄럽게 닿았다. 물속 돌처럼 서늘했고, 안쪽에서 아주 희미하게 맥이 뛰었다."}, {"s": null, "t": "여울의 손가락이 잠깐 굳었다가 내 손을 꽉 쥐었다."}, {"s": null, "t": "나는 차갑지 않다고 했다. 여울은 고개를 숙인 채 대답하지 않았다. 잡은 손에 힘이 조금 더 들어갔다."}, {"s": "q:g_yeoul", "t": "…건너자. 셋째 돌이 흔들려. 거기선 내 쪽으로 디뎌."}, {"s": null, "t": "셋째 돌이 발밑에서 기우뚱했다. 여울이 내 손을 끌어당겼다. 나는 여울 쪽으로 몸을 기울여 다음 돌을 디뎠다. 물이 철썩 돌을 핥았다."}, {"s": null, "t": "건너편 갈대밭에 닿자 여울이 손을 놓고 망태를 내밀었다. 여울은 곧장 등을 돌려 갈대를 헤치기 시작했다. 왼손을 오른손으로 감싸 쥐고 있었다."}, {"s": null, "t": "나는 그 뒷모습을 보다가 망태를 들고 갈대밭으로 들어갔다. 갈대 이삭이 털붓처럼 목덜미를 간질였다."}, {"s": "q:g_yeoul", "t": "영사는 이삭 밑동에 감겨 있어. 끊기지 않게 살살 풀어. 두레박 줄 하나를 꼬려면 넉넉히 있어야 해."}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_3', 3, '놓지 않은 손', '잿빛 갈대숲에서 갈대 영사을(를) 모은다', '{"at": ["ash_reeds"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 4}]}'::jsonb, '[{"s": null, "t": "망태에 갈대 영사가 그득해졌을 즈음 갈대숲에 저녁 안개가 내려앉았다. 물길로 돌아오니 징검돌이 안개에 반쯤 묻혀 있었다. 안개가 살갗에 닿을 때마다 솜털에 잔 물방울이 맺혔다."}, {"s": null, "t": "여울이 첫 돌에 올라 이번엔 망설이지 않고 왼손을 내밀었다. 나는 그 손을 잡았다."}, {"s": null, "t": "돌을 하나씩 건넜다. 셋째 돌에서 여울은 이번에는 아무 말도 하지 않았다. 대신 내 손을 먼저 끌어당겼다."}, {"s": null, "t": "마지막 돌을 건너 마른 땅에 올라섰다. 여울은 손을 놓지 않았다. 나도 놓지 않았다. 둘은 손을 잡은 채 갈대 사이 길을 걸었다."}, {"s": null, "t": "반요촌 지붕이 보일 무렵에야 여울이 걸음을 늦췄다. 잡은 손을 내려다보았다."}, {"s": "q:g_yeoul", "t": "…다 건넜는데. 안 놓네, 우리."}, {"s": null, "t": "나는 손을 놓으려 했다. 여울의 손가락이 아주 조금 힘을 주었다. 나는 손을 그대로 두었다."}, {"s": "q:g_yeoul", "t": "섬에 온 뒤로 이 손은 늘 소매 속에 있었어. 보면 다들 놀라니까. 여기선 다 비늘이 있어서 굳이 잡을 일도 없었고."}, {"s": "q:g_yeoul", "t": "바깥 사람이 이 손을 잡아 준 건 네가 처음이야."}, {"s": null, "t": "여울은 말을 마치고 비로소 손을 놓았다. 놓은 손으로 제 손목의 비늘을 한 번 문질렀다. 이번에는 소매를 끌어내리지 않았다."}, {"s": null, "t": "나는 그 손목을 보았다. 저녁 안개 속에서 푸른 비늘이 등불도 없이 희미하게 빛났다."}, {"s": null, "t": "마을 어귀에서 풀무가 새로 부은 쇠고리를 들고 기다리고 있었다. 풀무는 소매를 걷은 여울의 손목을 한 번 보았다. 아무 말 없이 쇠고리를 건넸다."}, {"s": "q:g_yeoul", "t": "어, 고리가 다 됐네. 줄은 내가 꼴게. 밤새 꼬면 내일 아침엔 두레박을 들 수 있을 거야."}, {"s": null, "t": "여울이 갈대 영사 망태를 받아 들고 우물가로 걸어갔다. 몇 걸음 가다가 돌아섰다."}, {"s": "q:g_yeoul", "t": "다음에도 물길을 건널 일 있으면 같이 가자. 그 돌, 혼자 건너면 미끄럽단 말이야."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoul_4', 'side', '연담·여울', '배웅 노래', '여울이 아는 노래는 섬에 와서 배운 배웅 노래뿐이다. 여울은 바깥에서 사람을 맞을 때 부르는 노래를 묻고, 둘이 갈대숲 끝 갯바위에 앉아 낚싯대를 드리운 채 밤새 가사를 짓는다. 여울은 첫 줄만 비워 둔다.', 'banyo_village', 30, '{rg_yeoul_3}'::text[], null, 1608, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeoul", "stage": 4}'::jsonb where quest_id = 'rg_yeoul_4';
delete from public.world_quest_steps where quest_id = 'rg_yeoul_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_4', 1, '맞는 노래', '맞는 노래', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "해 질 녘 반요촌 장터 끝 화로 앞에서 누군가 낮게 노래를 불렀다. 길게 끌다 뚝 끊기는 가락이었다. 떠나는 이를 배웅하는 노래였다. 화로에서 마른 갈대 타는 냄새가 매캐하게 흘러왔다."}, {"s": null, "t": "여울은 화로에서 조금 떨어진 문간 돌에 앉아 그 노래를 듣고 있었다. 무릎 위에 쇠 문패 하나를 올려놓고 끌로 글자를 파고 있었다. 여울이 나를 보고 끌을 쥔 손으로 옆자리를 가리켰다."}, {"s": "q:g_yeoul", "t": "앉아, 앉아. 이게 마흔한 번째 문패야. 나무 문패는 이제 몇 개 안 남았어."}, {"s": "q:g_yeoul", "t": "오늘 주문은 생 월철이야. 문패 거는 고리가 모자라. 여섯 덩이면 돼."}, {"s": null, "t": "여울은 주문을 말하고 나서 끌을 멈췄다. 화로 쪽에서 노래가 끝 소절로 넘어갔다."}, {"s": "q:g_yeoul", "t": "저 노래 들려? 내가 아는 노래는 저거 하나뿐이야. 섬에 와서 배운 거."}, {"s": "q:g_yeoul", "t": "나, 처음엔 그 배를 보내는 쪽이었다고 했지? 그땐 배가 떠나도 부두에서 아무도 노래를 안 불렀어. 근데 섬에 와 보니까 여기선 부르더라. 떠나는 사람한테."}, {"s": null, "t": "여울이 끌을 문패 위에 내려놓고 나를 보았다."}, {"s": "q:g_yeoul", "t": "바깥에서는 사람을 맞을 때도 노래를 불러?"}, {"s": null, "t": "나는 부른다고 했다. 먼 길을 다녀온 사람이 마을 어귀에 들어서면 반기는 노래가 있다고 했다."}, {"s": "q:g_yeoul", "t": "…그렇구나. 그건 몰랐어. 나는 맞이할 일이 없었으니까."}, {"s": null, "t": "여울은 문패를 품에 안고 일어섰다."}, {"s": null, "t": "화로 쪽 노래가 끝났다. 노래하던 사람이 불씨를 재로 덮고 집으로 돌아갔다. 장터 끝이 조용해졌다."}, {"s": "q:g_yeoul", "t": "광석을 캐 오면 갯바위에 가자. 갈대숲 끝에 물이 넓게 트인 데가 있어. 낚싯대를 드리워 놓고 그 노래를 가르쳐 줘. 모르는 데는 우리가 지으면 되잖아."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_4', 2, '갯바위', '구중 봉연에서 생 월철을(를) 모은다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["raw_iron"], "r": ["sealed_abyss"], "n": 6}]}'::jsonb, '[{"s": null, "t": "생 월철 자루를 풀무에게 맡기고 여울과 갈대숲 끝으로 걸었다. 갈대가 끝나는 자리에 검은 바위들이 물 쪽으로 엎드려 있었다. 그 너머로 잿빛 물이 넓게 트여 있었다. 비릿한 물바람이 바위 틈을 빠져나와 머리카락을 헝클었다."}, {"s": null, "t": "여울은 가장 평평한 갯바위에 걸터앉아 낚싯대 두 개를 물에 드리웠다. 무릎 위에 종이를 펴고 붓을 꺼냈다."}, {"s": "q:g_yeoul", "t": "자, 바깥 맞이 노래를 불러 봐. 가락만이라도 괜찮아."}, {"s": null, "t": "나는 아는 가락을 낮게 흥얼거렸다. 바깥 맞이 노래는 첫머리에 돌아온 사람의 이름을 부르며 시작한다고도 했다."}, {"s": null, "t": "여울은 고개를 갸웃하며 들었다. 한 번 더 부르자 여울이 따라 흥얼거렸다. 가락 끝이 자꾸 배웅 노래 쪽으로 기울었다."}, {"s": "q:g_yeoul", "t": "어, 이상하다. 자꾸 이쪽으로 끝나네. 배웅 노래만 불러 버릇해서 그런가."}, {"s": null, "t": "나는 끝이 배웅 노래 같아도 괜찮다고 했다. 섬에서 짓는 노래니까 섬 가락이 섞여도 된다고 덧붙였다."}, {"s": null, "t": "여울이 붓을 멈추고 나를 보았다. 붓끝으로 종이를 톡 치고 고개를 끄덕였다."}, {"s": "q:g_yeoul", "t": "…그러네. 섬 노래니까. 그럼 가사도 섬 말로 짓자."}, {"s": null, "t": "여울이 종이에 반듯한 글씨로 한 줄을 적었다. 「검은 물 건너온 발에 재가 묻었네.」 그 아래에 한 줄을 더 적었다. 「털지 말고 들어오게, 문패 아래로.」"}, {"s": "q:g_yeoul", "t": "어때? 너무 슬픈가."}, {"s": null, "t": "나는 슬프지 않다고 했다. 재 묻은 발로 들어와도 된다는 노래라면 몇 번이고 듣고 싶다고 말했다."}, {"s": null, "t": "여울이 종이를 들어 올려 두 줄을 소리 없이 읽었다. 입술 끝이 조금 떨렸다."}, {"s": "q:g_yeoul", "t": "다행이다. …오늘 밤 안에 끝까지 짓자. 고기가 안 물면 그냥 앉아 있으면 되고."}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_4', 3, '비워 둔 첫 줄', '잿빛 갈대숲에서 낚시를 한다, 잿빛 갈대숲에서 쉰다', '{"at": ["ash_reeds"], "tasks": [{"t": "fish", "r": ["ash_reeds"], "n": 2}, {"t": "rest", "r": ["ash_reeds"], "n": 1}]}'::jsonb, '[{"s": null, "t": "밤이 깊도록 찌는 두어 번 잠겼다. 여울은 고기를 건질 때마다 종이에 한 줄씩 가사를 더했다. 고기가 안 물면 가락을 흥얼거리며 지운 줄을 다시 썼다."}, {"s": null, "t": "밤이 깊자 갯바위가 냉기를 뿜어 엉덩이가 저렸다. 나는 졸음이 올 때마다 낚싯대를 고쳐 쥐었다. 여울은 한 번도 졸지 않았다. 가락을 흥얼거리는 입술만 쉬지 않고 움직였다."}, {"s": null, "t": "새벽이 가까워 오자 물 위로 잿빛 안개가 낮게 깔렸다. 여울의 무릎 위 종이에 반듯한 글씨가 여섯 줄 채워져 있었다. 맨 윗줄만 비어 있었다."}, {"s": null, "t": "나는 왜 첫 줄을 비워 두느냐고 물었다. 여울이 붓을 붓통에 꽂았다."}, {"s": "q:g_yeoul", "t": "맞이 노래는 첫머리에 맞이하는 사람 이름을 부른다며. 네가 그랬잖아."}, {"s": "q:g_yeoul", "t": "근데 나는 아직 내 노래로 누굴 맞아 본 적이 없어. 누구 이름을 넣을지 몰라서 비워 뒀어."}, {"s": null, "t": "여울은 종이를 반으로 접어 품에 넣었다. 손목의 비늘을 문지르다 말고 손을 내렸다."}, {"s": "q:g_yeoul", "t": "첫 줄은 나중에 채울게. 맞이할 사람이 생기면."}, {"s": null, "t": "여울은 그 말을 하고 물 쪽으로 고개를 돌렸다. 안개 너머 물길 끝에 섬 끝 말뚝이 어렴풋이 서 있었다. 내가 늘 배를 타고 돌아오던 쪽이었다."}, {"s": null, "t": "여울의 손이 품 안의 종이 위에 한 번 얹혔다가 떨어졌다."}, {"s": null, "t": "나는 그 첫 줄에 누구의 이름이 들어가느냐고 묻지 않았다. 여울도 말하지 않았다."}, {"s": null, "t": "여울이 갯바위에서 일어나 낚싯대를 거뒀다. 망태에는 밤새 잡은 생선 몇 마리가 들어 있었다."}, {"s": null, "t": "나는 망태를 받아 어깨에 멨다. 생선 꼬리가 망태 틈으로 비어져 나와 파닥거렸다."}, {"s": "q:g_yeoul", "t": "이건 장터 솥에 넣자. 오늘 저녁은 국밥 흉내 다섯째 판이야."}, {"s": "q:g_yeoul", "t": "…밤새 같이 있어 줘서 고마워. 혼자 지었으면 또 배웅 노래가 됐을 거야."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_yeoul_5', 'side', '연담·여울', '맞이한 사람', '마을 문패를 다 쇠로 바꾸고 이름 없는 어귀 문간 하나가 남는다. 여울이 그 문간에 처음으로 맞이 등을 걸고, 등 아래 쇠패에 조사원의 이름과 「여울이 맞이한 사람」을 판다. 비워 둔 첫 줄에 조사원의 이름을 넣어 노래를 부른다.', 'banyo_village', 30, '{rg_yeoul_4}'::text[], null, 1609, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "yeoul", "stage": 5}'::jsonb where quest_id = 'rg_yeoul_5';
delete from public.world_quest_steps where quest_id = 'rg_yeoul_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_5', 1, '마지막 나무 문패', '마지막 나무 문패', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 마을 어귀 문간에 나무 문패 하나만 남아 걸려 있었다. 둘레 집들 문간에는 모두 쇠 문패가 걸려 안개 속에서 은빛으로 빛났다."}, {"s": null, "t": "여울이 그 마지막 나무 문패 앞에 서 있었다. 문패에는 아무 이름도 적혀 있지 않았다. 섬에 들어서는 사람이 처음 지나는 문간이었다."}, {"s": "q:g_yeoul", "t": "왔구나. 네가 날라 온 쇠로 마을 문패를 다 바꿨어. 쉰한 집, 전부. 이제 아침마다 문패를 고치러 나오는 사람이 하나도 없어."}, {"s": "q:g_yeoul", "t": "남은 건 여기 하나야. 어귀 문간. 사람이 안 사는 문이라 이름이 없어."}, {"s": null, "t": "여울이 문간 문짝을 손등으로 가볍게 두드렸다. 속이 빈 나무처럼 통통 가벼운 소리가 울렸다."}, {"s": "q:g_yeoul", "t": "처음 섬에 온 날, 이 문간 앞에서 한참 서 있었어. 들어가도 되나 싶어서. 아무도 들어오라는 말을 안 했거든. 다들 배웅 노래만 알았으니까."}, {"s": null, "t": "여울은 그 말을 하고 손목의 비늘을 문질렀다. 오래 지난 일을 말하는데도 손이 빨랐다."}, {"s": null, "t": "여울이 빈 나무 문패를 손바닥으로 쓸었다. 품에서 접힌 종이를 꺼냈다. 갯바위에서 지은 노래였다. 첫 줄은 여전히 비어 있었다."}, {"s": "q:g_yeoul", "t": "여기에 등을 달고 싶어. 어귀에 등이 걸려 있으면, 물길을 건너오는 사람이 멀리서도 섬을 보잖아."}, {"s": "q:g_yeoul", "t": "쇠로 등 고리랑 기둥 쇠테를 붓고, 갈대 영사로 등갓을 짤 거야. 솔래 아주머니가 갓 바느질을 해 준대."}, {"s": null, "t": "여울이 대장간 쪽을 턱으로 가리켰다."}, {"s": "q:g_yeoul", "t": "등잔은 풀무 아저씨가 쇠로 부어 준대. 기름은 갈대숲 물고기 기름을 짜서 쓰면 되고. 갓이랑 고리만 있으면 돼."}, {"s": null, "t": "여울은 종이를 다시 품에 넣고 나를 보았다."}, {"s": "q:g_yeoul", "t": "오늘은 주문이 둘이야. 월철 광석 여섯, 갈대 영사 셋. 영사는 물길 건너편 거로. …징검돌은 같이 건너자."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_5', 2, '등갓', '구중 봉연에서 월철 광석을(를) 모은다, 잿빛 갈대숲에서 갈대 영사을(를) 모은다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["ore"], "r": ["sealed_abyss"], "n": 6}, {"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 3}]}'::jsonb, '[{"s": null, "t": "징검돌을 건너 거둬 온 갈대 영사를 솔래에게 건네자, 솔래는 곧바로 바늘에 실을 꿰었다. 바느질 아낙의 손이 갈대 영사를 등갓 뼈대에 촘촘히 감아 나갔다. 마른 영사가 손가락 사이에서 사각사각 소리를 냈다."}, {"s": "q:sx_sollae", "t": "소맷자락 붙들고 숨던 애가 등을 다 단다니, 원. 섬에 등이 걸리는 건 배웅할 때뿐이었는데."}, {"s": null, "t": "솔래는 그 말만 하고 바느질에 고개를 숙였다. 여울이 등갓 곁에 쪼그려 앉아 솔래의 손을 들여다보았다."}, {"s": "q:g_yeoul", "t": "아주머니, 갓은 좀 밝게 비쳐야 해요. 멀리서도 보이게요."}, {"s": null, "t": "솔래는 대꾸 대신 영사를 한 겹으로 성기게 감기 시작했다. 감은 자리 사이로 불빛이 새어 나갈 틈이 생겼다."}, {"s": null, "t": "대장간에서는 풀무가 화덕에 불을 지피고 있었다. 내가 캐 온 월철 광석 자루가 화덕 곁에 놓여 있었다."}, {"s": "q:g_yeoul", "t": "고리랑 쇠테는 주괴로 부어야 한대. 이번엔 내가 숯을 넣을게. 너는 망치를 쳐."}, {"s": null, "t": "나는 망치를 쥐었다. 여울이 숯을 넣을 때마다 화덕 불이 화르르 솟았다. 쇠를 두드릴 때마다 땅땅 하는 소리가 대장간 벽을 울렸다. 화덕 열기에 앞섶이 금세 땀으로 젖었다."}, {"s": null, "t": "풀무가 곁을 지나다가 걸음을 멈췄다. 풀무는 망치질하는 내 손목을 한 번 고쳐 잡아 주고 말없이 제 화덕으로 돌아갔다."}, {"s": null, "t": "여울이 숯을 화덕에 넣다가 손을 멈췄다. 화덕 불빛에 여울의 얼굴이 붉게 물들었다."}, {"s": "q:g_yeoul", "t": "그리고… 하나 더 부어 줘. 손바닥만 한 패 하나. 등 아래 걸 거야. 새길 글자는 내가 정해 뒀어."}, {"s": null, "t": "나는 무슨 글자냐고 물었다. 여울이 숯을 화덕에 마저 넣었다."}, {"s": "q:g_yeoul", "t": "그건 비밀. 등을 걸고 나서 보여 줄게. 오늘 밤에."}, {"s": null, "t": "여울은 그 말을 하고 화덕 불을 바라보았다. 입꼬리가 아주 조금 올라가 있었다."}]'::jsonb, '{"xp": 2760}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_yeoul_5', 3, '맞이 등', '월철 주괴을(를) 만든다, 월철 주괴을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["iron_ingot"], "n": 2}], "give": {"iron_ingot": 2}}'::jsonb, '[{"s": null, "t": "밤이 되자 마을 사람들이 어귀 문간 앞에 하나둘 모여들었다. 밤공기가 차서 사람들의 입김이 안개에 섞여 하얗게 흩어졌다. 문간 기둥에 쇠테가 둘렸고, 쇠 고리에 솔래가 지은 갈대 영사 등갓이 매달려 있었다."}, {"s": null, "t": "여울이 등갓 안 심지에 불을 붙였다. 등불이 갈대 영사 결을 따라 은은하게 번졌다. 어귀 문간이 처음으로 환해졌다."}, {"s": null, "t": "묵호가 사람들 뒤에서 그 불빛을 올려다보았다. 노인은 아무 말 없이 지팡이를 짚고 서 있었다."}, {"s": null, "t": "솔래가 사람들 틈에서 나를 보더니 내 등을 살짝 떠밀었다. 나는 등 바로 아래까지 떠밀려 나갔다."}, {"s": null, "t": "여울이 등 아래에 쇠패 하나를 걸었다. 손바닥만 한 쇠패에 반듯한 글씨가 두 줄 파여 있었다. 윗줄은 내 이름이었다. 아랫줄은 「여울이 맞이한 사람」이었다."}, {"s": null, "t": "나는 쇠패 앞에 섰다. 손가락으로 내 이름을 짚어 보았다. 쇠에 판 글자는 안개에 젖어도 번지지 않았다."}, {"s": null, "t": "쇠패 아래 귀퉁이에는 작은 글씨가 하나 더 있었다. 쇠를 판 날짜였다. 여울의 글씨였다."}, {"s": null, "t": "여울이 품에서 접힌 종이를 꺼내 펼쳤다. 비어 있던 첫 줄에 반듯한 글씨가 새로 채워져 있었다. 내 이름이었다."}, {"s": null, "t": "여울이 숨을 한 번 고르고 노래를 불렀다. 첫 소절에서 여울은 내 이름을 길게 불렀다. 가락 끝이 배웅 노래처럼 뚝 끊기지 않고 등불 쪽으로 천천히 올라갔다."}, {"s": "q:g_yeoul", "t": "「{이름}, 검은 물 건너온 발에 재가 묻었네. 털지 말고 들어오게, 문패 아래로.」"}, {"s": null, "t": "노래가 끝나자 어귀 앞이 조용해졌다. 솔래가 소매로 눈가를 훔쳤다. 사람들 뒤에서 누군가 가락을 따라 낮게 흥얼거렸다."}, {"s": null, "t": "묵호가 지팡이로 땅을 한 번 콩 짚었다. 노인은 고개를 한 번 끄덕이고 집 쪽으로 돌아섰다. 굽은 등이 등불 밖으로 천천히 사라졌다."}, {"s": null, "t": "여울이 종이를 접어 품에 넣었다. 나를 보는 여울의 눈이 등불에 젖어 반짝였다. 손목의 비늘을 문지르지 않았다."}, {"s": null, "t": "나는 왜 첫 줄에 내 이름을 넣었느냐고 물었다. 여울이 등 아래 쇠패를 손바닥으로 덮었다."}, {"s": "q:g_yeoul", "t": "섬은 배웅만 하던 데야. 나도 그랬어. 바깥에선 보내는 쪽, 섬에 와서는 배웅하는 쪽."}, {"s": "q:g_yeoul", "t": "근데 너는 왔잖아. 봉연을 건너서, 또 오고, 또 오고. 말뚝 앞에 배를 대고 기다리면 늘 네가 왔어."}, {"s": "q:g_yeoul", "t": "배웅만 하던 섬에서, 내가 노래로 처음 맞이한 사람이니까. 그래서 첫 줄이야."}, {"s": null, "t": "여울이 쇠패에서 손을 떼고 한 걸음 물러섰다. 등불 아래서 쇠패 글자가 또렷하게 빛났다."}, {"s": "q:g_yeoul", "t": "이건 안 번져. 쇠에 팠으니까. 나도 안 잊어. …어서 와, {이름}."}]'::jsonb, '{"xp": 2760, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2, "hf_rg_yeoul_lamp": 1}, "title": "rg_yeoul"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_wolha_1', 'side', '연담·월하', '먹물 녹이는 약', '묵창 나루에서 「범인」이라 부르던 흑련 거둠꾼 월하가 십삼문 암시장에서 조사원을 붙든다. 흑련 장부고 옛 장부가 먹이 엉겨 넘어가지 않는다며 청정수를 주문하고, 흩어 버린 먹귀 값을 들먹이며 값을 깎는다. 끝내 한 닢 모자라게 셈하고 「앞으로도 부탁해도 돼요?」 한다.', 'hidden_bazaar', 40, '{mkq_1}'::text[], null, 1610, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_wolha_1';
delete from public.world_quest_steps where quest_id = 'rg_wolha_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_1', 1, '범인', '범인', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "십삼문 암시장은 해가 져야 문을 열었다. 열세 개의 문마다 등이 걸렸고, 등 아래로 이름이 붙지 않은 물건들이 오갔다. 흥정하는 목소리는 모두 낮았다. 돌 틈에 고인 물이 등불을 받아 기름처럼 일렁였고, 어느 문 안에선가 향 사르는 냄새가 났다."}, {"s": null, "t": "일곱째 문 앞 좌판에 사내 하나가 다리를 꼬고 걸터앉아 있었다. 검은 도포에 연꽃 매듭을 달았고, 손가락 사이에서 엽전 한 닢이 쉬지 않고 굴렀다."}, {"s": null, "t": "사내는 나를 보자 엽전을 멈추고 활짝 웃었다. 묵창 나루 주막에서 본 그 얼굴이었다."}, {"s": "q:mk_wolha", "t": "어라, 범인이다. 우리 먹귀 흩어 버린 그 조사원 맞죠?"}, {"s": "q:mk_wolha", "t": "그 값 아직 못 받았는데. 이렇게 제 발로 와 주시네요."}, {"s": null, "t": "나는 값을 치르러 온 게 아니라 지나가던 길이라고 했다. 월하가 좌판 위의 낡은 장부 한 권을 손바닥으로 툭 쳤다."}, {"s": "q:mk_wolha", "t": "지나가는 길이면 잘됐네요. 이거 좀 봐요."}, {"s": null, "t": "월하가 장부를 펼치려 했지만 장이 넘어가지 않았다. 장과 장 사이가 검게 엉겨 한 덩어리로 붙어 있었다. 장 틈에서 눅눅한 곰팡내와 묵은 먹 냄새가 훅 올라왔다."}, {"s": "q:mk_wolha", "t": "흑련 장부고에서 꺼내 온 옛 장부예요. 오래 묵은 먹이 습기를 먹으면 이렇게 엉겨요. 칼로 떼면 글자가 같이 찢어지고요."}, {"s": "q:mk_wolha", "t": "여기 적힌 건 다 맡아 둔 이름이에요. 찢으면 그 이름은 영영 못 읽어요. 내 밥줄이 찢어지는 거고, 맡긴 사람한테도 면목이 없죠."}, {"s": null, "t": "월하는 그렇게 말하며 엽전을 한 번 튕겼다. 받아 쥔 손으로 장부 귀퉁이를 조심스럽게 쓸었다."}, {"s": "q:mk_wolha", "t": "청정수에 불리면 먹이 풀려요. 글자는 안 다치고 장만 떨어지죠. 연금 하는 사람이 귀해서 그렇지."}, {"s": null, "t": "월하의 눈이 내 허리춤 도구 주머니에 가서 멈췄다."}, {"s": "q:mk_wolha", "t": "조사원, 약을 좀 지을 줄 알죠? 청정수 두 병만. 값은 시세에서… 그 먹귀 값을 빼면, 어디 보자."}, {"s": null, "t": "월하가 손가락을 꼽으며 셈을 하다가 멈췄다."}, {"s": "q:mk_wolha", "t": "어라, 이상하다. 셈해 보니까 조사원이 나한테 줘야 하네? 그건 봐줄게요. 시세 반값으로 하죠, 뭐."}, {"s": null, "t": "나는 반값은 너무하다고 했다. 월하가 엽전을 튕기며 웃었다."}, {"s": "q:mk_wolha", "t": "그럼 반에 조금 더. 흥정은 물건을 받고 마저 하고요. 수향 갈대는 연등 하수도 물가에 흔해요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_1', 2, '마저 하는 흥정', '연등 하수도에서 수향 갈대을(를) 모은다, 청정수을(를) 만든다, 청정수을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["lotus_sewer"], "n": 4}, {"t": "craft", "items": ["purify_water"], "n": 2}], "give": {"purify_water": 2}}'::jsonb, '[{"s": null, "t": "청정수 두 병을 좌판에 올려놓자 월하가 병 하나를 집어 등불에 비춰 보았다. 맑은 물빛이 월하의 손가락 사이로 흔들렸다."}, {"s": "q:mk_wolha", "t": "오, 맑네요. 이 정도면 제값을 쳐 줘야겠는데. 아까 반에 조금 더라고 했죠? 그 조금을 얼마로 할까."}, {"s": null, "t": "나는 시세대로 달라고 했다. 월하가 병을 내려놓고 턱을 괴었다."}, {"s": "q:mk_wolha", "t": "시세대로 주면 내 체면이 안 서요. 십삼문에서는 깎아야 장사예요. 안 깎으면 무슨 꿍꿍이가 있나 의심받고."}, {"s": null, "t": "월하가 좌판 너머 골목을 턱으로 가리켰다. 등 아래서 흥정하던 사람들이 이쪽을 힐끔거렸다."}, {"s": "q:mk_wolha", "t": "봐요, 벌써 저래요. 내가 제값을 주면 저 사람들 셈이 다 틀어져요. 내일부터 다들 나한테 제값을 달라고 할걸요."}, {"s": null, "t": "월하가 손으로 입을 가리고 목소리를 낮췄다."}, {"s": "q:mk_wolha", "t": "그러니까 조사원이 깎이는 척을 좀 해 줘요. 체면값이에요."}, {"s": null, "t": "월하는 손가락으로 좌판을 몇 번 두드리다가 엽전 꾸러미에서 몇 닢을 덜어 냈다. 시세보다 조금 모자란 값이었다."}, {"s": null, "t": "나는 깎이는 척은 못 하지만 깎인 값은 받겠다고 했다. 월하가 큰 소리로 혀를 찼다. 골목 사람들더러 들으라는 소리였다."}, {"s": "q:mk_wolha", "t": "이만큼. 그 대신 덤으로 구경을 시켜 줄게요. 이게 제대로 듣는지 봐야 나도 셈을 끝내죠."}, {"s": null, "t": "월하가 엉긴 장부를 옆구리에 끼고 일어섰다."}, {"s": "q:mk_wolha", "t": "장부고요. 흑련 사람 아니면 들어가기 힘든 데예요. 조사원이 지은 약이 듣는 걸 조사원 눈으로 보는 것도 재밌잖아요."}, {"s": "q:mk_wolha", "t": "약병은 조사원이 들어요. 내가 들었다가 떨어뜨리면 또 내가 손해니까. 장부고 서가 앞에서 넘겨줘요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_1', 3, '떨어진 장', '흑련 장부고을(를) 살핀다, 청정수을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "search", "r": ["ledger_cellar"], "n": 2}], "give": {"purify_water": 2}}'::jsonb, '[{"s": null, "t": "흑련 장부고 깊숙한 서가 아래에서 월하가 엉긴 장부를 펼쳐 놓았다. 장부고 안은 바깥보다 한결 썰렁했고, 발소리가 서가 사이로 먹먹하게 빨려 들어갔다. 내가 청정수를 장 사이에 조금씩 흘려 넣었다. 검게 엉긴 먹이 물을 머금고 천천히 풀렸다."}, {"s": null, "t": "월하가 얇은 대나무 칼로 장 사이를 살살 갈랐다. 장 하나가 소리 없이 떨어졌다. 그 아래 칸칸이 적힌 이름들이 하나도 찢어지지 않고 드러났다."}, {"s": "q:mk_wolha", "t": "…됐다."}, {"s": null, "t": "월하는 그 한마디를 하고 한동안 장을 들여다보았다. 손가락 끝으로 이름 몇 개를 짚어 내려가다가 짚던 손을 거뒀다."}, {"s": null, "t": "나는 아는 이름이냐고 물었다. 월하가 장부를 덮으며 웃었다."}, {"s": "q:mk_wolha", "t": "맡은 이름을 다 알면 장사를 못 해요. 모르는 척하는 게 일이에요."}, {"s": null, "t": "십삼문으로 돌아오니 밤 장이 파하고 있었다. 좌판 덮개를 접는 펄럭임 사이로 마지막 흥정 소리가 드문드문 들렸다. 월하가 좌판에 걸터앉아 아까 덜어 낸 엽전을 내 손에 올려놓았다. 시세에서 딱 한 닢이 모자랐다."}, {"s": null, "t": "나는 한 닢이 모자라다고 했다. 월하가 시치미를 떼고 엽전을 굴렸다."}, {"s": "q:mk_wolha", "t": "그 한 닢이 흥정이에요. 그거 없으면 우리 사이가 너무 맑아지잖아요. 청정수처럼."}, {"s": null, "t": "월하가 엽전을 튕겨 받아 쥐고 나를 보았다. 늘 눈만 웃던 얼굴이 이번에는 입도 같이 웃고 있었다."}, {"s": "q:mk_wolha", "t": "장부고에 엉긴 장부가 아직 산더미예요. 철마다 습기가 들어서 해마다 엉기고요."}, {"s": "q:mk_wolha", "t": "앞으로도 부탁해도 돼요, 조사원? 청정수든 뭐든. 값은 늘 한 닢씩 모자라게 쳐 줄게요."}, {"s": null, "t": "나는 한 닢이 모자라도 그러겠다고 했다. 월하가 휘파람을 불며 좌판의 등을 껐다."}, {"s": null, "t": "꺼진 등 아래서 월하가 엽전을 한 번 튕겼다. 떨어지는 엽전을 받아 쥐고 손바닥을 펴 보지도 않았다."}, {"s": "q:mk_wolha", "t": "그럼 우리, 단골 사이네요. 내가 남의 단골이 될 줄은 몰랐는데."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_wolha_2', 'side', '연담·월하', '엽전 내기', '영유리 값을 두고 월하가 엽전 내기를 건다. 월하는 일부러 지고, 조사원은 그 손놀림을 알아챈다. 「…눈치 빠른 손님은 장사꾼한테 손해예요.」 월하가 처음으로 값을 깎지 않고, 조사원이 돌려준 귀퉁이 깨진 내기 엽전을 따로 맡아 둔다.', 'hidden_bazaar', 40, '{rg_wolha_1}'::text[], null, 1611, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "wolha", "stage": 2}'::jsonb where quest_id = 'rg_wolha_2';
delete from public.world_quest_steps where quest_id = 'rg_wolha_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_2', 1, '글자를 비추는 유리', '글자를 비추는 유리', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "십삼문 일곱째 문 좌판 위에 장부 여러 권이 펼쳐져 마르고 있었다. 장마다 떨어진 자리가 매끈했다. 먹물 마르는 시큼한 냄새가 좌판 위를 떠돌았다."}, {"s": "q:mk_wolha", "t": "왔어요, 조사원? 지난번 청정수로 장부를 쉰 장 넘게 떼어 냈어요. 장부고 붓쟁이들이 이제 내 얼굴만 보면 약이 어디서 났느냐고 물어요."}, {"s": "q:mk_wolha", "t": "안 알려 줬어요. 좋은 거래처는 숨겨 둬야 장사죠."}, {"s": null, "t": "좌판 앞을 지나던 흑련 서리 하나가 월하에게 꾸벅 인사했다. 월하는 턱짓만 하고 나를 보았다."}, {"s": null, "t": "월하가 마른 장 하나를 들어 등불에 비췄다. 글자 몇 개가 먹빛이 바래 흐릿했다."}, {"s": "q:mk_wolha", "t": "떼어 놓고 보니 이번엔 글자가 흐려서 안 읽혀요. 영유리를 대고 비추면 바랜 먹이 도로 짙어 보이거든요."}, {"s": null, "t": "내가 미심쩍은 얼굴을 하자 월하가 엽전을 굴리던 손을 멈추고 손가락으로 동그라미를 만들어 눈에 댔다."}, {"s": "q:mk_wolha", "t": "이렇게요. 유리 알 하나를 장 위에 대면 먹이 유리 안에서 한 번 더 비쳐요. 바랜 획도 두 겹이 되니까 짙어 보이죠. 장부고에서 옛날부터 쓰던 수예요."}, {"s": "q:mk_wolha", "t": "장부고에 있던 영유리는 오래돼서 다 금이 갔어요. 금 간 유리로 보면 글자도 금이 가 보여요. 남의 이름을 금 간 채로 읽을 수는 없잖아요."}, {"s": null, "t": "월하는 그렇게 말하고 바랜 장을 조심스럽게 기름종이 위에 내려놓았다. 장사꾼의 손이 아니라 서리의 손처럼 반듯한 손길이었다."}, {"s": "q:mk_wolha", "t": "오늘 주문은 영유리 둘. 숯은 옛 순라청 담 밑에서 줍는다더라고요. 순라꾼 넋이 돌아다니니 조심하고."}, {"s": null, "t": "나는 값을 물었다. 월하가 엽전을 튕겨 받아 쥐고 눈을 가늘게 떴다."}, {"s": "q:mk_wolha", "t": "그건 물건을 보고 정해요. 지난번엔 한 닢도 안 깎였으니까, 이번엔… 재미있게 정하죠."}, {"s": null, "t": "월하는 그 말을 하며 엽전 꾸러미를 손바닥으로 톡톡 두드렸다. 무슨 꿍꿍이인지 알 수 없는 얼굴이었다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_2', 2, '앞면이면', '옛 순라청에서 정련 숯을(를) 모은다, 영유리을(를) 만든다, 영유리을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "gather", "items": ["charcoal"], "r": ["patrol_office"], "n": 4}, {"t": "craft", "items": ["spirit_glass"], "n": 2}], "give": {"spirit_glass": 2}}'::jsonb, '[{"s": null, "t": "영유리 두 알을 좌판에 내려놓자 월하가 하나를 집어 바랜 장 위에 댔다. 유리 아래에서 흐릿하던 글자가 또렷하게 떠올랐다."}, {"s": "q:mk_wolha", "t": "오, 읽힌다! …이건 비싸게 쳐 줘야겠네. 근데 비싸게 쳐 주긴 싫고."}, {"s": null, "t": "월하는 유리를 내려놓고 엽전 꾸러미를 끌렀다. 꾸러미에서 한 닢을 집어 들었다. 늘 손가락 사이에서 굴리던 엽전이 아니라, 귀퉁이 하나가 떨어져 나간 엽전이었다."}, {"s": "q:mk_wolha", "t": "이건 귀퉁이가 깨져서 아무도 안 받는 놈이에요. 내기할 때만 쓰죠. 앞면이면 내 값, 뒷면이면 조사원 값. 어때요?"}, {"s": null, "t": "나는 그러자고 했다. 월하가 엽전을 엄지로 튕겼다. 엽전이 등불 아래서 핑그르르 돌며 솟았다."}, {"s": null, "t": "월하가 떨어지는 엽전을 손등으로 받아 다른 손으로 덮었다. 덮은 손을 떼기 직전, 월하의 손가락이 아주 조금 움직였다. 등불 그늘 속이라 웬만해서는 못 봤을 움직임이었다."}, {"s": null, "t": "손을 떼자 엽전은 뒷면이었다."}, {"s": "q:mk_wolha", "t": "아이고, 졌네! 조사원 값으로 드려야겠다."}, {"s": null, "t": "월하는 아쉬운 척 혀를 차며 시세대로 엽전을 세어 놓았다. 귀퉁이가 깨진 엽전도 그 위에 얹었다."}, {"s": "q:mk_wolha", "t": "내기 엽전은 이긴 사람이 가져가요. 그래야 다음 내기를 또 하죠."}, {"s": null, "t": "나는 엽전 더미를 내려다보았다. 월하는 그사이 콧노래를 흥얼거렸다."}, {"s": null, "t": "나는 귀퉁이가 깨진 엽전을 집어 들었다. 손에 쥐니 뒷면 쪽 가장자리가 손톱만큼 닳아 있었다. 손가락으로 뒤집기 좋게 닳은 자리였다."}, {"s": null, "t": "월하는 내 손을 보지 않았다. 대신 영유리 두 알을 보자기에 싸며 일어섰다."}, {"s": "q:mk_wolha", "t": "하나는 내가 쓰고, 하나는 등잔골 장물 장수한테 넘기기로 했어요. 뒷골목을 지나야 하는데 거기 거울귀 놈들은 반짝이는 거라면 사족을 못 써요. 같이 가 줄래요? 유리는 조사원이 들고 가서 넘겨줘요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_2', 3, '눈치 빠른 손님', '등잔골 뒷골목의 요괴를 물리친다, 영유리을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "win", "r": ["lamp_alley"], "n": 6}], "give": {"spirit_glass": 2}}'::jsonb, '[{"s": null, "t": "등잔골 뒷골목은 처마가 낮아 벽마다 그을음이 검게 앉아 있었다. 깨진 거울 조각이 발밑에서 바삭바삭 밟혔다. 거울귀들이 흩어지고 나서야 장물 장수 가게 문이 열렸다. 월하는 유리 한 알을 넘기고 받은 엽전을 세지도 않고 품에 넣었다."}, {"s": null, "t": "십삼문으로 돌아오는 골목에서 나는 걸음을 멈추고 귀퉁이가 깨진 엽전을 월하에게 내밀었다."}, {"s": null, "t": "나는 아까 일부러 진 것 아니냐고 물었다. 엽전 뒷면 가장자리가 손가락으로 뒤집기 좋게 닳아 있더라고 덧붙였다."}, {"s": null, "t": "월하는 엽전을 받지 않고 나를 보았다. 손가락 사이를 구르던 제 엽전이 뚝 멈췄다."}, {"s": "q:mk_wolha", "t": "…조사원."}, {"s": null, "t": "월하는 그 한마디를 하고 한동안 아무 말도 하지 않았다. 골목 끝 등불이 흔들릴 때마다 월하의 얼굴이 밝아졌다 어두워졌다."}, {"s": "q:mk_wolha", "t": "눈치 빠른 손님은 장사꾼한테 손해예요. 알아요?"}, {"s": null, "t": "나는 손해를 보라고 한 말은 아니라고 했다. 일부러 져 줄 거면 그냥 제값을 주면 될 일이라고 했다."}, {"s": "q:mk_wolha", "t": "그게 안 돼서 엽전을 튕기는 거예요. 제값을 주면서 생색내는 건 내 성미에 안 맞거든요."}, {"s": null, "t": "월하가 엽전 꾸러미를 다시 끌렀다. 이번에는 엽전을 하나씩 세어 내 손에 올려놓았다. 시세에서 한 닢도 모자라지 않았다."}, {"s": "q:mk_wolha", "t": "이번엔 안 깎아요. 내기도 없고요. …골목 사람들이 들으면 큰일 나겠네."}, {"s": null, "t": "나는 귀퉁이가 깨진 엽전을 다시 내밀었다. 그 엽전은 진 사람 것이라고 했다. 월하가 손바닥 위 엽전을 내려다보다가 받아 쥐었다."}, {"s": "q:mk_wolha", "t": "진 사람 거라. …그럼 내가 맡아 둘게요. 언젠가 값을 매길 일이 생기면 그때 쓰죠."}, {"s": null, "t": "월하는 귀퉁이가 깨진 엽전을 도포 안쪽 주머니에 따로 넣었다. 늘 굴리던 엽전과 섞이지 않게 넣는 손길이었다."}, {"s": "q:mk_wolha", "t": "오늘은 셈이 딱 맞았네요. 이상하다, 속이 편하네."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_wolha_3', 'side', '연담·월하', '뒷골목 술상', '월하가 처음으로 남에게 술을 산다. 해장용 영초 차를 주문하고, 안주가 없어 둘이 구룡 폐수로에서 생선을 낚는다. 처마 밑 술상에서 「조사원 이름은 얼마 쳐 줄까요?」 하고 농담하다가, 값이 나오지 않는다며 웃음을 거둔다 — 제 이름도 한 번도 값을 매겨 본 적이 없다고.', 'hidden_bazaar', 40, '{rg_wolha_2}'::text[], null, 1612, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "wolha", "stage": 3}'::jsonb where quest_id = 'rg_wolha_3';
delete from public.world_quest_steps where quest_id = 'rg_wolha_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_3', 1, '해장 차', '해장 차', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "그날 밤 십삼문 일곱째 문 좌판에는 장부 대신 술병 하나와 잔 두 개가 놓여 있었다. 월하가 좌판에 턱을 괴고 엽전을 굴리고 있었다. 밤 장 흥정 소리 너머로 술 익는 냄새가 들척지근하게 풍겼다."}, {"s": "q:mk_wolha", "t": "앉아요, 앉아. 장부 얘기는 오늘 안 해요."}, {"s": "q:mk_wolha", "t": "오늘은 내가 한잔 살게요. 술을 산다고 했더니 다들 무슨 꿍꿍이냐고 하더라고요."}, {"s": null, "t": "나는 술병과 월하를 번갈아 보았다. 월하가 술병을 들어 흔들었다. 술이 찰랑찰랑 흔들렸다."}, {"s": "q:mk_wolha", "t": "꿍꿍이 없어요. 진짜로요. …그래서 더 의심받는 거지만."}, {"s": null, "t": "나는 그럼 왜 사느냐고 물었다. 월하가 술병 마개를 손가락으로 돌리며 생각에 잠겼다."}, {"s": "q:mk_wolha", "t": "글쎄요. 지난번에 조사원이 한 닢도 안 깎인 값을 받아 갔잖아요. 그 뒤로 내 셈이 영 안 맞아요. 받은 게 있으면 줘야 셈이 맞는데, 줄 게 생각이 안 나서."}, {"s": "q:mk_wolha", "t": "그래서 술로 했어요. 술은 같이 마시면 누가 누구한테 줬는지 흐려지거든요. 셈하기 싫을 때 딱이에요."}, {"s": null, "t": "월하는 그렇게 말하고 잔 두 개를 나란히 놓았다. 잔 둘을 가지런히 놓는 손이 어색했다."}, {"s": "q:mk_wolha", "t": "대신 주문이 하나 있어요. 이 술이 독해서 다음 날 머리가 깨져요. 영초 차 두 잔만 지어 와요. 해장용으로."}, {"s": null, "t": "독한 줄 알면서 그 술을 산 까닭이 궁금했다. 월하가 내 얼굴을 읽었는지 술병을 등불에 비춰 보았다."}, {"s": "q:mk_wolha", "t": "십삼문에서 제일 비싼 거라서요. 비싼 걸 사 줘야 대접한 티가 나죠."}, {"s": null, "t": "월하가 술병을 좌판 아래 그늘에 내려놓았다. 누가 집어 갈까 봐 발끝으로 한 번 더 밀어 넣었다."}, {"s": "q:mk_wolha", "t": "야령초랑 수향 갈대는 연등 하수도 물가에 다 있어요. 차를 지어 오면 뒷골목 처마 밑에 술상을 차려 놓고 기다릴게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_3', 2, '안주', '연등 하수도에서 야령초을(를) 모은다, 영초 차을(를) 만든다, 영초 차을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "gather", "items": ["herb"], "r": ["lotus_sewer"], "n": 4}, {"t": "craft", "items": ["spirit_tea"], "n": 2}], "give": {"spirit_tea": 2}}'::jsonb, '[{"s": null, "t": "영초 차 두 잔을 들고 가니 월하가 십삼문 뒷골목 처마 밑에 술상을 차려 놓고 있었다. 낡은 소반 위에 술병과 잔 두 개, 빈 접시 하나가 놓여 있었다. 낮 동안 데워진 돌담이 처마 밑에 아직 온기를 내뿜고 있었다."}, {"s": "q:mk_wolha", "t": "왔네요. 차는 거기 두고 앉아요. 아, 근데 안주가 없네."}, {"s": null, "t": "월하가 빈 접시를 손가락으로 톡 쳤다."}, {"s": "q:mk_wolha", "t": "술상을 차릴 줄 몰라서 안주를 잊었어요. 남한테 술을 사 본 적이 없거든요. 나한테 사 주는 사람도 없고."}, {"s": null, "t": "월하는 그렇게 말하고 겸연쩍게 웃었다. 눈만이 아니라 입도 함께 웃는 웃음이었다."}, {"s": null, "t": "나는 그럼 지금까지 술은 누구랑 마셨느냐고 물었다. 월하가 잔 하나를 손가락으로 톡 쳤다."}, {"s": "q:mk_wolha", "t": "혼자요. 장부고 서가에 기대서. 서가가 대작해 줘요. 말은 없는데 잔은 안 뺏어요."}, {"s": null, "t": "월하는 농담처럼 말하고 소반 위 잔 두 개를 내려다보았다. 잔 둘이 나란히 놓인 소반이 월하에게는 낯선 듯했다."}, {"s": null, "t": "나는 구룡 폐수로에 가면 생선 한두 마리는 낚을 수 있다고 했다. 월하가 손뼉을 쳤다."}, {"s": "q:mk_wolha", "t": "그거다! 나도 같이 갈래요. 낚시는 못 해도 구경은 잘해요. 엽전을 걸고 누가 먼저 낚나 내기해도 되고."}, {"s": null, "t": "나는 내기는 안 하겠다고 했다. 월하가 입을 삐죽였다."}, {"s": "q:mk_wolha", "t": "한 번 들키더니 깐깐해졌네. 알았어요, 알았어. 그럼 그냥 구경만. 차는 술상에 두고 가요. 내 거니까."}, {"s": null, "t": "월하가 소반을 처마 안쪽으로 밀어 넣고 도포 자락을 털었다."}, {"s": "q:mk_wolha", "t": "술상은 도망 안 가요. 생선은 도망가니까 먼저 잡으러 가요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_3', 3, '값', '구룡 폐수로에서 낚시를 한다, 영초 차을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "fish", "r": ["old_canal"], "n": 2}], "give": {"spirit_tea": 2}}'::jsonb, '[{"s": null, "t": "폐수로에서 낚은 생선 두 마리를 숯불에 구웠다. 껍질이 타닥타닥 터지며 고소한 기름 냄새가 처마 밑에 가득 찼다. 나는 노릇해진 생선을 접시에 올렸다. 월하는 낚시하는 내내 한 번도 쉬지 않고 떠들었고, 고기가 물 때마다 내 어깨를 툭툭 쳤다."}, {"s": null, "t": "처마 밑 술상에 마주 앉자 월하가 내 잔에 술을 따랐다. 제 잔에도 따르고 잔을 들어 보였다."}, {"s": "q:mk_wolha", "t": "자, 한 닢 모자란 거래를 위하여."}, {"s": null, "t": "술이 몇 순배 돌자 월하의 볼이 발그레해졌다. 월하가 잔을 손가락으로 빙빙 돌리며 나를 보았다."}, {"s": "q:mk_wolha", "t": "조사원, 그거 알아요? 거둠꾼은 이름을 보면 값부터 매겨요. 버릇이에요. 이 이름은 얼마, 저 이름은 얼마."}, {"s": "q:mk_wolha", "t": "조사원 이름은 얼마 쳐 줄까요? 먹귀를 흩어 버리는 이름이니까 꽤 비싸겠는데. 장부 한 권 통째로? 아니, 두 권?"}, {"s": null, "t": "월하는 웃으며 손가락을 꼽았다. 셋째 손가락을 꼽다가 손을 멈췄다. 웃음이 천천히 걷혔다."}, {"s": null, "t": "월하가 잔을 내려놓았다."}, {"s": "q:mk_wolha", "t": "…어, 이상하네. 값이 안 나와요. 셈이 안 돼요."}, {"s": "q:mk_wolha", "t": "이 노릇을 하면서 수천 개를 매겨 왔는데. 값이 안 나오는 이름은 처음이에요."}, {"s": null, "t": "월하는 잔에 남은 술을 들여다보았다. 처마 끝에서 등불이 흔들렸다."}, {"s": "q:mk_wolha", "t": "생각해 보니 하나 더 있네요. 내 이름. 그것도 한 번도 값을 매겨 본 적이 없어요. 매기기 싫어서 안 매긴 건지, 안 나와서 못 매긴 건지는 모르겠지만."}, {"s": null, "t": "월하는 그 말을 하고 나서 스스로 놀란 얼굴로 입을 다물었다. 술병을 들어 제 잔을 채웠다."}, {"s": "q:mk_wolha", "t": "취했네. 이건 술값에 쳐요. 들은 거 다 잊어요, 조사원."}, {"s": null, "t": "나는 잊겠다고 하지 않았다. 대신 영초 차 한 잔을 월하 앞으로 밀어 주었다."}, {"s": null, "t": "월하가 찻잔을 내려다보다가 피식 웃었다. 두 손으로 잔을 감싸 쥐고 천천히 마셨다. 찻잔에서 오른 풀 내음이 술 냄새를 조금 밀어냈다."}, {"s": "q:mk_wolha", "t": "…해장은 내일 하는 건데. 성질도 급하셔."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_wolha_4', 'side', '연담·월하', '맡긴 이름', '장마철 장부 곰팡이를 막을 농축 약초액을 주문한 월하와 비 오는 처마 밑에서 밤을 지새운다. 월하가 흑련 장부에 맡겨 둔 제 이름 이야기를 처음 꺼낸다 — 본명은 말하지 않는다. 조사원이 묻지 않자 「…그래서 편해요, 조사원은.」', 'hidden_bazaar', 40, '{rg_wolha_3}'::text[], null, 1613, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "wolha", "stage": 4}'::jsonb where quest_id = 'rg_wolha_4';
delete from public.world_quest_steps where quest_id = 'rg_wolha_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_4', 1, '장마철', '장마철', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "장마가 들어 십삼문 암시장 골목마다 빗물이 고였다. 좌판들은 처마 안으로 바짝 당겨 앉아 있었다. 빗줄기가 기와를 두드리는 소리가 골목을 메웠고, 젖은 흙과 하수 냄새가 눅진하게 올라왔다."}, {"s": null, "t": "월하는 일곱째 문 처마 밑에서 장부 더미에 기름종이를 덮고 있었다. 도포 자락이 반쯤 젖어 있었다."}, {"s": "q:mk_wolha", "t": "거기 서 있지 말고 들어와요. 처마 밖은 물바다예요."}, {"s": "q:mk_wolha", "t": "이 비에 내 밥줄이 다 상하게 생겼어요. 장마철엔 곰팡이가 슬거든요. 곰팡이가 먹을 갉아 먹어요."}, {"s": null, "t": "월하가 기름종이를 들춰 장부 귀퉁이를 보여 주었다. 희끗희끗한 곰팡이가 먹 글자 둘레에 번져 있었다. 코끝에 퀴퀴한 냄새가 닿았다."}, {"s": null, "t": "월하가 기름종이를 도로 덮었다. 덮는 손끝이 곰팡이 슨 귀퉁이를 피해 갔다."}, {"s": "q:mk_wolha", "t": "먹이 먹히면 이름이 비어요. 비면 맡긴 사람이 와도 돌려줄 게 없죠. 맡은 이름을 잃어버리는 거예요. 장사꾼한테 그보다 큰 창피는 없어요."}, {"s": null, "t": "월하는 말끝에 웃지 않았다. 처마 끝에서 떨어진 빗방울이 장부 더미를 덮은 기름종이 위에 툭툭 튀었다."}, {"s": null, "t": "처마 밑으로 흑련 서리 하나가 젖은 장부를 안고 뛰어들었다. 서리는 월하에게 고개를 꾸벅하고 장부를 기름종이 더미 위에 얹은 뒤 다시 빗속으로 뛰어나갔다."}, {"s": "q:mk_wolha", "t": "저 사람도 아침부터 저래요. 장부고 지붕이 새서 젖은 걸 다 이리로 날라요. 내 처마가 제일 넓거든요."}, {"s": "q:mk_wolha", "t": "농축 약초액을 묽게 타서 장부고 바닥에 뿌리면 곰팡이가 안 슬어요. 두 병이면 이번 장마는 나요."}, {"s": null, "t": "나는 처마 밖 하늘을 올려다보았다. 월하가 손바닥을 처마 밖으로 내밀었다. 빗방울이 손바닥에 후두둑 떨어졌다."}, {"s": "q:mk_wolha", "t": "열흘은 더 와요. 떨어지는 빗방울이 아직 무겁거든요."}, {"s": "q:mk_wolha", "t": "야령초는 구룡 폐수로 둑에 많아요. 비를 맞으면서 캐야 하니까… 값은 이번엔 안 깎을게요. 빗값으로."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_4', 2, '처마 밑', '구룡 폐수로에서 야령초을(를) 모은다, 농축 약초액을(를) 만든다, 농축 약초액을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "gather", "items": ["herb"], "r": ["old_canal"], "n": 8}, {"t": "craft", "items": ["herbal_extract"], "n": 2}], "give": {"herbal_extract": 2}}'::jsonb, '[{"s": null, "t": "농축 약초액 두 병을 품에 안고 돌아오니 비가 더 굵어져 있었다. 후두둑 빗줄기가 처마를 두드렸다."}, {"s": null, "t": "월하가 처마 밑에서 손짓했다. 나는 처마 안으로 뛰어들었다. 젖은 옷자락이 등에 쩍 들러붙어 으슬으슬 한기가 돌았다. 월하가 내 젖은 어깨를 보았다."}, {"s": "q:mk_wolha", "t": "다 젖었네. 우산이라도 빌려줄걸. 나는 우산을 안 써서 생각을 못 했어요."}, {"s": null, "t": "나는 왜 우산을 안 쓰느냐고 물었다. 월하가 기름종이 한 장을 펴 들며 대답했다."}, {"s": "q:mk_wolha", "t": "우산을 쓰면 한 손이 묶이잖아요. 거둠꾼은 늘 두 손이 비어 있어야 해요. 하나는 엽전을 굴리고, 하나는 남의 이름을 받아 들고."}, {"s": null, "t": "월하가 젖은 도포 자락을 들어 보였다."}, {"s": "q:mk_wolha", "t": "그래서 비 오는 날엔 이렇게 젖죠, 뭐."}, {"s": null, "t": "월하가 그 말끝에 재채기를 했다. 나는 품에서 마른 수건을 꺼내 건넸다."}, {"s": null, "t": "월하는 수건을 받아 들고 잠깐 내려다보았다. 얼굴을 닦지 않고 젖은 장부 더미를 덮은 기름종이부터 닦았다."}, {"s": "q:mk_wolha", "t": "장부가 먼저예요. 버릇이라. …고마워요. 그다음은 내 얼굴."}, {"s": null, "t": "월하가 처마 끝으로 떨어지는 빗줄기를 올려다보았다. 빗줄기가 굵어 골목 건너편 등불이 흐려 보였다."}, {"s": "q:mk_wolha", "t": "이 비, 금방 안 그쳐요. 약병은 이 기름종이에 싸서 줘요. 장부고까지는 비가 그치면 가요. 젖으면 큰일이니까."}, {"s": null, "t": "월하가 처마 밑 평상 한쪽을 비워 주었다. 나는 그 자리에 앉았다. 월하는 엽전을 굴리지 않고 무릎 위에 손을 얹고 있었다."}, {"s": "q:mk_wolha", "t": "비가 오는 날엔 엽전을 안 굴려요. 젖은 손에서 미끄러지면 골목 물웅덩이로 굴러가니까."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_4', 3, '장부에 맡긴 것', '십삼문 암시장에서 쉰다, 농축 약초액을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "rest", "r": ["hidden_bazaar"], "n": 1}], "give": {"herbal_extract": 2}}'::jsonb, '[{"s": null, "t": "비는 밤이 깊도록 그치지 않았다. 처마 밑 평상에 나란히 앉아 빗소리를 들었다. 골목의 등불이 하나둘 꺼져 갔다. 빗물에 식은 바람이 평상 아래로 스며들어 종아리에 소름이 돋았다."}, {"s": null, "t": "월하가 먼저 입을 열었다. 빗소리에 묻힐 만큼 낮은 목소리였다."}, {"s": "q:mk_wolha", "t": "조사원은 내 이름이 안 궁금해요?"}, {"s": null, "t": "나는 월하라고 불리지 않느냐고 했다. 월하가 피식 웃었다."}, {"s": "q:mk_wolha", "t": "그건 호칭이에요. 흑련 사람은 들어올 때 이름을 회원 장부에 맡겨요. 그러고는 호칭으로 불려요. 나는 월하. 누가 붙였는지도 잊었어요."}, {"s": "q:mk_wolha", "t": "내 이름도 흑련 장부에 맡겨 뒀어요. 거둠꾼이 맡아 둔 남의 이름들하고 똑같이."}, {"s": null, "t": "월하가 처마 끝 빗줄기를 보았다. 손가락 사이에 엽전이 없었다."}, {"s": "q:mk_wolha", "t": "맡기고 나서는 그 이름을 부르는 사람이 거의 없어요. 나도 안 불러요. 가끔 생각은 나요. 그런 이름이 있었다는 것만."}, {"s": null, "t": "월하는 거기서 말을 멈추고 나를 보았다. 무언가를 기다리는 눈이었다."}, {"s": null, "t": "나는 그 이름을 묻지 않았다. 빗소리만 처마를 오래 두드렸다."}, {"s": "q:mk_wolha", "t": "…안 물어보네요."}, {"s": null, "t": "나는 말하고 싶을 때 말하면 된다고 했다. 맡겨 둔 것은 맡긴 사람이 찾아가는 법이라고 덧붙였다."}, {"s": null, "t": "월하가 고개를 숙였다. 젖은 도포 자락을 손가락으로 만지작거렸다. 빗소리가 몇 번 굵어졌다 가늘어진 뒤에야 낮게 웃었다."}, {"s": "q:mk_wolha", "t": "다들 물어봐요. 처음 보는 사람은 꼭 물어요. 본명이 뭐냐고. 그럼 나는 값을 불러요. 그 이름 비싸다고. 그러면 다들 웃고 말죠."}, {"s": "q:mk_wolha", "t": "조사원은 안 물어보니까 값을 부를 데가 없네."}, {"s": null, "t": "비가 조금 가늘어졌다. 월하가 평상에서 일어나 기름종이에 싼 약병을 품에 안았다."}, {"s": "q:mk_wolha", "t": "…그래서 편해요, 조사원은. 장부고에 다녀올게요. 기다리지 말고 자요."}, {"s": null, "t": "월하는 빗속으로 몇 걸음 걸어가다가 돌아섰다. 우산 없이 두 손을 비운 채였다."}, {"s": "q:mk_wolha", "t": "그 이름은 장부에 그냥 둘 거예요. 대신 조사원 앞에서는 앞으로 아무것도 값을 안 부를게요. 그거면 되죠?"}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_wolha_5', 'side', '연담·월하', '부르는 이름', '처음 보여 준 엉긴 장부의 마지막 장을 둘이 장부고에서 떼어 낸다. 헤어지는 골목 끝에서 월하가 내기 엽전에 끈을 꿰어 건네고, 돌아보며 처음으로 조사원의 이름을 부른다. 「이제 「조사원」 말고 이름으로 부를래요. 값을 안 매긴 이름이니까 아무 때나 부를 거예요.」', 'hidden_bazaar', 40, '{rg_wolha_4}'::text[], null, 1614, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "wolha", "stage": 5}'::jsonb where quest_id = 'rg_wolha_5';
delete from public.world_quest_steps where quest_id = 'rg_wolha_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_5', 1, '마지막 엉긴 장', '마지막 엉긴 장', '{"at": ["hidden_bazaar"]}'::jsonb, '[{"s": null, "t": "장마가 걷힌 뒤 십삼문 암시장 골목에 마른 바람이 불었다. 일곱째 문 좌판 위에 장부들이 가지런히 쌓여 있었다. 엉긴 것도, 곰팡이가 슨 것도 없었다. 젖었던 돌담은 다 말라 하얗게 바래 있었다."}, {"s": "q:mk_wolha", "t": "왔네요. 조사원 약으로 장부고가 한 철을 났어요. 청정수, 영유리, 영초 차, 농축 약초액. 장부고 서리들이 조사원이 오는 날을 손꼽아요."}, {"s": null, "t": "월하가 좌판 위 장부 더미에서 한 권을 뽑아 들었다. 표지 귀퉁이가 닳은 낡은 장부였다. 처음 만난 밤 좌판 위에 놓여 있던 바로 그 장부였다."}, {"s": null, "t": "좌판 옆을 지나던 흑련 서리 하나가 그 장부를 보고 고개를 갸웃했다. 월하는 손을 휘휘 저어 서리를 보냈다."}, {"s": "q:mk_wolha", "t": "다들 이 장부는 왜 안 떼냐고 물어요. 아무한테도 대답을 안 했어요."}, {"s": "q:mk_wolha", "t": "엉긴 장부가 딱 한 권 남았어요. 조사원을 붙들고 보여 줬던 그 장부요. 앞장만 떼고 뒷장은 아직 못 뗐어요."}, {"s": null, "t": "나도 그 까닭을 물었다. 월하가 엽전을 굴리며 어깨를 으쓱했다."}, {"s": "q:mk_wolha", "t": "다른 거 떼느라 바빠서요. …는 핑계고. 그거 다 떼면 조사원이 올 일이 없어질까 봐 미뤘어요."}, {"s": null, "t": "월하는 그 말을 웃으며 했다. 엽전이 손가락 사이에서 한 번 미끄러졌다. 월하는 엽전을 얼른 주워 쥐었다."}, {"s": "q:mk_wolha", "t": "농담이에요. 반은. 청정수 두 병만 더요. 이번 걸로 마지막 장까지 다 떼죠."}, {"s": null, "t": "나는 나머지 반은 뭐냐고 물었다. 월하가 엽전을 쥔 손을 펴지도 쥐지도 않은 채 장부 표지만 보았다."}, {"s": "q:mk_wolha", "t": "그건 장을 다 떼고 말할게요. 지금 말하면 값을 부를 것 같아서."}, {"s": null, "t": "월하는 장부를 옆구리에 끼고 일어섰다. 좌판 등잔의 심지를 한 번 돋우고 나를 보았다."}, {"s": "q:mk_wolha", "t": "수향 갈대는 늘 가던 데 있죠? 연등 하수도. 조사원이 다녀오는 동안 여기서 안 졸고 기다릴게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_5', 2, '돌아보는 걸음', '연등 하수도에서 수향 갈대을(를) 모은다, 청정수을(를) 만든다, 청정수을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["lotus_sewer"], "n": 4}, {"t": "craft", "items": ["purify_water"], "n": 2}], "give": {"purify_water": 2}}'::jsonb, '[{"s": null, "t": "청정수 두 병을 내밀자 월하가 병을 받지 않고 엉긴 장부를 옆구리에 끼었다."}, {"s": "q:mk_wolha", "t": "장부고로 가요. 처음처럼. 약병은 조사원이 들고, 서가 앞에서 넘겨줘요."}, {"s": null, "t": "월하가 앞장서 골목을 걸었다. 몇 걸음 가다 돌아서서 내가 따라오는지 보았다. 처음 장부고에 갈 때는 한 번도 돌아보지 않던 사람이었다."}, {"s": null, "t": "세 번째로 눈이 마주쳤을 때 월하가 얼른 앞을 보며 엽전을 튕겼다."}, {"s": "q:mk_wolha", "t": "약병 든 사람이 넘어지면 내 손해니까요."}, {"s": null, "t": "나는 넘어진 적이 한 번도 없다고 했다. 월하가 피식 웃었다."}, {"s": "q:mk_wolha", "t": "알아요. 그러니까 하는 말이에요. 넘어질 일 없는 사람이 따라오는지 자꾸 확인하는 거, 이상하죠."}, {"s": null, "t": "월하는 거기서 말을 끊고 엽전을 굴렸다. 엽전이 구르는 소리가 골목 벽에 부딪쳐 또르르 울렸다."}, {"s": null, "t": "장부고 들머리 계단 앞에서 월하가 걸음을 멈추고 계단 아래 어둠을 내려다보았다. 계단 밑에서 마른 바람이 올라와 목덜미를 쓸었다."}, {"s": "q:mk_wolha", "t": "처음 같이 내려갔을 때, 조사원이 약병을 꼭 두 손으로 들고 갔던 거 기억나요? 흔들릴까 봐. 그거 보고 웃음을 참느라 혼났어요."}, {"s": null, "t": "나는 그때 월하가 한 번도 돌아보지 않았는데 어떻게 봤느냐고 물었다. 월하가 계단을 한 칸 내려서며 어깨너머로 대답했다."}, {"s": "q:mk_wolha", "t": "뒤통수에도 눈이 있거든요. …농담이에요. 서가 유리에 비쳤어요."}, {"s": "q:mk_wolha", "t": "장부를 다 떼고 나면 할 말이 하나 있어요. 그건 장부고 말고, 돌아오는 골목에서 할게요."}, {"s": null, "t": "월하는 그 말을 하고 먼저 계단을 내려갔다. 이번에는 내려가는 동안 두 번 돌아보았다."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_wolha_5', 3, '골목 끝에서', '흑련 장부고을(를) 살핀다, 청정수을(를) 넘긴다', '{"at": ["hidden_bazaar"], "tasks": [{"t": "search", "r": ["ledger_cellar"], "n": 2}], "give": {"purify_water": 2}}'::jsonb, '[{"s": null, "t": "흑련 장부고 서가 아래에서 마지막 장이 소리 없이 떨어졌다. 월하가 대나무 칼을 내려놓고 장부를 덮었다. 장부 표지를 손바닥으로 한 번 쓸었다."}, {"s": "q:mk_wolha", "t": "끝났다. 맨 처음 거가 맨 마지막이네."}, {"s": null, "t": "십삼문으로 돌아오는 골목은 밤 장이 다 파해 조용했다. 등불이 하나 건너 하나 꺼져 있었다. 골목 끝에서 길이 갈렸다. 나는 바깥 길로, 월하는 일곱째 문 쪽으로 가야 했다. 깊은 밤 돌바닥에서 찬 기운이 신발 바닥으로 배어 올라왔다."}, {"s": null, "t": "갈림길에서 월하가 걸음을 멈췄다. 품에서 검은 연꽃 매듭 끈 하나를 꺼냈다. 끈에 엽전 한 닢이 꿰여 있었다. 귀퉁이 하나가 떨어져 나간 엽전이었다."}, {"s": "q:mk_wolha", "t": "그때 내기 엽전이에요. 진 사람 거라고 조사원이 돌려준 거. 맡아 둔다고 했죠."}, {"s": "q:mk_wolha", "t": "값을 매길 일이 생기면 쓴다고 했는데, 안 쓰기로 했어요. 구멍에 끈을 꿰었으니 이제 못 써요. 끈을 꿴 엽전은 돈이 아니라 장신구예요."}, {"s": null, "t": "월하가 끈을 내 손바닥에 올려놓았다. 손바닥 위에서 귀퉁이가 깨진 엽전이 등불을 받아 반짝였다."}, {"s": null, "t": "나는 고맙다고 했다. 월하가 뒤로 두어 걸음 물러났다. 손을 한 번 흔들고 일곱째 문 쪽으로 돌아섰다."}, {"s": null, "t": "월하는 몇 걸음 걷다가 멈췄다. 골목 끝 꺼져 가는 등불 아래서 천천히 돌아보았다."}, {"s": "q:mk_wolha", "t": "{이름}."}, {"s": null, "t": "월하가 내 이름을 불렀다. 엽전을 굴리지도, 웃지도 않은 얼굴이었다. 골목이 조용해서 그 목소리가 오래 남았다."}, {"s": null, "t": "나는 그 자리에 선 채 월하를 보았다. 월하가 그제야 웃었다. 눈도 입도 같이 웃었다."}, {"s": "q:mk_wolha", "t": "놀랐어요? 이제 「조사원」 말고 이름으로 부를래요."}, {"s": "q:mk_wolha", "t": "거둠꾼은 이름을 보면 값부터 매긴다고 했죠. 조사원 이름은 값이 안 나온다고 했고."}, {"s": "q:mk_wolha", "t": "그래서 안 매기기로 했어요. 값을 안 매긴 이름이니까, 아무 때나 부를 거예요. 장사할 때도, 흥정할 때도, 그냥 지나가다가도."}, {"s": null, "t": "월하가 늘 굴리던 제 엽전을 꺼내 튕겼다. 엽전이 등불 아래서 돌다가 월하의 손바닥에 떨어졌다. 월하는 손을 펴 보지도 않고 엽전을 주머니에 넣었다."}, {"s": "q:mk_wolha", "t": "그건 이제 월하가 부르는 이름이에요. 장부에 안 적고, 값도 안 매기고, 내가 부르는 거."}, {"s": "q:mk_wolha", "t": "잘 가요, {이름}. 다음에 또 와요. 한 닢 모자라게 쳐 줄게요."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2, "of_acc_rg_wolha_coin": 1}, "title": "rg_wolha"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_daon_1', 'side', '연담·다온', '꿀물 풀', '짐배가 드는 날이면 다온은 선창 일꾼들에게 꿀물을 타 준다. 꿀이 모자라 단맛을 오래 붙들어 줄 풀이 필요해진 다온이 조사원에게 처음으로 「주문」을 한다. 당번은 늘 맨 나중에 마신다는 다온에게 조사원이 「당번 몫」을 만들어 준다.', 'mukchang_ferry', 40, '{mkq_1}'::text[], null, 1615, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_daon_1';
delete from public.world_quest_steps where quest_id = 'rg_daon_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_1', 1, '선창의 꿀물 사발', '선창의 꿀물 사발', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "묵창 나루 선창에 짐배 한 척이 닿아 있었다. 일꾼들이 소금 자루를 어깨에 메고 출렁이는 널판을 건너 뭍으로 올라왔다. 강물에서 먹빛 물비린내가 올라왔고, 자루에서 흘린 굵은 소금이 널판 위에서 서걱서걱 밟혔다."}, {"s": null, "t": "선창 돌계단 맨 아래 칸에 다온이 쪼그려 앉아 있었다. 무릎 앞에 물동이 하나와 손바닥만 한 꿀단지 하나가 놓여 있었다."}, {"s": null, "t": "다온은 국자로 물을 떠 사발에 부었다. 숟가락 끝으로 꿀을 아주 조금 떠 넣고 휘휘 저었다. 그러고는 사발을 두 손으로 받쳐 들고 일꾼들 사이를 종종걸음으로 뛰어다녔다."}, {"s": "q:mk_daon", "t": "우리 아저씨들, 꿀물이요, 꿀물! 흘리지 말고 마셔요. 사발을 깨지 말고요!"}, {"s": null, "t": "일꾼 하나가 사발을 받아 단숨에 들이켰다. 손등으로 입을 훔친 일꾼은 다온의 머리를 투박하게 한 번 쓰다듬고 다시 짐배 쪽으로 갔다."}, {"s": null, "t": "빈 사발을 받아 들고 돌아서던 다온이 나를 보았다. 눈이 동그래진 다온이 사발을 든 채 계단을 뛰어 올라왔다."}, {"s": "q:mk_daon", "t": "어, {이름} 님! 언제 왔어요? 와, 딱 맞춰 왔네요!"}, {"s": null, "t": "나는 계단에 줄지어 놓인 사발들을 둘러보았다. 다온이 빈 사발을 물동이 옆에 엎어 놓고 어깨를 으쓱했다."}, {"s": "q:mk_daon", "t": "짐배 들어오는 날엔 제가 꿀물 당번이에요. 어른들은 짐을 부리느라 정신없잖아요. 목이 타도 물을 뜰 틈이 없대요."}, {"s": "q:mk_daon", "t": "근데 꿀이 요것밖에 없어요. 묵창댁 아주머니가 국을 끓이고 남은 걸 조금씩 모아 준 거예요."}, {"s": null, "t": "다온이 꿀단지를 기울여 보였다. 단지 바닥에 노란 꿀이 손톱만큼 남아 있었다."}, {"s": "q:mk_daon", "t": "그래서 풀을 넣으려고요. 야령초 잎을 물에 우리면 좀 쌉싸름한데요, 거기다 꿀을 넣으면 단맛이 입에 오래 남아요. 꿀을 반만 넣어도 된다니까요."}, {"s": null, "t": "나는 그 풀을 어디서 구하느냐고 물었다. 다온의 입이 삐죽 나왔다."}, {"s": "q:mk_daon", "t": "빙혼곡 고갯길 바위틈에 잔뜩 있어요. 근데 우리 서리님이 저 혼자서는 빙혼곡에 가지 말래요. 늑대가 나온다고요."}, {"s": "q:mk_daon", "t": "그러니까 {이름} 님이 좀 따다 주세요. 값은 치를게요. 진짜로요!"}, {"s": null, "t": "다온이 허리춤에서 작은 주머니를 꺼내 흔들었다. 엽전 몇 닢이 짤랑거렸다. 나는 웃으며 주머니를 도로 다온의 허리춤에 찔러 주었다."}, {"s": "q:mk_daon", "t": "안 받으면 안 된다니까요! 서리님이 그랬어요, 장부에 적는 건 다 값이 있는 거라고요. 이것도 제 공책에 적을 거예요."}, {"s": null, "t": "짐배에서 일꾼 하나가 다온을 불렀다. 다온은 빈 사발을 집어 들고 계단을 뛰어 내려가다가 나를 돌아보았다."}, {"s": "q:mk_daon", "t": "다섯 줌이요, 다섯 줌! 마지막 짐배가 해 질 녘에 오니까 그 전에 와야 돼요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_1', 2, '반 사발', '빙혼곡에서 야령초을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["herb"], "r": ["frost_valley"], "n": 5}]}'::jsonb, '[{"s": null, "t": "빙혼곡 바위틈에서 딴 야령초를 들고 나루로 돌아오니 짐배는 반쯤 비어 있었다. 다온은 선창 계단에 앉아 빈 사발들을 포개고 있었다. 빙혼곡에서 묻혀 온 냉기가 내 손가락 마디에 아직 얼얼하게 남아 있었다."}, {"s": "q:mk_daon", "t": "왔다! 보여 줘요, 빨리요!"}, {"s": null, "t": "다온이 내 손에서 야령초 묶음을 받아 들고 코를 박았다. 다온은 잎을 하나씩 뜯어 물동이 물에 헹구었다. 줄기는 따로 모아 계단 옆에 놓았다."}, {"s": "q:mk_daon", "t": "줄기는 써서 안 돼요. 잎만 넣는 거예요."}, {"s": null, "t": "다온은 잎을 담은 물동이를 안고 주막 부엌으로 들어갔다. 나도 그 뒤를 따랐다. 부뚜막 한쪽 끝에 작은 솥이 하나 걸려 있었다. 아궁이 열기가 훅 끼쳐 문턱을 넘자마자 얼굴이 달아올랐다."}, {"s": null, "t": "부엌을 맡은 묵창댁이 큰 국솥을 젓다가 우리를 돌아보았다. 묵창댁이 국자로 부뚜막 가장자리를 탁탁 두드렸다. 부뚜막에 숯으로 그은 금이 하나 있었다."}, {"s": "q:sx_mk_jumak", "t": "다온아, 요 쥐방울아, 이 금 넘어오지 마라. 거기까지가 네 솥이야. 조사원도 거기서만 서 있고."}, {"s": null, "t": "다온이 혀를 쏙 내밀고는 나를 돌아보며 부뚜막의 금을 손가락으로 가리켰다."}, {"s": "q:mk_daon", "t": "네에. {이름} 님, 이 금 밟으면 큰일 나요. 아주머니 국자가 엄청 아파요."}, {"s": null, "t": "나는 금 바깥으로 한 발 물러섰다. 다온이 키득 웃으며 작은 솥에 물과 야령초 잎을 부었다."}, {"s": null, "t": "물이 끓자 부엌 가득 쌉싸름한 풀 냄새가 퍼졌다. 다온은 솥을 내려 한 김 식혔다. 그다음 꿀을 숟가락 끝으로 한 번 떠 넣고 휘휘 저었다."}, {"s": null, "t": "다온이 첫 사발을 떠서 나에게 내밀었다. 사발에는 꿀물이 절반만 담겨 있었다."}, {"s": "q:mk_daon", "t": "{이름} 님은 짐을 안 날랐으니까 반 사발! 일꾼이 아니잖아요."}, {"s": null, "t": "나는 사발을 받으려고 손을 내밀었다. 다온이 내 손을 보더니 사발을 도로 거두어 갔다. 내 손등에 빙혼곡 바위에 긁힌 자국이 벌겋게 나 있었다."}, {"s": "q:mk_daon", "t": "……어, 그거 바위에 긁힌 거죠? 그럼 일한 거네. 일한 거 맞네요."}, {"s": null, "t": "다온이 솥을 기울여 사발을 찰랑찰랑하게 채웠다. 다시 내민 사발에서 풀 냄새와 단내가 함께 올라왔다. 한 모금 마시자 쌉싸름한 맛 뒤로 단맛이 오래 남았다."}, {"s": null, "t": "나는 꿀을 반만 넣었는데도 달다고 했다. 다온이 코를 찡긋하며 웃었다."}, {"s": null, "t": "선창 쪽에서 쨍그랑 사발 깨지는 소리가 났다. 다온이 펄쩍 뛰어 부엌 문간으로 달려갔다. 문간에서 선창을 내다본 다온이 어깨를 축 늘어뜨리고 돌아왔다."}, {"s": "q:mk_daon", "t": "또 깼어요. 아저씨들 손바닥이 다 솥뚜껑 같아서 사발이 자꾸 미끄러진대요. 오늘만 벌써 세 개째예요."}, {"s": "q:mk_daon", "t": "아, 맞다! 수향 갈대 줄기를 잘라서 대롱으로 꽂으면요, 사발을 안 기울여도 마실 수 있잖아요. 그럼 덜 깰 거예요. 빈칸 벌판 어귀 물가에 갈대가 엄청 많아요."}, {"s": "q:mk_daon", "t": "갈대 꺾어 오면 마지막 짐배 올 때까지 주막에서 좀 쉬어요. 빙혼곡에 갔다 와서 다리가 아프잖아요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_1', 3, '당번 몫', '빈칸 벌판에서 수향 갈대을(를) 모은다, 묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["blank_field"], "n": 4}, {"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "해 질 녘 마지막 짐배가 선창에 닿았다. 강물이 붉은 기를 머금었고, 선창 널판에는 낮의 볕이 미지근하게 남아 있었다. 다온은 내가 꺾어 온 수향 갈대를 손가락 길이로 잘라 사발마다 하나씩 꽂았다."}, {"s": null, "t": "일꾼들이 짐을 내려놓고 사발 앞에 쪼그려 앉았다. 덩치 큰 어른들이 갈대 대롱을 입에 물고 꿀물을 쪽쪽 빨아 먹었다. 그 모습이 우스워 다온이 배를 잡고 웃었다."}, {"s": "q:mk_daon", "t": "봐요, 봐요! 하나도 안 깼어요! 하나도요!"}, {"s": null, "t": "일꾼 하나가 대롱을 문 채 엄지를 치켜세웠다. 다온은 그 엄지를 보고 어깨를 으쓱 올렸다."}, {"s": null, "t": "짐배가 다 비자 선창이 조용해졌다. 다온은 빈 사발들을 물동이에 담그고 계단에 털썩 앉았다. 나도 그 옆에 앉았다. 강바람이 식어 가는 사이로 젖은 사발에서 단내가 희미하게 풍겼다."}, {"s": null, "t": "다온이 솥 바닥에 남은 꿀물을 마지막 사발에 따랐다. 바닥까지 긁어도 두 모금이 되지 않았다. 다온은 그것을 홀짝 마시고 입술을 핥았다."}, {"s": null, "t": "나는 하루 종일 꿀물을 타면서 정작 다온의 몫은 마셨느냐고 물었다. 다온이 빈 사발을 내려다보며 고개를 저었다."}, {"s": "q:mk_daon", "t": "당번은 원래 맨 나중에 마시는 거예요. 남으면 마시고, 안 남으면 말고요."}, {"s": null, "t": "다온은 아무렇지 않게 말하고 사발을 물동이에 넣었다. 나는 다음에는 당번 몫을 맨 먼저 떠 두라고 했다. 다온이 눈을 깜박였다."}, {"s": "q:mk_daon", "t": "당번 몫이요? 그런 게 어딨어요. ……있어요?"}, {"s": null, "t": "나는 이제부터 있다고 했다. 다온이 입을 벌린 채 나를 올려다보다가 품에서 공책을 꺼냈다."}, {"s": null, "t": "공책 앞쪽에는 삐뚤빼뚤한 「다온」과 내 이름이 적혀 있었다. 다온은 빈 장을 펼치고 숯 조각을 쥐어 꾹꾹 눌러 적었다."}, {"s": "q:mk_daon", "t": "「꿀물 풀 — 야령초 다섯 줌, 갈대 네 단. {이름} 님이 가져옴.」 그리고요, 「당번 몫 있음.」 이것도 적었어요."}, {"s": null, "t": "다온이 숯을 내려놓고 손가락에 묻은 검댕을 바지에 쓱쓱 닦았다. 그러고는 무릎을 끌어안고 나를 곁눈질했다."}, {"s": "q:mk_daon", "t": "짐배는 날마다 오잖아요. 꿀물도 날마다 타야 되고요. 그럼 풀은 맨날 모자라요."}, {"s": "q:mk_daon", "t": "그러니까…… 앞으로도 부탁해도 돼요? 꿀물 풀이요. 값은 꼭 치를게요."}, {"s": null, "t": "나는 그러겠다고 했다. 다온이 공책을 탁 덮고 벌떡 일어났다. 선창 끝으로 달려간 다온이 빈 물동이를 머리 위로 번쩍 들어 보였다."}, {"s": "q:mk_daon", "t": "내일 또 와요! 내일은 당번 몫을 먼저 떠 놓을게요. {이름} 님 거랑 제 거랑 둘 다요!"}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_daon_2', 'side', '연담·다온', '공책 한 장', '다온의 공책에는 나루 사람마다 한 장씩 이름과 「좋아하는 것」이 적혀 있다. 조사원의 장이 새로 생기고, 빈칸을 채우려는 다온이 조사원이 하는 일을 곁에서 하나하나 적는다. 그날 저녁 조사원이 다온의 빈칸을 묻는다.', 'mukchang_ferry', 40, '{rg_daon_1}'::text[], null, 1616, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "daon", "stage": 2}'::jsonb where quest_id = 'rg_daon_2';
delete from public.world_quest_steps where quest_id = 'rg_daon_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_2', 1, '사람마다 한 장', '사람마다 한 장', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "새벽에 먹비가 한 차례 지나가서 주막 뒤 평상 널판이 아직 축축했다. 그 평상에서 다온이 공책을 펼쳐 놓고 엎드려 있었다. 젖은 나무 냄새에 숯 냄새가 섞여 올라왔다. 숯 조각을 쥔 손이 공책 위에서 바쁘게 움직였다."}, {"s": null, "t": "내가 다가가자 다온이 고개를 번쩍 들었다. 볼에 숯 검댕이 한 줄 묻어 있었다."}, {"s": "q:mk_daon", "t": "{이름} 님! {이름} 님이 날라 준 거, 하나도 안 빼고 다 적어 놨어요. 야령초가 열네 줌, 갈대가 아홉 단, 약제 바탕이 세 줌! 약제 바탕은 묵창댁 아주머니가 국에 넣었는데요, 덕배 할아버지가 국이 쌉쌀해졌대요."}, {"s": "q:mk_daon", "t": "그 뒤로 꿀물이 한 번도 안 떨어졌어요. 사발도 딱 하나 깼고요. 당번 몫도 날마다 먼저 떠 둬요."}, {"s": null, "t": "나는 다온의 어깨 너머로 공책을 들여다보았다. 다온이 공책을 내 쪽으로 돌려 보였다."}, {"s": null, "t": "장마다 맨 위에 나루 사람 이름이 하나씩 적혀 있었다. 이름 아래에는 「좋아하는 것」이라는 칸이 그어져 있었다."}, {"s": "q:mk_daon", "t": "이건 덕배 할아버지 장이에요. 「국밥 국물 많이」. 이건 뱃사공 노을 할아버지 장이고요, 「바람 부는 새벽」. 이상하죠? 바람 불면 춥기만 한데."}, {"s": "q:mk_daon", "t": "묵창댁 아주머니는 「넓은 부뚜막」이고요. 서리님 장은…… 아직 비었어요. 물어봐도 안 가르쳐 줘요."}, {"s": null, "t": "다온이 장을 넘기다가 한 장에서 손을 멈췄다. 맨 위에 삐뚤빼뚤한 글씨로 내 이름이 적혀 있었다. 그 아래 「좋아하는 것」 칸은 비어 있었다."}, {"s": "q:mk_daon", "t": "{이름} 님 장이에요. 어제 만들었어요. 근데 여기가 비어 있으니까 자꾸 신경 쓰여요."}, {"s": "q:mk_daon", "t": "{이름} 님은 뭐 좋아하세요?"}, {"s": null, "t": "나는 금방 대답하지 못했다. 다온이 숯을 입에 물려다가 얼른 내려놓았다. 숯 맛을 본 적이 있는 얼굴이었다."}, {"s": "q:mk_daon", "t": "생각 안 나면 같이 찾으면 돼요. 일하는 걸 보면 다 알아요."}, {"s": "q:mk_daon", "t": "오늘 빈칸 벌판 어귀로 채집하러 가죠? 저도 어귀 물가까지만 따라갈래요. 거기까진 혼자서도 다녀 봤어요. 옆에서 보고 적을게요."}, {"s": null, "t": "다온이 공책을 품에 넣고 평상에서 뛰어내렸다. 짚신 한 짝이 벗겨져 평상 밑으로 굴러 들어갔다. 다온은 엎드려 신을 꺼내 신고 나보다 먼저 나루 어귀로 달려갔다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_2', 2, '하는 걸 보면', '빈칸 벌판에서 채집한다', '{"at": ["blank_field"], "tasks": [{"t": "gather", "r": ["blank_field"], "n": 4}]}'::jsonb, '[{"s": null, "t": "빈칸 벌판 어귀 물가는 갈대가 허리까지 차올라 있었다. 다온은 물가 바위에 걸터앉아 공책을 무릎에 폈다. 내가 채집하는 동안 다온은 한 번도 눈을 떼지 않았다. 물가 진흙이 신발 밑창에 쩍쩍 들러붙었고, 갈대 잎끼리 쓸리는 소리가 마른 빗소리처럼 들렸다."}, {"s": null, "t": "나는 갈대를 꺾고 나서 밑동에 묻은 흙을 손으로 털었다. 다온의 숯이 공책 위에서 사각사각 움직였다."}, {"s": "q:mk_daon", "t": "「꺾고 나서 흙을 털어 줌.」 적었다!"}, {"s": null, "t": "나는 바위틈에서 갈대 먹을 한 덩이 캐 냈다. 손바닥에 묻은 먹이 미끈거렸다. 나는 그 먹을 바지에 닦으려다 갈대 잎에 닦았다. 사각사각 소리가 또 들렸다."}, {"s": "q:mk_daon", "t": "「먹 묻은 손은 바지 말고 풀에 닦음.」 이것도 적었어요. 서리님은 소매에 닦던데."}, {"s": null, "t": "나는 그만 피식 웃고 말았다. 다온이 숯을 귀에 꽂고 진지한 얼굴을 했다."}, {"s": "q:mk_daon", "t": "덕배 할아버지 장에도 「국자 두 번 흔들고 담음」이 있어요. 하는 걸 보면요, 그 사람이 보여요."}, {"s": null, "t": "채집을 마치고 우리는 물가에 나란히 앉았다. 다온이 공책을 펴고 다시 물었다."}, {"s": "q:mk_daon", "t": "그래서요, 좋아하는 거 찾았어요?"}, {"s": null, "t": "나는 잠깐 생각하다가 지난번 선창에서 마신 꿀물이 좋았다고 했다. 다온의 숯이 공책 위에서 멈췄다."}, {"s": "q:mk_daon", "t": "에이, 그건 제가 탄 거잖아요."}, {"s": null, "t": "나는 그래서 좋았다고 했다. 다온의 귀 끝이 빨개졌다. 다온은 공책에 코를 박을 듯이 고개를 숙이고 무언가를 꾹꾹 눌러 적었다."}, {"s": "q:mk_daon", "t": "……적었어요. 근데 그거 하나로는 칸이 너무 휑해요. 「잘 먹는 것」 칸도 있단 말이에요."}, {"s": null, "t": "다온이 물가를 내려다보았다. 물살 아래로 손가락만 한 고기 떼가 반짝 지나갔다."}, {"s": "q:mk_daon", "t": "오늘 저녁엔 선창에서 고기를 잡아서 묵창댁 아주머니한테 국을 끓여 달래요. 먹는 걸 보면 또 알 수 있어요."}, {"s": "q:mk_daon", "t": "딱 두 마리만 잡아요. 한 마리는 {이름} 님 거, 한 마리는 제 거. 저는 낚싯대가 없으니까 옆에서 미끼를 끼워 줄게요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_2', 3, '아무도 안 물어본 칸', '묵창 나루에서 낚시를 한다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "fish", "r": ["mukchang_ferry"], "n": 2}]}'::jsonb, '[{"s": null, "t": "내가 잡은 고기 두 마리는 묵창댁의 손을 거쳐 뽀얀 생선국이 되었다. 주막 구석 자리에 국그릇 둘이 김을 올리며 놓였다. 비린내가 말끔히 가신 국물에서 파 향과 고소한 기름 냄새가 함께 피어올랐다."}, {"s": "q:sx_mk_jumak", "t": "꼬맹이랑 조사원, 둘이서 싹 다 먹고 가. 국물 남기면 다음엔 안 끓여 준다."}, {"s": null, "t": "묵창댁이 국자를 어깨에 걸치고 부엌으로 돌아갔다. 다온은 숟가락을 들지 않고 턱을 괸 채 나만 보고 있었다."}, {"s": null, "t": "나는 국물부터 한 숟가락 떠먹었다. 혀끝이 델 만큼 뜨거웠다. 다온의 숯이 또 사각거렸다."}, {"s": "q:mk_daon", "t": "「국물 먼저.」 어, 덕배 할아버지랑 똑같다!"}, {"s": null, "t": "다온은 그제야 숟가락을 들고 국을 후후 불었다. 둘 다 그릇을 비웠을 때 다온이 공책을 펼쳐 내 장을 보여 주었다."}, {"s": null, "t": "내 이름 아래 「좋아하는 것」 칸에 「다온이 탄 꿀물」이라고 적혀 있었다. 「잘 먹는 것」 칸에는 「생선국. 국물 먼저.」가 적혀 있었다. 그 아래에도 깨알 같은 글씨가 빼곡했다."}, {"s": "q:mk_daon", "t": "이제 안 비었어요. 봐요, 공책에서 제일 긴 장이에요."}, {"s": null, "t": "나는 공책을 넘겨 보다가 맨 앞쪽에서 손을 멈췄다. 맨 위에 「다온」이라고 적힌 장이 있었다. 그 장의 「좋아하는 것」 칸이 비어 있었다."}, {"s": null, "t": "나는 다온은 무엇을 좋아하느냐고 물었다. 다온이 국그릇을 든 채 굳었다."}, {"s": "q:mk_daon", "t": "저요? ……그런 거 아무도 안 물어봤는데."}, {"s": null, "t": "다온이 국그릇을 내려놓고 오래도록 공책을 내려다보았다. 숯을 쥐었다가 놓았다가 다시 쥐었다."}, {"s": "q:mk_daon", "t": "꿀물이요. 근데 제가 타는 거 말고요. 누가 타 주는 꿀물이요."}, {"s": "q:mk_daon", "t": "그건 엄마가 타 준 뒤로 한 번도 못 마셔 봤어요. 다들 제가 타 준 거만 마시니까요."}, {"s": null, "t": "다온이 자기 장의 빈칸에 그 말을 아주 작게 적었다. 다 적고 나서 다온은 공책을 얼른 덮고 나를 흘겨보았다."}, {"s": "q:mk_daon", "t": "아무한테도 말하면 안 돼요. 서리님한테도요! 이건 공책 비밀이에요."}, {"s": null, "t": "나는 말하지 않겠다고 했다. 다온이 새끼손가락을 내밀었다. 나는 그 작은 손가락에 내 새끼손가락을 걸었다."}, {"s": "q:mk_daon", "t": "손가락 건 것도 적을 거예요. 근데 {이름} 님 장에다가요. 제 장엔 비밀만 적을 거예요."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_daon_3', 'side', '연담·다온', '갈대 너머 비밀 자리', '짐배가 들지 않는 날, 다온이 아무에게도 알려 주지 않은 자리로 조사원을 데려간다. 빈칸 벌판 어귀 갈대숲 너머의 둥근 풀밭이다. 둘은 표주박 하나로 꿀물을 번갈아 마시고, 갈대를 꺾고, 나란히 누워 구름에 이름을 붙인다.', 'mukchang_ferry', 40, '{rg_daon_2}'::text[], null, 1617, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "daon", "stage": 3}'::jsonb where quest_id = 'rg_daon_3';
delete from public.world_quest_steps where quest_id = 'rg_daon_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_3', 1, '쉬는 날', '쉬는 날', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "짐배가 들지 않는 날이라 선창은 텅 비어 있었다. 구름이 높이 뜬 맑은 날이었고, 볕에 데워진 돌계단에서 물때 냄새가 희미하게 올라왔다. 다온이 선창 계단 맨 위에서 두 발을 동동 구르며 나를 기다리고 있었다. 허리춤에 갈대 대롱 한 다발이 꽂혀 있었다."}, {"s": "q:mk_daon", "t": "왔다! {이름} 님, 이거 봐요. 대롱을 서른 개나 깎았어요. 이제 아저씨들이 대롱이 없으면 꿀물을 안 마신다니까요."}, {"s": "q:mk_daon", "t": "묵창 갈대 먹은 서리님 드리려고 따로 싸 놨어요. 서리님 벼루는 맨날 말라 있잖아요."}, {"s": null, "t": "나는 서리님이 받으면 반가워하겠다고 했다. 다온이 고개를 크게 끄덕이다 말고 입을 비죽였다."}, {"s": "q:mk_daon", "t": "서리님은 반가워도 안 웃어요. 그러니까 공책 칸이 안 채워지죠."}, {"s": null, "t": "다온이 주위를 한 번 둘러보더니 목소리를 낮췄다. 손바닥을 입가에 세우고 내 귀 쪽으로 몸을 기울였다."}, {"s": "q:mk_daon", "t": "오늘은 짐배가 안 오잖아요. 그럼 저도 쉬는 날이에요. 비밀 자리를 알려 줄게요."}, {"s": null, "t": "다온이 등 뒤에 감추고 있던 표주박 하나를 꺼내 보였다. 표주박 주둥이를 갈대 잎으로 꼭 막아 두었다."}, {"s": "q:mk_daon", "t": "빈칸 벌판 어귀 물가 있잖아요. 거기서 갈대숲을 쭉 헤치고 들어가면 풀밭이 나와요. 갈대가 키보다 커서 밖에선 하나도 안 보여요. 아무한테도 안 알려 준 데예요."}, {"s": null, "t": "다온은 짚신을 벗어 끈으로 묶더니 허리춤에 매달았다. 맨발로 계단을 콩콩 내려가는 걸음이 신나 있었다."}, {"s": "q:mk_daon", "t": "갈대숲에선 맨발이 최고예요. 신을 신으면 진흙에 푹 빠져서 벗겨져요. 저번에 한 짝 잃어버렸단 말이에요."}, {"s": null, "t": "나루 어귀를 벗어나자 다온이 앞장서 갈대숲으로 들어갔다. 갈대가 볕을 가려 공기가 금세 서늘해졌고, 발밑에서 진흙이 질척였다. 몇 걸음 가지 않아 다온의 걸음이 느려졌다. 다온이 갈대 사이에서 이쪽저쪽 고개를 돌렸다."}, {"s": "q:mk_daon", "t": "……어? 저번엔 분명 이쪽이었는데. 갈대가 또 자랐나?"}, {"s": null, "t": "다온이 멋쩍게 웃으며 나를 돌아보았다. 갈대 잎이 다온의 정수리 위에서 사각사각 흔들렸다."}, {"s": "q:mk_daon", "t": "제가 길을 자꾸 잃어버려요. 저번에도 해 질 때까지 헤맸어요. {이름} 님이 앞에서 길을 좀 찾아 줘요. 둥근 풀밭이에요. 거기서 갈대가 딱 끊겨요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_3', 2, '표주박 하나', '빈칸 벌판을(를) 살핀다', '{"at": ["blank_field"], "tasks": [{"t": "search", "r": ["blank_field"], "n": 2}]}'::jsonb, '[{"s": null, "t": "갈대숲을 두 번 헤맨 끝에 갈대가 툭 끊기고 둥근 풀밭이 나왔다. 사방이 키 큰 갈대로 둘러싸여 바람 소리만 사각사각 들렸다. 바람이 막힌 풀밭 안에는 볕이 고여 있었고, 풀 비린내 섞인 훈김이 코끝에 감겼다."}, {"s": "q:mk_daon", "t": "여기예요! 찾았다, 찾았어요!"}, {"s": null, "t": "다온이 맨발로 풀밭 한가운데로 뛰어들었다. 젖은 흙이 발가락 사이로 찔꺽찔꺽 비어져 나왔다. 다온은 그것도 재미있다는 듯 깔깔 웃었다."}, {"s": null, "t": "다온이 내 발을 내려다보며 손짓했다. 나도 신을 벗었다. 발바닥에 닿는 흙이 차갑고 보드라웠다."}, {"s": "q:mk_daon", "t": "여기 갈대는 속대가 달아요. 나루 갈대보다 훨씬요. 씹어 봐요, 얼른요."}, {"s": null, "t": "다온이 갈대 한 줄기를 꺾어 껍질을 벗기고 하얀 속대를 내밀었다. 씹어 보니 끝에서 은은한 단물이 배어 나왔다."}, {"s": null, "t": "다온이 표주박 주둥이의 갈대 잎을 뽑았다. 안에는 꿀물이 반쯤 차 있었다. 다온이 한 모금 마시고 표주박을 내게 내밀었다."}, {"s": "q:mk_daon", "t": "표주박이 하나밖에 없어서요. 번갈아 마셔요."}, {"s": null, "t": "나는 한 모금 마시고 표주박을 돌려주었다. 다온이 또 한 모금 마시고 다시 내밀었다. 표주박이 몇 번을 오가는 동안 꿀물이 금세 바닥을 보였다."}, {"s": "q:mk_daon", "t": "나루 아저씨들은 꿀물을 받기만 하잖아요. 같이 마시는 사람은 없어요. 주고받으면서 마시니까 더 달아요."}, {"s": null, "t": "다온이 빈 표주박을 흔들어 보며 아쉬운 듯 입맛을 다셨다. 그러다 무언가 생각난 얼굴로 둘레의 갈대를 가리켰다."}, {"s": "q:mk_daon", "t": "아, 꿀물 대롱은 이제 여기 갈대로 해야겠다. 단내가 나니까 아저씨들이 더 잘 마실 거예요."}, {"s": null, "t": "다온이 갈대 한 묶음을 끌어안아 보였다. 품에 다 들어오지 않아 갈대 끝이 다온의 턱을 간질였다. 다온이 재채기를 하고 웃었다."}, {"s": "q:mk_daon", "t": "다 꺾으면 누워요. 여기 누우면 하늘만 보여요. 그게 제일 좋아요. 아무도 안 부르고, 아무 데도 안 가도 되고요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_3', 3, '구름 이름', '빈칸 벌판에서 수향 갈대을(를) 모은다, 빈칸 벌판에서 쉰다', '{"at": ["blank_field"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["blank_field"], "n": 5}, {"t": "rest", "r": ["blank_field"], "n": 1}]}'::jsonb, '[{"s": null, "t": "갈대를 다 묶고 나서 우리는 풀밭에 나란히 누웠다. 갈대 끝이 하늘을 둥글게 둘러싸고 있었다. 그 둥근 하늘 안으로 구름이 천천히 흘러갔다. 볕을 머금은 풀이 등에 닿아 뜨뜻했다."}, {"s": "q:mk_daon", "t": "저 구름은 덕배 할아버지 국솥이에요. 봐요, 김이 올라가는 거."}, {"s": null, "t": "다온이 손가락으로 구름을 하나씩 짚었다. 묵창댁 아주머니 국자, 노을 할아버지 돛, 서리님 장부가 차례로 하늘에 생겼다. 서리님 장부라는 구름은 하나도 네모나지 않았다."}, {"s": "q:mk_daon", "t": "{이름} 님도 하나 지어 봐요."}, {"s": null, "t": "나는 둥글고 작은 구름 하나를 가리키며 표주박이라고 했다. 다온이 고개를 갸웃하다가 손뼉을 쳤다."}, {"s": "q:mk_daon", "t": "맞다, 표주박! 그럼 그 옆에 꼬리 달린 건 대롱이에요."}, {"s": null, "t": "구름 이름 짓기는 해가 기울도록 이어졌다. 갈대 끝에 걸린 볕이 꿀빛으로 짙어졌다. 다온의 목소리가 조금씩 느려지더니, 어느새 고른 숨소리만 들려왔다. 다온은 공책을 가슴에 끌어안은 채 잠들어 있었다."}, {"s": null, "t": "바람에 공책이 들썩이며 한 장이 넘어갔다. 펼쳐진 장에 삐뚤빼뚤한 글씨가 적혀 있었다. 「비밀 자리 — {이름} 님한테만 알려 줌. 표주박 같이 마심.」이라는 글씨였다."}, {"s": null, "t": "나는 공책을 덮어 다온의 팔 안에 다시 끼워 주었다. 갈대 그림자가 길어질 때까지 나는 그대로 누워 있었다."}, {"s": null, "t": "풀밭에 저녁 이슬이 내려 종아리가 서늘해졌다. 다온은 해가 거의 다 지고서야 눈을 비비며 일어났다. 하품을 길게 하고 나서 나를 보더니 화들짝 놀랐다."}, {"s": "q:mk_daon", "t": "제가 잤어요? 얼마나요? 큰일 났다, 아저씨들 저녁 꿀물…… 아, 오늘 짐배가 없는 날이지."}, {"s": null, "t": "다온이 다시 털썩 누웠다가 벌떡 일어나 갈대 묶음을 끌어안았다. 다온은 풀밭 가장자리에서 한 번 돌아서서 둥근 풀밭을 오래 바라보았다."}, {"s": "q:mk_daon", "t": "여기는요, 엄마 말고는 처음 데려온 거예요. 엄마랑은 아주 옛날에 왔어요. 그때는 제가 엄마 등에 업혀서 왔고요."}, {"s": null, "t": "다온은 그 말만 하고 갈대숲으로 들어섰다. 갈대숲을 빠져나가는 길에 다온이 내 소매를 잡았다."}, {"s": "q:mk_daon", "t": "다음에도 둘만 와요. 여기는 공책에 이름을 적은 사람만 오는 데예요."}, {"s": null, "t": "나는 그러자고 했다. 다온이 소매를 놓지 않고 앞장서 걸었다. 이번에는 한 번도 길을 잃지 않았다."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_daon_4', 'side', '연담·다온', '쓴 물', '빙혼곡에 눈이 와 꿀 짐이 고개를 넘지 못한다. 꿀 없이 쓴 풀물만 타던 다온이 엄마가 쓴 약 뒤에 주던 꿀 한 숟가락을 떠올리고 운다. 그날 밤 둘은 쓴 물을 똑같이 나눠 끝까지 마신다.', 'mukchang_ferry', 40, '{rg_daon_3}'::text[], null, 1618, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "daon", "stage": 4}'::jsonb where quest_id = 'rg_daon_4';
delete from public.world_quest_steps where quest_id = 'rg_daon_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_4', 1, '꿀 없는 날', '꿀 없는 날', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "선창에 짐배가 닿아 있었지만 일꾼들의 얼굴이 하나같이 찌푸려 있었다. 다들 사발을 받아 한 모금 마시고는 혀를 내둘렀다. 빙혼곡에서 내려온 바람이 매서워 일꾼들 입에서 허연 입김이 피어올랐고, 강물 위에는 찬 김이 낮게 서려 있었다."}, {"s": null, "t": "다온은 계단 맨 아래 칸에서 말없이 사발을 채우고 있었다. 꿀단지는 뚜껑이 열린 채 계단 옆에 엎어져 있었다."}, {"s": "q:mk_daon", "t": "……{이름} 님, 왔어요?"}, {"s": "q:mk_daon", "t": "꿀이 없어요. 빙혼곡에 눈이 와서 꿀 실은 짐이 고개를 못 넘었대요. 묵창댁 아주머니 꿀도 다 떨어졌고요."}, {"s": null, "t": "다온이 사발 하나를 내밀었다. 꿀 없이 야령초만 우린 물이었다. 한 모금 마시자 쓴맛이 혀뿌리까지 확 퍼졌다."}, {"s": "q:mk_daon", "t": "쓰죠? 아저씨들도 다 쓰대요. 그래도 안 마시는 것보단 낫대요. 그래서 계속 타는 거예요."}, {"s": null, "t": "다온의 눈가가 벌겋게 달아 있었다. 다온은 내가 그것을 보는 줄 알고 고개를 홱 돌려 물동이에 국자를 담갔다."}, {"s": null, "t": "나는 꿀 대신 넣을 것이 없겠느냐고 물었다. 다온이 국자를 쥔 채 물동이만 들여다보다가 고개를 저었다."}, {"s": "q:mk_daon", "t": "꿀 대신 되는 건 없어요. 대신에…… 약제 바탕을 넣으면 쓴 건 그대론데 몸이 따뜻해져요. 꿀물이 못 되면 약이라도 돼야죠."}, {"s": "q:mk_daon", "t": "빙혼곡 고갯길 바위 밑에 약제 바탕이 있어요. 눈 녹은 데로 가면 돼요. 네 줌만요."}, {"s": null, "t": "다온은 그 말만 하고 다시 사발을 채웠다. 평소처럼 「진짜예요」나 「값은 치를게요」를 덧붙이지 않았다."}, {"s": null, "t": "짐을 다 부린 일꾼 하나가 빈 사발을 돌려주며 다온의 어깨를 툭 쳤다. 다온은 고개만 꾸벅 숙였다. 웃지 않았다."}, {"s": null, "t": "나는 계단을 올라가다 돌아보았다. 다온이 엎어진 꿀단지를 바로 세워 뚜껑을 덮고 있었다. 빈 단지를 덮는 손이 느렸다."}, {"s": "q:mk_daon", "t": "늦으면 저 혼자 약을 타고 있을 거예요. 그러니까 빨리 와요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_4', 2, '숟가락 하나', '빙혼곡에서 약제 바탕을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["medicine_base"], "r": ["frost_valley"], "n": 4}]}'::jsonb, '[{"s": null, "t": "약제 바탕을 들고 돌아왔을 때 선창에는 아무도 없었다. 짐배는 떠났고, 빈 사발들이 물동이에 담겨 있었다. 널판에 하얗게 앉은 서리가 발밑에서 바삭거렸다."}, {"s": null, "t": "다온은 선창 끝 말뚝 뒤에 무릎을 끌어안고 앉아 있었다. 다온의 어깨가 들썩이고 있었다. 내 발소리를 듣자 다온이 소매로 얼굴을 북북 문질렀다."}, {"s": "q:mk_daon", "t": "안 울었어요. 진짜예요."}, {"s": null, "t": "나는 아무 말 없이 다온 옆에 앉았다. 강물이 말뚝에 찰싹찰싹 부딪혔다. 찰싹 소리가 수없이 되풀이된 뒤에야 다온이 무릎에 얼굴을 묻은 채 입을 열었다."}, {"s": "q:mk_daon", "t": "엄마가요, 저 아플 때 쓴 약을 먹였어요. 다 먹으면 꿀을 한 숟가락 줬고요. 그거 먹으려고 쓴 거 꾹 참고 다 먹었어요."}, {"s": "q:mk_daon", "t": "오늘 꿀이 없잖아요. 쓴 물만 타니까…… 그 숟가락 생각이 나서요."}, {"s": null, "t": "다온의 목소리가 떨렸다. 다온은 더 말하지 않고 소매로 코를 훌쩍 닦았다."}, {"s": null, "t": "나는 다온의 등을 천천히 쓸어 주었다. 다온이 내 쪽으로 조금 기울어 내 어깨에 머리를 댔다. 강바람이 목덜미를 파고들었다. 기댄 머리에서 풀물 냄새와 아궁이 연기 냄새가 배어 있었다."}, {"s": "q:mk_daon", "t": "선창 아저씨들은 몰라요. 제가 왜 꿀물을 타는지. 그냥 꼬맹이가 심심해서 그러는 줄 알아요."}, {"s": null, "t": "나는 아저씨들이 몰라도 나는 안다고 했다. 다온이 고개를 들어 나를 보았다. 눈이 퉁퉁 부어 있었다."}, {"s": "q:mk_daon", "t": "……공책에 엄마 장도 있어요. 근데 「좋아하는 것」 칸을 못 채웠어요. 엄마가 뭘 좋아했는지 한 번도 안 물어봤어요."}, {"s": "q:mk_daon", "t": "생각나는 건 꿀 숟가락밖에 없어요. 근데 그건 엄마가 좋아한 게 아니라 제가 좋아한 거잖아요."}, {"s": null, "t": "나는 엄마는 다온이 쓴 약을 다 먹는 것을 좋아했을 거라고 했다. 다온이 눈을 크게 떴다가 다시 무릎에 얼굴을 묻었다. 이번에는 어깨가 들썩이지 않았다."}, {"s": "q:mk_daon", "t": "……그거 적어도 돼요? 엄마 장에요?"}, {"s": null, "t": "나는 적어도 된다고 했다. 다온이 코를 한 번 더 훌쩍이고 고개를 들었다."}, {"s": "q:mk_daon", "t": "오늘은 꿀물을 안 탈래요. 그냥 앉아 있을래요. 같이 쉬어요."}, {"s": "q:mk_daon", "t": "해 지면 제가 약 탈게요. 가져온 약제 바탕을 넣어서요. {이름} 님 거랑 제 거랑, 딱 두 사발만요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_4', 3, '반만 쓴 물', '묵창 나루에서 쉰다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "rest", "r": ["mukchang_ferry"], "n": 1}]}'::jsonb, '[{"s": null, "t": "밤이 내리자 다온이 주막 부엌 작은 솥에 약제 바탕과 야령초 줄기를 넣고 끓였다. 검푸른 물이 보글보글 끓어오르며 쓴 냄새가 부엌 가득 퍼졌다. 아궁이 불빛이 다온의 볼을 발갛게 달궜다."}, {"s": null, "t": "묵창댁이 코를 막고 부엌 문간을 지나가다 멈칫했다. 묵창댁은 아무 말 없이 찬장 깊은 데서 작은 종지 하나를 꺼내 부뚜막 금 위에 놓고 나갔다."}, {"s": null, "t": "종지에는 꿀이 바닥에 아주 조금 깔려 있었다. 다온이 종지를 들여다보다가 내 얼굴을 보았다."}, {"s": "q:mk_daon", "t": "이거 아주머니가 숨겨 둔 거예요. 넣을까요?"}, {"s": null, "t": "나는 다온이 정하라고 했다. 다온은 종지를 두 손에 쥐고 망설이다가 찬장에 도로 넣었다."}, {"s": "q:mk_daon", "t": "내일 아침 아저씨들 첫 사발에 넣을래요. 오늘은 그냥 쓴 걸 마셔요."}, {"s": null, "t": "다온이 사발 둘에 약물을 똑같이 나눠 따랐다. 두 사발의 높이를 눈으로 몇 번이나 견주고 나서야 손을 뗐다. 우리는 부엌 문지방에 나란히 앉아 사발을 들었다."}, {"s": null, "t": "첫 모금에 혀가 오그라들 만큼 쓴맛이 목구멍까지 번졌다. 다온의 얼굴이 잔뜩 구겨졌다. 나도 모르게 얼굴을 찡그렸다. 다온이 그걸 보고 풋 웃음을 터뜨렸다."}, {"s": "q:mk_daon", "t": "{이름} 님 얼굴 좀 봐요! 저보다 더 쓴 얼굴이에요!"}, {"s": null, "t": "우리는 서로의 얼굴을 보며 한 모금씩 마셨다. 다온이 한 모금 마시면 나도 한 모금 마셨다. 사발이 비어 갈수록 웃음이 많아졌다."}, {"s": null, "t": "마지막 모금을 넘기고 다온이 빈 사발을 거꾸로 들어 보였다. 한 방울도 떨어지지 않았다."}, {"s": "q:mk_daon", "t": "끝까지 다 마셨다! 혼자 마셨으면 반도 못 마셨을 거예요."}, {"s": "q:mk_daon", "t": "쓴 거는요, 같이 마시면 반만 써요. 오늘 알았어요."}, {"s": null, "t": "다온이 품에서 공책을 꺼냈다. 다온은 맨 뒤쪽의 한 장을 펼쳐 「좋아하는 것」 칸에 숯으로 천천히 적었다. 「다온이 쓴 약 다 먹는 것」이라는 글씨였다."}, {"s": null, "t": "다온은 그 장을 덮고 이번에는 제 장을 펼쳤다. 비밀이 적힌 칸 아래에 새 줄을 하나 더 적었다. 「쓴 물 — 같이 마시면 반만 씀」이라는 줄이었다."}, {"s": "q:mk_daon", "t": "이것도 비밀이에요. 근데 {이름} 님은 알아도 돼요. 같이 마셨으니까."}, {"s": null, "t": "다온은 공책을 덮고 내 어깨에 다시 머리를 기댔다. 얼마 안 가 다온의 숨소리가 고르게 바뀌었다. 아궁이 불씨가 다 사그라들 때까지 나는 움직이지 않았다."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_daon_5', 'side', '연담·다온', '꿀물 친구', '빙혼곡 눈이 녹아 꿀이 다시 들어온 날, 다온이 꿀물을 딱 두 사발만 타겠다며 가장 좋은 풀을 주문한다. 밤 선창 계단에서 다온은 두 사발을 다 조사원 앞에 밀고, 조사원은 한 사발을 저어 다온에게 돌려준다. 다온의 공책 비밀 칸이 채워진다.', 'mukchang_ferry', 40, '{rg_daon_4}'::text[], null, 1619, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "daon", "stage": 5}'::jsonb where quest_id = 'rg_daon_5';
delete from public.world_quest_steps where quest_id = 'rg_daon_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_5', 1, '두 사발만', '두 사발만', '{"at": ["mukchang_ferry"]}'::jsonb, '[{"s": null, "t": "선창 계단에 짐배가 둘이나 닿아 있었다. 일꾼들이 갈대 대롱을 꽂은 사발을 받아 들고 꿀물을 쪽쪽 빨았다. 계단 옆 꿀단지가 노랗게 차 있었다. 눈 녹은 물이 불어 강물 소리가 한결 우렁찼고, 볕에 데워진 단지에서 단내가 계단 위까지 올라왔다."}, {"s": "q:mk_daon", "t": "{이름} 님! 꿀이 들어왔어요, 꿀이요! 빙혼곡에 눈이 녹았대요!"}, {"s": null, "t": "다온이 사발을 나눠 주던 손을 멈추고 품에서 공책을 꺼냈다. 공책이 처음 봤을 때보다 두 배는 두꺼워져 있었다. 다온이 뒤쪽 장들을 빠르게 넘겼다."}, {"s": "q:mk_daon", "t": "{이름} 님이 날라다 준 거 다 세어 봤어요. 야령초가 쉰두 줌, 갈대가 서른한 단, 약제 바탕이 열아홉 줌이요. 갈대 먹이랑 이것저것도 있고요. 공책 세 장이 꽉 찼어요."}, {"s": "q:mk_daon", "t": "국물 많이 할아버지, 덕배 할아버지요, 이제 대롱으로 국물까지 마신다니까요. 묵창댁 아주머니가 그거 보고 국자로 때릴 뻔했어요."}, {"s": null, "t": "다온이 깔깔 웃다가 갑자기 진지한 얼굴로 공책을 덮었다."}, {"s": "q:mk_daon", "t": "근데 오늘은 부탁이 좀 달라요. 오늘 저녁엔 꿀물을 딱 두 사발만 탈 거예요. 제일 좋은 걸로요."}, {"s": null, "t": "나는 누구에게 줄 꿀물이냐고 물었다. 다온이 입술을 꾹 다물고 고개를 저었다."}, {"s": "q:mk_daon", "t": "그건 비밀이에요. 공책 비밀보다 더 비밀!"}, {"s": null, "t": "다온이 두 손으로 입을 틀어막았다. 손가락 사이로 웃음이 새어 나왔다."}, {"s": "q:mk_daon", "t": "대신 제일 좋은 풀이 있어야 돼요. 갈대는 비밀 자리 거로요. 거기 갈대가 제일 달잖아요. 야령초는 빙혼곡 고갯마루 바위틈 거요. 거기 게 향이 제일 좋아요."}, {"s": null, "t": "다온이 손가락을 하나씩 접으며 셈을 했다. 갈대 넷, 야령초 넷이라고 입속으로 중얼거렸다."}, {"s": "q:mk_daon", "t": "넷씩이요. 두 사발에 넣고 남는 건 내일 아저씨들 거고요."}, {"s": "q:mk_daon", "t": "저는 그동안 솥을 닦아 놓고, 부뚜막 금도 다시 그어 놓을게요. 해 지기 전까지예요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_5', 2, '쫓겨난 부엌', '빈칸 벌판에서 수향 갈대을(를) 모은다, 빙혼곡에서 야령초을(를) 모은다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["blank_field"], "n": 4}, {"t": "gather", "items": ["herb"], "r": ["frost_valley"], "n": 4}]}'::jsonb, '[{"s": null, "t": "갈대와 야령초를 건네자 다온이 하나하나 코에 대고 킁킁 냄새를 맡았다. 다온은 만족한 듯 고개를 크게 끄덕였다."}, {"s": "q:mk_daon", "t": "좋아요, 다 좋아요. 이제 {이름} 님은 부엌에 들어오면 안 돼요!"}, {"s": null, "t": "다온이 두 손으로 내 등을 밀어 부엌 문밖으로 내보냈다. 부엌 안에서 솥뚜껑 여닫는 소리와 무언가 달그락거리는 소리가 들렸다."}, {"s": null, "t": "묵창댁이 부엌에서 쫓겨나 내 옆에 섰다. 묵창댁은 국자를 든 채 어이없다는 얼굴로 부엌 문을 보았다."}, {"s": "q:sx_mk_jumak", "t": "내 부엌에서 내가 쫓겨나는 날도 다 있네. 저 쥐방울만 한 게, 아까부터 솥만 세 번을 닦더라."}, {"s": null, "t": "묵창댁은 혀를 차며 주막 마당으로 나갔다. 부엌 문틈으로 다온의 얼굴이 쏙 나왔다."}, {"s": "q:mk_daon", "t": "{이름} 님. 꿀을 많이 넣는 게 좋아요, 조금 넣는 게 좋아요?"}, {"s": null, "t": "나는 대답하려다 말고 다온의 공책을 가리켰다. 다온이 아, 하고 입을 벌렸다. 다온의 얼굴이 문틈으로 쏙 들어갔다가 공책을 들고 다시 나왔다."}, {"s": "q:mk_daon", "t": "아, 공책에 있다! 「반만 넣어도 달다고 함.」 첫날 적은 거예요. 까먹을 뻔했네."}, {"s": "q:mk_daon", "t": "첫날 거는 맨 앞에 있어요. 안 지워지게 숯으로 두 번 덧썼어요."}, {"s": null, "t": "다온의 얼굴이 다시 들어갔다. 잠시 뒤 부엌 안에서 다온이 흥얼거리는 소리가 새어 나왔다. 가락도 가사도 없이 콧소리로만 이어지는 노래였다."}, {"s": null, "t": "나는 부엌 문 옆 벽에 등을 기댔다. 흥얼거림이 끊겼다 이어졌다 했다. 솥에서 김이 오르는 소리가 그 사이를 채웠다. 문틈으로 달큰한 야령초 향이 새어 나와 벽에 기댄 등까지 따스해졌다."}, {"s": "q:mk_daon", "t": "아직 멀었어요! 야령초는 천천히 우려야 된단 말이에요."}, {"s": "q:mk_daon", "t": "그동안 주막 평상에서 한숨 자고 와요. 다 되면 깨울게요. 진짜로 자야 돼요. 엿보면 처음부터 다시 할 거예요!"}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_daon_5', 3, '두 사발', '자율 활동을 끝까지 마친다', '{"at": ["mukchang_ferry"], "tasks": [{"t": "idle", "n": 1, "k": "rest"}]}'::jsonb, '[{"s": null, "t": "다온이 나를 흔들어 깨웠을 때 나루에는 등불이 하나둘 켜져 있었다. 다온은 쟁반에 사발 둘을 받쳐 들고 있었다. 밤공기가 선선했고, 주막 쪽에서 장작 타는 냄새가 실려 왔다. 사발마다 갈대 대롱이 하나씩 꽂혀 있었다."}, {"s": "q:mk_daon", "t": "따라와요. 계단으로요."}, {"s": null, "t": "우리는 선창 돌계단 맨 위 칸에 나란히 앉았다. 강물 위에 나루 등불이 길게 흔들렸다. 다온이 쟁반을 우리 사이에 내려놓았다."}, {"s": null, "t": "두 사발에 꿀물이 찰랑찰랑하게 차 있었다. 꿀물이 등불을 받아 노랗게 빛났다. 다온이 두 사발을 한꺼번에 내 앞으로 밀었다."}, {"s": "q:mk_daon", "t": "둘 다 {이름} 님 거예요."}, {"s": null, "t": "나는 사발과 다온을 번갈아 보았다. 다온이 무릎을 끌어안고 강물만 보며 말했다."}, {"s": "q:mk_daon", "t": "나루 아저씨들이 그러는데요, 엄청 친한 사람끼리는 꿀물 한 사발을 나눠 마신대요. 그런 사람을 꿀물 친구라고 한대요."}, {"s": "q:mk_daon", "t": "비밀 자리에서 표주박으로 같이 마셨잖아요. 쓴 물도 끝까지 같이 마셨고요. 그러니까 {이름} 님은 꿀물 친구가 맞아요."}, {"s": "q:mk_daon", "t": "근데 꿀물 친구는 한 사발을 나눠 마시는 거잖아요. {이름} 님한테는 두 사발을 다 줄게요. 제가 맨날 당번이라 그동안 못 준 거까지요."}, {"s": null, "t": "다온이 말을 마치고 귀 끝까지 빨개져 고개를 푹 숙였다. 나는 사발 하나를 들어 대롱으로 휘휘 저었다. 바닥에 가라앉은 꿀이 노랗게 풀려 올라왔다."}, {"s": null, "t": "나는 그 사발을 다온 앞에 내밀었다. 다온이 사발과 내 얼굴을 번갈아 보았다."}, {"s": "q:mk_daon", "t": "……이거 제 거예요?"}, {"s": null, "t": "나는 내가 저어서 타 준 꿀물이라고 했다. 다온의 입술이 달싹였다. 공책 비밀 칸에 적힌 글씨를 떠올리는 얼굴이었다."}, {"s": "q:mk_daon", "t": "누가 타 주는 꿀물……."}, {"s": null, "t": "다온이 두 손으로 사발을 받아 들고 대롱을 물었다. 한 모금 빨아 마신 다온은 대롱을 문 채 숨도 쉬지 않는 듯 가만히 있었다. 사발 위로 눈물 한 방울이 똑 떨어졌다."}, {"s": "q:mk_daon", "t": "달아요. 제가 탄 거보다 훨씬요. 이상하다, 똑같은 꿀인데."}, {"s": null, "t": "다온이 소매로 눈가를 문지르며 웃었다. 우리는 계단에 나란히 앉아 각자의 사발을 천천히 비웠다."}, {"s": null, "t": "사발이 다 비자 다온이 공책을 꺼냈다. 다온은 맨 앞 제 장을 펼쳐, 비밀 칸의 작은 글씨 둘레에 동그라미를 크게 쳤다."}, {"s": null, "t": "그다음 다온은 내 장을 펼쳤다. 맨 위 내 이름 앞에 숯으로 꾹꾹 눌러 글자를 덧붙였다. 삐뚤빼뚤했지만 한 획도 빠지지 않은 글씨로 「다온의 꿀물 친구」라고 적었다."}, {"s": "q:mk_daon", "t": "이제 공책에도 적었어요. 적은 건 안 까먹어요. 그러니까 {이름} 님도 까먹으면 안 돼요, 알았죠?"}, {"s": "q:mk_daon", "t": "다음에 짐배가 오는 날엔 당번 몫 말고 친구 몫을 떠 둘게요. 그건 맨 먼저 뜨는 거예요."}, {"s": null, "t": "나는 까먹지 않겠다고 했다. 다온이 빈 사발 둘을 포개 쟁반에 올리고, 그 위에 공책을 얹었다. 강물 위의 등불이 다온의 웃는 얼굴을 노랗게 비추었다."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2, "of_acc_rg_daon_ring": 1}, "title": "rg_daon"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_hisu_1', 'side', '연담·희수', '장부 표지', '묵창 나루 출납 서리 희수는 철마다 열흘씩 본부 정청 출납청에 올라와 나루 장부를 정청 장부와 한 줄씩 맞춘다. 빙혼곡 눈 녹은 물에 젖어 들뜬 장부를 다시 묶으려고 희수가 조사원에게 실과 종이를 주문한다. 희수는 장부마다 귀퉁이에 「희수 적음」이라고 적지만, 납품한 이의 이름은 적지 않는다.', 'hq_yard', 40, '{mkq_1}'::text[], null, 1620, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_hisu_1';
delete from public.world_quest_steps where quest_id = 'rg_hisu_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_1', 1, '젖은 장부', '젖은 장부', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "본부 정청 출납청은 대청 뒤쪽 좁은 방이었다. 서안마다 장부가 산처럼 쌓여 있었고, 먹 냄새와 묵은 종이 냄새가 한데 엉겨 있었다. 창이 작아 한낮에도 등잔을 켜 두었는지, 서까래가 그을음으로 거뭇했다."}, {"s": null, "t": "방 맨 구석 서안에 희수가 앉아 있었다. 희수 앞에 펼쳐진 장부는 표지가 물에 불어 우글쭈글했다. 희수는 들뜬 표지 귀퉁이를 손끝으로 꾹꾹 눌러 펴고 있었다. 젖은 종이에서 시큼한 냄새가 났다."}, {"s": null, "t": "내 발소리에 희수가 고개를 들었다. 희수는 붓을 붓걸이에 걸고 자리에서 일어나 고개를 짧게 숙였다."}, {"s": "q:mk_hisu", "t": "조사원? ……정청엔 무슨 일로 오셨어요."}, {"s": null, "t": "나는 출납청에 희수가 와 있다는 말을 듣고 왔다고 했다. 희수의 눈이 잠깐 커졌다가 곧 장부로 돌아갔다."}, {"s": "q:mk_hisu", "t": "철마다 열흘씩 올라와요. 나루 출납 장부를 정청 장부랑 한 줄씩 맞춰야 해서요. 틀린 줄이 나오면 열흘이 보름이 되고요."}, {"s": "q:mk_hisu", "t": "이번엔 오다가 빙혼곡에서 눈 녹은 물을 밟았어요. 보따리가 젖어서, 장부가 이렇게 됐고요."}, {"s": null, "t": "희수가 장부를 들어 보였다. 표지와 속장을 묶은 실이 물에 불어 느슨하게 늘어져 있었다. 장부를 조금만 흔들어도 속장이 들썩였다."}, {"s": "q:mk_hisu", "t": "속장은 말리면 돼요. 묶은 실은 다시 해야 하고요. 이대로 두면 속장이 한 장씩 빠집니다. 빠진 장은…… 없던 일이 돼요."}, {"s": null, "t": "나는 정청 창고 쪽을 돌아보았다. 희수가 내 눈길을 따라가다 고개를 저었다."}, {"s": "q:mk_hisu", "t": "있긴 있어요. 출납청 몫이 아니라서, 청을 올리면 사흘은 걸립니다. 그럼 대조가 사흘 밀리고요."}, {"s": null, "t": "희수가 잠깐 말을 멈추고 서안 위의 붓을 바로 놓았다. 무언가를 청하기 전에 손부터 정리하는 사람 같았다."}, {"s": "q:mk_hisu", "t": "조사원께 부탁드려도 될까요. 장부 묶는 실은 질겨야 해요. 영사로 꼰 실타래면 물에 젖어도 안 늘어집니다. 두 타래만요."}, {"s": "q:mk_hisu", "t": "값은 출납청에서 치를게요. 납품으로, 정식으로 적어 두겠습니다."}, {"s": null, "t": "희수는 그 말을 하고 다시 서안에 앉았다. 앉자마자 붓을 들어 젖은 장부의 첫 줄을 옮겨 적기 시작했다. 내가 문을 나설 때까지 희수는 한 번도 고개를 들지 않았다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_1', 2, '「조사원」 세 글자', '영사 실타래을(를) 만든다, 영사 실타래을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "craft", "items": ["spirit_thread"], "n": 2}], "give": {"spirit_thread": 2}}'::jsonb, '[{"s": null, "t": "영사 실타래 두 타래를 서안에 올려놓자, 희수가 한 타래를 집어 실 끝을 당겨 보았다. 은빛 실이 팽팽하게 버텼다. 희수가 실을 손끝으로 퉁기자 낮게 팽 하는 소리가 났다."}, {"s": "q:mk_hisu", "t": "좋네요. 꼬임이 고릅니다."}, {"s": null, "t": "희수는 장부 등에 꿰어 있던 옛 실을 가위로 끊어 냈다. 속장이 흐트러지지 않게 왼손으로 꼭 누른 채였다. 희수는 송곳으로 구멍 자리를 다시 짚고 새 실을 바늘에 꿰었다."}, {"s": null, "t": "바늘이 장부 등을 드나들 때마다 사각사각 소리가 났다. 희수의 손은 빠르지 않았지만 한 땀도 다시 뜨지 않았다."}, {"s": null, "t": "나는 맞은편 걸상에 앉아 그 손을 보았다. 희수가 바늘을 멈추지 않고 말했다."}, {"s": "q:mk_hisu", "t": "그렇게 보고 계시면 손이 굳어요. 딴 데를 보셔도 되는데요."}, {"s": null, "t": "나는 다른 데를 보겠다고 하고 계속 보았다. 희수의 바늘이 한 번 멈췄다가 다시 움직였다. 희수의 귀 끝이 조금 붉어져 있었다."}, {"s": null, "t": "마지막 매듭을 짓고 나서 희수가 장부 맨 앞 출납 줄을 펼쳤다. 희수는 오늘 날짜 아래에 「영사 실타래 둘 — 납품」이라고 적었다. 납품한 이 칸에는 「조사원」 세 글자만 적었다."}, {"s": null, "t": "나는 왜 이름을 적지 않느냐고 물었다. 희수가 붓을 든 채 잠시 그 칸을 내려다보았다."}, {"s": "q:mk_hisu", "t": "장부에 적은 이름은 남아요. 남는 건 반듯해야 하고요."}, {"s": "q:mk_hisu", "t": "이름은…… 함부로 적는 게 아니에요. 아직은 「조사원」이면 돼요."}, {"s": null, "t": "희수는 장부를 덮었다. 덮고 나서 장부 등을 손바닥으로 한 번 쓸었다. 새 실이 손바닥 아래에서 단단하게 만져졌다."}, {"s": "q:mk_hisu", "t": "실은 됐어요. 이제 표지가 문제예요. 표지 안쪽에 황지를 한 겹 대야 물이 속장까지 안 스며요."}, {"s": "q:mk_hisu", "t": "장서각 지하서고 서가 사이에 쓰다 남은 황지가 굴러다녀요. 세 장만 주워다 주세요. 서고 책벌레가 먼저 먹어 치우기 전에요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_1', 3, '희수 적음', '장서각 지하서고에서 황지을(를) 모은다', '{"at": ["hq_yard"], "tasks": [{"t": "gather", "items": ["seal_paper"], "r": ["hq_archive"], "n": 3}]}'::jsonb, '[{"s": null, "t": "황지 세 장을 건네자 희수가 풀 그릇을 끌어당겼다. 희수는 황지를 표지 안쪽에 대고 손바닥으로 문질러 기포를 밀어냈다. 쌀풀의 시큼한 냄새가 서안 위에 번졌다. 쭈글쭈글하던 표지가 팽팽하게 펴졌다."}, {"s": null, "t": "희수는 새 표지 앞면에 붓을 댔다. 「묵창 나루 출납」 여섯 글자가 반듯하게 내려앉았다. 획마다 굵기가 같았고, 글자 사이도 자로 잰 듯 고르게 벌어져 있었다."}, {"s": null, "t": "희수는 표지 맨 아래 귀퉁이에 작은 글씨로 한 줄을 더 적었다. 「희수 적음」이라는 넉 자가 귀퉁이에 얌전히 앉았다."}, {"s": null, "t": "내가 그 넉 자를 손가락으로 가리키자 희수가 붓을 씻으며 대답했다."}, {"s": "q:mk_hisu", "t": "제가 적은 장부엔 다 그렇게 적어요. 누가 적었는지 남아 있어야, 틀렸을 때 누구를 찾아가야 하는지 아니까요."}, {"s": "q:mk_hisu", "t": "틀린 적은…… 아직 없지만요."}, {"s": null, "t": "희수의 입꼬리가 아주 조금 올라갔다가 내려왔다. 웃은 건지 아닌지 알 수 없을 만큼 짧았다."}, {"s": null, "t": "젊은 서리 하나가 장부 더미를 안고 출납청 문간을 지나가다 고개를 꾸벅 숙였다. 희수도 고개를 숙여 받았다. 서리가 지나가자 희수가 서안 위 장부 더미를 손바닥으로 툭 쳤다."}, {"s": "q:mk_hisu", "t": "이게 이번 열흘 치 밥줄이에요. 철마다 이만큼씩 올라와요. 실도, 종이도, 장부 싸는 천도 늘 모자라고요."}, {"s": "q:mk_hisu", "t": "조사원. 앞으로도…… 부탁드려도 될까요. 정청에 올라올 때마다요. 출납청 납품으로 정식으로 적겠습니다."}, {"s": null, "t": "나는 그러겠다고 했다. 희수가 고개를 짧게 숙였다. 이번에는 아까보다 조금 오래 숙였다."}, {"s": "q:mk_hisu", "t": "고맙습니다. 그럼 장부에 한 줄 더 적어 둘게요."}, {"s": null, "t": "희수가 출납 줄 끝에 「정청에 올라올 때마다 납품 — 조사원」이라고 적었다."}, {"s": null, "t": "희수는 그 세 글자를 잠깐 내려다보았다. 붓끝이 그 옆 빈자리에 한 번 닿을 듯하다가 떨어졌다. 희수는 붓을 붓걸이에 걸고 장부를 덮었다."}, {"s": "q:mk_hisu", "t": "다음 철에 또 올라와요. 그땐 표지가 안 젖게 빙혼곡을 돌아서 오겠습니다."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_hisu_2', 'side', '연담·희수', '흔들린 획', '밤늦은 출납청에서 대조에 지친 희수의 획이 흔들린다. 조사원이 나루 장부의 숫자를 소리 내어 불러 주고, 희수는 받아 적다가 「천천히요」 하고 말한다. 희수는 획이 흔들릴 때마다 종이 귀퉁이에 이름 하나를 반듯하게 써 본다고 하지만, 누구 이름인지는 알려 주지 않는다.', 'hq_yard', 40, '{rg_hisu_1}'::text[], null, 1621, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "hisu", "stage": 2}'::jsonb where quest_id = 'rg_hisu_2';
delete from public.world_quest_steps where quest_id = 'rg_hisu_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_2', 1, '맨 나무 걸상', '맨 나무 걸상', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "밤이 깊었는데도 출납청 창호지에 등잔 불빛이 비쳤다. 문을 열자 희수가 서안 앞에 앉아 있었다. 장부가 둘 펼쳐져 있었고, 희수는 두 장부를 번갈아 짚으며 숫자를 맞추고 있었다. 밤바람이 처마를 훑고 지나갈 때마다 창호지가 떨렸고, 방 안에는 등잔 기름 타는 냄새가 무겁게 고여 있었다."}, {"s": "q:mk_hisu", "t": "조사원? 이 시각에요?"}, {"s": "q:mk_hisu", "t": "이번 철 대조는 줄이 많아서요. 나루에 들어온 소금이며 장작이며, 한 줄 한 줄 다 맞춰야 해요."}, {"s": null, "t": "희수가 다시 붓을 들었다. 붓끝이 종이에 닿는 순간 획이 가늘게 떨렸다. 희수는 붓을 떼고 그 획을 내려다보았다. 미간이 좁혀졌다."}, {"s": null, "t": "나는 언제부터 앉아 있었느냐고 물었다. 희수가 등잔 심지를 흘끗 보았다."}, {"s": "q:mk_hisu", "t": "해 질 녘부터요. ……아니, 점심 지나고부터네요."}, {"s": null, "t": "희수가 걸상에서 몸을 고쳐 앉다가 허리를 짚었다. 출납청 걸상은 등받이도 방석도 없는 맨 나무였다. 마룻바닥에서 올라오는 냉기가 발목까지 서늘했다."}, {"s": null, "t": "나는 걸상에 깔 것이라도 있어야겠다고 했다. 희수가 고개를 저으려다 말고 걸상 모서리를 손끝으로 쓸었다."}, {"s": "q:mk_hisu", "t": "정청 걸상은 다 이래요. 서리가 편하면 존다고, 옛날부터요."}, {"s": "q:mk_hisu", "t": "……근데 깔개를 깔지 말라는 말은 규정에 없긴 하네요."}, {"s": null, "t": "희수가 제 말에 놀란 듯 입을 다물었다."}, {"s": "q:mk_hisu", "t": "삼베 깔개면 돼요. 먹이 튀어도 빨면 되니까요. 하나만 지어 주시겠어요?"}, {"s": null, "t": "희수는 고개를 숙이고 다시 붓을 들었다. 다음 획은 아까보다 덜 떨렸다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_2', 2, '천천히요', '삼베 깔개을(를) 만든다, 삼베 깔개을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "craft", "items": ["hf_rug_hemp"], "n": 1}], "give": {"hf_rug_hemp": 1}}'::jsonb, '[{"s": null, "t": "삼베 깔개를 걸상에 펴 주자 희수가 그 위에 조심스럽게 앉았다. 희수는 깔개를 손바닥으로 한 번 쓸고 작게 숨을 내쉬었다."}, {"s": "q:mk_hisu", "t": "……따뜻하네요."}, {"s": null, "t": "희수는 다시 붓을 들었다. 몇 줄을 맞추고 나자 획이 또 흔들렸다. 희수가 붓을 멈추고 눈을 꾹 감았다가 떴다."}, {"s": null, "t": "나는 숫자를 불러 주겠다고 했다. 내가 나루 장부를 읽고 희수가 정청 장부에 맞춰 적으면 눈이 덜 지칠 터였다. 희수가 나를 보다가 나루 장부를 내 쪽으로 밀었다."}, {"s": "q:mk_hisu", "t": "셋째 장부터요. 「소금 — 열두 섬」부터 불러 주세요."}, {"s": null, "t": "나는 줄을 따라 숫자를 읽었다. 소금 열두 섬, 장작 마흔 단, 묵창 갈대 먹 스무 덩이를 차례로 불렀다. 희수의 붓이 내 목소리를 따라 사각사각 움직였다."}, {"s": null, "t": "내 목소리가 빨라지자 희수의 붓이 따라오다 획 하나가 비뚤어졌다. 희수가 붓을 멈추고 고개를 숙인 채 말했다."}, {"s": "q:mk_hisu", "t": "……천천히요."}, {"s": null, "t": "나는 천천히 다시 읽었다. 희수의 붓도 천천히 움직였다. 획이 더는 흔들리지 않았다. 등잔 심지가 낮아질 때마다 나는 읽기를 멈추고 심지를 돋우었다. 심지를 건드리면 불똥이 탁 튀며 불빛이 잠깐 환해졌다."}, {"s": null, "t": "자정이 넘어서야 희수가 붓을 내려놓고 손목을 주물렀다. 그러다 남는 종이 귀퉁이에 붓을 대고 무언가를 썼다. 획 몇 개를 긋고 나서 희수는 손바닥으로 그 귀퉁이를 덮었다."}, {"s": null, "t": "나는 덮인 귀퉁이를 바라보았다. 희수가 손바닥을 떼지 않고 고개를 저었다."}, {"s": "q:mk_hisu", "t": "획이 흔들릴 때 쓰는 거예요. 아는 이름 하나를 또박또박 써 보면 손이 돌아와요. 서리들은 다 하나씩 있어요."}, {"s": "q:mk_hisu", "t": "누구 이름인지는…… 안 알려 드릴 거예요."}, {"s": null, "t": "희수가 그 귀퉁이를 접어 장부 갈피에 끼웠다. 그러고는 마지막 장을 넘기다가 이마를 짚었다."}, {"s": "q:mk_hisu", "t": "장부로는 다 맞는데 창고 숫자가 안 맞아요. 나루에서 올려 보낸 먹 상자 둘이 정청 창고 목록에 없어요."}, {"s": "q:mk_hisu", "t": "장서각 지하서고로 잘못 들어갔을 수도 있어요. 서고에서 「묵창」이라고 적힌 상자를 좀 찾아 주시겠어요? 저는 여기서 나머지를 맞출게요. 이번엔 혼자서도 천천히 할 수 있을 것 같아요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_2', 3, '쉰 목소리', '장서각 지하서고을(를) 살핀다', '{"at": ["hq_yard"], "tasks": [{"t": "search", "r": ["hq_archive"], "n": 2}]}'::jsonb, '[{"s": null, "t": "지하서고는 곰팡내와 쥐 오줌 냄새가 뒤엉켜 숨을 얕게 쉬어야 했다. 구석 서가 맨 아래 칸에서 먼지를 손가락 두께로 뒤집어쓴 상자 둘을 찾았다. 상자 겉에 「묵창」이라고 적혀 있었다. 상자를 들고 출납청으로 돌아오니 창호지가 푸르스름하게 밝아 오고 있었다. 문틈으로 스민 새벽 공기에 손등이 시렸다."}, {"s": null, "t": "희수는 깔개 위에 앉은 채 마지막 장부를 덮고 있었다. 내가 상자를 내려놓자 희수가 상자 겉의 글씨를 확인하고 장부에 동그라미 두 개를 쳤다."}, {"s": "q:mk_hisu", "t": "맞네요. 이번 철 대조가 끝났어요. 하루나 일찍요."}, {"s": null, "t": "희수가 걸상에서 일어나 기지개를 켜려다 말고 팔을 내렸다. 내 눈을 의식한 듯 소매를 가지런히 펴고 고개를 숙였다."}, {"s": "q:mk_hisu", "t": "밤새 숫자를 불러 주셨잖아요. 목이 쉬셨겠어요."}, {"s": null, "t": "나는 괜찮다고 했다. 목소리가 쩍 갈라져 나왔다. 희수가 그 목소리를 듣고 입술을 꾹 다물었다. 웃음을 참는 얼굴이었다."}, {"s": "q:mk_hisu", "t": "전혀 안 괜찮은 목소린데요."}, {"s": null, "t": "희수가 서안 아래에서 찻주전자를 꺼내 식은 보리차를 한 잔 따라 주었다. 식은 보리차는 텁텁하고 밍밍했지만 나는 그것을 단숨에 비웠다. 희수가 빈 잔에 한 잔을 더 따랐다."}, {"s": null, "t": "희수는 장부 갈피에 끼워 둔 종이 귀퉁이를 한 번 만져 보았다. 꺼내지는 않았다."}, {"s": "q:mk_hisu", "t": "다음 철에 올라오면요. ……숫자, 또 불러 주실래요?"}, {"s": "q:mk_hisu", "t": "혼자 맞추면 밤에 획이 흔들려요. 누가 불러 주니까 덜 흔들리더라고요."}, {"s": null, "t": "나는 부르러 오겠다고 했다. 쉰 목소리가 또 갈라졌다. 희수가 이번에는 웃음을 참지 못하고 고개를 돌렸다."}, {"s": "q:mk_hisu", "t": "다음엔 목에 좋은 거라도 드시고 오세요. 출납청 보리차는 맛이 없어요."}, {"s": null, "t": "희수가 깔개를 반듯하게 접어 걸상 위에 올려놓았다. 접힌 모서리가 자로 잰 듯 맞았다. 희수는 그 위에 손을 한 번 얹었다가 뗐다."}, {"s": "q:mk_hisu", "t": "다음 철까지 이 깔개는 여기 둘게요. 다른 서리가 못 앉게, 접어서요."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_hisu_3', 'side', '연담·희수', '서리의 밤참', '서안에서는 밥을 먹지 않는 희수 곁에 점심 주먹밥이 밤까지 식어 있다. 조사원이 출납청 문간 마루에 밤참을 차리고, 희수는 어릴 적 고을 명부의 틀린 이름을 반듯하게 고쳐 적어 준 서리 이야기를 꺼내다 말을 잇지 못한다. 그 뒤 희수가 조사원에게 매듭 짓는 법을 가르친다.', 'hq_yard', 40, '{rg_hisu_2}'::text[], null, 1622, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "hisu", "stage": 3}'::jsonb where quest_id = 'rg_hisu_3';
delete from public.world_quest_steps where quest_id = 'rg_hisu_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_3', 1, '식은 주먹밥', '식은 주먹밥', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "출납청에 들어서자 희수가 깔개 위에 앉아 장부를 넘기고 있었다. 서안 한쪽에 종이에 싼 주먹밥 하나가 놓여 있었다. 손을 댄 흔적이 없었다. 싼 종이에 기름이 배어 있었고, 손끝으로 눌러 보니 밥이 돌처럼 굳어 있었다."}, {"s": "q:mk_hisu", "t": "조사원. ……잠깐만요, 이 줄만 맞추고요."}, {"s": null, "t": "나는 주먹밥을 가리키며 언제 것이냐고 물었다. 희수의 눈길이 주먹밥으로 갔다가 장부로 돌아왔다."}, {"s": "q:mk_hisu", "t": "점심 거예요. 이따 먹으려고요."}, {"s": null, "t": "창밖은 이미 캄캄했다. 정청 부엌 쪽에서 저녁상을 물리는 그릇 소리가 달그락달그락 넘어왔다. 내가 창밖을 가리키자 희수가 장부를 덮지 않은 채 대답했다."}, {"s": "q:mk_hisu", "t": "서안에서는 안 먹어요. 국물이 튀면 장부가 상하고, 밥알이 붙으면 숫자가 가려지잖아요. 그래서 일이 끝나고 먹어요."}, {"s": "q:mk_hisu", "t": "……근데 일이 안 끝나요."}, {"s": null, "t": "희수가 스스로도 우스웠는지 입술을 깨물었다. 나는 서안 말고 마루에서 먹으면 되지 않느냐고 했다. 희수가 문간 마루를 돌아보았다."}, {"s": "q:mk_hisu", "t": "마루에서요? ……마루에서 먹지 말라는 말도 규정엔 없네요."}, {"s": null, "t": "나는 밤참을 지어 오겠다고 했다. 희수가 사양하려다 서안 위의 식은 주먹밥을 보고 말을 삼켰다."}, {"s": "q:mk_hisu", "t": "그럼…… 야령초 나물밥이면 좋겠어요. 나루 주막에서 가끔 먹는데, 쌉쌀해서 졸음이 깨요."}, {"s": "q:mk_hisu", "t": "두 그릇이요. 한 그릇은 조사원 거예요. 혼자 먹으면 또 장부를 보게 되니까요."}, {"s": null, "t": "희수가 주먹밥을 종이째 서안 서랍에 넣었다. 서랍을 닫는 손이 조금 망설였다."}, {"s": "q:mk_hisu", "t": "이건 내일 아침에 먹을게요. 정말이에요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_3', 2, '고쳐 적은 이름', '야령초 나물밥을(를) 만든다, 야령초 나물밥을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "craft", "items": ["herb_rice"], "n": 2}], "give": {"herb_rice": 2}}'::jsonb, '[{"s": null, "t": "나물밥 두 그릇을 들고 오니 희수는 출납청 문간 마루에 나와 앉아 있었다. 장부는 방 안에 두고 온 빈손이었다. 빈손이 어색한지 희수가 무릎 위에서 손가락을 꼼지락거렸다. 밤 마루는 발바닥이 시릴 만큼 찼다."}, {"s": null, "t": "우리는 마루 끝에 나란히 앉아 나물밥을 먹었다. 쌉쌀한 나물 향이 김을 타고 코끝에 닿았다. 희수는 처음 몇 숟가락을 말없이 먹었다. 숟가락질이 점점 빨라졌다."}, {"s": "q:mk_hisu", "t": "……배가 고팠나 봐요. 몰랐네요."}, {"s": null, "t": "정청 마당은 고요했다. 마당 건너 대청 처마 끝에서 등 하나가 바람에 흔들렸다. 우물가에서 두레박 줄이 바람결에 삐걱거렸다. 희수가 그릇을 반쯤 비우고 숟가락을 내려놓았다."}, {"s": null, "t": "나는 희수에게 왜 서리가 되었느냐고 물었다. 희수가 처마 끝 등불을 바라보며 얼른 대답하지 않았다."}, {"s": "q:mk_hisu", "t": "제가 자란 고을엔 해마다 한 번씩, 정청에서 서리가 명부를 맞추러 왔어요."}, {"s": "q:mk_hisu", "t": "일곱 살 때였나. 그 서리가 제 줄을 짚더니 이름이 틀렸다는 거예요. 획이 하나 빠졌다고요. 앞 서리가 대충 적은 거였죠."}, {"s": "q:mk_hisu", "t": "그 서리가 제 이름을 긁어내고…… 새로 적어 줬어요. 아주 반듯하게. 한 획도 안 빠지게."}, {"s": null, "t": "희수의 목소리가 거기서 끊겼다. 희수는 숟가락을 다시 들었다가 내려놓았다."}, {"s": "q:mk_hisu", "t": "그러고 나서 그랬어요. 이제 안 지워진다고."}, {"s": "q:mk_hisu", "t": "적힌 이름은 남으니까. 그렇게 적힌 이름은…… 그래서요. 그래서 저도."}, {"s": null, "t": "희수는 문장을 끝맺지 못했다. 희수가 그릇에 남은 밥을 숟가락으로 꾹꾹 눌렀다. 나는 더 묻지 않고 마저 밥을 먹었다."}, {"s": null, "t": "희수가 헛기침을 하고 고개를 들었다. 얼굴이 붉게 달아올라 있었다."}, {"s": "q:mk_hisu", "t": "밥 먹으면서 할 얘기가 아니었네요. 딴 얘기를 해요."}, {"s": null, "t": "희수가 문간 옆 보따리를 끌어당겼다. 장부를 싸 다니는 보자기였다. 보자기를 여미는 끈이 해져 너덜너덜했다."}, {"s": "q:mk_hisu", "t": "보자기 끈 끝에 노리개를 달면 끈이 덜 풀려요. 묵직하니까요. 매듭 짓는 법을 가르쳐 드릴게요."}, {"s": "q:mk_hisu", "t": "하나 지어서 주세요. ……밥값이에요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_3', 3, '비뚤어진 매듭', '노리개을(를) 만든다, 노리개을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "craft", "items": ["of_acc_norigae"], "n": 1}], "give": {"of_acc_norigae": 1}}'::jsonb, '[{"s": null, "t": "내가 지은 노리개를 받아 든 희수가 매듭을 이리저리 돌려 보았다. 매듭 하나가 조금 비뚤어져 있었다. 희수가 그 매듭을 손끝으로 짚었다."}, {"s": "q:mk_hisu", "t": "여기요. 한 번 덜 감으셨네요."}, {"s": null, "t": "나는 다시 짓겠다고 했다. 희수가 고개를 저으며 노리개를 보자기 끈에 매달았다."}, {"s": "q:mk_hisu", "t": "그냥 이대로 둘게요. 장부라면 다시 지어 달라고 했겠지만, 보자기니까요."}, {"s": null, "t": "희수가 보자기를 한 번 흔들어 보았다. 노리개가 달랑거리며 보자기 끈을 묵직하게 잡아 주었다. 매듭 끝 술이 희수의 손목을 간질였다."}, {"s": "q:mk_hisu", "t": "우리 나루 꼬마, 다온이가 보면 뭐라고 할까요. 서리님 보자기에 왜 삐뚤어진 게 달렸냐고 하겠죠."}, {"s": null, "t": "희수가 그 말을 하며 처음으로 소리 내어 웃었다. 짧고 낮은 웃음이었다. 웃고 나서 희수는 스스로 놀란 듯 손등으로 입을 가렸다."}, {"s": null, "t": "마루 위에 빈 그릇 둘이 나란히 놓여 있었다. 희수가 그릇을 포개다가 손을 멈췄다."}, {"s": "q:mk_hisu", "t": "아까 그 얘기요. 나루 사람들한테도 한 적이 없어요. 정청에서도요."}, {"s": "q:mk_hisu", "t": "……조사원은 대답을 재촉하지 않으시니까. 그래서 말이 나왔나 봐요."}, {"s": null, "t": "나는 다음 철에도 밤참을 가져오겠다고 했다. 희수가 포갠 그릇을 들고 일어섰다."}, {"s": "q:mk_hisu", "t": "그럼 마루는 비워 둘게요. 장부는 방 안에 두고요."}, {"s": null, "t": "희수가 출납청 안으로 들어가다 문턱에서 멈췄다. 희수는 서안 서랍을 열어 아까 넣어 둔 식은 주먹밥을 꺼냈다."}, {"s": "q:mk_hisu", "t": "이것도 지금 먹을래요. 내일 아침까지 두면 또 잊어버릴 것 같아서요."}, {"s": null, "t": "희수가 마루로 돌아와 내 옆에 다시 앉았다. 식은 주먹밥을 반으로 갈라 한쪽을 내게 내밀었다. 나는 그것을 받아 들었다. 우리는 말없이 식은 밥을 마저 먹었다. 굳은 밥알이 입 안에서 서걱거렸지만, 씹을수록 단맛이 배어 나왔다."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_hisu_4', 'side', '연담·희수', '소매', '희수가 조사원의 겉옷 소매가 해진 것을 먼저 알아본다. 희수는 붉은 부적실을 구해 오라 하고, 겉을 꿰맨 뒤 소매 안쪽에 무언가를 수놓는다. 끝내 보여 주지 않고 흰 실로 시침질해 덮은 채 장부에 「수선, 미완」이라고 적는다.', 'hq_yard', 40, '{rg_hisu_3}'::text[], null, 1623, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "hisu", "stage": 4}'::jsonb where quest_id = 'rg_hisu_4';
delete from public.world_quest_steps where quest_id = 'rg_hisu_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_4', 1, '해진 소매', '해진 소매', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "출납청 서안 위에 낯익은 보자기가 놓여 있었다. 지난번 비뚤어진 노리개가 그 끈에 달랑거렸다. 한낮 볕이 창살 사이로 비스듬히 들어와, 볕살 속에서 먼지가 느리게 떠다녔다. 희수가 보자기를 풀며 나를 맞았다."}, {"s": "q:mk_hisu", "t": "조사원. 보세요, 나루 명부 덮개를 새로 쌌어요. 이제 빙혼곡 눈을 밟아도 안 젖어요."}, {"s": null, "t": "희수가 보자기에서 장부를 꺼내다 손을 멈췄다. 희수의 눈길이 내 팔에 머물러 있었다."}, {"s": "q:mk_hisu", "t": "……소매가 해졌네요."}, {"s": null, "t": "나는 내 소매를 내려다보았다. 오른 소매 끝 바느질이 터져 실밥이 너풀거리고 있었다. 언제 그렇게 됐는지 알 수 없었다."}, {"s": "q:mk_hisu", "t": "그대로 다니시면 반 뼘은 더 뜯어질 거예요. 벗어 주세요. 꿰매 드릴게요."}, {"s": null, "t": "나는 바쁜 사람에게 그런 일까지 맡길 수 없다고 했다. 희수가 장부를 덮고 나를 똑바로 보았다."}, {"s": "q:mk_hisu", "t": "장부 묶는 손이에요. 소매 하나 꿰매는 데 반 식경이면 돼요."}, {"s": "q:mk_hisu", "t": "실은…… 따로 있으면 좋겠어요. 폐쇄 사당 금줄에 붉게 물든 부적실이 걸려 있어요. 비바람을 맞아도 색이 안 바래요. 네 가닥만요."}, {"s": null, "t": "나는 고개를 갸웃했다. 겉 바느질이라면 흰 실이면 될 터였다. 희수가 잠깐 말을 고르다가 장부를 다시 펼쳤다."}, {"s": "q:mk_hisu", "t": "……안쪽에 쓸 데가 있어서요."}, {"s": null, "t": "나는 무엇에 쓰느냐고 다시 묻지 않았다. 희수가 그것을 알아챈 듯 붓을 쥔 손에서 힘을 조금 뺐다."}, {"s": null, "t": "희수는 더 말하지 않았다. 장부를 넘기는 손끝이 평소보다 빨랐다. 첫 줄을 적으려던 붓이 줄 위에서 한 번 멈칫했다."}, {"s": "q:mk_hisu", "t": "사당 금줄은 높이 걸려 있어요. 손을 뻗어도 안 닿으면 돌을 하나 딛고 서세요. 금줄에 묶인 부적은 건드리지 마시고요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_4', 2, '보지 마세요', '폐쇄 사당에서 부적실을(를) 모은다', '{"at": ["hq_yard"], "tasks": [{"t": "gather", "items": ["talisman_thread"], "r": ["shrine_ruins"], "n": 4}]}'::jsonb, '[{"s": null, "t": "부적실을 건네고 겉옷을 벗어 주자, 희수는 서안 위의 장부를 모두 한쪽으로 밀어 두었다. 서안 위에 내 겉옷 하나만 펼쳐졌다. 겉옷에 밴 흙냄새와 사당 향 냄새가 묵은 종이 냄새 사이로 퍼졌지만, 희수는 아랑곳하지 않았다."}, {"s": null, "t": "희수는 터진 소매 끝을 손끝으로 편 다음 흰 실로 겉 바느질을 촘촘히 떴다. 한 땀 한 땀 간격이 고르게 맞았다."}, {"s": null, "t": "겉을 다 꿰매고 나서 희수가 소매를 뒤집었다. 안쪽 솔기 위에 붉은 부적실을 꿴 바늘을 댔다. 바늘을 한 번 뜬 희수가 내 쪽을 흘끗 보았다."}, {"s": "q:mk_hisu", "t": "보지 마세요. 아직이에요."}, {"s": null, "t": "희수가 몸을 돌려 내게서 소매를 가렸다. 희수의 등 너머로 바늘이 천을 드나드는 소리만 사각사각 들렸다."}, {"s": null, "t": "나는 무엇을 하는지 물었다. 희수의 바늘이 멈췄다."}, {"s": "q:mk_hisu", "t": "안쪽은 겉에서 안 보이잖아요. 안 보이는 데를 단단히 해 두는 거예요. 장부 등처럼요."}, {"s": "q:mk_hisu", "t": "……대답이 됐나요?"}, {"s": null, "t": "나는 안 됐다고 했다. 희수의 어깨가 조금 들썩였다. 웃은 것 같았다."}, {"s": "q:mk_hisu", "t": "오래 걸려요. 서두르면 획이…… 아니, 땀이 비뚤어져요."}, {"s": null, "t": "희수는 끝내 돌아보지 않고 바늘만 움직였다. 등잔불에 비친 희수의 그림자가 벽에서 작게 오르내렸다."}, {"s": null, "t": "나는 걸상에 앉아 기다리겠다고 했다. 희수의 바늘이 또 한 번 멈췄다."}, {"s": "q:mk_hisu", "t": "저녁까지 걸릴 거예요. 객사에 가서 좀 쉬다 오세요. 여기 계시면 자꾸 이쪽을 보실 거잖아요."}, {"s": "q:mk_hisu", "t": "보시면 손이 굳는다니까요. 처음 실 묶을 때 말씀드렸잖아요."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_4', 3, '수선, 미완', '자율 활동을 끝까지 마친다', '{"at": ["hq_yard"], "tasks": [{"t": "idle", "n": 1, "k": "rest"}]}'::jsonb, '[{"s": null, "t": "해 질 녘 출납청에 돌아오니 희수가 내 겉옷을 곱게 개어 서안 위에 올려 두고 있었다. 희수는 개어 둔 겉옷 위에 두 손을 얹고 있었다. 서쪽 창으로 든 노을빛이 그 손등에 붉게 얹혀 있었다."}, {"s": "q:mk_hisu", "t": "다 됐어요. 겉은요."}, {"s": null, "t": "나는 겉옷을 받아 소매를 살펴보았다. 터졌던 자리가 감쪽같이 아물어 있었다. 소매를 뒤집어 보니 안쪽 솔기가 흰 실 시침질로 덮여 있었다."}, {"s": null, "t": "나는 흰 실로 덮인 안쪽을 손끝으로 짚었다. 희수가 서안 위 장부를 괜히 바로 놓았다."}, {"s": "q:mk_hisu", "t": "아직 다 안 됐어요. 안쪽은요."}, {"s": "q:mk_hisu", "t": "다 되면 보여 드릴게요. ……다 되면요."}, {"s": null, "t": "나는 다 될 때까지 소매 안쪽을 들여다보지 않겠다고 했다. 희수가 그 말을 듣고 장부 위에 손을 얹었다."}, {"s": null, "t": "희수가 시침질한 자리를 손끝으로 한 번 눌렀다. 실밥 하나 삐져나오지 않게 단단히 덮여 있었다."}, {"s": null, "t": "나는 겉옷을 입었다. 소매 안쪽에서 무언가 살짝 도톰한 것이 팔목에 닿았다."}, {"s": "q:mk_hisu", "t": "함부로 뜯으시면 안 돼요. 장부에 적어 둘 거예요."}, {"s": null, "t": "희수가 정말로 장부를 펼쳐 한 줄을 적었다. 「겉옷 소매 하나 — 수선, 미완」이라는 줄이었다."}, {"s": null, "t": "나는 미완이면 언제 완성되느냐고 물었다. 희수가 붓을 씻으며 창밖을 보았다."}, {"s": "q:mk_hisu", "t": "나루로 내려가기 전에요. 이번 철 대조가 끝나는 날이요."}, {"s": "q:mk_hisu", "t": "그때까지 소매 안쪽에 손을 넣으시면 안 돼요. 팔목으로만 느끼세요."}, {"s": null, "t": "희수가 얼른 장부 쪽으로 얼굴을 돌렸다. 나는 소매 끝을 손으로 감싸 쥐었다. 팔목 안쪽의 도톰한 것이 맥박처럼 만져졌다."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_hisu_5', 'side', '연담·희수', '적은 이름', '대조를 마친 희수가 묵창 나루로 내려가기 전날, 둘이 장부 보자기 끈을 꼬고 조사원은 처음 나루로 함께 내려가던 날처럼 노정 건량을 짓는다. 새벽 정청 대문 앞에서 희수가 소매의 시침질을 푼다. 소매 안쪽에는 조사원의 이름이 첫 획부터 끝 획까지 반듯하게 수놓여 있다.', 'hq_yard', 40, '{rg_hisu_4}'::text[], null, 1624, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "hisu", "stage": 5}'::jsonb where quest_id = 'rg_hisu_5';
delete from public.world_quest_steps where quest_id = 'rg_hisu_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_5', 1, '텅 빈 서안', '텅 빈 서안', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "출납청 서안이 처음으로 텅 비어 있었다. 장부들은 모두 보자기에 싸여 문간에 쌓여 있었고, 희수는 빈 서안을 걸레로 닦고 있었다. 물걸레가 지나간 자리에서 젖은 나무 냄새가 올라왔다. 장부가 빠져나간 방은 처음 보는 곳처럼 휑하게 비어 보였다."}, {"s": "q:mk_hisu", "t": "조사원. 이번 철 대조가 끝났어요. 조사원이 날라 주신 실이랑 종이로 장부 열두 권을 다시 묶었고요."}, {"s": "q:mk_hisu", "t": "장부에 적힌 납품이 마흔 줄이 넘어요. 한 사람한테서 이렇게 많이 받은 적이 없대요. 선임 서리님이 그러시더라고요."}, {"s": null, "t": "희수가 걸레를 개어 서안 모서리에 걸었다. 희수의 눈길이 내 소매에 닿았다가 얼른 떨어졌다. 나는 소매 안쪽이 아직 시침질된 채라는 것을 떠올렸다."}, {"s": null, "t": "나는 문간에 쌓인 보따리들을 바라보았다."}, {"s": "q:mk_hisu", "t": "내일 새벽에요. 빙혼곡을 넘으려면 해 뜨기 전에 나서야 해서요."}, {"s": null, "t": "나는 열흘이 짧았다고 했다. 희수가 걸레를 쥐었던 손을 소매 안쪽으로 감췄다."}, {"s": "q:mk_hisu", "t": "……저도요. 이번 철은 장부가 빨리 맞았어요. 그래서 짧았나 봐요."}, {"s": "q:mk_hisu", "t": "다음 철까지 석 달이에요. 깔개는 출납청 궤짝에 넣고 잠가 둘게요. 아무도 못 꺼내게요."}, {"s": null, "t": "희수가 문간의 장부 보따리를 들어 보았다. 비뚤어진 노리개가 달린 그 보자기였다. 보자기를 여민 끈이 또 너덜너덜해져 있었다."}, {"s": "q:mk_hisu", "t": "끈이 장부 무게를 못 견디네요. 부적실 두 가닥을 꼬아서 새 끈을 해야겠어요."}, {"s": "q:mk_hisu", "t": "이번엔 같이 꼬아 주세요. 혼자 꼰 끈은 언젠가 풀려요. 둘이 서로 반대로 꼬면 안 풀리고요."}, {"s": null, "t": "희수가 보따리를 내려놓았다. 보따리 위에 손을 얹은 채 잠깐 서 있었다."}, {"s": "q:mk_hisu", "t": "부적실 두 가닥이요. 한 가닥은 조사원 거, 한 가닥은 제 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_5', 2, '같이 꼰 끈', '부적실을(를) 만든다, 부적실을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "craft", "items": ["talisman_thread"], "n": 2}], "give": {"talisman_thread": 2}}'::jsonb, '[{"s": null, "t": "부적실 두 가닥을 건네자 희수가 한 가닥 끝을 내 손에 쥐여 주었다. 희수는 나머지 한 가닥을 쥐고 뒤로 세 걸음 물러섰다."}, {"s": "q:mk_hisu", "t": "저는 오른쪽으로, 조사원은 왼쪽으로 꼬세요. 같은 쪽으로 꼬면 풀려요."}, {"s": null, "t": "우리는 출납청 양 끝에 서서 실을 꼬았다. 실을 비틀 때마다 손바닥이 따끔따끔 달아올랐다. 실이 팽팽해지자 가운데서 두 가닥이 서로를 감으며 한 줄이 되었다. 희수가 한 걸음씩 다가오며 꼬인 실을 손바닥으로 훑었다."}, {"s": null, "t": "마지막에 희수의 손이 내 손 바로 앞에서 멈췄다. 희수가 꼬인 끈 끝을 내 손에서 받아 매듭을 지었다. 희수의 손가락이 잠깐 내 손등에 닿았다가 떨어졌다."}, {"s": "q:mk_hisu", "t": "……안 풀리네요. 잘 꼬셨어요."}, {"s": null, "t": "희수가 새 끈으로 보자기를 묶었다. 비뚤어진 노리개도 새 끈으로 옮겨 달았다. 희수는 다 묶은 보따리를 문간에 세워 두었다."}, {"s": null, "t": "희수가 서안 아래에서 빈 주머니 하나를 꺼냈다. 무언가를 넣으려다 말고 주머니 입을 오므렸다."}, {"s": "q:mk_hisu", "t": "처음 나루에 내려가던 날, 기억하세요? 그날 조사원께 노정 건량 세 개를 지어 달라고 했었잖아요."}, {"s": null, "t": "나는 기억한다고 했다. 희수가 빈 주머니를 내게 내밀었다."}, {"s": "q:mk_hisu", "t": "이번에도 부탁드려요. 세 개요. 정청 주방 건량은 짜서 빙혼곡에서 목이 말라요. 조사원이 지은 건 안 짰는데."}, {"s": null, "t": "희수가 그 말을 하고 입을 다물었다. 그날 건량 맛까지 기억하고 있었다는 것을 들킨 얼굴이었다."}, {"s": "q:mk_hisu", "t": "……그리고 내일 새벽, 정청 대문 앞에서요. 떠나기 전에 드릴 게 있어요."}, {"s": "q:mk_hisu", "t": "소매 안쪽, 어젯밤에 거의 다 했어요. 마지막 획이 하나 남았어요. 오늘 밤에 마칠게요."}, {"s": null, "t": "희수가 등잔 심지를 돋우었다. 오늘 밤에도 이 방 불이 늦게까지 켜져 있을 것 같았다."}]'::jsonb, '{"xp": 4640}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_hisu_5', 3, '희수가 적은 이름', '노정 건량을(를) 만든다, 노정 건량을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "craft", "items": ["travel_ration"], "n": 3}], "give": {"travel_ration": 3}}'::jsonb, '[{"s": null, "t": "새벽 정청 대문 앞은 아직 푸르스름했다. 문지방에 밤이슬이 축축하게 맺혀 있었고, 빙혼곡 쪽에서 내려온 바람에 귓불이 얼얼했다. 희수가 장부 보따리를 등에 지고 대문 기둥 옆에 서 있었다. 내가 건넨 건량 주머니가 보따리 끈에 매달려 있었다."}, {"s": "q:mk_hisu", "t": "오셨네요. 시간 맞춰서."}, {"s": null, "t": "희수가 보따리를 내려놓고 내 앞에 섰다. 희수는 말없이 내 오른팔을 들어 소매 끝을 뒤집었다. 손톱 끝으로 시침질한 흰 실 끝을 찾아 쥐었다."}, {"s": "q:mk_hisu", "t": "다 됐어요. 어젯밤에 마지막 획까지 했어요."}, {"s": null, "t": "희수가 흰 실을 스르르 당겨 뽑았다. 시침질이 풀리며 소매 안쪽 솔기가 드러났다."}, {"s": null, "t": "붉은 부적실로 수놓은 글자가 솔기를 따라 한 줄로 이어져 있었다. 내 이름이었다. 첫 획부터 마지막 획까지 하나도 빠지지 않고 반듯했다."}, {"s": null, "t": "획마다 굵기가 같았고 글자 사이도 고르게 벌어져 있었다. 이름 끝 아래에는 「희수 적음」이라는 넉 자가 아주 작게 수놓여 있었다."}, {"s": null, "t": "나는 그 글씨에서 눈을 떼지 못했다. 희수가 내 소매 끝을 쥔 채 놓지 않았다."}, {"s": "q:mk_hisu", "t": "출납청 장부엔 줄곧 「조사원」이라고만 적었잖아요. 이름은 함부로 적는 게 아니라서요."}, {"s": "q:mk_hisu", "t": "함부로가 아니게 될 때까지…… 기다렸어요. 그동안 획 연습도 했고요. 흔들릴 때마다 종이 귀퉁이에 썼던 것도……"}, {"s": null, "t": "희수의 문장이 끊겼다. 희수가 입술을 꾹 깨물고 소매에 수놓인 이름 위를 손끝으로 한 번 쓸었다."}, {"s": "q:mk_hisu", "t": "부르는 건, 아직 서툴러요. 입으로는 잘 안 나와요."}, {"s": "q:mk_hisu", "t": "그래도 적는 건…… 끝까지, 적었어요."}, {"s": null, "t": "희수가 소매를 놓고 한 걸음 물러섰다. 희수의 귀 끝이 새벽바람에도 식지 않을 만큼 붉었다."}, {"s": "q:mk_hisu", "t": "이건 희수가 적은 이름이에요. 반듯하게 적었으니까 안 지워져요. 제가 적은 건 틀린 적이 없잖아요."}, {"s": null, "t": "희수가 보따리를 등에 지고 고개를 숙였다. 이번에는 아주 오래 숙였다."}, {"s": null, "t": "고개를 든 희수가 빙혼곡 쪽 길로 몇 걸음 걸어가다 한 번 돌아보았다."}, {"s": "q:mk_hisu", "t": "다음 철에 올라오면요, 그 소매가 또 해졌나 볼 거예요. 해졌으면…… 또 꿰매 드릴게요."}, {"s": null, "t": "나는 소매를 접어 수놓인 이름을 팔목 안쪽으로 감췄다. 희수가 그것을 보고 입꼬리를 아주 조금 올렸다. 희수는 다시 돌아보지 않고 새벽길로 걸어 나갔다."}]'::jsonb, '{"xp": 4640, "gil": 165, "items": {"moonlight_essence": 2, "travel_ration": 2, "of_top_rg_hisu_coat": 1}, "title": "rg_hisu"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_danbi_1', 'side', '연담·단비', '엿판 첫날', '백골 장터 어귀에 엿판을 차린 단비가, 엿만 먹은 손님은 목이 메어 물 마시러 가 버린다며 짭짤한 말린 생선포를 주문한다. 첫 장날 단비는 엿을 반으로 꺾어 한쪽을 늘 따로 싸 둔다.', 'bone_market', 50, '{mde_danbi_2}'::text[], null, 1625, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_danbi_1';
delete from public.world_quest_steps where quest_id = 'rg_danbi_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_1', 1, '목 메는 엿', '목 메는 엿', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "이른 아침 백골 장터 어귀에는 마른 바람이 붉은 모래를 쓸고 다녔고, 그 바람을 등진 자리에 처음 보는 좌판 하나가 놓여 있었다. 판자 두 장을 엇대어 짠 엿판이었고, 한가운데에 뚜껑에 작은 손자국이 남은 엿 항아리가 앉아 있었다."}, {"s": null, "t": "좌판 뒤에서 단비가 오른손 하나로 엿 가락을 늘어놓고 있었다. 먹빛으로 굳은 왼손은 항아리 손잡이에 걸쳐 두었다. 갓 고아 온 엿에서 달큰한 조청 내음이 피어올라 좌판 둘레에 끈끈하게 고였다."}, {"s": null, "t": "좌판 끝에는 여운비가 등을 돌린 채 짐 꾸러미를 세고 있었다. 입술이 숫자를 따라 달싹였다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님! 마침 잘 오셨어요, 오늘이 첫 장이거든요! 엿판 이름도 지었어요. 「단비네」요. 「여단 엿방」은 대장님이 안 된다고 하셔서요."}, {"s": null, "t": "여운비가 꾸러미 매듭을 누르던 손을 멈추지도 않고 낮게 대꾸했다."}, {"s": "north_league:yeo", "t": "…짐 수 세는 중이오."}, {"s": null, "t": "여운비는 끝내 돌아보지 않았다. 단비가 혀를 쏙 내밀고 내 쪽으로 몸을 기울였다. 성한 오른쪽 귀가 내 쪽을 향해 있었다."}, {"s": "red_moon_cult:danbi", "t": "근데요, 큰일 났어요. 아침부터 손님이 셋이나 왔는데, 셋 다 엿을 하나씩 입에 쏙 넣더니 그냥 가 버렸어요."}, {"s": null, "t": "나는 엿이 맛있어서 그 자리에서 다 먹고 간 모양이라고 했다. 단비가 고개를 세차게 저었다."}, {"s": "red_moon_cult:danbi", "t": "아니라니까요. 엿이 달잖아요. 단 걸 먹으면 목이 메고, 목이 메면 물을 마시러 가고, 물을 마시러 간 손님은요, 안 돌아와요."}, {"s": null, "t": "맞은편 육포 좌판에서 장터 아낙이 고개를 쭉 내밀었다."}, {"s": "q:sx_ep_marketwife", "t": "그러니께 엿 아가씨, 우리 육포를 같이 팔자니까유. 짭짤한 게 옆에 있어야 단 게 또 당기는 법이유."}, {"s": null, "t": "단비가 엿 가락 하나를 오른손 손가락 사이에 끼워 빙글 돌리며 입을 삐죽였다."}, {"s": "red_moon_cult:danbi", "t": "에이, 아주머니네 육포는 짚신 밑창만큼 질기잖아요. 엿이랑 같이 씹다간 턱이 빠져요."}, {"s": null, "t": "장터 아낙이 흥 하고 고개를 돌렸다. 단비는 웃음을 참으며 엿 가락 하나를 집어 좌판 모서리에 대고 똑 꺾었다."}, {"s": null, "t": "엿이 딱 소리를 내며 반으로 갈라졌고, 단비의 손끝에 조청이 쩍 들러붙었다. 단비는 한쪽을 제 입에 넣고, 남은 반쪽을 기름종이에 싸서 좌판 구석에 놓았다."}, {"s": null, "t": "나는 그 반쪽은 왜 싸 두느냐고 물었다. 단비가 엿을 오물거리며 여운비의 등을 턱으로 가리켰다."}, {"s": "red_moon_cult:danbi", "t": "대장님 몫이에요. 일하실 땐 아무것도 안 드시는 분이거든요. 저녁에 드려야죠. 그래도 안 드시면… 뭐, 제가 먹고요."}, {"s": "red_moon_cult:danbi", "t": "그래서 말인데요, {이름} 님. 짭짤한 것 좀 만들어 주실래요? 말린 생선포 같은 거요. 엿 한 입, 생선포 한 입. 그러면 손님이 좌판 앞에서 오래 씹잖아요. 오래 씹다 보면 엿을 하나 더 사요. 틀림없어요."}, {"s": "red_moon_cult:danbi", "t": "생선은 월식성 아래 바위 해안에서 잘 잡혀요. 장터에서 사면 너무 비싸고요. 저도 따라갈게요! 엿판은 대장님이 봐 주신대요."}, {"s": null, "t": "여운비의 등이 한 번 굳었다. 여운비는 돌아보지 않은 채 목소리만 넘겨 보냈다."}, {"s": "north_league:yeo", "t": "…그런 말 한 적 없소."}, {"s": null, "t": "단비가 손가락에 묻은 조청을 쪽 빨고는 시치미를 뚝 뗐다."}, {"s": "red_moon_cult:danbi", "t": "방금 하셨잖아요, 「짐 수 세는 중이오」. 그게 엿판을 봐 주겠다는 말이에요. 저는 대장님 말은 다 알아들어요."}, {"s": null, "t": "여운비의 어깨가 한 번 들썩였다. 여운비는 여전히 돌아보지 않고 꾸러미 하나를 엿판 위로 옮겨 놓았다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_1', 2, '방울 소리와 물고기', '적월교 월식성에서 낚시를 한다', '{"at": ["red_moon_fort"], "tasks": [{"t": "fish", "r": ["red_moon_fort"], "n": 4}]}'::jsonb, '[{"s": null, "t": "월식성 아래 바위 해안은 바람이 셌다. 파도가 철썩철썩 바위를 때릴 때마다 짠 물보라가 날아올랐다. 바위마다 붙은 따개비가 신 밑창을 까슬까슬 긁었고, 하늘 한쪽에는 낮달이 붉은 기를 띤 채 걸려 있었다."}, {"s": null, "t": "단비는 내 곁 넓적한 바위에 쪼그려 앉아 있었다. 줄이 당겨질 때마다 단비가 오른손을 번쩍 들었고, 허리춤의 방울이 짤랑짤랑 울렸다."}, {"s": null, "t": "나는 줄을 감으며 방울부터 좀 풀어 두라고 했다. 단비가 입을 삐죽 내밀었다."}, {"s": "red_moon_cult:danbi", "t": "아침에도 똑같은 소리를 들었는데. 물고기가 제 방울 소리를 듣고 도망간다고요. 진짜였나 봐요."}, {"s": null, "t": "단비는 방울을 풀려다 손을 멈췄다."}, {"s": null, "t": "오른손 하나로는 허리끈 매듭이 풀리지 않았다. 내가 매듭을 풀어 방울을 단비의 소매 안에 넣어 주었다."}, {"s": "red_moon_cult:danbi", "t": "고마워요. 이건 무녀 때부터 달던 거라 못 버리겠어요. 축문은 이제 안 들리지만, 방울 소리는 멀리까지 가잖아요."}, {"s": null, "t": "단비가 소매 속 방울을 오른손으로 꾹 눌렀다. 방울 소리가 멎자 생선이 연달아 줄 끝에 올라와 바위 위에서 퍼덕였다."}, {"s": null, "t": "나는 줄을 다시 던지며, 왜 하필 엿 장사를 골랐는지 슬쩍 떠보았다. 단비가 파도를 보며 무릎을 끌어안았다."}, {"s": "red_moon_cult:danbi", "t": "우리 언년 할머니가 그러셨거든요. 장터 꼬맹이들 이마 닦아 주던 손으로 엿을 하나씩 쥐여 주라고요. 무녀 노릇은 이제 못 하니까… 그거라도 하고 싶었어요."}, {"s": "red_moon_cult:danbi", "t": "근데 엿만 쥐여 주면 애들은 좋아하는데, 어른들은 그냥 가 버려요. 어른들은 단 거 하나로는 안 머물더라고요."}, {"s": null, "t": "단비가 바위 위로 올라온 생선을 내려다보다가 코를 킁킁거렸다."}, {"s": "red_moon_cult:danbi", "t": "여기서 바로 손질해서 말려요! 바닷바람에 말리면 금방 꼬들꼬들해진대요. 다 마르면 엿판에 올려 주세요. 값은 장부에 꼬박꼬박 달아 둘게요."}, {"s": null, "t": "나는 생선을 손질해 바위 위에 널었다. 볕에 달궈진 바위 위에서 생선 살이 금세 꾸덕꾸덕해졌다. 단비는 오른손으로 생선포 끝을 꾹꾹 눌러 바람에 날아가지 않게 했다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_1', 3, '반쪽 둘', '말린 생선포을(를) 만든다, 말린 생선포을(를) 넘긴다', '{"at": ["bone_market"], "tasks": [{"t": "craft", "items": ["treat_fish"], "n": 2}], "give": {"treat_fish": 2}}'::jsonb, '[{"s": null, "t": "말린 생선포를 엿판 한쪽에 올려놓자 단내 옆에 짭조름한 바다 냄새가 섞였다. 단비가 엿 한 조각과 생선포 한 조각을 내 손바닥에 나란히 올렸다."}, {"s": "red_moon_cult:danbi", "t": "같이 드셔 보세요. 한 입에, 한꺼번에요!"}, {"s": null, "t": "나는 둘을 한 입에 넣었다. 단맛 뒤에 짠맛이 왔고, 짠맛 뒤에 다시 단맛이 돌았다. 내가 엄지를 들어 보이자 단비가 오른손으로 좌판을 탁 쳤다."}, {"s": null, "t": "한낮이 되자 붉은 모래 먼지 속으로 사람들이 오갔고, 옆 좌판 꼬치구이에서는 숯불에 기름 떨어지는 소리가 지글지글 났다. 단비의 목소리가 장터 소리를 뚫고 쨍쨍 울렸고, 손님들이 엿과 생선포를 번갈아 씹으며 좌판 앞에 오래 서 있었다."}, {"s": null, "t": "한 손님이 단비의 왼쪽에서 값을 물었다. 단비는 그 말을 듣지 못하고 오른쪽 손님에게만 엿을 내밀었다. 왼쪽 손님이 머쓱한 얼굴로 돌아섰다."}, {"s": null, "t": "나는 그 손님을 불러 세워 생선포 한 조각을 덤으로 쥐여 주었다. 손님이 엿 두 가락을 사 갔다."}, {"s": null, "t": "단비가 그 모습을 보고 한동안 입을 다물었다. 이윽고 단비가 오른손으로 제 왼쪽 귀를 톡 건드렸다."}, {"s": "red_moon_cult:danbi", "t": "이쪽으로는요, 장터 소리도 안 들어와요. 손님 말도요. 무녀 할 땐 축문을 듣는 귀라고 엄청 아꼈는데, 지금은 그냥… 조용한 귀예요."}, {"s": null, "t": "단비가 웃었다. 웃는 얼굴 그대로 엿 가락 하나를 또 꺾어 반쪽을 기름종이에 쌌다. 좌판 구석에 기름종이 꾸러미가 둘이 되었다."}, {"s": null, "t": "나는 반쪽이 또 늘었다고 했다. 단비가 꾸러미 둘을 나란히 맞춰 놓았다."}, {"s": "red_moon_cult:danbi", "t": "하나는 대장님 거, 하나는 오늘 수고한 사람 거예요. 누가 수고했는지는 장이 끝나 봐야 알죠."}, {"s": null, "t": "장터 지붕 위로 붉은 달이 떠오를 무렵 생선포가 바닥났다. 장부를 덮은 여운비가 그제야 좌판 쪽으로 돌아섰다. 단비가 첫 꾸러미를 여운비의 손바닥에 올려놓았다."}, {"s": "north_league:yeo", "t": "…나중에 먹겠소."}, {"s": null, "t": "여운비는 꾸러미를 품에 넣고 짐 꾸러미를 지고 장터 안쪽으로 걸어갔다. 단비는 그 뒷모습을 보다가 남은 꾸러미를 풀어 제 입에 쏙 넣었다."}, {"s": "red_moon_cult:danbi", "t": "오늘 수고한 사람은 저예요! 첫 장인데 다 팔았잖아요."}, {"s": null, "t": "단비가 엿을 오도독 깨물며 웃었다. 실컷 웃던 단비가 빈 기름종이를 손끝으로 접으며 나를 올려다보았다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님, 앞으로도 부탁해도 돼요? 생선포도 좋고, 다른 짭짤한 것도요. 날마다 다른 걸 해 주시면 손님들이 「내일은 뭐가 있나」 하고 또 올 거예요."}, {"s": null, "t": "나는 그러겠다고 했다. 단비가 기름종이를 반듯하게 펴서 엿 항아리 밑에 깔았다."}, {"s": "red_moon_cult:danbi", "t": "그럼 약속한 거예요! {이름} 님이 엿판 손님이 아니라, 엿판이 {이름} 님 손님인 거예요. 장부 첫 줄에 그렇게 적어 달라고 장부 쓰는 분한테 졸라야지."}]'::jsonb, '{"gil": 205}'::jsonb)
