insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_danbi_2', 'side', '연담·단비', '오른쪽 자리', '큰 장날 저녁, 장꾼들에게 팔 매운탕을 단비와 함께 끓인다. 장터 소리에 단비가 자꾸 말을 놓치자, 나는 말없이 단비의 오른쪽으로 자리를 옮긴다.', 'bone_market', 50, '{rg_danbi_1}'::text[], null, 1626, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "danbi", "stage": 2}'::jsonb where quest_id = 'rg_danbi_2';
delete from public.world_quest_steps where quest_id = 'rg_danbi_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_2', 1, '장부 한 장', '장부 한 장', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "엿판 위에 장부 한 권이 펼쳐져 있었다. 반듯한 글씨로 「생선포」, 「나물밥」, 「생선찜」이 줄줄이 적혀 있었고, 줄마다 끝에 내 이름이 붙어 있었다."}, {"s": "red_moon_cult:danbi", "t": "이거 보세요, {이름} 님. 지난 장날마다 날라다 주신 생선포랑 나물밥이에요. 대장님이 눈에 불을 켜고 하나도 안 빼고 적어 놓으셨어요. 벌써 한 장이 꽉 찼다니까요."}, {"s": null, "t": "단비가 장부를 오른손으로 넘겨 보였다. 마지막 줄 옆에는 작은 글씨로 「나물밥 짬. 손님이 그리 말함.」이라고 한 줄이 더 적혀 있었다."}, {"s": "red_moon_cult:danbi", "t": "그 줄도 대장님 글씨예요. 짜다는 건 손님 말이고요, 정작 쓰신 분은 두 그릇이나 비우셨어요."}, {"s": null, "t": "좌판 끝 여운비의 자리가 비어 있었다. 단비가 내 눈길을 따라가더니 고개를 북쪽으로 까딱했다."}, {"s": "red_moon_cult:danbi", "t": "고찰에 올라가셨어요. 가죽 끈 일이 있으시대요. 그래서 오늘은 저 혼자 장사하는데… 하필 오늘이 큰 장이지 뭐예요."}, {"s": null, "t": "장터 어귀로 짐 수레가 끝없이 들어오고 있었다. 사방에서 흥정하는 소리, 북 치는 소리, 수레바퀴 소리가 한꺼번에 터졌다. 짐 부리는 소의 누린내와 말린 고추의 매운내가 바람에 뒤섞여 밀려왔다."}, {"s": "red_moon_cult:danbi", "t": "큰 장날엔 장꾼들이 장터에서 저녁을 먹고 자요. 그럼 국물이 있어야 하거든요. 매운탕이요! 국물을 한 그릇 먹고 엿으로 입가심하면 딱이잖아요."}, {"s": "red_moon_cult:danbi", "t": "매운탕엔 야령초가 들어가야 맛이 나요. 적사 황무지 사당 언덕에 많거든요. 같이 가서 뜯어요. 솥은 장터 아주머니한테 벌써 빌려 놨어요."}, {"s": null, "t": "맞은편 육포 좌판에서 장터 아낙이 큰 솥 하나를 턱으로 가리켰다."}, {"s": "q:sx_ep_marketwife", "t": "솥값은 국물 한 그릇이유. 겁나게 맵게."}, {"s": null, "t": "단비가 오른손으로 가슴을 탕 치며 큰소리를 쳤다."}, {"s": "red_moon_cult:danbi", "t": "그럼 아주머니 건 제일 맵게 해 드릴게요!"}, {"s": null, "t": "장터 아낙이 입맛을 다시며 솥뚜껑을 두드렸다. 단비가 그 소리를 오른쪽 귀로 듣고 키득 웃었다."}, {"s": null, "t": "단비가 엿판에 「잠깐 나감」이라고 쓴 나무패를 걸었다. 글씨가 오른쪽으로 비뚜름하게 기울어 있었다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_2', 2, '말이 안 들리는 솥 앞', '적사 황무지에서 야령초을(를) 모은다', '{"at": ["bone_market"], "tasks": [{"t": "gather", "items": ["herb"], "r": ["red_plain"], "n": 4}]}'::jsonb, '[{"s": null, "t": "야령초를 한 아름 뜯어 장터로 돌아오니 해가 기울어 있었다. 소매에 풋풋한 풀물 냄새가 배어 있었다. 장꾼들이 모닥불을 하나둘 피워 매캐한 연기가 낮게 깔렸고, 장터는 아까보다 더 시끄러웠다."}, {"s": null, "t": "단비가 빌린 솥을 엿판 곁 화덕에 걸었다. 왼손으로는 솥 손잡이를 잡을 수 없어서 단비가 오른손으로 솥을 밀자 솥이 기우뚱 기울었다. 내가 반대쪽 손잡이를 붙잡았다."}, {"s": "red_moon_cult:danbi", "t": "고마워요! 그대로, 그대로 잡고 계세요! 물 부을게요!"}, {"s": null, "t": "단비가 물을 붓는 사이 나는 야령초는 언제 넣느냐고 물었다. 단비는 대답 없이 물바가지만 기울였다. 물줄기가 솥 바닥을 때리는 소리가 콸콸 울렸다."}, {"s": null, "t": "나는 한 번 더 물었다. 단비가 고개를 들었는데 엉뚱하게 솥뚜껑을 집어 들었다."}, {"s": "red_moon_cult:danbi", "t": "뚜껑이요? 에이, 아직 안 덮어요. 끓어야 덮죠."}, {"s": null, "t": "나는 말없이 솥 반대편을 돌아 단비의 오른쪽으로 가서 섰다. 그 자리에서 야령초는 언제 넣느냐고 다시 물었다."}, {"s": "red_moon_cult:danbi", "t": "물이 끓으면 바로요. …어라?"}, {"s": null, "t": "단비가 나를 올려다보았다. 눈이 동그래져 있었다. 단비는 솥과 나를 번갈아 보다가 갑자기 허리를 꺾고 웃기 시작했다."}, {"s": "red_moon_cult:danbi", "t": "아까부터 뭘 물어보셨구나! 저는 솥에 물을 붓는 소리밖에 못 들었어요. 근데 지금은 다 들려요. 오른쪽이니까요!"}, {"s": null, "t": "단비는 웃음이 그치지 않아 물바가지를 내려놓고 쪼그려 앉았다. 어깨가 오래도록 들썩였다. 장터 아낙이 고개를 빼고 이쪽을 보았다."}, {"s": "q:sx_ep_marketwife", "t": "무녀 아가씨, 솥 앞에서 뭘 그리 웃어유?"}, {"s": null, "t": "단비가 쪼그려 앉은 채 손사래를 쳤다."}, {"s": "red_moon_cult:danbi", "t": "무녀 아니라니까요, 아주머니! 엿 장수예요, 엿 장수!"}, {"s": null, "t": "단비가 웃음을 겨우 삼키고 일어섰다. 눈가에 맺힌 물기를 오른손 등으로 훔쳤다."}, {"s": "red_moon_cult:danbi", "t": "장터에선요, 다들 제 왼쪽에 서요. 거기가 비어 보이나 봐요. 근데 거기 선 사람한테 「저 그쪽은 못 들어요」 하기가 좀… 그래서 그냥 웃고 말았거든요."}, {"s": null, "t": "물이 보글보글 끓기 시작했다. 솥에서 오른 김이 얼굴을 훅 덮쳐 눈썹 끝이 축축해졌다. 단비가 야령초를 솥 위에 들고 나를 보았다."}, {"s": "red_moon_cult:danbi", "t": "생선은 {이름} 님이 손질해서 넣어 주세요. 저는 한 손이라 칼질이 느려서요. 두 솥을 끓여서 장꾼들 저녁을 먹여요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_2', 3, '비뚜름한 나무패', '매운탕을(를) 만든다, 매운탕을(를) 넘긴다', '{"at": ["bone_market"], "tasks": [{"t": "craft", "items": ["spicy_stew"], "n": 2}], "give": {"spicy_stew": 2}}'::jsonb, '[{"s": null, "t": "매운탕 두 솥은 해가 다 지기도 전에 바닥을 보였다. 고추기름 냄새가 장터 골목 끝까지 번져 지나가던 장꾼들의 발길을 죄다 붙잡은 덕이었다."}, {"s": null, "t": "장꾼들이 빈 그릇을 내려놓고 엿 한 가락씩을 사 갔다. 장터 아낙은 제일 매운 그릇을 비우고 혀를 내밀며 물을 찾았다."}, {"s": null, "t": "장꾼들이 하나둘 모닥불 가로 흩어지자 엿판 앞이 조용해졌다. 해가 진 모래땅에서 서늘한 기운이 올라와 발목을 감쌌다. 단비가 빈 솥을 오른손으로 박박 닦았고, 나는 단비의 오른쪽에서 그릇을 포갰다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님, 아까부터 계속 제 오른쪽에만 계시네요?"}, {"s": null, "t": "나는 그쪽이 잘 들리는 쪽이라서 그렇다고 했다. 단비가 솥을 닦던 손을 멈췄다."}, {"s": "red_moon_cult:danbi", "t": "대장님도 그러세요. 늘 제 오른쪽에 서시거든요. 오른 눈이 안 보이시니까, 그렇게 서면 대장님은 성한 눈으로 저를 보시고 저는 성한 귀로 말을 듣고. 딱 맞잖아요."}, {"s": "red_moon_cult:danbi", "t": "근데 {이름} 님은… 그냥 오른쪽으로 오셨어요. 아무 말도 없이요. 제가 못 듣는다고 말하기도 전에요."}, {"s": null, "t": "단비는 그 말을 하고 솥을 다시 닦았다. 솥 바닥을 닦는 손이 아까보다 느렸다."}, {"s": null, "t": "일을 다 마치고 단비가 엿 항아리에서 엿 한 가락을 꺼내 여느 때처럼 반으로 꺾었다. 반쪽은 제 입에 넣고, 반쪽은 기름종이에 쌌다."}, {"s": "red_moon_cult:danbi", "t": "고찰 가신 분은 사흘 뒤에나 내려오신대요. 그때까지 안 녹게 꽁꽁 싸 둬야겠다."}, {"s": null, "t": "단비가 꾸러미를 엿판 서랍에 넣었다. 그러고는 엿판에 걸린 나무패를 떼어 뒤집었다. 뒷면에 「오른쪽에서 불러 주세요」라고 새로 썼다."}, {"s": null, "t": "나는 글씨가 아까보다 더 비뚜름하다고 했다. 단비가 나무패를 엿판 오른쪽 모서리에 걸며 혀를 쏙 내밀었다."}, {"s": "red_moon_cult:danbi", "t": "오른쪽으로 기울어야 손님이 오른쪽으로 오죠. 일부러 그렇게 쓴 거예요, 일부러!"}, {"s": null, "t": "단비가 나무패를 손끝으로 툭 쳤다. 나무패가 밤바람에 달그락거리며 오른쪽을 가리켰다."}, {"s": "red_moon_cult:danbi", "t": "다음 장날에도 와 주세요. 오른쪽 자리는 비워 둘게요. 아, 대장님 오시는 날만 빼고요."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_danbi_3', 'side', '연담·단비', '엿 안 먹는 날', '들리지 않는 왼쪽 귀가 안에서 웅웅 울리는 날, 단비는 엿판을 닫고 엿에 손을 대지 않는다. 나는 어죽을 끓여 단비에게 떠먹이고, 단비는 그날 먹지 못한 엿 반쪽을 내게 맡긴다.', 'bone_market', 50, '{rg_danbi_2}'::text[], null, 1627, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "danbi", "stage": 3}'::jsonb where quest_id = 'rg_danbi_3';
delete from public.world_quest_steps where quest_id = 'rg_danbi_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_3', 1, '「오늘 쉼」', '「오늘 쉼」', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "잿빛 구름이 낮게 덮인 아침, 엿판에 「오늘 쉼」이라고 쓴 나무패가 걸려 있었다. 비뚜름한 글씨였다. 엿 항아리 뚜껑은 닫혀 있었고, 좌판 위에는 마른 바람에 날린 모래가 얇게 쌓여 있었다."}, {"s": null, "t": "단비는 좌판 뒤 걸상에 담요를 둘러쓰고 앉아 있었다. 무릎 위에 엿 꾸러미가 놓여 있었지만 하나도 풀려 있지 않았다."}, {"s": null, "t": "내가 단비의 오른쪽으로 가서 서자 단비가 담요 속에서 고개를 들었다. 얼굴이 하얗게 질려 있었고, 담요 밖으로 나온 이마에 식은땀이 송골송골 맺혀 있었다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님… 오셨어요? 장꾼들이 매운탕은 또 언제 하냐고 자꾸 물어요. 근데 오늘은 못 해요. 장사는 쉬어요."}, {"s": null, "t": "나는 단비 앞에 쪼그려 앉아 얼굴을 살폈다. 단비가 오른손으로 제 왼쪽 귀를 감쌌다."}, {"s": "red_moon_cult:danbi", "t": "이쪽이요. 안 들리는 쪽인데요, 가끔 안에서 웅웅 울어요. 큰 북을 귓속에 넣고 둥둥 치는 것 같아요. 하루쯤 지나면 가라앉긴 해요."}, {"s": null, "t": "단비가 눈을 질끈 감았다. 담요 끝을 쥔 오른손이 바르르 떨렸다."}, {"s": null, "t": "나는 무릎 위의 엿 꾸러미를 보았다."}, {"s": null, "t": "단비는 엿을 늘 품에 넣고 다녔고, 기분이 무너지는 날에는 엿을 먹지 않았다. 일행이던 때 그 버릇을 여러 번 보았다."}, {"s": null, "t": "내가 꾸러미를 손끝으로 가리키자 단비가 꾸러미를 내려다보다가 고개를 저었다."}, {"s": "red_moon_cult:danbi", "t": "오늘은 엿이 맛이 없어요. 맛없는 날은 안 먹어요. 맛없게 먹으면… 엿한테 미안하잖아요."}, {"s": "red_moon_cult:danbi", "t": "아픈 날엔 엿 말고 죽을 먹어야 하는데요, 제가 죽을 끓이면 죄다 눌어요. 한 손으로 저으면 바닥까지 안 닿거든요."}, {"s": null, "t": "단비가 눈을 반쯤 뜨고 나를 보았다. 평소처럼 웃으려다 입꼬리가 다 올라가지 못했다."}, {"s": "red_moon_cult:danbi", "t": "…어죽이 먹고 싶어요. 생선이 들어간 거요. 월식성 바위에서 잡은 생선이면 더 좋고요. 저 오늘은 못 따라가겠어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_3', 2, '투정', '적월교 월식성에서 낚시를 한다', '{"at": ["bone_market"], "tasks": [{"t": "fish", "r": ["red_moon_fort"], "n": 3}]}'::jsonb, '[{"s": null, "t": "생선을 들고 돌아오니 단비는 아까 그 자리에서 꾸벅꾸벅 졸고 있었다. 내가 화덕에 작은 솥을 걸자 단비가 담요를 끌어안은 채 눈을 떴다."}, {"s": "red_moon_cult:danbi", "t": "오셨어요? 저 안 잤어요, 진짜예요. 귀 우는 소리를 들으면서 눈만 감고 있었어요."}, {"s": null, "t": "나는 생선을 손질해 솥에 넣고 노정 건량을 부숴 함께 끓였다. 불은 낟알이 퍼지면서 국물이 뽀얗게 걸쭉해졌다. 단비는 걸상에 앉은 채 고개만 내밀고 솥 안을 들여다보았다."}, {"s": "red_moon_cult:danbi", "t": "더 저어 주세요, 바닥에 눌어요. 아니, 아니, 너무 세요! 생선살이 다 부서지잖아요."}, {"s": null, "t": "나는 젓는 손을 늦췄다. 단비가 담요 밖으로 눈만 내밀고 솥을 지켜보았다."}, {"s": "red_moon_cult:danbi", "t": "네, 그 정도요. 언년 할머니가 엿을 저으실 때 꼭 그렇게 저으셨어요. 사람 등 쓸어 주듯이요."}, {"s": null, "t": "나는 젓는 손을 쉬지 않으며 언년 할머니 댁 소식을 물었다. 담요 덩어리가 위아래로 꼼지락거렸다."}, {"s": "red_moon_cult:danbi", "t": "보름마다 가요. 엿을 받으러요. 할머니는 제 왼쪽 귀를 아시니까 늘 오른쪽에서 소리를 지르세요. 장터까지 다 들릴 만큼요."}, {"s": null, "t": "죽이 끓어오르자 김이 엿판 위로 피어올랐다. 단비가 코를 킁킁거리다가 얼굴을 찡그렸다."}, {"s": "red_moon_cult:danbi", "t": "소금을 너무 넣으신 것 같은데요. 냄새가 짜요."}, {"s": null, "t": "나는 아직 소금을 넣지 않았다고 했다. 단비가 잠깐 입을 다물었다가 담요를 머리끝까지 뒤집어썼다."}, {"s": "red_moon_cult:danbi", "t": "…그럼 바다 냄새인가 보죠, 뭐. 아무튼 짜게 하지 마세요."}, {"s": null, "t": "담요 속에서 웃음 섞인 숨소리가 새어 나왔다. 귀 울림이 조금 가라앉은 모양이었다."}, {"s": "red_moon_cult:danbi", "t": "두 그릇 끓여 주세요. 하나는 지금 먹고, 하나는 이따 밤에 먹을래요. 밤에 또 울면 따뜻한 걸 먹어야 하거든요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_3', 3, '맡아 둔 반쪽', '어죽을(를) 만든다, 어죽을(를) 넘긴다', '{"at": ["bone_market"], "tasks": [{"t": "craft", "items": ["fish_porridge"], "n": 2}], "give": {"fish_porridge": 2}}'::jsonb, '[{"s": null, "t": "나는 어죽 한 그릇을 떠서 단비 앞에 내밀었다. 단비는 숟가락을 받지 않고 담요 밖으로 입만 쏙 내밀었다."}, {"s": "red_moon_cult:danbi", "t": "손이 담요 밖으로 안 나와요. 떠 주세요, 네?"}, {"s": null, "t": "나는 숟가락으로 죽을 떠서 후후 불어 단비의 입에 넣어 주었다. 단비가 우물우물 씹다가 눈을 감았다."}, {"s": "red_moon_cult:danbi", "t": "앗, 뜨거워요. 아니, 맛있어요. 뜨거운데 맛있어요!"}, {"s": null, "t": "단비는 한 숟갈을 받을 때마다 투정을 하나씩 했다. 생선살이 크다, 국물이 많다, 숟가락이 차갑다. 투정을 하면서도 입은 꼬박꼬박 벌렸다."}, {"s": null, "t": "그릇이 반쯤 비었을 때 단비가 오른손을 담요 밖으로 꺼냈다. 무릎 위의 엿 꾸러미를 풀어 엿 한 가락을 꺼냈다."}, {"s": null, "t": "단비가 엿 가락을 걸상 모서리에 대고 똑 꺾었다. 한쪽은 꾸러미에 도로 넣고, 다른 반쪽을 기름종이에 싸서 내 손바닥에 올려놓았다."}, {"s": "red_moon_cult:danbi", "t": "이거 맡아 주세요. 오늘은 제가 못 먹으니까요. 다 나으면 돌려주셔야 해요. 그날 먹을 거예요."}, {"s": null, "t": "내가 반쪽을 받아 들고 머뭇거리자 단비가 고개를 저었다."}, {"s": "red_moon_cult:danbi", "t": "늘 드리는 쪽은 꾸러미에 넣었어요. 이건 제 몫이에요. …제 몫을 남한테 맡겨 보는 건 처음이에요."}, {"s": null, "t": "단비가 남은 죽을 다 받아먹고 담요를 어깨까지 내렸다. 얼굴에 핏기가 조금 돌아와 있었다."}, {"s": "red_moon_cult:danbi", "t": "그 걱정 많은 대장님한테는 귀가 운 거 말하지 마세요. 아시면 고찰 일을 다 내팽개치고 내려오셔서 밤새 제 오른쪽에 앉아 계실 거예요. 장부도 안 쓰시고요."}, {"s": null, "t": "나는 입을 다물겠다고 약속했다. 그 밤 나는 엿판 곁에 남아 화덕 불을 지켰다. 장터가 잠든 뒤로는 천막 자락이 바람에 펄럭이는 소리와 숯이 톡톡 튀는 소리만 들렸다. 단비는 자정 무렵 남은 어죽 한 그릇을 혼자 숟가락을 들고 비웠다."}, {"s": null, "t": "희뿌연 새벽빛이 모래 위로 번질 무렵 단비가 담요를 걷고 일어나 앉았다. 오른손을 내 쪽으로 쭉 내밀었다."}, {"s": "red_moon_cult:danbi", "t": "이제 안 울어요! 제 몫을 돌려주세요."}, {"s": null, "t": "나는 품에서 기름종이 꾸러미를 꺼내 단비의 손바닥에 올려 주었다. 단비가 종이를 풀어 엿 반쪽을 입에 넣었다. 오래 씹고 나서 단비가 웃었다. 이번에는 입꼬리가 끝까지 올라갔다."}, {"s": "red_moon_cult:danbi", "t": "맛있다. 오늘은 맛있는 날이에요."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_danbi_4', 'side', '연담·단비', '장 쉬는 날', '단비가 엿판 문을 하루 닫고 적사 황무지 모래 언덕에 올라 달을 보자고 한다. 달 아래에서 단비는 열네 살 서약 날 밤 이 언덕에서 엿을 다 녹도록 쥐고만 있었던 이야기를 웃지 않고 꺼낸다.', 'bone_market', 50, '{rg_danbi_3}'::text[], null, 1628, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "danbi", "stage": 4}'::jsonb where quest_id = 'rg_danbi_4';
delete from public.world_quest_steps where quest_id = 'rg_danbi_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_4', 1, '도시락', '도시락', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "하늘이 말갛게 갠 오후, 엿판 앞에 「장 쉼」이라고 쓴 나무패가 걸려 있었다. 이번 글씨는 반듯했다. 좌판 뒤에서 단비가 봇짐을 싸고 있었는데, 엿 꾸러미가 봇짐 맨 위에 얹혀 있었다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님! 저 그 뒤로 귀가 한 번도 안 울었어요. 어죽 덕인가 봐요. 장꾼들은 생선찜 맛을 들여서 날마다 졸라요."}, {"s": "red_moon_cult:danbi", "t": "그래서 오늘은 장을 쉬어요. 아픈 날 말고요, 그냥 쉬는 날! 엿 장사를 시작하고 처음이에요."}, {"s": null, "t": "나는 쉬는 날에는 뭘 하며 보낼 셈인지 떠보았다. 단비가 봇짐 끈을 오른손과 이로 묶다가 고개를 들었다."}, {"s": "red_moon_cult:danbi", "t": "몰라요. 그래서 {이름} 님을 부른 거잖아요. 무녀 할 땐 쉬는 날이 없었거든요. 제사 없는 날엔 액막이, 액막이 없는 날엔 축문 외우기였어요."}, {"s": "red_moon_cult:danbi", "t": "오늘 밤에 보름달이 뜬대요. 적사 황무지 모래 언덕에 올라가면 달이 장터에서 볼 때보다 훨씬 커 보여요. 우리 거기 가서 달을 봐요."}, {"s": null, "t": "단비가 봇짐을 메어 보다가 너무 가볍다는 듯 고개를 갸웃했다."}, {"s": null, "t": "나는 나무패 글씨가 이번에는 반듯하다고 했다. 단비가 엿판의 나무패를 오른손으로 톡 쳤다."}, {"s": "red_moon_cult:danbi", "t": "그럼요. 쉬는 날이니까 반듯하게 쓴 거예요. 비뚜름하게 쓰면 손님들이 장난인 줄 알고 문을 막 두드리거든요."}, {"s": null, "t": "맞은편 좌판의 장터 아낙이 육포를 자르다 말고 이쪽을 흘끔 보았다. 단비가 아낙에게 오른손을 흔들어 보였다."}, {"s": "red_moon_cult:danbi", "t": "아주머니, 오늘은 제 손님 다 가져가셔도 돼요! 대신 내일 돌려주셔야 해요!"}, {"s": null, "t": "아낙이 코웃음을 치며 육포 칼을 내려놓았다. 단비는 그 콧방귀까지 다 들었다는 듯 키득거렸다."}, {"s": "red_moon_cult:danbi", "t": "엿은 제가 쌌어요. 도시락은 {이름} 님이 싸 주세요. 나물밥이요! 사당 언덕 야령초로 지은 거요."}, {"s": "red_moon_cult:danbi", "t": "대장님은 고찰에 계세요. 오늘은 우리 둘이 가요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_4', 2, '미끄러지는 모래', '야령초 나물밥을(를) 만든다, 야령초 나물밥을(를) 넘긴다', '{"at": ["red_plain"], "tasks": [{"t": "craft", "items": ["herb_rice"], "n": 2}], "give": {"herb_rice": 2}}'::jsonb, '[{"s": null, "t": "적사 황무지의 붉은 모래 언덕은 해가 기울수록 빛깔이 짙어졌다. 바람이 불 때마다 언덕 마루에서 모래가 가는 물줄기처럼 흘러내렸다. 한낮의 열기가 아직 모래에 남아 신 밑창 너머로 발바닥이 후끈했다."}, {"s": null, "t": "단비가 앞장서서 언덕을 올랐다. 발을 디딜 때마다 모래가 발밑에서 쓸려 내려갔고, 단비는 세 걸음 오르고 한 걸음 미끄러졌다."}, {"s": "red_moon_cult:danbi", "t": "어릴 땐 단숨에 올랐는데! 모래가 그새 더 미끄러워졌나 봐요!"}, {"s": null, "t": "단비가 오른손을 뒤로 뻗었다."}, {"s": null, "t": "나는 그 손을 잡아 끌어 올렸다. 단비는 언덕 마루에 올라설 때까지 내 손을 놓지 않았다."}, {"s": null, "t": "언덕 마루에서 아래를 내려다보니 사당 처마와 아랫마을 흙집 여섯 채가 작게 보였다. 그중 한 집 마당에서 엿을 고는 연기가 가늘게 피어오르고 있었다."}, {"s": "red_moon_cult:danbi", "t": "저기, 저 집이 언년 할머니 집이에요. 오늘도 엿을 고시네. 저 연기만 봐도 단내가 나는 것 같아요."}, {"s": null, "t": "나는 내려가 들러 보자고 했다. 단비가 고개를 저었다."}, {"s": "red_moon_cult:danbi", "t": "오늘은 안 들를래요. 엿을 받으러 온 날이 아니라 쉬러 온 날이잖아요. 할머니한테 가면 저 또 솥을 젓고 있을 거예요."}, {"s": null, "t": "단비는 연기를 오래 바라보았다. 웃고 있었지만 눈은 그 집 마당의 우물 쪽에 머물러 있었다."}, {"s": null, "t": "그때 언덕 반대편 비탈에서 모래가 툭툭 솟아올랐다. 모래 속에 몸을 묻고 있던 것들이 해 질 녘 냄새를 맡고 머리를 내밀고 있었다."}, {"s": "red_moon_cult:danbi", "t": "어머, 저것들 또 나왔네! 도시락 냄새를 맡았나 봐요. {이름} 님, 달을 볼 때까지 저것들 좀 쫓아 주세요. 저는 여기서 엿을 지키고 있을게요."}, {"s": null, "t": "단비가 봇짐을 끌어안고 모래 위에 털썩 앉았다. 소매 속 방울이 짤랑 울렸다."}, {"s": "red_moon_cult:danbi", "t": "다 쫓으면 여기서 달이 뜰 때까지 쉬어요. 달은요, 기다려야 떠요. 서두르면 안 뜬다니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_4', 3, '녹은 엿', '적사 황무지의 요괴를 물리친다, 적사 황무지에서 쉰다', '{"at": ["red_plain"], "tasks": [{"t": "win", "r": ["red_plain"], "n": 6}, {"t": "rest", "r": ["red_plain"], "n": 1}]}'::jsonb, '[{"s": null, "t": "비탈의 것들을 쫓아내고 돌아오니 단비가 모래 위에 나물밥 두 그릇을 나란히 꺼내 놓고 있었다. 둘이 나란히 앉아 나물밥을 먹는 동안 해가 완전히 졌다. 야령초의 쌉쌀한 향이 밥알 사이에서 올라왔고, 볕이 빠진 모래는 금세 식어 엉덩이 밑이 썰렁해졌다."}, {"s": null, "t": "모래 언덕 너머로 보름달이 올라왔다. 장터에서 보던 것보다 두 배는 커 보였다. 붉은 모래가 달빛을 받아 은빛으로 바뀌었다."}, {"s": "red_moon_cult:danbi", "t": "커요… 저거 보세요, 진짜 크다."}, {"s": null, "t": "단비가 달을 보며 엿 꾸러미를 풀었다. 엿 한 가락을 꺼내 쥐었는데, 입에 넣지 않고 손에 쥔 채로 가만히 있었다."}, {"s": "red_moon_cult:danbi", "t": "열네 살 때요. 서약한 날 밤에 여기 왔었어요. 혼자서요."}, {"s": null, "t": "단비의 목소리에 웃음기가 없었다. 단비는 달에서 눈을 떼지 않았다."}, {"s": "red_moon_cult:danbi", "t": "서약이 끝나고 교주님이 엿 한 가락을 주셨어요. 무녀가 된 상이라고요. 그걸 들고 장터를 빠져나와서 여기까지 걸어왔어요. 왜 왔는지는 모르겠어요. 그냥… 장터에서 멀어지고 싶었나 봐요."}, {"s": "red_moon_cult:danbi", "t": "입에 넣으려고 했는데 안 넘어가더라고요. 입안에서 종이 타는 냄새가 났거든요. 그 이름 태운 냄새요. 그래서 그냥 쥐고만 있었어요. 달이 뜰 때부터 질 때까지요. 엿이 손바닥에서 다 녹아서 손가락 사이로 줄줄 흘렀어요."}, {"s": null, "t": "단비가 오른손을 펴 보였다. 손바닥 위의 엿 가락은 아직 단단했다."}, {"s": "red_moon_cult:danbi", "t": "그 뒤로 엿을 늘 품에 넣고 다녀요. 다 먹으면 괜찮은 날이고, 못 먹으면 안 괜찮은 날이고요. 그걸로 알아요. 제가 괜찮은지, 아닌지."}, {"s": null, "t": "나는 아무 말도 하지 않았다. 단비의 오른쪽에 앉아 단비가 보는 달을 함께 보았다."}, {"s": null, "t": "달이 한 뼘쯤 올라왔을 때 단비가 엿 가락을 무릎에 대고 똑 꺾었다. 반쪽을 입에 넣고 오래 씹었다. 이번에는 넘어갔다."}, {"s": "red_moon_cult:danbi", "t": "…오늘은 괜찮은 날이네요."}, {"s": null, "t": "단비는 남은 반쪽을 기름종이에 쌌다. 늘 따로 챙겨 두던 꾸러미를 이번에는 제 품에 넣었다."}, {"s": "red_moon_cult:danbi", "t": "이건 그냥 들고 내려갈래요. 이 얘기, 대장님한테도 안 했거든요. 이 얘기를 들은 사람이 하나 더 생겼다는 거… 그거 표시해 두고 싶어서요."}, {"s": null, "t": "단비가 품에 넣은 꾸러미를 오른손으로 꾹 눌렀다. 차가워진 밤바람이 불자 모래가 소리 없이 무너져 내렸다. 우리는 달이 언덕 너머로 기울 때까지 그 자리에 앉아 있었다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_danbi_5', 'side', '연담·단비', '반쪽', '큰 장이 끝나는 밤, 단비가 장터 이웃들에게 생선찜을 돌리자고 한다. 모두 돌아간 뒤 단비는 마지막 엿을 반으로 꺾어 내 오른손에 쥐여 준다.', 'bone_market', 50, '{rg_danbi_4}'::text[], null, 1629, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "danbi", "stage": 5}'::jsonb where quest_id = 'rg_danbi_5';
delete from public.world_quest_steps where quest_id = 'rg_danbi_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_5', 1, '장 끝나는 밤', '장 끝나는 밤', '{"at": ["bone_market"]}'::jsonb, '[{"s": null, "t": "백골 장터의 큰 장이 마지막 날을 맞고 있었다. 짐 수레들이 하나둘 짐을 꾸리기 시작했고, 엿판 위 엿 항아리는 바닥이 보였다. 해가 짧아진 철이라 천막 그림자가 길게 늘어졌고, 천막을 걷는 소리가 여기저기서 펄럭였다."}, {"s": null, "t": "단비가 엿판에 기대어 장부를 넘기고 있었다. 장부는 어느새 세 권째였다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님, 이것 좀 보세요! 그동안 {이름} 님이 지고 오신 걸 우리 깐깐쟁이 대장님이 다 적어 놓으셨어요. 생선포, 나물밥, 매운탕, 어죽, 생선찜… 그 밖에도 엄청 많아요. 장부 세 권 통틀어서 {이름} 님 줄이 제일 길어요."}, {"s": null, "t": "단비가 장부를 덮고 장터를 둘러보았다. 맞은편 육포 좌판, 옆자리 국밥 솥, 바늘 장수의 천막이 하나씩 걷히고 있었다."}, {"s": "red_moon_cult:danbi", "t": "장 끝나는 밤엔 다들 짐을 싸느라 저녁을 못 먹거든요. 그래서 오늘은 제가 장터 사람들 저녁을 대접하려고요. 생선찜으로요. 엿판을 차리고 처음 맞는 큰 장 끝이잖아요."}, {"s": null, "t": "그때 장터 가운데 길로 대호법 사마겸이 성큼성큼 걸어왔다. 거한은 엿판 앞을 지나다 바닥이 드러난 항아리를 흘끗 내려다보았다."}, {"s": "red_moon_cult:sama", "t": "다 팔았구나. 엿판 앞에서 다들 오래 서서 씹는다더니, 헛말은 아니었군."}, {"s": null, "t": "단비가 빈 항아리를 끌어안고 의기양양하게 턱을 치켜들었다."}, {"s": "red_moon_cult:danbi", "t": "오래 씹을 것도 같이 파니까요, 대호법님!"}, {"s": null, "t": "사마겸은 무어라 대꾸하려다 그만두고 큼지막한 손을 한 번 휘젓고는 지나갔다. 단비가 그 등을 보며 킥 웃었다."}, {"s": null, "t": "엿판 곁에 여운비의 짐 꾸러미가 보이지 않았다. 단비가 고찰 쪽 하늘을 한 번 올려다보았다."}, {"s": "red_moon_cult:danbi", "t": "대장님은 고찰에서 첫눈 끈을 보시고 내일 아침에야 내려오신대요. 그러니까 오늘 저녁 대접은 저 혼자 내는 거예요."}, {"s": null, "t": "단비가 장부를 품에 넣고 빈 항아리 뚜껑을 덮었다. 뚜껑 위 작은 손자국을 오른손 엄지로 한 번 쓸었다."}, {"s": "red_moon_cult:danbi", "t": "생선찜은요, 생선이랑 야령초를 겹겹이 깔고 쪄야 해요. 그러니까 둘 다 넉넉해야 해요."}, {"s": "red_moon_cult:danbi", "t": "생선은 월식성 바위 해안에서 낚고, 야령초는 사당 언덕에서 뜯어요. 이번엔 같이 가요! 방울은 이제 소매에 넣고 다니니까 걱정 마세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_5', 2, '이웃 저녁', '적월교 월식성에서 낚시를 한다, 적사 황무지에서 야령초을(를) 모은다', '{"at": ["bone_market"], "tasks": [{"t": "fish", "r": ["red_moon_fort"], "n": 3}, {"t": "gather", "items": ["herb"], "r": ["red_plain"], "n": 4}]}'::jsonb, '[{"s": null, "t": "생선과 야령초를 들고 돌아오니 장터에는 모닥불만 남아 있었다. 장작이 튈 때마다 불티가 별처럼 밤하늘로 날아올랐다. 단비가 빌린 찜솥을 화덕에 걸었고, 나는 단비의 오른쪽에 서서 생선을 손질했다."}, {"s": null, "t": "단비는 오른손으로 야령초를 솥 바닥에 깔다가 나를 돌아보았다. 내가 오른쪽에 서 있는지 단비는 이제 굳이 확인하지 않았다."}, {"s": "red_moon_cult:danbi", "t": "처음 엿판을 차린 날 기억나세요? 손님이 엿만 먹고 가 버렸잖아요. 그날 저 진짜 울 뻔했어요."}, {"s": null, "t": "나는 그날 단비가 웃고 있었다고 했다. 단비가 야령초를 깔던 손을 멈췄다."}, {"s": "red_moon_cult:danbi", "t": "웃으면서 울 뻔한 거예요. 저 그런 건 잘하거든요. 무녀 때 배운 거예요. …근데 요즘은 잘 안 해요. 안 해도 되니까요."}, {"s": null, "t": "찜솥에서 생선 살 익는 냄새와 야령초 향이 어우러져 퍼지자 짐을 싸던 장터 사람들이 하나둘 고개를 돌렸다. 장터 아낙이 제일 먼저 그릇을 들고 왔다."}, {"s": "q:sx_ep_marketwife", "t": "엿 장수가 저녁을 다 낸다고? 장 끝나는 밤에? 이거 장부에 적어 둬야겄네."}, {"s": null, "t": "단비가 국자를 든 채 오른손을 홰홰 내저었다."}, {"s": "red_moon_cult:danbi", "t": "적지 마세요, 아주머니! 오늘 건 값이 없어요."}, {"s": null, "t": "장터 아낙이 그릇을 품에 끌어안고 고개를 꼿꼿이 쳐들었다."}, {"s": "q:sx_ep_marketwife", "t": "값이 없으면 내가 미안해서 못 먹지. 내일 육포 한 줌 놓고 갈 거유."}, {"s": null, "t": "단비가 국자 끝으로 아낙의 그릇 가장자리를 톡 건드리며 웃었다."}, {"s": "red_moon_cult:danbi", "t": "그럼 그건 값이 아니라 선물이네요. 선물은 받을게요!"}, {"s": null, "t": "장터 아낙이 혀를 차며 그릇을 들고 줄 맨 앞에 섰다. 그 뒤로 국밥 솥 장수와 바늘 장수가 그릇을 들고 따라섰다."}, {"s": null, "t": "나는 찜솥 손잡이를 잡고 있었고, 단비는 그 오른쪽에서 그릇을 하나씩 받아 들었다. 줄이 길어질수록 단비의 목소리가 쨍쨍해졌다."}, {"s": null, "t": "단비가 찜솥 뚜껑을 들어 올리며 나를 보았다. 김 너머로 단비의 얼굴이 환했다."}, {"s": "red_moon_cult:danbi", "t": "두 솥을 쪄서 싹 다 돌려요. 그릇은 제가 나를게요. 저 한 손으로도 그릇은 잘 날라요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_danbi_5', 3, '단비의 엿 반쪽', '약초 생선찜을(를) 만든다, 약초 생선찜을(를) 넘긴다', '{"at": ["bone_market"], "tasks": [{"t": "craft", "items": ["herb_fish_steam"], "n": 2}], "give": {"herb_fish_steam": 2}}'::jsonb, '[{"s": null, "t": "생선찜 두 솥이 모두 비었다. 장터 사람들은 빈 그릇을 돌려주며 저마다 엿판 앞에 무언가를 하나씩 놓고 갔다. 육포 한 줌, 바늘 한 쌈, 국밥 솥 장수의 무 두 개였다."}, {"s": null, "t": "모닥불이 하나둘 꺼지고 장터가 조용해졌다. 사그라든 불더미에서 젖은 재 냄새가 났다. 단비가 엿판 앞에 쌓인 것들을 오른손으로 하나씩 쓰다듬었다."}, {"s": "red_moon_cult:danbi", "t": "값은 안 받는다고 했는데… 다들 값을 놓고 가셨네."}, {"s": null, "t": "단비가 엿 항아리 뚜껑을 열었다. 항아리 바닥에 엿 한 가락이 남아 있었다. 오늘 장의 마지막 엿이었다."}, {"s": null, "t": "단비가 엿 가락을 꺼내 손바닥에 올려놓고 말없이 내려다보았다. 뚜껑 위 작은 손자국에 달빛이 내려앉아 있었다."}, {"s": "red_moon_cult:danbi", "t": "마지막 엿은 늘 반으로 꺾어요. 반쪽은 제가 먹고, 반쪽은 대장님 몫이고요. 엿판을 차린 날부터 하루도 안 빼먹었어요."}, {"s": null, "t": "단비가 엿을 좌판 모서리에 대고 똑 꺾었다. 엿이 반으로 갈라졌다. 단비는 한쪽을 제 입에 넣었다."}, {"s": null, "t": "남은 반쪽을 기름종이에 싸려던 단비의 손이 멈췄다. 단비가 고개를 들어 나를 보았다. 나는 단비의 오른쪽에 서 있었다."}, {"s": null, "t": "단비가 기름종이를 내려놓았다. 반쪽 엿을 맨손으로 쥐고 내 오른손을 잡아당겼다. 내 손바닥을 펴서 엿을 올리고, 손가락을 하나씩 오므려 쥐여 주었다."}, {"s": "red_moon_cult:danbi", "t": "반쪽은 원래 대장님 몫인데… 오늘은 {이름} 님 거예요."}, {"s": null, "t": "나는 손 안의 엿을 내려다보았다. 엿은 단비의 손바닥 온기로 조금 말랑해져 있었다. 나는 장터 안쪽 그 깐깐한 장부쟁이 몫은 어쩌느냐고 물었다."}, {"s": "red_moon_cult:danbi", "t": "내일 아침에 첫 가락을 통째로 드리면 돼요. 통째로 받으시면 귀 끝이 빨개지실걸요? 그것도 보고 싶어요."}, {"s": null, "t": "단비가 웃었다. 웃음 끝이 조금 떨렸다. 단비는 내 손을 놓지 않은 채 오른손에 힘을 꼭 주었다."}, {"s": "red_moon_cult:danbi", "t": "이건 아무나 못 받는 거예요. 단비의 엿 반쪽이요. 장날마다 제 오른쪽에 서 준 사람 거예요. 귀 울던 날 제 몫을 맡아 준 사람 거고, 달을 보던 밤에 그 얘기를 들어 준 사람 거예요."}, {"s": "red_moon_cult:danbi", "t": "먹어도 돼요. 아껴 두셔도 되고요. 아껴 두시면 제가 또 꺾어 드릴게요. 반쪽은 다 먹어도 또 생기거든요."}, {"s": null, "t": "나는 엿을 입에 넣었다. 단비가 내 오른쪽 어깨에 이마를 톡 기댔다가 금세 떼었다. 소매 속 방울이 짤랑 울렸다. 그 소리는 텅 빈 장터 끝까지 멀리 갔다."}]'::jsonb, '{"gil": 205, "title": "rg_danbi", "items": {"hf_rg_danbi_stall": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_unbi_1', 'side', '연담·여운비', '다시 메는 썰매 끈', '겨우내 삭은 고찰 썰매 끈을 갈 사람으로 맹주가 여운비를 불러올린다. 앞자리는 이제 제 자리가 아니라면서도 끈만은 제 손으로 보겠다는 여운비가, 끈 감으로 쓸 강화 요수 가죽을 주문한다.', 'iron_monastery', 50, '{mde_unbi_2}'::text[], null, 1630, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_unbi_1';
delete from public.world_quest_steps where quest_id = 'rg_unbi_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_1', 1, '삭은 끈', '삭은 끈', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "철벽 고찰 연무장 뒤 헛간 문이 활짝 열려 있었다. 늦겨울 찬바람이 헛간 안까지 휘돌았고, 묵은 가죽에서 쿰쿰한 냄새가 올라왔다. 헛간 바닥에 썰매 끈이 뱀 허물처럼 길게 늘어져 있었다."}, {"s": null, "t": "끈 한가운데에 여운비가 쪼그려 앉아 있었다. 여운비는 끈을 한 뼘씩 손바닥으로 훑어 가다가, 어느 한 자리에서 끈을 양손으로 잡아당겼다. 끈이 툭 소리를 내며 끊어졌다."}, {"s": null, "t": "산문 쪽에서 빗자루를 든 혜각이 지나가다 헛간을 들여다보았다."}, {"s": "north_league:hyegak", "t": "허허, 또 하나 끊으셨네. 손님, 우리 끈 귀신께서 아침부터 끈만 끊고 계십니다. 고치시는 건지 부수시는 건지, 소승은 통 모르겠어요."}, {"s": null, "t": "혜각이 웃으며 산문 쪽으로 사라졌다. 여운비가 끊어진 끈 두 토막을 들고 고개를 들었다."}, {"s": "north_league:yeo", "t": "당신이구려. 맹주께서 부르셨소. 겨우내 썰매 끈이 다 삭았다 하셔서. …끊어질 끈은 미리 끊어 보는 거요. 길 위에서 끊어지는 것보단 낫지 않소."}, {"s": null, "t": "나는 장터의 엿 장부를 떠올렸다. 장부를 두고 올라와도 되느냐고 하자 여운비가 끈 토막을 무릎에 내려놓았다."}, {"s": "north_league:yeo", "t": "장부는 지금 그 엿 장수가 쓰고 있소. 글씨가 죄다 오른쪽으로 기울었을 거요. 내려가면 고쳐야겠소."}, {"s": "north_league:yeo", "t": "앞자리는 이제 내 자리가 아니오. 바람을 늦게 읽는 사람이 앞에 서면 뒤가 다 묻히는 법이오. 그래도 끈만은 내가 보겠소. 끈은 눈이 아니라 손으로 보는 거니까."}, {"s": null, "t": "여운비가 끊어진 끈의 단면을 엄지로 쓸었다. 가죽이 바스러져 가루가 떨어졌다."}, {"s": "north_league:yeo", "t": "요수 가죽을 옻에 먹여 질기게 만든 끈이라야 하오. 그런데 고찰엔 무두질하는 손이 없구려. 내 손은 매듭밖에 모르고."}, {"s": null, "t": "여운비가 고개를 들어 나를 보았다. 남은 왼 눈이 내 얼굴에서 조금 아래로 내려가 내 신발에 머물렀다. 신 끈 하나가 풀려 있었다."}, {"s": null, "t": "여운비가 그쪽으로 손을 뻗다가 그만두었다. 손은 다시 무릎 위의 끈 토막으로 돌아갔다."}, {"s": "north_league:yeo", "t": "설피골에 요수 가죽이 나오오. 가죽은 내가 직접 골라야 하니 같이 가겠소. 털이 촘촘하고 배 쪽이 두꺼운 놈이 좋소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_1', 2, '손으로 고르는 가죽', '설피골에서 요수 가죽을(를) 모은다', '{"at": ["snow_hollow"], "tasks": [{"t": "gather", "items": ["beast_hide"], "r": ["snow_hollow"], "n": 4}]}'::jsonb, '[{"s": null, "t": "설피골 바람은 고찰보다 매서웠다. 숨을 들이쉴 때마다 콧속이 쩍쩍 달라붙었다. 눈이 쌓인 비탈 아래에서 여운비가 내가 모아 온 가죽을 한 장씩 눈 위에 펼쳤다."}, {"s": null, "t": "여운비는 가죽을 눈으로 보지 않았다. 손바닥을 가죽 위에 얹고 천천히 쓸어 내리면서 두께를 가늠했다."}, {"s": "north_league:yeo", "t": "이건 쓸 만하오. 이것도. …이건 등가죽이라 얇구려. 끈 말고 덧대는 데나 쓰겠소."}, {"s": null, "t": "바람이 휙 불어 가죽 한 장이 눈 위를 미끄러졌다."}, {"s": null, "t": "가죽은 여운비의 오른쪽으로 날아갔다. 여운비는 그쪽을 보지 못하고 왼쪽만 더듬었다."}, {"s": null, "t": "나는 오른쪽으로 날아간 가죽을 잡아 여운비의 손에 쥐여 주었다. 여운비가 가죽을 받아 들고 잠깐 말이 없었다."}, {"s": "north_league:yeo", "t": "…그쪽은 내가 못 보오. 장터에선 그 시끄러운 엿 장수가 그쪽 소리를 일러 주는데. 여긴 그 입이 없구려."}, {"s": null, "t": "여운비가 가죽을 무릎에 올려놓았다. 손끝으로 가죽의 털결을 거슬러 쓸었다."}, {"s": "north_league:yeo", "t": "아버지가 늘 그러셨소. 썰매 끈 하나에 사람 하나가 매달린다고. 그러니 끈은 남이 만든 걸 믿지 말고 제 손으로 당겨 보라 하셨지."}, {"s": null, "t": "나는 그럼 이 가죽도 손수 다듬을 작정인지 물었다. 여운비가 털결을 쓸던 손을 거두었다."}, {"s": "north_league:yeo", "t": "다듬는 건 당신이 하시오. 나는 당겨 보겠소. 당신이 다듬은 걸 내가 당겨서 안 끊어지면… 그때부터 믿겠소."}, {"s": null, "t": "여운비가 가죽 한 장을 내 무릎에 툭 올려놓았다. 손바닥으로 쓸어 보라는 뜻이었다."}, {"s": null, "t": "여운비가 옆구리에 찬 작은 단지를 끌러 내게 내밀었다. 고찰에서 얻어 온 옻이었다. 마개를 따자 시큼하고 알싸한 옻 냄새가 찬 공기 속으로 번졌다."}, {"s": "north_league:yeo", "t": "두 장이면 끈 열두 줄은 나오오. 다듬어서 주시오. 고찰 헛간에서 당겨 보리다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_1', 3, '당겨 보는 끈', '강화 요수 가죽을(를) 만든다, 강화 요수 가죽을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "craft", "items": ["reinforced_leather"], "n": 2}], "give": {"reinforced_leather": 2}}'::jsonb, '[{"s": null, "t": "헛간 구석 화로에서 숯이 빨갛게 달아오르는 사이, 여운비가 강화 요수 가죽을 끈 굵기로 잘랐다. 칼이 지나갈 때마다 단단한 가죽이 사각사각 소리를 냈다."}, {"s": null, "t": "끈 열두 줄이 다 나오자 여운비가 첫 줄의 한쪽 끝을 내게 건넸다. 반대쪽 끝은 여운비가 쥐었다."}, {"s": "north_league:yeo", "t": "당기시오. 힘껏 당기시오!"}, {"s": null, "t": "우리는 끈 양 끝을 잡고 헛간 끝과 끝으로 물러섰다. 끈이 팽팽해졌다."}, {"s": null, "t": "여운비가 발을 버티고 몸을 뒤로 젖혔다. 끈은 끊어지지 않았다."}, {"s": null, "t": "여운비는 열두 줄을 모두 그렇게 당겨 보았다. 한 줄도 끊어지지 않았다. 헛간 안이 냉골인데도 마지막 줄을 내려놓은 여운비의 이마에는 땀이 맺혀 있었다."}, {"s": null, "t": "나는 이제 믿느냐고 물었다. 여운비가 끈 열두 줄을 한 줄씩 사려 고리에 걸었다."}, {"s": "north_league:yeo", "t": "길에 나가 봐야 아는 거요. 헛간에서 멀쩡하던 끈이 눈길에서 끊어지기도 하니까."}, {"s": null, "t": "칭찬은 아니었다. 여운비는 끈을 다 걸고 나서 헛간 문간에 걸터앉았다. 나도 그 곁에 앉았다. 여운비는 나를 자기 왼쪽에 앉게 하려고 엉덩이를 조금 옮겼다."}, {"s": "north_league:yeo", "t": "고찰 썰매가 열두 대요. 끈은 철마다 다시 봐야 하오. 눈이 녹을 때 한 번, 첫눈이 올 때 한 번. 그 사이에도 끊어질 건 끊어지고."}, {"s": null, "t": "여운비가 무릎 위에 손을 얹고 산 아래를 내려다보았다. 골짜기마다 녹다 만 눈이 희끗희끗 남아 있었다."}, {"s": "north_league:yeo", "t": "…앞으로도 부탁해도 되겠소? 가죽이든 끈이든 신이든. 가죽을 다룰 줄 아는 손이 고찰에 하나만 있어도 썰매꾼들이 덜 춥소."}, {"s": null, "t": "나는 그러겠다고 했다. 여운비가 짧게 숨을 내쉬었다. 그러고는 내 발을 내려다보았다. 신 끈은 아직 풀려 있었다."}, {"s": "north_league:yeo", "t": "…그 끈, 매시오. 눈길에서 밟히면 넘어지오."}, {"s": null, "t": "나는 신 끈을 고쳐 맸다. 여운비는 그동안 산 아래만 보고 있었다. 내가 다 매고 나서야 여운비가 일어섰다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_unbi_2', 'side', '연담·여운비', '오른쪽이 비는 길', '새 끈을 단 썰매를 끌고 설피골 시험길에 나선다. 여운비가 보지 못하는 오른쪽으로 썰매가 기울자 내가 먼저 붙잡고, 여운비는 오랜만에 「…나쁘지 않소」를 꺼낸다.', 'iron_monastery', 50, '{rg_unbi_1}'::text[], null, 1631, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "unbi", "stage": 2}'::jsonb where quest_id = 'rg_unbi_2';
delete from public.world_quest_steps where quest_id = 'rg_unbi_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_2', 1, '미끄러운 신', '미끄러운 신', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "산문 처마 끝 고드름에서 물방울이 똑똑 떨어지는 맑은 아침이었다. 고찰 산문 앞에 빈 썰매 한 대가 놓여 있었다."}, {"s": null, "t": "새 끈이 썰매 앞에 반듯하게 매여 있었다. 여운비가 썰매 곁에 서서 끈 매듭을 하나씩 손끝으로 눌러 보고 있었다."}, {"s": "north_league:yeo", "t": "왔구려. 당신이 다듬어 준 가죽으로 썰매 열두 대 끈을 다 갈았소. 남은 자투리로는 썰매꾼들 장갑 손바닥을 덧댔고. 다들 손이 덜 시리다 하더이다."}, {"s": null, "t": "여운비가 썰매 끈을 한 번 당겨 보고 손을 털었다."}, {"s": "north_league:yeo", "t": "오늘은 끈을 길에 내보낼 거요. 설피골 시험길로. 짐 대신 돌을 싣고 끝까지 끌어 보겠소."}, {"s": null, "t": "나는 끈 한 줄을 집어 어깨에 걸어 보았다. 여운비가 그것을 보다가 내 발로 눈을 내렸다."}, {"s": "north_league:yeo", "t": "그 신으론 안 되오. 바닥이 매끄러워서 눈길에선 미끄러지오. 썰매를 끄는 사람 발이 미끄러지면 끈이 아무리 질겨도 소용없소."}, {"s": "north_league:yeo", "t": "고찰 썰매꾼들 신도 바닥이 다 닳았소. 가죽 미투리 두 켤레만 지어 주시오. 한 켤레는 당신이, 한 켤레는 내가 신어 보겠소. 썰매꾼들한테 신기기 전에 우리가 먼저 미끄러져 봐야 하지 않겠소."}, {"s": null, "t": "여운비가 제 발을 내려다보았다. 여운비의 신도 바닥이 반들반들했다."}, {"s": null, "t": "나는 여운비의 신부터 고치지 그랬느냐고 했다. 여운비가 발을 슬쩍 뒤로 물렸다."}, {"s": "north_league:yeo", "t": "내 신은 맨 나중이오. 썰매꾼들 신을 다 보고 나서야 내 신을 보오."}, {"s": "north_league:yeo", "t": "그러다 보면 늘 못 보고 넘어갔소. 그러니 이번엔 같이 짓자는 거요. 당신 것과 내 것을, 한꺼번에."}, {"s": null, "t": "여운비가 그 말을 하고 썰매 끈 쪽으로 고개를 돌렸다. 그 뒤로 한동안 끈 매듭만 만지작거렸다."}, {"s": "north_league:yeo", "t": "설피골 요수 가죽에 수향 갈대를 엮어 바닥을 대면 눈을 잘 움켜쥐오. 가죽은 지난번에 남은 걸 쓰시구려."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_2', 2, '기우는 썰매', '가죽 미투리을(를) 만든다, 가죽 미투리을(를) 넘긴다', '{"at": ["snow_hollow"], "tasks": [{"t": "craft", "items": ["s2_swift"], "n": 2}], "give": {"s2_swift": 2}}'::jsonb, '[{"s": null, "t": "우리는 새 미투리를 신고 설피골 시험길에 들어섰다. 미투리 바닥의 갈대가 눈을 뽀드득뽀드득 움켜쥐었다. 바늘 같은 찬 공기에 귓불이 얼얼했다."}, {"s": null, "t": "썰매 끈 두 줄 가운데 왼쪽 줄은 여운비가, 오른쪽 줄은 내가 어깨에 걸었다. 돌을 실은 썰매가 눈 위를 스르륵 미끄러졌다."}, {"s": "north_league:yeo", "t": "걸음을 맞추시오. 당신이 빠르면 썰매가 내 쪽으로 돌고, 내가 빠르면 당신 쪽으로 도니까."}, {"s": null, "t": "비탈을 하나 내려갈 때였다. 길 오른쪽 가장자리가 눈 처마처럼 비어져 나와 있었다. 썰매 오른쪽 날이 그 처마를 밟았고, 썰매가 오른쪽으로 크게 기울었다."}, {"s": null, "t": "여운비는 그쪽을 보지 못했다. 여운비가 앞으로 계속 끄는 사이 썰매 짐이 와르르 오른쪽으로 쏠렸다."}, {"s": null, "t": "나는 끈을 놓고 썰매 오른쪽으로 몸을 던졌다. 어깨로 썰매 옆구리를 받치자 기울던 썰매가 쿵 소리를 내며 다시 바로 섰다."}, {"s": "north_league:yeo", "t": "…뭐요! 방금 무슨 소리요?"}, {"s": null, "t": "여운비가 고개를 왼쪽으로 크게 돌려 그제야 나를 보았다. 내 어깨에 눈이 잔뜩 묻어 있었다."}, {"s": null, "t": "나는 오른쪽 처마를 밟았다고 했다. 여운비가 썰매 오른쪽 날 아래를 손으로 더듬었다. 무너진 눈 처마가 손에 만져졌다."}, {"s": "north_league:yeo", "t": "내가 먼저 봤어야 하는 자리였소. 앞에 서던 때 같았으면 술이 먼저 알려 줬을 텐데."}, {"s": null, "t": "여운비가 손에 묻은 눈을 털었다. 그러고는 내 어깨의 눈을 손바닥으로 툭툭 털어 주었다."}, {"s": "north_league:yeo", "t": "…나쁘지 않소."}, {"s": null, "t": "여운비가 등을 돌려 다시 끈을 어깨에 걸었다. 귀 끝이 빨갰다. 추위 탓만은 아닌 듯했다."}, {"s": "north_league:yeo", "t": "시험길 끝까지 가 봅시다. 끝에 눈 처마가 또 있는지 살펴야 하오. 이번엔 당신이 오른쪽 길가를 보며 가시오. 끝에 닿으면 좀 쉬었다 갑시다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_2', 3, '오른쪽에 선 사람', '설피골을(를) 살핀다, 설피골에서 쉰다', '{"at": ["snow_hollow"], "tasks": [{"t": "search", "r": ["snow_hollow"], "n": 2}, {"t": "rest", "r": ["snow_hollow"], "n": 1}]}'::jsonb, '[{"s": null, "t": "시험길 끝은 얼음 못가 바위 그늘이었다. 못을 덮은 얼음이 이따금 쩡, 쩡 하고 울었다. 우리는 썰매를 세우고 바위 아래에 나란히 앉았다."}, {"s": null, "t": "여운비가 품에서 대나무 잎에 싼 주먹밥 두 개를 꺼냈다. 혜각이 싸 준 것이었는데, 품의 온기로 아직 미지근했다."}, {"s": null, "t": "여운비가 주먹밥 하나를 내게 건넸다."}, {"s": null, "t": "나는 여운비의 오른쪽에 앉아 있었다. 여운비는 내게 주먹밥을 건네려고 몸을 오른쪽으로 크게 돌려야 했다."}, {"s": "north_league:yeo", "t": "고찰 사람들은 다들 내 왼쪽에 서오. 내가 보는 쪽이니까. 그래야 내가 마음을 놓는 줄로들 아오."}, {"s": null, "t": "나는 그럼 왼쪽으로 옮겨 앉겠다고 했다. 여운비가 고개를 저었다."}, {"s": "north_league:yeo", "t": "아니오. …거기 있으시오."}, {"s": null, "t": "나는 일어서려던 무릎을 도로 내렸다. 여운비가 주먹밥 하나를 내 쪽으로 조금 더 밀어 주었다."}, {"s": null, "t": "여운비는 주먹밥을 한 입 베어 물고 천천히 씹었다."}, {"s": "north_league:yeo", "t": "안 보이는 쪽이 비어 있으면, 거기서 뭐가 올지 몰라 늘 어깨가 굳소. 그런데 오늘은 그쪽에 당신이 있었구려. 썰매가 기우는 것도 당신이 먼저 잡았고."}, {"s": "north_league:yeo", "t": "비어 있지 않으면… 어깨가 덜 굳더이다. 그걸 오늘 알았소."}, {"s": null, "t": "여운비가 주먹밥을 마저 먹고 대나무 잎을 반듯하게 접었다. 접은 잎을 품에 넣었다."}, {"s": null, "t": "해가 기울어 얼음 못 위로 푸른 그늘이 번지자 우리는 썰매를 돌려 고찰로 향했다. 끈을 다시 어깨에 걸 때 여운비가 오른쪽 줄을 턱으로 가리켰다."}, {"s": "north_league:yeo", "t": "돌아가는 길도 당신이 그쪽이오. 끈은 오늘 안 끊어졌고, 신도 안 미끄러졌소. 그거면 됐소."}, {"s": null, "t": "「그거면 됐소」는 여운비가 「나쁘지 않소」 다음으로 아끼는 말이라고, 언젠가 단비가 손가락을 꼽으며 일러 준 적이 있었다. 나는 그 말을 마음속으로 하나 더 세었다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_unbi_3', 'side', '연담·여운비', '신 끈', '썰매꾼들이 신을 행전 짚신을 함께 짓는다. 다 지은 신을 신어 보는 날, 여운비가 늘 그랬듯 내 신 끈을 매 주려다, 이번에는 내가 먼저 여운비의 신 끈을 맨다.', 'iron_monastery', 50, '{rg_unbi_2}'::text[], null, 1632, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "unbi", "stage": 3}'::jsonb where quest_id = 'rg_unbi_3';
delete from public.world_quest_steps where quest_id = 'rg_unbi_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_3', 1, '끈 달린 신', '끈 달린 신', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "고찰 헛간 벽에 가죽 미투리 여러 켤레가 줄지어 걸려 있었다. 갈대 엮은 바닥에서 마른 풀 냄새가 났다."}, {"s": null, "t": "바닥마다 갈대가 촘촘히 엮여 있었다. 여운비가 그 앞에 서서 한 켤레씩 바닥을 뒤집어 보고 있었다."}, {"s": "north_league:yeo", "t": "당신이 지은 미투리를 신고 썰매꾼들이 고개를 두 번 넘었소. 한 사람도 안 미끄러졌다 하오. 장갑에 덧댄 가죽도 아직 멀쩡하고."}, {"s": null, "t": "여운비가 미투리 한 켤레를 벽에서 내려 발목 쪽을 손가락으로 벌려 보였다."}, {"s": "north_league:yeo", "t": "문제는 발목이오. 고갯마루엔 눈이 무릎까지 쌓이는데, 미투리는 발목이 낮아서 눈이 다 들어오오. 젖은 발로 하루를 걸으면 발가락을 잃소."}, {"s": "north_league:yeo", "t": "그래서 행전 짚신을 지어야 하오. 발목을 가죽으로 감싸고 끈으로 정강이까지 동여매는 신이오. 북령 썰매꾼들은 원래 그걸 신었소. 그런데 그 신을 짓던 고집 센 늙은 썰매꾼 영감이 몇 해 전에 세상을 뜨고 나서, 짓는 손이 끊겼구려."}, {"s": null, "t": "나는 짓는 법을 아느냐고 물었다. 여운비가 미투리를 도로 벽에 걸었다."}, {"s": "north_league:yeo", "t": "매는 법은 아오. 짓는 건 당신이 하시오. 매는 건 내가 가르쳐 드리리다."}, {"s": null, "t": "나는 칼을 쓰는 여운비가 가죽을 오리는 편이 빠르겠다고 했다. 여운비가 제 손바닥을 펴서 내려다보았다."}, {"s": "north_league:yeo", "t": "칼은 쥐어도 가죽칼은 다르오. 칼로 베듯 오리면 가죽이 울고 갈라지오. 당신 손이 낫소. 미투리만 봐도 알겠더이다."}, {"s": null, "t": "여운비는 그 말을 하고 미투리 한 켤레의 바닥을 엄지로 꾹 눌렀다. 갈대 엮음이 흐트러지지 않았다."}, {"s": "north_league:yeo", "t": "…나쁘다는 말은 아니오."}, {"s": "north_league:yeo", "t": "행전 짚신엔 갈대가 미투리보다 곱절은 들어가오. 수향 갈대가 설피골 개울가에 자라니, 같이 가서 베어 옵시다. 낫은 내가 들겠소."}, {"s": null, "t": "여운비가 헛간 구석에서 낫 하나를 집어 들었다. 칼날을 엄지로 한 번 쓸어 보고 허리에 찼다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_3', 2, '매는 법', '설피골에서 수향 갈대을(를) 모은다', '{"at": ["iron_monastery"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["snow_hollow"], "n": 4}]}'::jsonb, '[{"s": null, "t": "갈대를 한 짐 지고 고찰로 돌아오자 여운비가 헛간 바닥에 갈대를 펼쳤다. 언 갈대에 엉겨 있던 서리가 녹아 바닥이 금세 축축해졌다. 나는 그 곁에 앉아 요수 가죽을 발목 둘레로 오렸다."}, {"s": null, "t": "여운비는 내가 오리는 손을 말없이 보다가, 가죽 끝이 비뚤어지자 손가락으로 톡 짚었다."}, {"s": "north_league:yeo", "t": "거기, 한 푼 더. 발목 뼈가 닿는 자리요. 거기가 좁으면 사흘 뒤엔 피가 나오."}, {"s": null, "t": "가죽에 갈대 바닥을 대고 나자 여운비가 가죽 끈 한 가닥을 들었다. 신 발목의 고리에 끈을 꿰더니 엇갈려 감아 올렸다."}, {"s": "north_league:yeo", "t": "셋을 엇갈리고 넷째에서 한 번 감아 돌리시오. 그래야 걷는 동안 안 풀리오. 썰매 짐을 묶는 매듭이랑 같은 이치요."}, {"s": null, "t": "나는 끈 끝을 들여다보며 넷째 고리를 손끝으로 짚었다. 여운비가 끈 끝을 손가락에 감아 보였다."}, {"s": "north_league:yeo", "t": "셋까지는 발을 조이고, 넷째부터는 정강이를 조이오. 거기서 한 번 돌려 둬야 위아래가 따로 놀지 않소."}, {"s": null, "t": "나는 따라 해 보았다. 넷째 고리에서 끈이 꼬였다."}, {"s": null, "t": "여운비가 내 손 위에 제 손을 얹어 끈을 바로 돌려 주었다. 여운비의 손은 차갑고 단단했다."}, {"s": null, "t": "나는 이 매는 법을 누구에게 배웠느냐고 물었다. 여운비의 손이 잠깐 멈췄다."}, {"s": "north_league:yeo", "t": "아버지요. 첫 호송 날, 아버지가 내 신 끈을 매 주셨소. 무릎을 꿇고. 그러고는 그 위에 술을 달아 주셨지."}, {"s": "north_league:yeo", "t": "그 뒤로는 남의 신 끈이 풀려 있으면 못 참겠더이다. 당신 신 끈도 몇 번 매 줬고. 처음 고찰에서 썰매를 호송하던 날 밤에도."}, {"s": null, "t": "여운비가 손을 거두었다. 매듭은 바로 서 있었다."}, {"s": "north_league:yeo", "t": "두 켤레 지으시오. 다 지으면 산문 앞 눈밭에서 신어 봅시다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_3', 3, '무릎 꿇은 사람', '행전 짚신을(를) 만든다, 행전 짚신을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "craft", "items": ["s2_road"], "n": 2}], "give": {"s2_road": 2}}'::jsonb, '[{"s": null, "t": "밤새 내린 눈이 발목까지 쌓여 햇빛에 눈이 시렸다. 산문 앞 눈밭에 행전 짚신 두 켤레가 나란히 놓였다. 여운비가 한 켤레를 집어 내 발 앞에 내려놓았다."}, {"s": "north_league:yeo", "t": "신으시오. 끈은 내가 매리다."}, {"s": null, "t": "나는 신에 발을 넣었다. 여운비가 내 앞에 한쪽 무릎을 꿇고 끈을 집어 들었다. 그러다 여운비의 손이 멈췄다."}, {"s": null, "t": "여운비는 내 오른발 끈을 매려 하고 있었다. 오른쪽이었다. 여운비는 고개를 왼쪽으로 크게 꺾어야 끈 끝을 볼 수 있었다. 끈 끝이 자꾸 손가락 사이로 빠져나갔다."}, {"s": "north_league:yeo", "t": "…가만히 계시오. 금방 되오."}, {"s": null, "t": "나는 신을 신은 채 여운비의 손에서 끈을 받아 내가 맸다. 셋을 엇갈리고 넷째에서 한 번 감아 돌렸다. 여운비가 무릎을 꿇은 채 그것을 보았다."}, {"s": null, "t": "내 끈을 다 매고 나서, 나는 남은 한 켤레를 집어 여운비의 발 앞에 놓았다. 그러고는 여운비 앞에 무릎을 꿇었다."}, {"s": "north_league:yeo", "t": "…지금 뭐 하는 거요?"}, {"s": null, "t": "나는 대답하지 않고 여운비의 발을 신에 넣어 주었다. 끈을 집어 셋을 엇갈리고 넷째에서 감아 돌렸다. 여운비가 가르쳐 준 그대로였다."}, {"s": null, "t": "여운비는 꼼짝하지 않았다. 내가 오른발 끈을 다 매고 왼발로 넘어갔을 때, 여운비가 고개를 홱 돌렸다. 귀 끝이 새빨갰다."}, {"s": "north_league:yeo", "t": "…넷째 고리가, 조금 느슨하오."}, {"s": null, "t": "나는 넷째 고리를 다시 조였다. 여운비가 그제야 숨을 내쉬었다."}, {"s": "north_league:yeo", "t": "아버지 말고 내 신 끈을 매 준 사람은 없었소. 대장이 신 끈 하나도 못 매서 남한테 맡기면 썰매꾼들이 웃는다 해서. 그래서 늘 내 손으로 맸지."}, {"s": null, "t": "나는 이제 대장이 아니니 웃을 사람도 없다고 했다. 여운비가 나를 내려다보았다. 남은 왼 눈이 한동안 내 얼굴에 머물렀다."}, {"s": "north_league:yeo", "t": "당신은 늘 그렇게 쉽게 말하는구려."}, {"s": null, "t": "여운비가 입술을 한 번 깨물었다. 그 말 끝에 무언가를 더 하려다 그만둔 얼굴이었다."}, {"s": null, "t": "나는 그 말 끝을 기다렸다. 여운비는 끝내 말을 잇지 않고 눈밭 쪽으로 고개를 돌렸다."}, {"s": null, "t": "여운비가 일어서서 눈밭을 몇 걸음 걸어 보았다. 끈은 풀리지 않았다. 여운비가 제 발을 내려다보다가 아주 작게 웃었다. 웃음은 금방 사라졌지만 귀 끝은 고찰 안으로 들어갈 때까지 빨갰다."}, {"s": "north_league:yeo", "t": "내일 고개에 오릅시다. 당신도 그 신을 신고 오시오."}]'::jsonb, '{"gil": 205}'::jsonb)
