insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_unbi_4', 'side', '연담·여운비', '불침번 둘', '첫 눈보라가 오기 전 고개 길표를 살피러 서리솔 고개에 오른 두 사람이 눈보라에 갇혀 바위 굴에서 밤을 보낸다. 불침번을 반씩 서기로 한 밤, 여운비가 처음으로 먼저 잠든다.', 'iron_monastery', 50, '{rg_unbi_3}'::text[], null, 1633, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "unbi", "stage": 4}'::jsonb where quest_id = 'rg_unbi_4';
delete from public.world_quest_steps where quest_id = 'rg_unbi_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_4', 1, '길표 보러 가는 길', '길표 보러 가는 길', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "고찰 산문 위 하늘이 잿빛으로 낮게 내려앉아 있었다. 여운비가 산문 기둥에 기대어 서서 오른 뺨을 하늘 쪽으로 들고 있었다. 공기에서 쇠붙이 같은 눈 냄새가 묻어났다."}, {"s": "north_league:yeo", "t": "썰매꾼들이 행전 짚신을 다 신었소. 발목이 안 젖는다고 혜각 수좌한테 절을 하더이다. 수좌는 당신한테 하라고 했고."}, {"s": null, "t": "여운비가 하늘을 보던 얼굴을 내렸다. 표정이 굳어 있었다."}, {"s": "north_league:yeo", "t": "볼이 시리오. 사흘 안에 첫 눈보라가 올 거요. 그 전에 서리솔 고개 길표 돌을 살펴야 하오. 눈이 덮이면 길표가 안 보이고, 길표가 안 보이면 썰매가 벼랑으로 가니까."}, {"s": null, "t": "나는 길표 돌이 무엇이냐고 물었다. 여운비가 산문 기둥 아래쪽을 손끝으로 짚었다. 기둥 밑동에 짧은 칼 홈이 여럿 패어 있었다."}, {"s": "north_league:yeo", "t": "고개를 넘을 때마다 길가 돌에 칼로 홈을 하나씩 긋소. 홈이 있는 돌만 따라가면 벼랑을 안 밟지. 첫눈 전에 홈을 다시 그어 둬야 눈 속에서도 손끝으로 찾을 수 있소."}, {"s": null, "t": "나는 길표만 보는 일이면 혼자 다녀와도 되겠다고 했다. 여운비가 고개를 저었다."}, {"s": "north_league:yeo", "t": "고개는 혼자 넘는 데가 아니오. 호송대장이 아니어도 지키는 규칙이오. …게다가 오른쪽 길가는 내가 못 보고."}, {"s": null, "t": "여운비는 그 말을 하고 헛기침을 했다. 칼끈을 고쳐 매는 손이 평소보다 바빴다."}, {"s": null, "t": "여운비가 산문 밖 하늘을 한 번 더 올려다보았다."}, {"s": "north_league:yeo", "t": "지금 떠납시다. 하룻길이니 짐은 가볍게 꾸립시다. 그래도 망태 하나는 있어야 하오. 끈 자투리, 숯, 주먹밥을 담을 것. 그런데 고찰 망태는 썰매꾼들이 다 메고 나갔소."}, {"s": null, "t": "나는 썰매꾼 망태를 하나 빌리자고 했다. 여운비가 고개를 저었다."}, {"s": "north_league:yeo", "t": "고개 망태는 빌리는 게 아니오. 제 짐은 제 망태에 지는 거요. 그래야 제 무게를 제가 알지."}, {"s": "north_league:yeo", "t": "약초꾼 망태 하나만 지어 주시오. 갈대로 짜고 부적실로 어깨끈을 박으면 눈에 젖어도 안 처지오. 다 지으면 당신이 메시오. 나는 칼을 메리다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_4', 2, '눈보라', '약초꾼 망태을(를) 만든다, 약초꾼 망태을(를) 넘긴다', '{"at": ["frost_pine_pass"], "tasks": [{"t": "craft", "items": ["t2_gather"], "n": 1}], "give": {"t2_gather": 1}}'::jsonb, '[{"s": null, "t": "서리솔 고개 길은 소나무 사이로 구불구불 이어졌다. 솔잎에 앉은 서리가 바람에 흩날려 뺨을 따끔따끔 찔렀고, 찬 공기에 송진 냄새가 실려 왔다."}, {"s": null, "t": "여운비가 앞서 걸으며 길가의 길표 돌을 하나씩 손으로 짚었다. 돌마다 칼로 그은 홈이 여럿 남아 있었다."}, {"s": null, "t": "고갯마루에 닿기 전에 바람이 바뀌었다. 여운비가 걸음을 멈추고 오른 뺨을 바람 쪽으로 돌렸다."}, {"s": "north_league:yeo", "t": "…빠르오. 사흘이 아니라 오늘이구려."}, {"s": null, "t": "말이 끝나기도 전에 눈발이 몰려왔다."}, {"s": null, "t": "휘이잉 소리와 함께 하얀 벽이 소나무 사이로 쏟아져 들어왔다. 한 걸음 앞에 선 여운비의 등이 흐려졌다."}, {"s": "north_league:yeo", "t": "내 망토 끝을 잡으시오! 절대 놓지 마시오!"}, {"s": null, "t": "나는 여운비의 망토 자락을 움켜쥐었다. 여운비가 눈보라 속을 더듬어 길가 바위 비탈로 나를 끌고 갔다. 비탈 아래에 사람 둘이 겨우 들어앉을 만한 바위 굴이 있었다."}, {"s": "north_league:yeo", "t": "호송대가 쓰던 굴이오. 아직 있었구려."}, {"s": null, "t": "굴 안에 들어서자 바람 소리가 한결 멀어졌다. 여운비가 망태에서 숯을 꺼내 불을 붙였다. 불빛이 굴 벽을 주황빛으로 물들였고, 젖은 망토 자락에서 김이 피어올랐다."}, {"s": null, "t": "그때 굴 밖 눈보라 속에서 무언가가 낮게 그르렁거렸다. 불빛을 보고 모여든 것들이었다. 여운비가 칼을 뽑아 들고 굴 어귀로 나섰다."}, {"s": "north_league:yeo", "t": "불이 꺼지면 우리가 얼고, 저것들이 들어오면 불이 꺼지오. 쫓읍시다. 당신이 오른쪽을 맡으시오."}, {"s": null, "t": "여운비가 칼끝으로 어둠의 왼쪽을 겨누었다. 나는 여운비의 오른쪽에 서서 칼을 뽑았다."}, {"s": "north_league:yeo", "t": "다 쫓고 나서 불침번을 정합시다. 눈보라는 아침에야 그칠 거요. 둘 다 자면 불이 꺼지고, 둘 다 안 자면 내일 고개를 못 내려가오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_4', 3, '먼저 잠든 사람', '서리솔 고개의 요괴를 물리친다, 서리솔 고개에서 쉰다', '{"at": ["frost_pine_pass"], "tasks": [{"t": "win", "r": ["frost_pine_pass"], "n": 6}, {"t": "rest", "r": ["frost_pine_pass"], "n": 1}]}'::jsonb, '[{"s": null, "t": "굴 어귀의 것들을 쫓아내고 돌아오니 불이 반쯤 사그라들어 있었다. 여운비가 숯을 더 얹고 불가에 앉았다. 나도 그 오른쪽에 앉았다."}, {"s": "north_league:yeo", "t": "불침번은 반씩 서겠소. 앞 반은 당신, 뒤 반은 나. 뒤 반을 설 사람이 먼저 자 둬야 하니, 나는 먼저 자겠소."}, {"s": null, "t": "여운비는 그렇게 말해 놓고 칼을 무릎에 눕힌 채 앉아 있었다. 눈을 감지 않았다."}, {"s": null, "t": "나는 먼저 잔다면서 왜 안 눕느냐고 물었다. 여운비가 불을 보며 대답했다."}, {"s": "north_league:yeo", "t": "호송대장 노릇 열두 해 동안 남보다 먼저 잔 적이 없소. 썰매꾼들이 다 잠든 걸 보고 나서야 잤지. 버릇이 그렇게 들었소."}, {"s": null, "t": "나는 오늘은 썰매꾼이 없다고 했다. 여운비가 나를 돌아보았다."}, {"s": "north_league:yeo", "t": "…당신이 있지 않소."}, {"s": null, "t": "나는 그럼 내가 먼저 눈을 감은 척하겠다고 했다. 여운비가 콧김을 짧게 내뿜었다. 웃음 같았다."}, {"s": null, "t": "나는 망태를 베고 누워 눈을 감았다. 굴 밖 눈보라 소리와 불이 타는 소리만 들렸다. 얼마쯤 지나 여운비가 숯을 하나 더 얹는 소리가 났고, 그 뒤로 조용해졌다."}, {"s": null, "t": "눈을 떠 보니 여운비가 칼을 무릎에 눕힌 채 고개를 떨구고 있었다. 숨이 고르고 길었다. 잠든 것이었다."}, {"s": null, "t": "나는 일어나 앉아 불을 지켰다. 망토가 여운비의 어깨에서 흘러내려 있었다. 나는 그 망토를 끌어 올려 여운비의 어깨를 덮었다. 여운비가 깨지 않았다."}, {"s": null, "t": "새벽녘 눈보라가 잦아들었다. 굴 어귀로 희붐한 빛이 들어오자 여운비가 퍼뜩 고개를 들었다. 여운비가 굴 밖과 불과 나를 차례로 보았다."}, {"s": "north_league:yeo", "t": "…뒤 반은 내가 서기로 하지 않았소."}, {"s": null, "t": "나는 깨우기 아까워서 그냥 두었다고 했다. 여운비가 어깨의 망토를 손끝으로 쥐었다. 덮어 준 사람이 누구인지 묻지 않았다."}, {"s": "north_league:yeo", "t": "처음이오. 남보다 먼저 잔 건. 그것도 앞 반을 남한테 통째로 맡기고."}, {"s": null, "t": "여운비가 망토를 여미고 일어섰다. 굴 어귀에 서서 오른 뺨을 바람 쪽으로 돌렸다. 바람이 잔잔했다. 맑고 찬 공기를 들이쉬자 가슴속까지 시렸다."}, {"s": "north_league:yeo", "t": "동쪽 바람이오. 오늘은 맑겠구려. …다음 불침번은 내가 앞 반을 서겠소. 그래야 셈이 맞지."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_unbi_5', 'side', '연담·여운비', '눈길 동무', '여운비가 망토 깃에 댈 강화 요수 가죽을 주문하고, 누구 망토인지는 묻지 말라고 한다. 설피골 눈길을 함께 걸은 끝에, 여운비는 제 길 장부의 길동무 칸 오른쪽에 내 이름을 적는다.', 'iron_monastery', 50, '{rg_unbi_4}'::text[], null, 1634, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "unbi", "stage": 5}'::jsonb where quest_id = 'rg_unbi_5';
delete from public.world_quest_steps where quest_id = 'rg_unbi_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_5', 1, '묻지 말 것', '묻지 말 것', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": null, "t": "헛간 밖에는 함박눈이 소리 없이 내리고 있었다. 고찰 헛간에 붉은 술이 달린 칼걸이 하나가 걸려 있었다."}, {"s": null, "t": "그 아래 작업대 위에 두꺼운 모직 망토 하나가 펼쳐져 있었다. 깃은 아직 달려 있지 않았다."}, {"s": null, "t": "여운비가 작업대 앞에 앉아 바늘을 쥐고 있었다. 내가 헛간에 들어서자 여운비가 망토 위에 손바닥을 얹어 덮었다."}, {"s": "north_league:yeo", "t": "왔구려. 당신 손을 거친 가죽으로 썰매 끈, 장갑, 신, 망태까지 다 했소. 고찰 썰매꾼들 몸에 당신 손이 안 간 데가 없을 거요. 혜각 수좌 말로는 썰매꾼 하나가 당신 이름을 대며 절을 세 번 했다 하더이다."}, {"s": null, "t": "나는 손바닥 밑에 숨긴 그 망토가 누구 것인지 넌지시 떠보았다. 여운비가 망토를 덮은 손을 치우지 않았다."}, {"s": "north_league:yeo", "t": "…묻지 마시오."}, {"s": null, "t": "여운비가 바늘을 작업대에 내려놓았다. 헛기침을 한 번 했다."}, {"s": "north_league:yeo", "t": "깃을 대야 하오. 모직만으로는 고개 바람을 못 막소. 깃은 옻을 먹인 가죽이라야 목이 안 트지. 강화 요수 가죽 두 장만 다듬어 주시오."}, {"s": "north_league:yeo", "t": "누구 것인지는 묻지 마시오. 다 지으면 알게 될 거요."}, {"s": null, "t": "나는 장터 엿 장수 몫인가 보다고 했다. 여운비가 바늘을 쥔 손을 멈췄다."}, {"s": "north_league:yeo", "t": "그 애는 망토를 안 입소. 무겁다나. 내 망토를 덮어 줘도 아침이면 걷어차 놓고 있소."}, {"s": null, "t": "여운비가 바늘 끝으로 망토 자락을 한 번 콕 찔렀다. 대답은 그것으로 끝이었다."}, {"s": null, "t": "여운비가 다시 바늘을 집었다. 바늘 끝이 아까보다 빨리 움직였다."}, {"s": "north_league:yeo", "t": "깃을 다 달면 설피골 눈길을 한 번 걸읍시다. 망토를 지어 놓고 눈길을 안 걸어 보면, 지은 게 아니라 꿰맨 것뿐이오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_5', 2, '깃', '강화 요수 가죽을(를) 만든다, 강화 요수 가죽을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "craft", "items": ["reinforced_leather"], "n": 2}], "give": {"reinforced_leather": 2}}'::jsonb, '[{"s": null, "t": "다듬은 가죽을 내밀자 여운비가 한 장씩 손바닥으로 쓸어 두께를 쟀다. 그러고는 말없이 가죽을 깃 모양으로 잘랐다."}, {"s": null, "t": "여운비가 깃을 망토 목둘레에 대고 바늘을 찔렀다."}, {"s": null, "t": "두꺼운 가죽에 바늘이 잘 들어가지 않았다. 바늘이 가죽을 뚫을 때마다 뿍, 하는 둔한 소리가 났다. 나는 맞은편에 앉아 망토 자락을 팽팽하게 당겨 잡았다."}, {"s": "north_league:yeo", "t": "그대로 잡고 계시오. 조금만 더 당기고."}, {"s": null, "t": "깃 한쪽을 다 꿰맨 여운비가 실을 이로 끊었다."}, {"s": null, "t": "그러고는 작업대 서랍에서 붉은 실 몇 가닥을 꺼냈다. 칼자루 끝 술에서 뽑아낸 실이었다."}, {"s": null, "t": "여운비가 그 붉은 실로 깃 안쪽에 작은 매듭 하나를 지었다."}, {"s": null, "t": "셋을 엇갈리고 넷째에서 한 번 감아 돌린 매듭이었다. 매듭 끝에 짧은 술이 달랑거렸다."}, {"s": null, "t": "나는 그 매듭이 신 끈 매는 법과 같다고 했다. 여운비가 바늘을 내려놓았다."}, {"s": "north_league:yeo", "t": "북령 사람은 매듭 한 가지로 다 묶소. 신도, 썰매 짐도, 사람도."}, {"s": null, "t": "나는 사람도 묶느냐고 되물었다. 여운비가 실을 이로 끊으며 대답하지 않았다."}, {"s": null, "t": "여운비가 망토를 들어 올려 털었다."}, {"s": null, "t": "묵직한 모직이 펄럭이며 헛간 안에 바람을 일으켰고, 양털 냄새가 훅 풍겼다. 깃 안쪽의 붉은 술이 그 바람에 날렸다."}, {"s": "north_league:yeo", "t": "다 됐소. 이제 걸어 봐야지. 설피골 눈길이오. 처음 끈을 당겨 본 시험길 말고, 고개 너머 산골로 가는 옛 호송 길 말이오. 길이 눈에 덮였으니 길가를 더듬어 가야 하오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_unbi_5', 3, '길동무 칸', '설피골에 간다, 설피골을(를) 살핀다', '{"at": ["snow_hollow"], "tasks": [{"t": "travel", "r": ["snow_hollow"], "n": 1}, {"t": "search", "r": ["snow_hollow"], "n": 2}]}'::jsonb, '[{"s": null, "t": "옛 호송 길은 눈에 덮여 어디가 길이고 어디가 벼랑인지 보이지 않았다. 여운비가 앞서 걸으며 바람을 읽었고, 나는 여운비의 오른쪽에서 길가 눈 처마를 살폈다. 걸음마다 눈이 무릎까지 빠졌고, 발을 뺄 때마다 차가운 눈가루가 행전 틈으로 스며들었다."}, {"s": null, "t": "고갯마루 바위 아래에서 여운비가 걸음을 멈추었다. 품에서 손바닥만 한 장부를 꺼냈다. 겉장이 닳아 해진 장부였다."}, {"s": "north_league:yeo", "t": "호송 장부는 넘겼소. 그래도 이것만은 못 놓겠더이다. 내가 걷는 길은 다 여기 적소. 날짜, 바람, 길동무."}, {"s": null, "t": "여운비가 장부를 펼쳤다. 줄마다 맨 끝에 칸이 둘 있었다. 왼쪽 칸에는 거의 모든 줄에 같은 이름이 적혀 있었다. 「단비」였다. 오른쪽 칸은 모두 비어 있었다."}, {"s": "north_league:yeo", "t": "왼쪽 칸은 엿 장수가 차지했소. 내가 보는 쪽이니까. 오른쪽은… 내가 못 보는 쪽이라 늘 비워 뒀소. 못 보는 데에 누구 이름을 적으면, 거짓말 같아서."}, {"s": null, "t": "여운비가 장부를 무릎에 얹고 붓을 꺼냈다. 붓끝을 입김으로 녹여 오늘 날짜를 적었다. 바람 칸에는 「동쪽」이라 적었다."}, {"s": null, "t": "여운비의 붓이 오른쪽 칸 위에서 멈췄다. 붓끝이 얼어붙을 만큼 오래 그대로 있다가, 여운비가 그 칸에 내 이름을 적었다. 한 획 한 획이 느리고 반듯했다."}, {"s": null, "t": "여운비는 앞 장들로 넘어갔다. 썰매가 기울던 날과 신 끈을 매던 날, 눈보라 굴에서 먼저 잠든 날이 적힌 줄들이었다. 그 줄마다 비어 있던 오른쪽 칸에 내 이름을 하나씩 적어 넣었다."}, {"s": null, "t": "나는 못 보는 쪽에 적으면 거짓말이라고 하지 않았느냐고 물었다. 여운비가 붓을 거두었다."}, {"s": "north_league:yeo", "t": "못 봤어도 거기 있었잖소. 썰매가 기울 때도, 불이 꺼질 뻔할 때도. 있었던 걸 적는 건 거짓말이 아니오."}, {"s": null, "t": "여운비가 장부를 덮고 일어섰다. 망태에서 깃을 단 망토를 꺼내 두 손으로 펼쳤다. 그러고는 내 등 뒤로 돌아가 망토를 내 어깨에 걸쳤다."}, {"s": null, "t": "두툼한 모직이 어깨를 감싸자 몸에 배어 있던 한기가 조금씩 풀렸다. 여운비가 내 앞으로 돌아와 깃을 여며 주었다. 깃 안쪽의 붉은 술 매듭이 내 목덜미에 닿았다."}, {"s": "north_league:yeo", "t": "북령 호송대 망토요. 길동무한테 하나씩 지어 주는 거요. 아버지가 그러셨소. 망토를 나눠 입은 사람끼리는 같은 눈길을 걷는다고."}, {"s": null, "t": "여운비가 깃을 여민 손을 거두지 않았다. 바람이 불어와 여운비의 오른 뺨에 닿았다. 여운비가 그 바람을 볼로 읽는 동안, 남은 왼 눈은 내 얼굴을 보고 있었다."}, {"s": "north_league:yeo", "t": "왼눈으론 바람을 못 보고, 볼로는 길가 처마를 못 보오. 그 몫은 당신이 보는 거요. 내 눈길은 이제 둘이오."}, {"s": "north_league:yeo", "t": "당신은 여운비의 눈길 동무요. 장부에 그렇게 적었으니 고칠 생각은 마시오. 북령 매듭은 한 번 지으면 안 풀리니까."}, {"s": null, "t": "여운비가 등을 돌려 고갯길을 내려가기 시작했다. 나는 망토를 여미고 그 오른쪽으로 걸음을 맞췄다. 여운비가 앞을 보며 짧게 말했다."}, {"s": "north_league:yeo", "t": "…나쁘지 않소. 아주."}]'::jsonb, '{"gil": 205, "title": "rg_unbi", "items": {"of_top_rg_unbi_cape": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_cheongpa_1', 'side', '연담·청파', '배에 실을 생선', '노들 영감의 배를 맡아 손님을 나르게 된 청파가, 긴 뱃길 손님들 밥에 쓸 생선을 주문한다. 노는 저어도 배 밑 깊은 물은 내려다보지 않는 청파를 태우고 백지교와 연화늪으로 낚시를 간다.', 'river_ferry', 50, '{mde_cheongpa_2}'::text[], null, 1635, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_cheongpa_1';
delete from public.world_quest_steps where quest_id = 'rg_cheongpa_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_1', 1, '배고픈 손님들', '배고픈 손님들', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "구름나루 선창에 나룻배 한 척이 매여 있었다. 뱃전이 반들반들 닳은 오래된 배였다. 아침 물안개가 아직 걷히지 않아 선창 널판이 축축했고, 물비린내가 코끝에 감겼다. 고물에 청파가 노를 무릎에 가로놓고 앉아 있었다."}, {"s": null, "t": "청파 곁에는 굵은 밧줄 한 사리가 둘둘 감겨 있었다. 줄 끝에 낡은 매듭 몇 개가 매달려 있었다. 물굴에서 청파의 허리에 감겼던 잠수 줄이었다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님! 오셨어요? 저 이제 이 배를 맡았어요! 노들 영감님 배요. 영감님 허리가 시원찮으셔서 노는 제가 저어요."}, {"s": null, "t": "청파가 일어서다 쿨럭, 쇳소리가 섞인 기침을 했다. 기침이 가라앉자 청파가 뱃전을 손바닥으로 탕탕 두드렸다."}, {"s": "q:sn_cheongpa", "t": "근데요, 손님들이 배에서 자꾸 배고프대요. 장대 등을 따라 염등촌까지 가면 한나절이 넘게 걸리거든요. 주막 달래 아주머니가 주먹밥을 싸 주시긴 하는데, 생선 없이 주먹밥만 드리니까 손님들이 반쯤 가면 노래를 딱 안 불러요."}, {"s": null, "t": "나는 노래와 생선이 무슨 상관인지 몰라 고개를 갸웃했다. 청파가 눈을 동그랗게 떴다."}, {"s": "q:sn_cheongpa", "t": "상관 엄청 많아요! 수향 뱃사람은 배부르면 노래하고, 배고프면 노를 젓는 사람 흉을 봐요. 어제는요, 제 기침 소리를 흉내 냈어요. 다 같이요!"}, {"s": null, "t": "뱃전 너머 선창 끝에서 노들 영감이 허리를 두드리며 혀를 찼다."}, {"s": "river_alliance:nodeul", "t": "허허, 흉내를 낸 게 아니라 같이 기침을 해 준 게지. 이 녀석아, 생선은 네가 잡을 수도 있지 않으냐."}, {"s": null, "t": "청파가 두 팔을 활짝 벌려 보이며 볼멘소리를 했다."}, {"s": "q:sn_cheongpa", "t": "영감님, 저 노를 젓느라 팔 두 개가 다 바쁘다니까요."}, {"s": null, "t": "노들 영감이 껄껄 웃으며 주막 쪽으로 걸어갔다. 청파가 그 등을 보다가 나를 돌아보았다."}, {"s": "q:sn_cheongpa", "t": "그러니까 {이름} 님이 잡아 주세요. 백지교 다리 밑에 붕어가 잘 물어요. 제가 노를 저어서 모셔다드릴게요. 대신 저는 배에 앉아 있을게요. 낚싯대는 {이름} 님이 드시고요."}, {"s": null, "t": "청파가 고물의 밧줄 사리를 발로 슬쩍 배 한쪽으로 밀어 놓았다. 나는 그 줄을 보다가 청파를 보았다. 청파는 그 눈길을 알아챘는지 노를 번쩍 들어 보였다."}, {"s": "q:sn_cheongpa", "t": "출발해요! 이번엔 안 박을게요, 진짜로요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_1', 2, '내려다보지 않는 물', '백지교에서 낚시를 한다', '{"at": ["paper_bridge"], "tasks": [{"t": "fish", "r": ["paper_bridge"], "n": 4}]}'::jsonb, '[{"s": null, "t": "한낮 볕이 물 위에 부서져 눈이 부셨지만 백지교 다리 그늘 안은 서늘했다. 그 그늘 아래에서 청파가 배를 멈췄다."}, {"s": null, "t": "다리 밑 물살이 느려 붕어가 연달아 줄 끝에 올라왔다. 나는 생선을 배 바닥의 물통에 담았고, 청파는 노를 쥔 채 그것을 구경했다."}, {"s": "q:sn_cheongpa", "t": "또요! 또 물었어요! {이름} 님, 손이 진짜 빨라지셨어요!"}, {"s": null, "t": "청파는 줄 끝을 볼 때 고개를 들었다."}, {"s": null, "t": "물통 속 생선을 볼 때도 고개를 들었다. 배 옆으로 고개를 숙여 물 밑을 들여다보는 일만은 한 번도 하지 않았다."}, {"s": null, "t": "나는 물이 무서우냐고 물었다. 청파가 노를 쥔 손을 꼼지락거렸다."}, {"s": "q:sn_cheongpa", "t": "아니요. 물은 좋아요. 위에서 보는 물은 진짜 좋아요. 불빛이 다 비치고, 어디로 흐르는지도 보이고요."}, {"s": null, "t": "청파가 노 끝으로 물 위에 비친 다리 그림자를 가리켰다. 물결이 일 때마다 그림자가 흔들렸다."}, {"s": "q:sn_cheongpa", "t": "근데 밑을 들여다보면요, 몸이 먼저 들어가고 싶어 해요. 숨은 짧아졌는데 몸은 아직 잠수꾼인가 봐요. 그래서 안 봐요. 보면 들어갈 것 같아서요."}, {"s": null, "t": "청파가 쿨럭쿨럭 기침을 했다. 기침 끝에 웃었지만 눈은 물을 피해 다리 기둥 쪽에 가 있었다."}, {"s": null, "t": "나는 고물의 밧줄 사리로 눈을 돌렸다. 청파가 내 눈길을 따라 발치의 줄을 내려다보았다."}, {"s": "q:sn_cheongpa", "t": "못 버리겠더라고요. 이 줄에 다들 매듭을 지어 주셨잖아요. {이름} 님 매듭도 있어요. 그 꽁꽁 묶은 거요. 사실 그건 매듭이 아니라 그냥 꽁꽁이지만요."}, {"s": null, "t": "청파가 줄 끝의 매듭 하나를 손가락으로 툭 건드렸다. 투박하게 뭉쳐 놓은 매듭이었다. 물을 먹었다 마르기를 되풀이한 줄이 손끝에 거칠거칠했다."}, {"s": "q:sn_cheongpa", "t": "붕어만으론 모자라요. 손님들 국을 끓이려면 큼직한 것도 있어야 해요. 연화늪으로 가요! 거긴 가물치가 물거든요. 제가 저어 갈게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_1', 3, '노래하는 배', '천엽 연화늪에서 낚시를 한다', '{"at": ["river_ferry"], "tasks": [{"t": "fish", "r": ["lotus_marsh"], "n": 3}]}'::jsonb, '[{"s": null, "t": "생선을 가득 싣고 구름나루로 돌아오자 주막 달래가 물통을 받아 갔다. 그날 저녁 주막 부엌에서 생선국 끓는 냄새가 선창까지 흘러나왔고, 배에 오른 손님들은 뜨끈한 생선국과 주먹밥을 받아 들었다."}, {"s": null, "t": "청파가 노를 저어 장대 등 사이로 배를 몰았다. 장대 끝 등불이 물 위에 길게 비쳐 흔들렸다. 반쯤 갔을 때 손님 하나가 뱃노래를 시작했다."}, {"s": null, "t": "다른 손님들이 하나둘 따라 불렀다. 노랫소리가 물 위로 멀리 퍼져 나갔다."}, {"s": "q:sn_cheongpa", "t": "들으셨어요? 노래해요! 배부르니까 노래한다니까요!"}, {"s": null, "t": "청파가 노를 저으며 나를 돌아보았다."}, {"s": null, "t": "얼굴이 환했다. 손님들의 노래에 맞춰 노가 물을 철썩철썩 갈랐다."}, {"s": null, "t": "손님들을 염등촌에 내려 주고 돌아오는 길이었다."}, {"s": null, "t": "빈 배에 청파와 나만 남았다. 청파는 노를 젓는 손을 늦추고 장대 등이 물에 비치는 것을 보았다."}, {"s": "q:sn_cheongpa", "t": "증조할아버지도 이렇게 손님을 나르셨을 거예요. 값을 받고요. 저는 값을 안 받고 나르기로 했어요. 그 대신 밥은 꼭 먹여 드리고 싶어요. 배에 탄 사람이 배고프면 안 되잖아요."}, {"s": null, "t": "청파가 그 말을 하고 쿨럭 기침을 했다. 기침이 길어지자 청파는 노를 뱃전에 걸쳐 두고 숨을 골랐다. 나는 노를 받아 저었다. 노 손잡이에 청파의 손 온기가 아직 남아 있었다."}, {"s": "q:sn_cheongpa", "t": "고마워요. …{이름} 님은 또 제 대신 뭘 잡아 주시네요. 그때는 줄이었는데, 오늘은 노네."}, {"s": null, "t": "구름나루 선창에 배를 대자 청파가 밧줄을 말뚝에 감았다. 청파가 감는 매듭을 나는 따라 보았다. 손이 빠르고 매듭이 단단했다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님, 앞으로도 부탁해도 돼요? 생선이요. 손님은 날마다 타는데 생선은 날마다 안 오거든요. {이름} 님이 날마다 가져다주시면요, 제 배는 날마다 노래할 거예요."}, {"s": null, "t": "나는 그러겠다고 했다. 청파가 말뚝 매듭을 꽉 당기고 활짝 웃었다."}, {"s": "q:sn_cheongpa", "t": "그럼 약속이에요! {이름} 님은 평생 뱃삯이 없어요. 뭐, 원래 아무한테도 안 받지만… {이름} 님한테는 더더욱 안 받아요."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_cheongpa_2', 'side', '연담·청파', '매듭', '청파가 선창 끝에서 잠수꾼 매듭을 가르쳐 준다. 매듭을 지은 낚싯줄이 정말 버티는지 연화원 못에서 시험하고, 기침에 끊기는 청파의 말 대신 내 손이 매듭을 마저 잇는다.', 'river_ferry', 50, '{rg_cheongpa_1}'::text[], null, 1636, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "cheongpa", "stage": 2}'::jsonb where quest_id = 'rg_cheongpa_2';
delete from public.world_quest_steps where quest_id = 'rg_cheongpa_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_2', 1, '꽁꽁 말고 매듭', '꽁꽁 말고 매듭', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "구름나루 선창 끝에 청파가 다리를 쭉 뻗고 앉아 있었다. 무릎 위에 짧게 잘라 낸 밧줄 토막 여러 개가 놓여 있었다. 강바람이 선선한 오후라 볕에 마른 널판 틈에서 나무 냄새가 올라왔다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님! {이름} 님이 낚아 오신 붕어랑 가물치 덕분에 손님들이 날마다 노래했어요. 어제는 가물치국을 두 그릇씩 드셔서 배가 무거워졌다니까요. 노를 젓느라 혼났어요."}, {"s": null, "t": "청파가 밧줄 토막 하나를 내게 내밀었다."}, {"s": "q:sn_cheongpa", "t": "오늘은 매듭을 배우세요. 잠수꾼 매듭이요! {이름} 님 매듭은 꽁꽁이라 물에 젖으면 다시는 안 풀리잖아요. 잠수꾼 매듭은 안 풀리다가도, 풀어야 할 땐 한 번에 풀려요."}, {"s": null, "t": "나는 밧줄 토막을 받아 들고 머뭇거렸다. 청파가 다른 토막을 손가락에 감았다."}, {"s": "q:sn_cheongpa", "t": "낚싯줄 때문이에요. 요즘 {이름} 님 줄이 자꾸 끊어지잖아요, 매듭 자리에서. 큰 놈이 물면 그런 매듭은 지가 먼저 끊어져요."}, {"s": null, "t": "청파가 밧줄 토막 두 개를 겹쳐 쥐었다."}, {"s": null, "t": "한쪽 끝을 고리로 만들고 다른 끝을 고리 속으로 꿰었다. 손이 빨랐다."}, {"s": "q:sn_cheongpa", "t": "먼저 토끼가 굴에서 나와요. 나무를 한 바퀴 돌고요. 그다음에 다시 굴로…"}, {"s": null, "t": "청파의 말이 기침에 끊겼다."}, {"s": null, "t": "쿨럭쿨럭 쇳소리가 선창에 울렸다. 청파는 한 손으로 입을 막고 다른 손으로 매듭 끝을 쥔 채 몸을 웅크렸다."}, {"s": null, "t": "나는 청파가 쥔 줄 끝을 받아 고리 속으로 꿰어 넣었다. 매듭이 조여졌다. 기침이 멎은 청파가 눈물이 맺힌 눈으로 매듭을 보았다."}, {"s": "q:sn_cheongpa", "t": "…맞아요. 그거예요. 토끼가 굴로 들어갔어요."}, {"s": "q:sn_cheongpa", "t": "매듭이 진짜 버티는지는 물고기가 알려 줘요. 폐쇄된 연화원 못에 큰 잉어가 살거든요. 그 줄로 낚아 보세요. 안 끊어지면 제대로 지은 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_2', 2, '버틴 줄', '폐쇄된 연화원에서 낚시를 한다', '{"at": ["sealed_garden"], "tasks": [{"t": "fish", "r": ["sealed_garden"], "n": 3}]}'::jsonb, '[{"s": null, "t": "폐쇄된 연화원 못가에 청파가 쪼그려 앉아 있었다. 무너진 담장 너머로 시든 연잎 냄새와 고인 물의 눅눅한 내음이 번졌다. 청파는 못물을 내려다보지 않고 내 낚싯줄 끝만 보았다."}, {"s": null, "t": "큰 잉어가 물자 줄이 활처럼 휘었다. 청파가 벌떡 일어섰다."}, {"s": "q:sn_cheongpa", "t": "당기지 말고 버티세요! 매듭을 믿으세요! 토끼를 믿으세요!"}, {"s": null, "t": "줄은 끊어지지 않았다."}, {"s": null, "t": "잉어가 물 위로 끌려 올라오자 청파가 두 손을 번쩍 들었다. 기침이 터졌지만 웃음이 먼저였다."}, {"s": "q:sn_cheongpa", "t": "됐다! 안 끊어졌어요! 예전 그 매듭이었으면 지금쯤 잉어가 {이름} 님 바늘 물고 연못 바닥에서 자랑하고 있었을걸요?"}, {"s": null, "t": "청파는 줄 끝의 매듭을 손가락으로 만져 보았다."}, {"s": null, "t": "젖은 매듭이 단단하게 조여져 있었다. 청파가 끝을 톡 당기자 매듭이 한 번에 풀렸다."}, {"s": "q:sn_cheongpa", "t": "봐요, 풀어야 할 땐 이렇게 풀려요. 잠수꾼은 물속에서 줄이 걸리면 이걸 풀고 올라와야 하거든요. 숨이 모자라니까, 한 번에요."}, {"s": null, "t": "청파가 풀린 줄을 다시 내게 건넸다. 이번엔 다른 매듭을 가르쳤다. 둘을 겹쳐 묶는 매듭이었다. 청파가 말을 하다 기침에 끊길 때마다 나는 청파의 손에서 줄 끝을 받아 매듭을 마저 지었다."}, {"s": null, "t": "매듭을 다섯 개쯤 배웠을 때 청파가 못가 풀밭에 털썩 드러누웠다. 숨이 가빴다."}, {"s": "q:sn_cheongpa", "t": "좀 쉬어요. 매듭을 가르치는 게 잠수보다 숨이 더 차요. 말을 너무 많이 해서 그런가 봐요."}, {"s": null, "t": "청파가 풀밭에 누운 채 손바닥을 하늘로 펴 보였다. 손바닥에 노를 젓느라 생긴 굳은살이 박여 있었다."}, {"s": "q:sn_cheongpa", "t": "해 질 때까지 여기서 쉬다 가요. 연화원은 해 질 녘에 연잎이 닫히는 소리가 나요. 아주 작게요. 그걸 듣고 있으면 숨이 고르게 돼요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_2', 3, '식구 매듭', '폐쇄된 연화원에서 쉰다', '{"at": ["sealed_garden"], "tasks": [{"t": "rest", "r": ["sealed_garden"], "n": 1}]}'::jsonb, '[{"s": null, "t": "해가 기울자 못 위의 연잎들이 하나둘 오므라들었다. 사르르, 사르르 하는 소리가 못 전체에서 났다. 선선해진 저녁 바람이 수면에 잔물결을 그렸다."}, {"s": null, "t": "청파가 눈을 감고 그 소리를 들었다. 숨이 아까보다 고르고 길었다."}, {"s": null, "t": "청파가 품에서 짧은 밧줄 토막 하나를 꺼냈다."}, {"s": null, "t": "그 위에 매듭 하나가 지어져 있었다. 처음 보는 모양이었다."}, {"s": "q:sn_cheongpa", "t": "이건 식구 매듭이에요. 수향에서 배를 새로 띄우면 식구들이 지어 주는 거요. 다시는 땅에 앉지 말라고요. 제 잠수 줄 맨 처음 매듭도 이거였어요. 엄마가 지어 준 거요."}, {"s": null, "t": "청파가 매듭 끝을 손가락으로 쓸었다. 매듭은 오래되어 색이 바래 있었다."}, {"s": "q:sn_cheongpa", "t": "이건 가르쳐 드릴 수가 없어요. 식구가 아니면 안 지어 주는 거라서요. 그래서… 그때 물굴에서 {이름} 님이 지은 꽁꽁 매듭이요, 저는 좀 좋았어요. 식구 매듭은 아니지만, 식구가 짓는 자리에 지어 주셨잖아요."}, {"s": null, "t": "나는 그건 몰라서 아무렇게나 묶은 것이라고 했다. 청파가 웃음을 터뜨리다 기침을 했다."}, {"s": "q:sn_cheongpa", "t": "알아요! 그래서 더 좋았던 거예요. 몰라서 그렇게 묶었는데, 안 풀렸잖아요. 그날 제가 이백 숨 넘게 물속에 있었는데도요."}, {"s": null, "t": "청파가 몸을 일으켜 앉았다. 밧줄 토막을 내 손에 쥐여 주었다."}, {"s": null, "t": "식구 매듭이 아니라 오늘 배운 다섯 매듭이 한 줄에 나란히 지어져 있었다. 내가 지은 것이었다."}, {"s": "q:sn_cheongpa", "t": "이건 {이름} 님 거예요. 오늘 배운 거요. 집에 가서 다 풀고 다시 지어 보세요. 다 풀리고 다 지어지면, 다음엔 하나 더 가르쳐 드릴게요."}, {"s": null, "t": "나는 밧줄 토막을 받아 품에 넣었다. 청파가 연못가에서 일어나 무릎의 풀을 털었다."}, {"s": null, "t": "품 안에서 젖은 밧줄의 냉기가 천천히 가셨다. 청파가 그 모습을 보고 키득 웃었다."}, {"s": "q:sn_cheongpa", "t": "돌아가요! 노는 제가 저을게요. 매듭은 {이름} 님이 묶으세요. 말뚝에 배를 매는 거요. 이번엔 꽁꽁 말고요!"}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_cheongpa_3', 'side', '연담·청파', '발만 담그기', '숨통이 상한 뒤로 물에 몸을 담근 적이 없는 청파가 처음으로 연화늪 얕은 물에 발을 담근다. 그날 밤에는 청파가 꿀 탄 영초 차를 끓여 와, 일행이던 시절 선창 끝의 그 밤처럼 둘이 나눠 마신다.', 'river_ferry', 50, '{rg_cheongpa_2}'::text[], null, 1637, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "cheongpa", "stage": 3}'::jsonb where quest_id = 'rg_cheongpa_3';
delete from public.world_quest_steps where quest_id = 'rg_cheongpa_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_3', 1, '벗어 둔 신', '벗어 둔 신', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "볕이 선창 널판을 따끈하게 데운 아침, 구름나루 선창에 청파의 배가 매여 있었다. 청파는 배 고물에 앉아 제 신을 벗었다 신었다 하고 있었다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님! 영감님이 연화원 잉어로 잉어 고음을 끓이셨어요. 손님들이 그걸 먹고 사흘 내내 기운이 넘쳐서, 서로 노를 젓겠다고 싸웠다니까요."}, {"s": null, "t": "청파가 신을 벗어 뱃전에 나란히 놓았다. 맨발이 선창 널판 위에서 꼼지락거렸다."}, {"s": "q:sn_cheongpa", "t": "오늘 연화늪에 가요. 손님 국을 끓일 생선을 잡으러요. 근데 그거 말고, 하나 더 해 보려고요."}, {"s": null, "t": "청파가 발가락을 오므렸다 폈다."}, {"s": "q:sn_cheongpa", "t": "발만요. 물에 발만 담가 보려고요. 물굴에서 나온 뒤로 한 번도 안 담갔거든요. 물에 닿으면 몸이 자꾸 밑으로 내려가고 싶어 할까 봐서요."}, {"s": "q:sn_cheongpa", "t": "연화늪은 가장자리가 얕아요. 무릎도 안 와요. 거기선 들어가고 싶어도 못 들어가요. 그러니까 거기서 해 보려고요."}, {"s": null, "t": "선창 끝에서 그물을 손질하던 노들 영감이 고개를 들었다. 영감은 청파의 맨발을 물끄러미 보더니 혀를 찼다."}, {"s": "river_alliance:nodeul", "t": "허허, 발만이다. 무릎을 넘어가면 내가 노로 엉덩이를 칠 게야."}, {"s": null, "t": "청파가 화들짝 놀라 맨발을 오므렸다."}, {"s": "q:sn_cheongpa", "t": "영감님! 거기서 다 들으셨어요?"}, {"s": null, "t": "노들 영감은 대꾸 없이 그물로 눈을 돌렸다. 청파가 얼굴이 빨개져서 나를 돌아보았다."}, {"s": "q:sn_cheongpa", "t": "영감님이 저렇게 말씀하시는 건 해도 된다는 뜻이에요. 안 된다는 뜻이면 아예 노를 감춰 버리시거든요."}, {"s": null, "t": "청파가 벗은 신을 품에 안았다. 신을 신지 않고 들고 가려는 듯했다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님은 그동안 낚시하세요. 저는 옆에서 발만 담그고 있을게요. 혹시 제가 좀 이상하면… 그냥 제 이름을 불러 주세요. 그럼 돌아올게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_3', 2, '첫 발', '천엽 연화늪에 간다, 천엽 연화늪에서 낚시를 한다', '{"at": ["lotus_marsh"], "tasks": [{"t": "travel", "r": ["lotus_marsh"], "n": 1}, {"t": "fish", "r": ["lotus_marsh"], "n": 3}]}'::jsonb, '[{"s": null, "t": "천엽 연화늪 가장자리는 갈대가 무성했고, 물은 맑고 얕았다. 나는 갈대 사이 바위에 앉아 줄을 던졌다. 청파는 내 곁 물가 진흙에 쪼그려 앉아 있었다. 늪에서는 진흙과 물풀이 뒤섞인 들큼한 냄새가 올라왔고, 갈대 사이에서 개구리 울음이 그치지 않았다."}, {"s": null, "t": "청파는 처음엔 물을 보지 않았다. 생선이 줄에 올라올 때마다 고개를 들어 박수를 쳤고, 생선이 물통에 담기면 다시 무릎을 끌어안았다."}, {"s": null, "t": "생선 셋째가 물통에 담겼을 때 청파가 숨을 크게 들이쉬었다. 그러고는 맨발 하나를 물가로 천천히 뻗었다."}, {"s": null, "t": "발가락 끝이 물에 닿았다. 청파가 흠칫 몸을 떨었다. 발가락 끝에서부터 종아리까지 소름이 오소소 돋았다."}, {"s": "q:sn_cheongpa", "t": "차가워요… 아, 차가워. 근데… 괜찮아요. 괜찮은 것 같아요."}, {"s": null, "t": "청파가 발을 조금 더 밀어 넣었다. 발목까지 물이 찰랑 올라왔다. 청파의 무릎이 바들바들 떨렸다. 숨소리가 거칠어지자 나는 청파의 이름을 불렀다."}, {"s": null, "t": "청파가 고개를 들어 나를 보았다. 눈이 젖어 있었지만 입은 웃고 있었다."}, {"s": "q:sn_cheongpa", "t": "네. 여기 있어요. 안 내려가요. 몸이 안 내려가고 싶대요. 그냥… 발만 차가워요."}, {"s": null, "t": "청파가 다른 발도 물에 넣었다. 두 발이 늪 가장자리 물속에 나란히 잠겼다. 청파는 한동안 그대로 앉아 발 위를 지나가는 작은 물고기를 보았다."}, {"s": "q:sn_cheongpa", "t": "물고기가 발등을 콕콕 쪼아요. 아, 간지러워. 물굴에선 물고기가 늘 휙 지나가 버렸는데. 그땐 제가 너무 바빴나 봐요."}, {"s": null, "t": "청파가 물에서 발을 빼고 진흙에 앉은 채 발을 탁탁 털었다. 품에서 작은 주전자 하나와 꿀 단지를 꺼냈다."}, {"s": "q:sn_cheongpa", "t": "오늘은 제가 차를 끓일게요. 꿀 탄 영초 차요. 그때 선창 끝에서 {이름} 님이 가져다주신 거, 제가 다 식혀서 한 번에 마셨잖아요. 사레들려서 등도 두드려 주시고. 오늘은 제가 끓여서, 안 식게 마실 거예요."}, {"s": null, "t": "청파가 주전자에 늪 가장자리 맑은 물을 떠 담았다. 그러고는 갈대 사이 마른 데에 돌을 괴어 불을 지폈다."}, {"s": "q:sn_cheongpa", "t": "차가 끓는 동안 쉬어요. 영초 차는 오래 우려야 목이 틔거든요. 다 우러날 때까지 여기 앉아 있어요. 저 오늘은 물가에 오래 앉아 있고 싶어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_3', 3, '안 식은 차', '천엽 연화늪에서 쉰다', '{"at": ["lotus_marsh"], "tasks": [{"t": "rest", "r": ["lotus_marsh"], "n": 1}]}'::jsonb, '[{"s": null, "t": "늪 위로 해가 지자 풀벌레 소리가 개구리 울음을 밀어냈다. 갈대 사이 작은 불 위에서 주전자가 보글보글 끓었다."}, {"s": null, "t": "청파가 꿀을 한 숟갈 떠 넣고 주전자를 흔들었다. 단내가 김을 타고 퍼졌다."}, {"s": null, "t": "청파가 주전자에서 차를 따라 잔 둘을 채웠다."}, {"s": null, "t": "한 잔을 내 손에 쥐여 주었다. 잔이 뜨거워서 손바닥이 얼얼했다."}, {"s": "q:sn_cheongpa", "t": "뜨거울 때 드세요. 식으면 꿀이 바닥에 가라앉아서 쓴맛만 나요. 그날 제가 마신 게 딱 그 맛이었어요."}, {"s": null, "t": "나는 차를 한 모금 마셨다."}, {"s": null, "t": "꿀의 단맛 뒤로 영초의 쌉싸름한 맛이 목을 타고 내려갔다. 청파도 잔을 두 손으로 감싸 쥐고 홀짝홀짝 마셨다."}, {"s": "q:sn_cheongpa", "t": "그날 밤에요… 저 진짜 가려고 했어요. 짐도 다 싸 놨고요. {이름} 님이 차를 가져다주셔서, 그것만 마시고 가려고 했어요."}, {"s": "q:sn_cheongpa", "t": "근데 {이름} 님이 차만 주시고 아무 말도 없이 옆에 앉아 계셨잖아요. 가라고도 안 하시고, 가지 말라고도 안 하시고요. 그러다 차가 다 식어 버렸어요. 마실 때를 놓쳐서요."}, {"s": null, "t": "청파가 잔을 내려다보며 작게 웃었다."}, {"s": "q:sn_cheongpa", "t": "대장님이 「가지 마시오」 하신 건 제가 동네방네 다 떠들고 다녔는데, {이름} 님이 옆에 앉아 계셨던 건 아무한테도 말 안 했어요. 그건 말하면 안 될 것 같았어요. 제 거 같아서요."}, {"s": null, "t": "나는 잔을 비우고 청파의 잔에 차를 더 따라 주었다. 청파가 얼른 잔을 내밀어 받았다."}, {"s": "q:sn_cheongpa", "t": "이번엔 안 식었어요. 끝까지 따뜻하네요."}, {"s": null, "t": "청파가 잔을 두 손으로 감싸고 김을 후 불었다. 김이 늪 위 어둠 속으로 흩어졌다."}, {"s": null, "t": "청파가 맨발을 다시 늪 물에 살짝 담갔다. 이번에는 떨지 않았다. 발 위로 늪 물이 찰랑거렸다."}, {"s": "q:sn_cheongpa", "t": "오늘은 발만 담갔어요. 다음엔… 다음엔 좀 더 해 볼 수 있을 것 같아요. 그때도 옆에 계셔 주세요. 아무 말도 안 하셔도 돼요. 그날처럼요."}, {"s": null, "t": "청파가 차를 마저 마셨다. 이번에는 식기 전에 다 마셨다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_cheongpa_4', 'side', '연담·청파', '한 숨', '청파가 품고 다니던 기름종이 꾸러미가 백지교 다리 밑 물에 빠진다. 바늘로 걸어 올리려다 실패하자, 청파는 한 숨만 들어가겠다고 하고 내게 줄을 맡긴다.', 'river_ferry', 50, '{rg_cheongpa_3}'::text[], null, 1638, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "cheongpa", "stage": 4}'::jsonb where quest_id = 'rg_cheongpa_4';
delete from public.world_quest_steps where quest_id = 'rg_cheongpa_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_4', 1, '빠진 꾸러미', '빠진 꾸러미', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "잔뜩 흐린 날이라 강물이 납빛으로 가라앉아 있었다. 구름나루 선창 끝에 청파가 쪼그려 앉아 있었다."}, {"s": null, "t": "노는 뱃전에 걸쳐 둔 채였다. 청파의 얼굴이 하얗게 질려 있었다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님… 손님 밥은 하루도 안 빠졌어요. 어제도요. 근데… 어제 일이 났어요."}, {"s": null, "t": "청파가 제 품을 두 손으로 눌러 보였다. 늘 불룩하던 품이 납작했다."}, {"s": "q:sn_cheongpa", "t": "기름종이 꾸러미요. 등도에서 주워 모은 걸 싸 둔 거요. 바랜 등롱 종이 열한 장이랑, 단비 누님이 준 엿 종이랑, 옛 나루 저자 배에서 떨어진 쇠못 하나요."}, {"s": "q:sn_cheongpa", "t": "어제 백지교 다리 밑을 지나다가 기침이 터졌거든요. 몸을 숙였는데 품에서 툭 빠져 버렸어요. 다리 밑 물이 두 길쯤 돼요. 꾸러미가 바닥 바위틈에 걸린 게 위에서도 보여요."}, {"s": null, "t": "청파는 그 말을 하면서도 물을 내려다보지 않았다. 손끝이 바들바들 떨렸다."}, {"s": null, "t": "나는 꾸러미 안의 것이 그렇게 귀하냐고 물었다. 청파가 그렇다는 듯 입을 열었다가, 도로 고개를 저었다."}, {"s": "q:sn_cheongpa", "t": "값은 하나도 없어요. 종이 쪼가리랑 쇠못인걸요. 근데 다 등도에서 하나씩 주운 거예요. 우리가 같이 다닌 데마다 하나씩요."}, {"s": "q:sn_cheongpa", "t": "그걸 품에 넣고 노를 저으면 배가 덜 흔들리는 것 같았어요. 그래서 늘 품에 넣고 다녔는데… 하필 품에 넣고 다녀서 빠졌네요."}, {"s": null, "t": "청파가 웃으려다 그만두었다. 쇳소리가 섞인 기침이 짧게 새어 나왔다."}, {"s": "q:sn_cheongpa", "t": "영감님 갈고리로 해 봤는데 안 닿았어요. 낚싯바늘이면 걸릴지도 몰라요. {이름} 님 바늘은 잘 걸리잖아요. 생선도 잘 걸리고요."}, {"s": null, "t": "나는 바늘로 걸어 보겠다고 했다. 청파가 노를 집어 들었다."}, {"s": "q:sn_cheongpa", "t": "모셔다드릴게요. 걸리면… 걸리면요, 저 진짜 울 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_4', 2, '한 숨만', '백지교에 간다, 백지교에서 낚시를 한다', '{"at": ["paper_bridge"], "tasks": [{"t": "travel", "r": ["paper_bridge"], "n": 1}, {"t": "fish", "r": ["paper_bridge"], "n": 3}]}'::jsonb, '[{"s": null, "t": "흐린 하늘 아래에서도 다리 밑 물은 맑았다. 물이끼 낀 다리 기둥에서 축축한 습기가 배어 나왔다."}, {"s": null, "t": "바닥 바위틈에 기름종이 꾸러미 하나가 끼어 있는 것이 보였다. 나는 줄을 내려 바늘 끝을 꾸러미 쪽으로 몰았다."}, {"s": null, "t": "바늘은 꾸러미를 스치고 지나갔다. 두 번째도, 세 번째도 마찬가지였다. 줄 끝에는 꾸러미 대신 붕어만 올라왔다."}, {"s": null, "t": "청파가 뱃전을 붙잡고 앉아 있었다. 바늘이 꾸러미를 스칠 때마다 청파의 손가락이 뱃전을 꽉 쥐었다."}, {"s": "q:sn_cheongpa", "t": "안 되겠어요. 바위틈에 꽉 끼었나 봐요. 위에서는 안 빠지겠어요."}, {"s": null, "t": "청파가 처음으로 고개를 숙여 물 밑을 내려다보았다. 청파는 물 밑에서 좀처럼 눈을 떼지 못했다. 숨소리가 가늘게 떨렸다."}, {"s": "q:sn_cheongpa", "t": "두 길이에요. 한 숨이면 닿아요. 물굴에서는 아흔여섯 숨도 버텼는걸요. 두 길쯤은… 한 숨이면 돼요."}, {"s": null, "t": "나는 고개를 저었다. 깊은 물에는 다시 들어가지 않기로 한 것 아니냐고 했다. 청파가 고개를 들었다."}, {"s": "q:sn_cheongpa", "t": "깊은 물은 안 들어가요. 이건 얕은 물이에요. 두 길이라니까요. 딱 한 숨이요. 내려가서 꾸러미를 빼 가지고 바로 올라올 거예요."}, {"s": "q:sn_cheongpa", "t": "저 혼자면 안 들어가요. 혼자면 무서우니까요. 근데 {이름} 님이 줄을 잡아 주시면 들어갈 수 있어요. 그때처럼요."}, {"s": null, "t": "청파가 고물에 실린 잠수 줄 사리를 끌어당겼다. 줄 끝을 제 허리에 감고 지난번에 배운 매듭을 지었다. 손이 떨려 매듭이 한 번 어긋났다. 나는 그 매듭을 받아 마저 지었다."}, {"s": "q:sn_cheongpa", "t": "고마워요. 그 매듭이면 안 풀려요. 풀어야 할 땐 제가 한 번에 풀고요."}, {"s": "q:sn_cheongpa", "t": "근데 지금 바로는 안 들어가요. 기침부터 가라앉아야 해요. 기침이 나는 숨으로 들어가면 물을 먹거든요. 숨이 고를 때까지 다리 밑에서 쉬어요. 그다음에 한 숨이에요."}, {"s": null, "t": "청파가 허리에 줄을 감은 채 뱃전에 등을 기대고 눈을 감았다. 나는 줄의 다른 끝을 손에 쥐고 그 곁에 앉았다. 강바람이 젖은 줄을 훑고 지나가 손바닥이 차가웠다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_4', 3, '올라온 숨', '백지교에서 쉰다', '{"at": ["paper_bridge"], "tasks": [{"t": "rest", "r": ["paper_bridge"], "n": 1}]}'::jsonb, '[{"s": null, "t": "구름 사이로 저녁 햇살이 비껴들 무렵 청파의 숨이 고르고 길어졌다. 청파가 눈을 뜨고 허리의 매듭을 손가락으로 눌러 보았다."}, {"s": "q:sn_cheongpa", "t": "됐어요. 이제 기침이 안 나요. 한 번 당기면 기다려 주세요. 두 번 당기면 끌어올려 주시고요. 아무것도 없으면…"}, {"s": null, "t": "청파가 말을 멈췄다. 나는 아무것도 없어도 끌어올리겠다고 했다. 청파가 허리의 매듭을 한 번 더 눌러 보았다."}, {"s": "q:sn_cheongpa", "t": "네, 그게 맞아요. 대장님은 기다린다고 하셨는데… 저는 이제 숨이 짧으니까요."}, {"s": null, "t": "청파가 숨을 세 번 깊이 들이쉬었다. 그러고는 소리도 없이 뱃전을 넘어 물속으로 미끄러졌다. 물이 한 번 출렁였다. 줄이 스르륵 풀려 나갔다."}, {"s": null, "t": "나는 줄을 두 손에 감아 쥐고 하나, 둘, 셋 숨을 셌다. 맑은 물 아래로 청파의 몸이 바위틈 쪽으로 내려가는 것이 보였다."}, {"s": null, "t": "열을 셌을 때였다. 줄이 탁, 탁, 두 번 당겨졌다."}, {"s": null, "t": "나는 줄을 힘껏 끌어당겼다. 물이 철썩 갈라지며 청파의 머리가 솟아올랐다. 청파는 한 손으로 뱃전을 붙잡고 다른 손으로 무언가를 높이 쳐들었다. 기름종이 꾸러미였다."}, {"s": null, "t": "내가 청파의 겨드랑이를 잡아 배 위로 끌어 올렸다. 청파가 배 바닥에 쓰러지듯 엎드려 물을 토했다. 쿨럭쿨럭 쇳소리가 섞인 기침이 오래 이어졌다."}, {"s": null, "t": "나는 청파의 등을 두드렸다. 기침이 겨우 잦아들었다. 청파가 배 바닥에 대자로 누워 꾸러미를 가슴에 꼭 끌어안았다. 젖은 머리칼에서 물이 뚝뚝 떨어졌고 입술이 파랗게 질려 있었다."}, {"s": "q:sn_cheongpa", "t": "…열 숨이었어요. 열 숨! 물굴에선 아흔여섯이었는데, 오늘은 열 숨에 죽는 줄 알았어요."}, {"s": null, "t": "청파가 웃었다. 처음에는 작게 웃다가 기침을 하고, 기침을 하다가 다시 웃었다. 웃음이 멈추지 않아 배가 흔들렸다."}, {"s": "q:sn_cheongpa", "t": "근데 들어갔어요. 들어갔다 나왔다고요! 몸이 밑으로 안 내려가고 싶어 했어요. 위로 올라오고 싶어 했어요. 줄이 위에 있으니까요."}, {"s": null, "t": "청파가 꾸러미를 풀어 보였다. 바랜 등롱 종이 열한 장과 엿 종이 한 장, 쇠못 하나가 젖지 않은 채 그대로 들어 있었다."}, {"s": "q:sn_cheongpa", "t": "다 있어요. 하나도 안 젖었어요! 기름종이는 원래 안 젖거든요. 그래서 이걸로 싼 거예요."}, {"s": null, "t": "청파가 허리에 감긴 줄을 풀지 않은 채 줄을 따라 손을 뻗었다. 줄 끝은 아직 내 손에 감겨 있었다. 청파는 그 손을 가만히 보다가 눈을 감았다."}, {"s": "q:sn_cheongpa", "t": "줄 끝에 {이름} 님 손이 있으니까 올라온 거예요. 다음에도… 아니에요. 오늘은 그냥 누워 있을래요."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_cheongpa_5', 'side', '연담·청파', '당번', '청파가 강을 거슬러 물이 시작되는 천경호까지 배를 몰고 가 보자고 한다. 호수에서 밤을 지새운 새벽, 청파는 제 허리 줄 끝을 내 손목에 감는다.', 'river_ferry', 50, '{rg_cheongpa_4}'::text[], null, 1639, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "cheongpa", "stage": 5}'::jsonb where quest_id = 'rg_cheongpa_5';
delete from public.world_quest_steps where quest_id = 'rg_cheongpa_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_5', 1, '물 시작하는 데', '물 시작하는 데', '{"at": ["river_ferry"]}'::jsonb, '[{"s": null, "t": "아침 햇살이 강물 위에서 잘게 부서지고 있었다. 구름나루 선창에 매인 청파의 배에 짐이 실려 있었다."}, {"s": null, "t": "짐은 물통과 꿀 단지, 작은 주전자, 고물에 감긴 잠수 줄 사리였다. 청파가 뱃머리에서 노를 닦고 있었다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님! {이름} 님이 날라다 주신 생선이요, 세어 보니까 손님 밥을 백 끼가 넘게 채웠더라고요. 행수님이 세어 주셨어요. 제 기침 세시듯이요."}, {"s": null, "t": "청파가 노를 뱃전에 기대 세우고 강 위쪽을 가리켰다. 강은 산 사이로 구불구불 거슬러 올라가고 있었다."}, {"s": "q:sn_cheongpa", "t": "오늘은 손님 없이 가요. 강 맨 위까지요. 천경호요! 이 강물이 다 거기서 시작한대요. 저는 평생 강 아래로만 다녀서, 물이 어디서 시작하는지 한 번도 못 봤어요."}, {"s": null, "t": "청파가 노를 다시 집어 들었다."}, {"s": "q:sn_cheongpa", "t": "노를 맡고 나서 강 아래는 다 가 봤어요. 염등촌도, 갑문도요. 근데 위로는 한 번도 안 가 봤어요. 거슬러 가려면 숨이 많이 들거든요."}, {"s": "q:sn_cheongpa", "t": "근데 이제는 갈 수 있을 것 같아요. 백지교에서 열 숨 동안 들어갔다 나왔잖아요. 숨이 짧아도 쉬엄쉬엄 가면 돼요. 그리고… {이름} 님이랑 가면 되고요."}, {"s": null, "t": "청파가 노 끝으로 뱃전을 톡 치며 웃었다."}, {"s": null, "t": "나는 선창 쪽을 돌아보았다. 노들 영감이 말뚝에 걸터앉아 손을 휘휘 내젓고 있었다."}, {"s": "river_alliance:nodeul", "t": "거슬러 가는 길은 젊은 것들이나 가는 게다. 내 허리는 강 아래밖에 몰라."}, {"s": null, "t": "영감이 그 말을 하고 품에서 꿀 단지 하나를 꺼내 청파의 배에 툭 던져 넣었다. 청파가 단지를 두 손으로 받아 들고 웃었다."}, {"s": "q:sn_cheongpa", "t": "영감님은 맨날 저러세요. 안 간다면서 꿀은 꼭 챙겨 주세요."}, {"s": "q:sn_cheongpa", "t": "천경호엔 하늘이 비치는 물고기가 산대요. 그걸 낚아다가 손님들한테 자랑할 거예요. 「물이 시작하는 데 사는 생선이에요」 하고요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_5', 2, '하늘 비치는 물', '천경호에 간다, 천경호에서 낚시를 한다', '{"at": ["sky_lake"], "tasks": [{"t": "travel", "r": ["sky_lake"], "n": 1}, {"t": "fish", "r": ["sky_lake"], "n": 3}]}'::jsonb, '[{"s": null, "t": "강을 거슬러 오르는 데 이틀이 걸렸다. 밤에는 강가 풀숲에 배를 대고 여울 소리를 들으며 잤다."}, {"s": null, "t": "청파는 노를 젓다가 숨이 차면 배를 강가에 대고 쉬었다. 그때마다 나는 노를 받아 조금씩 저었다."}, {"s": null, "t": "천경호에 닿은 것은 해 질 녘이었다. 산에서 내려온 바람이 차고 맑아 숨이 가슴 깊이 들어갔다."}, {"s": null, "t": "호수는 거울처럼 잔잔했다. 하늘과 산이 호수 위에 거꾸로 비쳐, 배가 하늘 위에 떠 있는 것 같았다."}, {"s": "q:sn_cheongpa", "t": "와… {이름} 님, 이거 보세요. 배 밑에 하늘이 있어요!"}, {"s": null, "t": "청파가 뱃전에 엎드려 호수를 내려다보았다."}, {"s": null, "t": "백지교에서처럼 망설이지 않았다. 물 밑에 비친 하늘을 오래 보았다."}, {"s": "q:sn_cheongpa", "t": "이상하다. 밑을 보는데 하나도 안 무서워요. 밑에 하늘이 있어서 그런가 봐요. 하늘로 내려가고 싶은 사람은 없잖아요."}, {"s": null, "t": "나는 줄을 던져 호수의 생선을 낚았다."}, {"s": null, "t": "비늘이 하늘빛으로 반짝이는 생선이 올라왔다. 청파가 생선을 두 손으로 받아 들고 입을 벌렸다."}, {"s": "q:sn_cheongpa", "t": "진짜예요! 비늘에 하늘이 비쳐요! 손님들이 이거 보면 다 노래하겠다."}, {"s": null, "t": "해가 지자 호수에 별이 떴다. 위에도 별, 아래에도 별이었다. 청파가 주전자에 호숫물을 떠서 꿀을 탄 영초 차를 끓였다."}, {"s": "q:sn_cheongpa", "t": "오늘은 여기서 자요. 배 위에서요. 나루에선 밤새 물 차오르는 소리를 들으며 잤는데, 여긴 물이 꼼짝도 안 하네요. 그러니까 오늘은 별 소리를 들으면서 자요."}, {"s": null, "t": "청파가 뱃바닥에 담요 두 장을 나란히 깔았다. 고물의 잠수 줄 사리가 담요 머리맡에 놓였다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_cheongpa_5', 3, '생명줄', '천경호에서 쉰다', '{"at": ["sky_lake"], "tasks": [{"t": "rest", "r": ["sky_lake"], "n": 1}]}'::jsonb, '[{"s": null, "t": "밤새 배는 호수 위에 가만히 떠 있었다. 새벽 안개가 수면 위로 낮게 깔렸고, 뱃전에 맺힌 이슬이 손등에 차갑게 떨어졌다. 내가 눈을 떴을 때 청파는 이미 일어나 앉아 잠수 줄 사리를 무릎에 풀어 놓고 있었다."}, {"s": null, "t": "청파가 줄 끝을 제 허리에 감았다. 매듭을 지었다. 식구 매듭도, 잠수꾼 매듭도 아닌, 처음 보는 모양이었다."}, {"s": null, "t": "나는 또 들어가려느냐고 물었다. 청파가 고개를 저었다."}, {"s": "q:sn_cheongpa", "t": "아니요, 안 들어가요. 오늘은 줄만 매는 거예요. 물에 안 들어가도 줄 끝을 누가 잡고 있는지 알면 마음이 놓이거든요."}, {"s": null, "t": "청파가 허리에 감은 줄을 따라 손을 뻗어 반대쪽 끝을 집어 들었다. 그 끝을 들고 내 앞으로 다가와 앉았다."}, {"s": "q:sn_cheongpa", "t": "손 주세요. 오른손이요. 노를 잡는 손 말고요."}, {"s": null, "t": "나는 손을 내밀었다. 청파가 줄 끝을 내 손목에 한 번, 두 번, 세 번 감았다. 그러고는 물굴에서 내가 지었던 그 매듭으로 묶었다. 투박하게 뭉친 매듭이었다."}, {"s": null, "t": "나는 그 매듭은 내 매듭이라고 했다. 청파가 매듭을 손가락으로 톡 건드리며 웃었다."}, {"s": "q:sn_cheongpa", "t": "네. {이름} 님 매듭이에요. 이건 안 풀려요. 풀어야 할 때도 안 풀려요. 그래서 이걸로 묶은 거예요."}, {"s": null, "t": "청파의 허리와 내 손목이 줄 하나로 이어졌다. 안개 속에서 줄이 느슨하게 늘어져 뱃바닥에 고리를 만들었다."}, {"s": "q:sn_cheongpa", "t": "수향 잠수꾼은 줄 잡을 사람을 정해 둬요. 물에 들 때마다 바꾸는 게 아니라, 늘 같은 사람한테 맡겨요. 그 사람 손을 알아야 줄이 당겨질 때 무슨 뜻인지 알거든요."}, {"s": "q:sn_cheongpa", "t": "물굴에서도, 백지교에서도, 그 전에 문패 건지던 날에도 {이름} 님이 잡아 주셨어요. 다른 사람한테 맡긴 적이 한 번도 없어요. 그러니까 이제 정할게요."}, {"s": null, "t": "청파가 숨을 한 번 고르고 쿨럭 기침을 했다. 기침이 멎자 청파는 내 손목의 매듭을 두 손으로 감쌌다."}, {"s": "q:sn_cheongpa", "t": "청파의 생명줄 당번이에요. {이름} 님이요. 제가 다시는 깊은 물에 못 들어가도, 이 줄은 {이름} 님 거예요. 물 위에서도요. 강을 거슬러 갈 때도요."}, {"s": "q:sn_cheongpa", "t": "바꾸면 안 돼요, {이름} 님. 당번은 바꾸는 거 아니에요. 아셨죠?"}, {"s": null, "t": "청파가 웃었다. 눈가가 젖어 있었지만 얼굴은 환했다. 안개가 걷히며 호수 위로 아침 해가 올라왔다. 위에도 해, 아래에도 해였다."}, {"s": null, "t": "청파가 줄을 허리에 감은 채 노를 잡았다. 나는 손목에 줄을 감은 채 그 곁에 앉았다. 배가 강을 따라 천천히 내려가기 시작했다. 줄은 내내 둘 사이에 느슨하게 걸려 있었다."}]'::jsonb, '{"gil": 205, "title": "rg_cheongpa", "items": {"hf_rg_cheongpa_reel": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_galmae_1', 'side', '연담·갈매', '무딘 칼들', '봄갈이를 앞둔 보름, 갈매가 화로 앞 걸상에서 마을 낫과 호미를 갈고 있다. 이가 빠진 날을 덧대려면 쇠가 있어야 하는데, 남의 쇠로 일하기 싫은 갈매가 주인공에게 쇠를 산다. 갈매는 등 뒤에 사람을 두지 않는다.', 'ember_village', 50, '{mde_galmae_2}'::text[], null, 1640, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_galmae_1';
delete from public.world_quest_steps where quest_id = 'rg_galmae_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_1', 1, '숫돌', '숫돌', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "봄갈이를 앞둔 보름이었다. 아직 바람 끝이 찼지만 잔불촌 화로 앞은 훈훈했고, 재 섞인 숯내가 골목 어귀까지 배어 나왔다. 화로 앞 걸상에 갈매가 앉아 있었다. 걸상 둘레 멍석 위에 낫이며 호미며 식칼이 수북이 쌓여 있었다."}, {"s": null, "t": "갈매는 숫돌을 무릎에 얹고 낫 하나를 갈고 있었다. 슥, 슥, 쇠 긁는 소리가 숯 튀는 소리에 섞였다."}, {"s": null, "t": "나는 인사를 하려고 갈매 뒤쪽으로 다가갔다. 내가 세 걸음 안으로 들어서자 갈매가 낫을 쥔 채 휙 돌아앉았다."}, {"s": "southern_remnant:galmae", "t": "야, 뒤로 오지 말라니까. 정찰대장 뒤에 소리 없이 붙는 놈은 대개 한 대 맞는다? …뭐야, 정청 끄나풀이잖아. 언제 왔어?"}, {"s": null, "t": "갈매가 낫을 도로 숫돌에 얹었다. 나는 앞으로 돌아가 멍석 맞은편에 쪼그려 앉았다."}, {"s": null, "t": "나는 멍석 위에 쌓인 날붙이 더미를 훑어보았다. 갈매가 내 눈길을 보더니 숫돌에 물을 한 줌 끼얹었다."}, {"s": "southern_remnant:galmae", "t": "마을 것을 싹 다 모아 왔지. 겨우내 언 땅을 파느라 날이 죄다 나갔대. 봄갈이 전엔 벼려 놔야 되거든."}, {"s": "southern_remnant:galmae", "t": "숫돌로 될 만한 건 갈고 있는데, 이런 꼴인 건 어림도 없어."}, {"s": null, "t": "갈매가 멍석 끝에서 호미 하나를 집어 들어 보였다. 날 끝이 이가 빠져 톱니처럼 들쭉날쭉했고, 겨우내 슨 녹에서 시큼한 쇳내가 끼쳤다."}, {"s": "southern_remnant:galmae", "t": "봐, 이건 날을 새로 덧대야 돼. 근데 덧대려면 쇠가 있어야 하잖아."}, {"s": null, "t": "나는 쇠불의 대장간에 쇠가 없느냐고 물었다. 갈매가 콧등을 찡그렸다."}, {"s": "southern_remnant:galmae", "t": "쇠불네 쇠는 쇠불이 거지. 그 녀석의 쇠로 내 일을 하면 그게 다 빚이야. 남명 사람은 빚지고는 못 산다고."}, {"s": null, "t": "화로 곁을 지나던 머루댁이 등에 업은 새벽이를 추스르며 혀를 끌끌 찼다."}, {"s": "q:sx_md_meoru", "t": "빚은 무슨 빚이야. 쇠불이는 달라면 군말 없이 줄 텐데. 아이고, 저 고집은 장군님한테서 고스란히 물려받았다니까."}, {"s": null, "t": "갈매는 머루댁 쪽을 보지도 않고 숫돌을 문질렀다. 머루댁이 웃으며 공동 부엌 쪽으로 걸어갔다. 포대기 밖으로 나온 새벽이의 주먹이 꼼지락거렸다."}, {"s": null, "t": "갈매가 낫을 내려놓고 나를 빤히 보았다."}, {"s": "southern_remnant:galmae", "t": "너, 쇠를 캘 줄 알지? 주괴도 부을 줄 알고. 그치?"}, {"s": null, "t": "나는 안다고 했다. 갈매가 턱을 들었다."}, {"s": "southern_remnant:galmae", "t": "그럼 너한테 살게. 공짜는 사양이야, 값은 제대로 쳐 줄 거고. 너한테 빚지는 건 더 싫거든."}, {"s": "southern_remnant:galmae", "t": "캘 거면 주혈 광산 월철로 해. 붉은 결이 굵어서 갯밭 흙에도 덜 닳거든. 아, 광산 원령들이 밤낮 굴속에서 쇳소리를 내며 울어 대니까 귀 단단히 막고 조심하고."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_1', 2, '그 자리 셈', '주혈 광산에서 월철 광석을(를) 모은다', '{"at": ["ember_village"], "tasks": [{"t": "gather", "items": ["ore"], "r": ["crimson_mine"], "n": 6}]}'::jsonb, '[{"s": null, "t": "광석 자루를 멍석 곁에 내려놓자 갈매가 자루 끈을 풀자 광산 굴의 축축한 흙내가 훅 올라왔다. 갈매가 한 덩이를 꺼냈다. 갈매는 광석을 화로 불빛에 이리저리 비춰 보았다."}, {"s": "southern_remnant:galmae", "t": "오, 결이 좋은데? 원령한테 쫓기지는 않았고?"}, {"s": null, "t": "나는 조금 쫓겼다고 했다. 갈매가 코웃음을 치면서 내 소매 끝에 묻은 돌가루를 툭툭 털어 주었다. 털고 나서야 제가 무엇을 했는지 알아챈 듯 손을 홱 거두었다."}, {"s": "southern_remnant:galmae", "t": "…가, 가루가 숫돌에 들어가면 날이 상하니까 그런 거야."}, {"s": null, "t": "갈매가 허리춤 주머니에서 엽전 꾸러미를 꺼내 멍석 위에 철컥 내려놓았다."}, {"s": "southern_remnant:galmae", "t": "자, 광석 값이야. 세어 봐."}, {"s": null, "t": "나는 꾸러미를 세지 않고 도로 밀었다. 아직 주괴를 붓지 않았으니 다 하고 받겠다고 했다. 갈매가 눈썹을 치켜올렸다."}, {"s": "southern_remnant:galmae", "t": "셈은 그 자리에서 하는 거라니까. 우리 집 영감이 입에 달고 살던 소리야. 미루면 잊어버리고, 잊어버리면 그게 곧 빚이라고."}, {"s": null, "t": "갈매가 꾸러미를 내 무릎 위에 도로 얹었다. 엽전이 짤랑 울렸다. 갈매 주머니에 들어 있던 엽전은 체온이 배어 미지근했다. 나는 하는 수 없이 꾸러미를 품에 넣었다."}, {"s": null, "t": "그때 아이 하나가 낫을 질질 끌며 화로 쪽으로 달려왔다. 아이의 맨발에 재가 허옇게 묻어 있었다. 아이는 갈매 앞에서 숨을 헐떡이며 낫을 내밀었다."}, {"s": "q:md_child", "t": "갈매 누나! 우리 할머니 낫도 좀요. 이게 없으면 나물을 못 캐신대요."}, {"s": null, "t": "갈매가 낫을 받아 날을 엄지로 쓸어 보았다. 아이는 갈매가 무어라 할지 몰라 발끝을 꼼지락거렸다."}, {"s": "southern_remnant:galmae", "t": "어디 보자… 이것도 덧대야겠네. 내일 와서 찾아가. 할머니한테 날 쪽은 잡지 마시라고 꼭 전하고."}, {"s": null, "t": "아이가 고개를 꾸벅 숙이고 쪼르르 뛰어갔다. 갈매가 멍석 위의 낫과 호미를 손가락으로 짚어 가며 세었다."}, {"s": "southern_remnant:galmae", "t": "덧댈 게 열하나네. 주괴 셋이면 되겠다."}, {"s": null, "t": "갈매가 손가락을 거두고 턱으로 대장간 쪽을 가리켰다."}, {"s": "southern_remnant:galmae", "t": "쇠불이한테 풀무만 빌리자. 동네 풀무는 빚이 아니니까. …말은 내가 해 둘게. 너는 붓기만 하면 돼."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_1', 3, '열한 자루', '월철 주괴을(를) 만든다, 월철 주괴을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "craft", "items": ["iron_ingot"], "n": 3}], "give": {"iron_ingot": 3}}'::jsonb, '[{"s": null, "t": "주괴 셋을 넘기자 갈매는 밤이 깊도록 화로 곁에서 날을 덧댔다. 대장간에서 빌려 온 작은 모루가 걸상 앞에 놓여 있었다. 밤공기가 차서 화로 곁을 조금만 벗어나도 어깨가 으슬으슬했다."}, {"s": null, "t": "갈매는 달군 쇠를 모루에 얹고 땅, 땅, 땅 짧게 두드렸다. 망치를 쥔 팔이 칼을 쥘 때처럼 곧았다."}, {"s": null, "t": "나는 화로 건너편에 앉아 다 된 날을 물통에 담갔다. 치이익 소리와 함께 쇳내 섞인 김이 얼굴로 확 끼쳤다. 김이 오를 때마다 갈매가 고개를 들어 내 쪽을 흘끗 보았다."}, {"s": null, "t": "나는 망치질은 누구에게 배웠느냐고 물었다."}, {"s": "southern_remnant:galmae", "t": "대장간 어깨너머로 배웠지. 할배는 숫돌만 가르쳐 줬어. 제 칼은 제가 갈아야 한다면서."}, {"s": "southern_remnant:galmae", "t": "일곱 살 땐가, 대장간 망치를 몰래 들고 나가서 혼자 두드려 봤거든. 쇠가 엿가락처럼 휘어 버린 거야. 근데 할배가 그걸 보고도 혼을 안 내더라. 그날 밤 국수만 유난히 굵게 썰었고."}, {"s": null, "t": "갈매가 그 말을 하고 망치를 멈췄다. 화로 불빛이 갈매의 옆얼굴에서 일렁였다. 갈매는 곧 다시 망치를 들었다."}, {"s": null, "t": "날을 덧댄 낫과 호미가 열한 자루가 되었다. 멍석 위의 새 날들이 화로 불빛을 받아 푸르스름하게 번뜩였다. 갈매가 마지막 자루를 멍석에 눕히고 어깨를 돌렸다. 우두둑 소리가 났다."}, {"s": "southern_remnant:galmae", "t": "자, 끝! 아침이면 다들 찾으러 오겠지."}, {"s": null, "t": "나는 모루를 대장간에 갖다 놓으려고 들어 올렸다. 모루를 안고 갈매 등 뒤로 돌아 나가는데, 갈매의 어깨가 움찔 굳었다가 천천히 풀렸다."}, {"s": "southern_remnant:galmae", "t": "…너 또 뒤로 갔지."}, {"s": null, "t": "나는 모루가 무거워서 그쪽으로 돌았다고 했다. 갈매가 돌아보지 않고 대꾸했다."}, {"s": "southern_remnant:galmae", "t": "알아, 알아. 그냥 버릇이야. 정찰대는 등 뒤에 사람을 안 두거든. 할배 말고는 아무도 안 뒀어."}, {"s": null, "t": "갈매는 그 말을 하고 입을 다물었다. 화로 속 숯이 타닥 튀었다. 갈매가 숫돌을 주머니에 쑤셔 넣으며 나를 돌아보았다."}, {"s": "southern_remnant:galmae", "t": "또 올 거지? 마을 일은 끝이 없거든. 낫이 끝나면 식칼이고, 식칼이 끝나면 또 낫이고."}, {"s": "southern_remnant:galmae", "t": "앞으로도 쇠를 좀 대 줄래? 필요한 건 그때그때 말할게."}, {"s": null, "t": "나는 그러겠다고 했다. 갈매가 「좋아」 하고 짧게 대꾸하더니 멍석 위의 낫 하나를 집어 들었다."}, {"s": "southern_remnant:galmae", "t": "셈은 끝났고, 이건 덤이야. 네가 캔 쇠로 덧댄 낫이야. 정청 끄나풀도 나물은 캐 먹어야 할 거 아냐."}, {"s": null, "t": "갈매가 낫 자루를 내 손에 쥐여 주었다. 자루에 갈매 손의 온기가 남아 있었다. 셈을 그렇게 따지던 사람이 덤을 얹어 주는 모습은 처음 보았다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_galmae_2', 'side', '연담·갈매', '대장간 불', '대장장이 쇠불이 장을 보러 가 대장간이 빈 보름, 공동 부엌 식칼이 부러진다. 갈매는 식은 풀무에 불을 넣고 주인공에게 칼 벼리는 법을 가르친다. 할배가 그랬듯 등 뒤에 서서 손등을 덮는다.', 'ember_village', 50, '{rg_galmae_1}'::text[], null, 1641, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "galmae", "stage": 2}'::jsonb where quest_id = 'rg_galmae_2';
delete from public.world_quest_steps where quest_id = 'rg_galmae_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_2', 1, '쪽지 붙은 문', '쪽지 붙은 문', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "봄갈이가 끝난 뒤의 보름이었다. 잔불촌 밭마다 이랑이 반듯하게 서 있었다. 갈아엎은 흙에서 들큰한 냄새가 올라왔고, 한낮 볕이 등에 따끈했다."}, {"s": null, "t": "갈매는 화로 앞이 아니라 대장간 문 앞에 서 있었다. 문에는 쪽지 한 장이 붙어 있었다. 「장 보러 감. 사흘 뒤 옴. 쇠불.」이라고 적혀 있었다."}, {"s": null, "t": "갈매가 내 발소리를 듣고 고개를 돌렸다. 이번에는 돌아앉지 않았다. 내가 앞쪽에서 걸어오고 있었기 때문이다."}, {"s": "southern_remnant:galmae", "t": "어, 왔네. 그사이 네가 갖다 준 주괴로 쟁기 보습 둘이랑 낫 일곱을 벼렸어. 수리 도구는 파수막마다 하나씩 돌렸고. 다들 날이 잘 든다더라."}, {"s": "southern_remnant:galmae", "t": "근데 오늘은 이게 말썽이야."}, {"s": null, "t": "갈매가 등 뒤에 감추고 있던 것을 내밀었다. 손잡이 바로 위에서 뚝 부러진 식칼이었다. 부러진 자리에 허연 비계가 엉겨 붙어 고기 기름내가 났다."}, {"s": "southern_remnant:galmae", "t": "공동 부엌 칼이야. 온 마을 밥줄이지. 어멈이 뼈를 내리치다가 이렇게 됐대. 부엌 칼이 두 자루뿐인데 둘 다 이가 나가서, 이러다 오늘 저녁 국거리를 손으로 찢게 생겼다니까."}, {"s": null, "t": "나는 쇠불이 올 때까지 기다리자고 했다. 갈매가 쪽지를 손가락으로 툭 쳤다."}, {"s": "southern_remnant:galmae", "t": "사흘이야, 사흘. 그동안 온 마을이 고기를 손으로 찢어 먹으라고? 내가 두드릴래. 쇠불이가 풀무는 마음대로 쓰랬어."}, {"s": null, "t": "갈매가 대장간 문을 밀어 열었다. 화덕이 싸늘하게 식어 있었다. 눅눅한 재 냄새가 코에 감겼고, 손을 대 보니 화덕 돌이 얼음장처럼 찼다. 숯 바구니가 바닥을 드러내고 있었다."}, {"s": "southern_remnant:galmae", "t": "숯도 쇠불이 거니까 손도 안 대. 불씨 고개 바위틈에 정련 숯이 나오거든. 그걸로 하면 돼."}, {"s": null, "t": "갈매가 빈 숯 바구니를 내 쪽으로 밀었다. 그러다 무언가 생각난 듯 바구니를 도로 끌어당겼다."}, {"s": null, "t": "나는 미심쩍은 얼굴로 쪽지를 다시 보았다. 갈매가 쪽지 아래 귀퉁이를 손가락으로 짚었다."}, {"s": null, "t": "쪽지 귀퉁이에 작은 글씨로 「갈매 누나는 풀무 써도 됨.」이라는 한 줄이 더 적혀 있었다."}, {"s": "southern_remnant:galmae", "t": "봤지? 풀무만이라고. 숯이랑 쇠는 쓰라는 말이 없잖아."}, {"s": "southern_remnant:galmae", "t": "같이 가자고 하려다 말았어. 화덕 바닥에 재가 굳어서 긁어내야 하거든. 너는 숯, 나는 재. 그래야 해 지기 전에 불을 넣지."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_2', 2, '등 뒤에서', '불씨 고개에서 정련 숯을(를) 모은다', '{"at": ["ember_village"], "tasks": [{"t": "gather", "items": ["charcoal"], "r": ["ember_pass"], "n": 4}]}'::jsonb, '[{"s": null, "t": "숯 바구니를 들고 대장간에 들어서자 화덕 바닥이 말끔했다. 긁어낸 재가 아직 뿌옇게 떠 있어 코가 간질거렸다. 갈매의 뺨에 재가 시커멓게 묻어 있었다."}, {"s": null, "t": "갈매가 숯을 화덕에 붓고 불씨를 넣었다. 나는 풀무 손잡이를 잡고 밀었다 당겼다. 쉭, 쉭, 바람이 들어갈 때마다 숯이 붉게 일어섰다. 화덕에서 뿜어 나온 열기에 눈이 따가웠다."}, {"s": "southern_remnant:galmae", "t": "됐다. 이번엔 너도 한번 두드려 봐."}, {"s": null, "t": "나는 풀무 손잡이를 놓고 얼떨떨하게 갈매를 보았다. 갈매가 무쇠 토막 하나를 집게로 집어 불 속에 넣었다."}, {"s": "southern_remnant:galmae", "t": "칼은 쓰는 사람이 한 번은 두드려 봐야 돼. 그래야 날이 왜 그렇게 생겼는지 알지."}, {"s": null, "t": "무쇠가 붉게 달아오르자 갈매가 그것을 모루에 올렸다. 갈매가 망치를 내 손에 쥐여 주었다."}, {"s": null, "t": "내가 첫 망치를 내리치자 쇠가 옆으로 비껴 미끄러졌다. 땅, 소리가 엇나갔다. 갈매가 혀를 찼다."}, {"s": "southern_remnant:galmae", "t": "아니, 팔로 치지 말고. 어깨에 힘 좀 빼 봐."}, {"s": null, "t": "갈매가 내 등 뒤로 돌아와 섰다. 갈매의 손이 망치 쥔 내 손등을 덮었다. 다른 손은 내 어깨를 지그시 눌렀다."}, {"s": "southern_remnant:galmae", "t": "들었다가, 떨어뜨려. 내리치는 게 아니라 그냥 떨어뜨리는 거야. …그렇지, 그거야."}, {"s": null, "t": "망치가 쇠 한가운데에 땅 떨어졌다. 둘째 망치, 셋째 망치가 땅, 땅 같은 자리에 떨어졌다. 엇나가던 소리가 고르게 박자를 찾았다."}, {"s": null, "t": "갈매의 숨이 내 귀 뒤에서 일정하게 오갔다. 갈매의 옷자락에서 숯내와 땀내가 섞여 났다. 망치가 열 번쯤 떨어진 뒤에야 갈매가 손을 뗐다."}, {"s": "southern_remnant:galmae", "t": "할배가 딱 이렇게 가르쳤어. 뒤에 서서. 팔이 하나라 한 손으로 내 손등만 덮었지만."}, {"s": null, "t": "갈매가 한 걸음 물러섰다. 나는 망치를 든 채 돌아보지 않고 다음 망치를 떨어뜨렸다."}, {"s": "southern_remnant:galmae", "t": "됐어, 그 박자로 두 자루를 만들자. 어멈 부엌 칼이 두 자루니까. 날 세우는 건 내가 봐 줄게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_2', 3, '숫돌 앞의 손', '무쇠 식칼을(를) 만든다, 무쇠 식칼을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "craft", "items": ["lt_cook_2"], "n": 2}], "give": {"lt_cook_2": 2}}'::jsonb, '[{"s": null, "t": "식칼 두 자루를 넘기자 갈매가 숫돌에 물을 끼얹었다. 갈매는 칼 한 자루를 숫돌에 눕히고 나를 손짓해 불렀다."}, {"s": "southern_remnant:galmae", "t": "날은 네가 세워 봐. 내가 뒤에서 봐 줄게."}, {"s": null, "t": "나는 숫돌 앞에 앉아 사각사각 칼을 밀었다. 갈매가 다시 내 등 뒤에 무릎을 꿇고 앉아 칼등을 쥔 내 손 위에 제 손을 얹었다."}, {"s": "southern_remnant:galmae", "t": "각도를 좀 더 눕혀. 손가락 하나 들어갈 만큼만 띄우고. 옳지, 그렇게."}, {"s": null, "t": "갈매의 손이 내 손등 위에서 숫돌을 따라 오갔다. 화덕 불이 등 뒤에서 따뜻했다. 숫돌에서 갈려 나온 쇳물이 거무스름하게 번졌다. 사각거리는 소리 말고는 대장간이 조용했다."}, {"s": "southern_remnant:galmae", "t": "처음 이렇게 숫돌을 배울 때 말이야, 등 뒤에 누가 있는데 하나도 안 무서운 게 이상하더라. 원래는 뒤에서 기척만 나도 칼부터 뽑았거든."}, {"s": null, "t": "갈매가 말을 끊었다. 숫돌 위의 칼이 멈췄다. 갈매가 내 손등에서 손을 거두고 내 뒤통수를 내려다보는 기척이 났다."}, {"s": "southern_remnant:galmae", "t": "…너는 아까부터 내가 뒤에 서 있는데 한 번을 안 돌아보네."}, {"s": null, "t": "나는 뒤에 선 사람이 갈매여서 돌아볼 까닭이 없었다고 했다."}, {"s": null, "t": "대장간이 한동안 조용했다. 갈매가 일어서는 소리가 났다. 돌아보니 갈매의 귀 끝이 화덕 불빛보다 빨갰다."}, {"s": "southern_remnant:galmae", "t": "칼이나 마저 갈아! 어멈이 기다리시잖아."}, {"s": null, "t": "대장간 문간에서 부엌 어멈 복례가 앞치마에 손을 닦으며 고개를 들이밀었다. 앞치마에서 다진 파 냄새가 풍겼다."}, {"s": "q:sn_bokrye", "t": "망치 소리가 나길래 와 봤소. 쇠불이가 벌써 왔나 했더니, 정찰대장이었구려."}, {"s": null, "t": "갈매가 날을 세운 식칼 두 자루를 무명에 싸서 복례에게 건넸다. 복례가 칼 한 자루를 꺼내 엄지로 날을 살짝 쓸어 보았다."}, {"s": "q:sn_bokrye", "t": "아이고, 잘 드는구려. 이제 저녁 국거리는 손으로 안 찢어도 되겠소."}, {"s": null, "t": "복례가 칼을 품에 안고 공동 부엌 쪽으로 돌아갔다. 부엌 쪽에서 국 끓는 냄새가 구수하게 건너왔다. 갈매가 모루 위에 남은 쇠 부스러기를 손바닥으로 쓸어 담았다."}, {"s": "southern_remnant:galmae", "t": "쇠불이가 오면 숯 바구니를 채워 놨다고 해 줘. 남의 대장간을 썼으면 갚고 가야지."}, {"s": null, "t": "나는 숯은 내가 캐 왔으니 내가 갚은 셈이라고 했다. 갈매가 쇠 부스러기 한 줌을 내 손바닥에 털어 놓았다."}, {"s": "southern_remnant:galmae", "t": "그럼 이건 네 몫. 첫 망치에 튄 거야. 엇나간 그놈."}, {"s": null, "t": "갈매가 웃음을 참으며 화덕 불을 덮었다. 나는 엇나간 쇠 부스러기를 버리지 않고 주머니에 넣었다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_galmae_3', 'side', '연담·갈매', '돌담', '한여름 보름, 갈매가 주인공의 닳은 무기를 보고 수리 도구를 맡긴다. 저녁에는 재의 해안에서 낚은 생선을 들고 마을 어귀 돌담에 올라 해 뜰 때까지 앉는다. 예전에는 갈매가 말이 없었지만 이번엔 갈매가 먼저 말을 건다. 둘은 등을 맞대고 앉는다.', 'ember_village', 50, '{rg_galmae_2}'::text[], null, 1642, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "galmae", "stage": 3}'::jsonb where quest_id = 'rg_galmae_3';
delete from public.world_quest_steps where quest_id = 'rg_galmae_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_3', 1, '닳은 날', '닳은 날', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "한여름 보름이었다. 잔불촌 골목마다 해가 쨍쨍 내리쬐었고, 화로 둘레에 놓인 물동이가 미지근하게 데워져 있었다. 골목 감나무에서 매미가 귀가 따갑게 울어 댔다."}, {"s": null, "t": "갈매는 화로 그늘 쪽 걸상에 앉아 부지깽이로 숯을 고르고 있었다. 갈매가 나를 보자 부지깽이로 제 발치를 톡톡 두드렸다. 앉으라는 뜻이었다."}, {"s": "southern_remnant:galmae", "t": "쇠불이가 네 얘기를 하더라. 네가 두드린 식칼을 보고 배를 잡고 웃더라고. 박자는 맞는데 힘이 한쪽으로 쏠렸다고. 어멈은 그래도 그 칼이 제일 잘 든대."}, {"s": null, "t": "나는 갈매 발치에 앉았다. 갈매가 내 허리춤을 보더니 눈을 가늘게 떴다."}, {"s": "southern_remnant:galmae", "t": "잠깐, 그거 이리 줘 봐."}, {"s": null, "t": "나는 {직업:호위=칼을/월궁=활을/퇴마=방울을/의무=부채를/봉인=금강령을/암영=단도를/조련=활을/*=무기를} 풀어 갈매에게 건넸다. 갈매가 그것을 무릎에 놓고 손끝으로 이리저리 쓸어 보았다."}, {"s": "southern_remnant:galmae", "t": "이 꼴로 다녔다고? 이음새가 다 헐거워졌잖아. 남의 낫은 그렇게 잘 덧대 주면서 제 건 들여다보지도 않네."}, {"s": null, "t": "나는 바빠서 미처 못 봤다고 했다. 갈매가 혀를 찼다."}, {"s": "southern_remnant:galmae", "t": "바쁠수록 제 무기부터 봐야지. 다치고 나서 보면 늦는다고."}, {"s": null, "t": "나는 갈매의 칼은 괜찮으냐고 물었다. 갈매가 제 칼자루를 손바닥으로 툭 쳤다. 칼집 안에서 칼날이 달그락 흔들렸다."}, {"s": "southern_remnant:galmae", "t": "…내 것도 좀 그렇긴 해. 그러니까 둘 다 고치자고."}, {"s": "southern_remnant:galmae", "t": "수리 도구를 두 벌만 만들어 와. 하나는 이거 손보는 데 쓰고, 하나는 내 칼에 쓸게."}, {"s": null, "t": "갈매가 내 무기를 제 걸상 옆에 기대 세워 두었다. 나는 그것을 가져가려고 손을 뻗었다. 갈매가 부지깽이로 내 손등을 톡 쳤다."}, {"s": "southern_remnant:galmae", "t": "놔둬. 수리 도구가 올 때까지 내가 맡아 둘게. 그 꼴로 들고 다니다 부러지기라도 하면 내가 찜찜하잖아."}, {"s": null, "t": "갈매가 내 무기 곁에 제 칼을 칼집째 기대 놓았다. 두 자루가 걸상 다리에 나란히 기대어 섰다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_3', 2, '저녁거리', '장비 수리 도구을(를) 만든다, 장비 수리 도구을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "craft", "items": ["repair_kit"], "n": 2}], "give": {"repair_kit": 2}}'::jsonb, '[{"s": null, "t": "수리 도구 두 벌을 넘기자 갈매는 내 무기부터 무릎에 올려놓았다. 헐거운 이음새를 하나씩 조이고, 닳은 데에 기름을 먹였다. 기름 먹인 천에서 들기름 냄새가 고소하게 번졌다."}, {"s": null, "t": "갈매의 손이 내 무기를 다룰 때는 제 칼을 다룰 때보다 느렸다. 갈매는 한 군데를 손볼 때마다 손끝으로 두 번씩 쓸어 보았다."}, {"s": "southern_remnant:galmae", "t": "됐다, 이제 안 덜그럭거려. 너 대체 어디서 이렇게 닳게 한 거야?"}, {"s": null, "t": "나는 등도에서 흰 밤을 걸을 때부터 손을 못 봤다고 했다. 갈매가 무기를 내게 돌려주며 콧방귀를 뀌었다."}, {"s": "southern_remnant:galmae", "t": "그럼 그때부터 쭉 이 꼴이었단 거네. 그때 말을 하지. …뭐, 그땐 우리 다 바빴으니까 할 말은 없지만."}, {"s": null, "t": "나는 갈매가 남의 무기를 이렇게 손보는 것은 처음 본다고 했다. 갈매가 손을 멈추지 않고 대꾸했다."}, {"s": "southern_remnant:galmae", "t": "남의 거 아니잖아, 네 거지. 네 등 뒤에서 이게 부러지면 내가 막아야 되거든. 미리 고쳐 두는 게 덜 귀찮아."}, {"s": null, "t": "갈매가 제 칼을 칼집에서 뽑아 같은 손길로 손보기 시작했다. 화로 저편에서 소이가 낮게 노래를 흥얼거렸다. 해가 고개 쪽으로 기울자 한낮의 열기가 조금 누그러졌다. 공동 부엌 굴뚝에서 저녁 짓는 연기가 피어올랐다."}, {"s": null, "t": "화로 쪽에서 아이들이 첩 차례를 두고 다투는 소리가 들렸다. 갈매가 그쪽을 흘끗 보고 피식 웃었다."}, {"s": "southern_remnant:galmae", "t": "쟤들은 맨날 저래. 서로 먼저 부르겠다고."}, {"s": "southern_remnant:galmae", "t": "오늘 밤은 마을 사람들이 화로에 둘러앉는 날이거든. 나는 걸상에 앉아서 첩을 무릎에 얹어야 하고."}, {"s": "southern_remnant:galmae", "t": "근데 난 첫 차례만 부르고 빠질래. 어멈이 오늘은 다들 돌아가면서 첩을 들겠대. 나는 돌담에 갈 거야."}, {"s": null, "t": "나는 왜 돌담이냐고 물었다. 갈매가 칼날을 기름 먹인 천으로 닦으며 대답했다."}, {"s": "southern_remnant:galmae", "t": "거기가 내 자리였거든. 우리 외팔 영감이 국경 정찰을 나가면 거기 올라앉아서 고개만 봤어. 할배가 오나, 안 오나."}, {"s": "southern_remnant:galmae", "t": "너도 와. 빈손으론 오지 말고. 재의 해안에 가서 뭐라도 낚아 와, 돌담에서 구워 먹게. 밤새 앉아 있으려면 배가 불러야 되거든."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_3', 3, '등을 맞대고', '재의 해안에서 낚시를 한다, 잔불촌에서 쉰다', '{"at": ["ember_village"], "tasks": [{"t": "fish", "r": ["ash_coast"], "n": 2}, {"t": "rest", "r": ["ember_village"], "n": 1}]}'::jsonb, '[{"s": null, "t": "밤이 깊었다. 마을 어귀 돌담 위에서 작은 숯불 하나가 타닥거렸다. 재의 해안에서 낚은 생선이 꼬챙이에 꿰여 숯불 위에서 지글지글 익었다. 껍질이 터져 기름이 숯에 떨어질 때마다 치익 소리와 함께 고소한 연기가 올랐다."}, {"s": null, "t": "갈매가 다 익은 꼬챙이 하나를 내 쪽으로 내밀었다. 화로 쪽에서 마을 사람들이 돌아가며 이름을 부르는 소리가 아득하게 들려왔다."}, {"s": null, "t": "갈매가 생선 살을 발라 먹다가 고개를 들었다. 불씨 고개 쪽 하늘이 별로 촘촘했다. 낮 볕을 머금은 돌담이 아직 엉덩이 밑에서 따끈했다."}, {"s": "southern_remnant:galmae", "t": "너 말이야, 그때 아무것도 안 물었잖아."}, {"s": null, "t": "나는 무슨 말인지 몰라 꼬챙이를 든 채 기다렸다. 갈매가 생선 가시를 돌담 밖으로 던졌다."}, {"s": "southern_remnant:galmae", "t": "처음 만났을 때 말이야. 할배가 「마지막 아이」라고 해서 내가 장작더미를 걷어차고 뛰쳐나왔을 때. 너 여기 와서 돌담 밑에 앉아서는, 해 뜰 때까지 아무것도 안 물었잖아."}, {"s": "southern_remnant:galmae", "t": "그게 고마웠다는 말을 여태 못 했어. 그래서 오늘 하려고. 이번엔 내가 먼저 말해 보려고."}, {"s": null, "t": "갈매는 숯불을 막대기로 뒤적였다. 불티가 위로 날아올랐다. 나는 대답 대신 내 꼬챙이의 생선 꼬리를 갈매 쪽으로 내밀었다. 갈매가 그것을 받아 먹었다."}, {"s": "southern_remnant:galmae", "t": "어릴 땐 여기 앉을 때마다 등을 돌담에 딱 붙이고 앉았어. 뒤에서 누가 올까 봐. 할배가 안 오는 밤엔 무서웠거든."}, {"s": "southern_remnant:galmae", "t": "근데 돌담 위에 앉으면 등 뒤가 비더라. 고개를 보면 마을이 등 뒤고, 마을을 보면 고개가 등 뒤고."}, {"s": null, "t": "갈매가 돌담 위에서 엉덩이를 들썩여 자리를 옮겼다. 갈매가 내 등 뒤로 돌아앉더니, 제 등을 내 등에 붙였다."}, {"s": "southern_remnant:galmae", "t": "등을 대 봐. 너는 마을 봐, 나는 고개 볼게. 그럼 둘 다 앞만 보면 되잖아."}, {"s": null, "t": "갈매의 등이 내 등에 닿았다. 따뜻했다. 갈매가 숨을 쉴 때마다 그 등이 천천히 부풀었다가 가라앉았다."}, {"s": null, "t": "우리는 그렇게 앉아 있었다. 갈매가 가끔 고개 쪽에서 본 것을 말했다. 별똥이 하나 지나갔고, 부엉이가 울었고, 파수막 화로 불빛이 깜빡였다."}, {"s": null, "t": "나도 가끔 마을 쪽에서 본 것을 말했다. 화로 앞에서 아이 하나가 졸다가 어른 무릎으로 쓰러졌고, 머루댁이 새벽이를 안고 들어갔다."}, {"s": "southern_remnant:galmae", "t": "…서로 등 뒤를 일러 주는 거. 이거 나쁘지 않은데? 북령 사람 말투로 하면."}, {"s": null, "t": "갈매가 그 말을 하고 혼자 픽 웃었다. 갈매의 웃음이 등을 타고 울려 왔다."}, {"s": null, "t": "밤새 식은 돌담에 이슬이 맺혀 손바닥이 축축했다. 불씨 고개 위로 하늘이 붉게 물들었다. 해가 고갯마루에 걸리자 갈매가 내 등에서 등을 떼고 돌담에서 훌쩍 뛰어내렸다."}, {"s": "southern_remnant:galmae", "t": "해 떴다! 이번엔 내가 먼저 말했으니까, 이걸로 셈은 끝이야."}, {"s": null, "t": "갈매가 돌아서서 마을 쪽으로 걸어가다 멈췄다. 갈매가 돌아보지 않고 덧붙였다."}, {"s": "southern_remnant:galmae", "t": "다음 보름에도 와. …그건 셈 아니고."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_galmae_4', 'side', '연담·갈매', '앞에 선 사람', '늦여름 보름, 불씨 고개 국경 길에 짐승 발자국이 났다는 말에 갈매가 정찰을 나간다. 갈매는 처음으로 주인공을 앞세우고 제가 뒤에서 걷는다. 「앞에서 뒤 안 돌아봐도 돼.」', 'ember_village', 50, '{rg_galmae_3}'::text[], null, 1643, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "galmae", "stage": 4}'::jsonb where quest_id = 'rg_galmae_4';
delete from public.world_quest_steps where quest_id = 'rg_galmae_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_4', 1, '국경 길', '국경 길', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "늦여름 보름이었다. 잔불촌 어귀에 들어서자 갈매가 칼집을 차고 서 있었다. 늦더위가 한풀 꺾여 아침 바람에 마른 풀 냄새가 섞여 있었다. 갈매 곁에서 남명 파수꾼 하나가 팔에 감은 천을 동여매고 있었다."}, {"s": "southern_remnant:galmae", "t": "마침 잘 왔다. 요즘 마을에서 너를 뭐라고 부르는지 알아? 「쇠를 대 주는 정청 사람」이래. 집집마다 네가 만든 수리 도구가 하나씩 걸려 있다나."}, {"s": null, "t": "파수꾼의 팔에 감긴 천에 피가 배어 있었고, 찧어 바른 쑥에서 쌉싸름한 약내가 났다. 내 눈길을 보고 파수꾼이 붕대를 감은 팔을 들어 보이며 얼굴을 찡그렸다."}, {"s": "q:md_south_watch", "t": "어젯밤에 국경 길에서 좀 긁혔어. 고개 너머에서 그 불쏘시개 같은 놈들, 불티 도깨비 떼가 넘어와서 길섶을 다 태워 놨더라고. 파수막 창도 한 자루 부러져 버렸고."}, {"s": null, "t": "갈매가 파수꾼의 붕대를 한 번 더 조여 주고 어깨를 툭 쳤다."}, {"s": "southern_remnant:galmae", "t": "들어가서 누워 있어. 오늘 정찰은 내가 나갈게."}, {"s": "q:md_south_watch", "t": "대장 혼자 가게요? 고갯마루 쪽 파수막은 화로도 꺼져 있을 텐데요."}, {"s": "southern_remnant:galmae", "t": "누가 혼자 간대? 저기 쇠를 대 주는 정청 사람을 데려갈 거야."}, {"s": null, "t": "파수꾼이 고개를 꾸벅 숙이고 마을 안으로 들어갔다. 갈매가 칼자루를 쥐었다 놓았다 하며 나를 보았다."}, {"s": "southern_remnant:galmae", "t": "같이 가자. 국경 길은 하루에 두 번은 봐야 되거든. 혼자 두 번 도느니 둘이 한 번 도는 게 낫지."}, {"s": null, "t": "나는 그러자고 하고 갈매 뒤에 섰다. 갈매가 고개를 저었다."}, {"s": "southern_remnant:galmae", "t": "아니, 아니. 오늘은 네가 앞에 서."}, {"s": null, "t": "나는 걸음을 멈추고 갈매를 돌아보았다. 갈매가 칼집을 고쳐 차며 시선을 피했다."}, {"s": "southern_remnant:galmae", "t": "길은 내가 일러 줄게. 너는 앞에서 걷기만 하면 돼. …그냥, 한번 해 보고 싶어서 그래. 뒤에서 걷는 거."}, {"s": null, "t": "갈매가 귀 끝을 긁었다. 나는 더 묻지 않고 앞으로 나섰다. 갈매가 내 등 뒤 세 걸음 자리에 가서 섰다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_4', 2, '뒤는 내가 봐', '불씨 고개에 간다, 불씨 고개의 요괴를 물리친다', '{"at": ["ember_pass"], "tasks": [{"t": "travel", "r": ["ember_pass"], "n": 1}, {"t": "win", "r": ["ember_pass"], "n": 6}]}'::jsonb, '[{"s": null, "t": "불씨 고개 국경 길은 길섶이 시커멓게 그을려 있었다. 바위틈마다 불티가 남아 반짝였다. 그을린 풀대가 발에 밟힐 때마다 바삭 부서졌고, 탄내가 목구멍을 긁었다."}, {"s": null, "t": "나는 앞에서 걸었다. 갈매는 세 걸음 뒤에서 따라왔다. 갈매는 처음엔 아무 말도 하지 않다가, 갈림길에 이를 때마다 짧게 일렀다."}, {"s": "southern_remnant:galmae", "t": "왼쪽으로. 바위 밑으로 낮게 가. 거기 미끄러우니까."}, {"s": null, "t": "고갯마루 아래 바위 뒤에서 불티 도깨비 떼가 와르르 쏟아져 나왔다. 불티가 확 번지며 길섶 마른풀이 화르르 타올랐다."}, {"s": null, "t": "나는 앞쪽 놈들을 막아섰다. 등 뒤에서도 바스락 소리가 났다. 나는 저도 모르게 고개를 돌렸다."}, {"s": "southern_remnant:galmae", "t": "돌아보지 마! 앞을 봐, 앞!"}, {"s": null, "t": "갈매의 칼이 내 등 뒤에서 휙 바람을 갈랐다. 뒤쪽 놈이 끽 소리를 내며 굴러떨어졌다. 나는 다시 앞을 보고 내 몫의 놈들을 쓰러뜨렸다."}, {"s": null, "t": "마지막 놈이 바위 너머로 달아나자 길섶의 불도 차츰 사그라졌다. 매캐한 연기가 고갯길에 깔렸다."}, {"s": null, "t": "갈매가 칼을 털어 칼집에 넣고 내 앞으로 걸어왔다. 갈매의 이마에 땀이 맺혀 있었고, 뺨에는 그을음이 한 줄 묻어 있었다."}, {"s": "southern_remnant:galmae", "t": "너 아까 왜 돌아봤어?"}, {"s": null, "t": "나는 뒤에서 소리가 나서 돌아봤다고 했다. 갈매가 손등으로 이마를 훔쳤다."}, {"s": "southern_remnant:galmae", "t": "앞에선 뒤를 안 돌아봐도 돼. 뒤는 내가 본다니까. 그러라고 내가 뒤에 선 거잖아."}, {"s": null, "t": "갈매의 목소리가 조금 떨렸다. 화가 난 것이 아니라 숨이 찬 것이었다. 갈매가 길섶에 떨어진 부러진 창 자루를 발끝으로 굴렸다."}, {"s": "southern_remnant:galmae", "t": "이게 어젯밤 부러졌다는 파수막 창이구나. 그럼 파수막에 창이 한 자루밖에 안 남았겠네."}, {"s": "southern_remnant:galmae", "t": "창을 두 자루만 만들어 줘. 파수막에 하나, 고갯마루 쪽 파수막에 하나. 오늘 같은 일이 또 생기면 파수꾼이 맨손으로 서 있게 생겼잖아."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_4', 3, '처음 뒤에서 걸어 본 길', '순찰 장창을(를) 만든다, 순찰 장창을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "craft", "items": ["guard_spear"], "n": 2}], "give": {"guard_spear": 2}}'::jsonb, '[{"s": null, "t": "창 두 자루를 파수막에 세우고 잔불촌으로 돌아오니 해가 졌다. 갈매가 걸상에 앉아 첩을 무릎에 얹고 첫 차례 이름들을 불렀다. 금빛 입김이 화로 속으로 날아들었다. 늦여름 밤바람에 풀벌레 소리가 실려 왔다."}, {"s": null, "t": "첫 차례가 끝나자 갈매가 첩을 머루댁에게 넘기고 화로에서 조금 떨어진 장작더미에 걸터앉았다. 갈매가 손짓으로 나를 불렀다."}, {"s": "southern_remnant:galmae", "t": "오늘 길은 어땠어?"}, {"s": null, "t": "나는 앞에서 걸으니 길이 넓어 보였다고 했다. 갈매가 무릎을 끌어안았다."}, {"s": "southern_remnant:galmae", "t": "나는 뒤에서 걸으니까 네 등만 보이더라. 그게 좀 이상했어."}, {"s": "southern_remnant:galmae", "t": "정찰대에선 막내가 뒤에서 걷거든. 앞은 제일 센 놈이 서고. 나는 열네 살 때부터 앞에만 섰어. 막내 소리를 듣기 싫어서. 「마지막 아이」 소리는 더 듣기 싫었고."}, {"s": "southern_remnant:galmae", "t": "할배랑 걸을 때만 뒤에 섰지. 한쪽 소매가 비어서 바람에 펄럭였거든. 난 그 펄럭이는 소매 자락만 보고 걸었어."}, {"s": null, "t": "갈매가 무릎을 끌어안은 채 오래 화로 쪽을 보았다. 화로의 흰 불씨가 숯 밑에서 고요히 빛났다. 엉덩이 밑 장작에서 송진 냄새가 진하게 올라왔다."}, {"s": "southern_remnant:galmae", "t": "늙은이 빈 소매 말고 다른 등을 보고 걸은 건 네가 처음이야. 오늘 해 보니까 알겠더라. 뒤에 선다고 막내가 되는 게 아니더라고. 지켜보는 쪽이 되는 거더라."}, {"s": null, "t": "나는 그럼 다음엔 내가 뒤에 서겠다고 했다. 갈매가 고개를 홱 돌려 나를 보았다."}, {"s": "southern_remnant:galmae", "t": "누가 그래도 된대? 다음은 내가 정할 거야."}, {"s": null, "t": "갈매가 입술을 비죽 내밀다가, 장작더미에서 일어나 내 정수리를 손바닥으로 꾹 눌렀다."}, {"s": "southern_remnant:galmae", "t": "…근데 아까 돌아보지 말라고 소리를 지른 거 말이야. 화나서 그런 거 아니야. 네가 돌아보다 앞에서 얻어맞을까 봐 그랬지."}, {"s": null, "t": "나는 알고 있다고 했다. 갈매가 손을 거두며 헛기침을 했다."}, {"s": "southern_remnant:galmae", "t": "알면 됐고. 다음에 오면 할 말이 하나 있어. 오늘은 말고."}, {"s": null, "t": "갈매는 그 말만 남기고 화로 앞 걸상으로 돌아갔다. 머루댁이 내민 첩을 다시 받아 무릎에 얹고, 다음 이름을 불렀다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_galmae_5', 'side', '연담·갈매', '맡긴 등', '가을 보름, 갈매가 제 방에 칼걸이를 놓겠다며 강철 주괴를 맡긴다. 고리가 둘 달린 칼걸이에 제 칼을 걸고, 맨손으로 앞장서 밤 고갯길을 오른다. 「등은 네가 봐. 맡긴다.」', 'ember_village', 50, '{rg_galmae_4}'::text[], null, 1644, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "galmae", "stage": 5}'::jsonb where quest_id = 'rg_galmae_5';
delete from public.world_quest_steps where quest_id = 'rg_galmae_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_5', 1, '벽에 걸린 칼', '벽에 걸린 칼', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "가을 보름이었다. 잔불촌 밭에서 메밀이 하얗게 피어 있었다. 메밀꽃의 들척지근한 냄새가 바람에 실려 왔고, 아침 공기가 제법 차가웠다. 화로 앞 걸상은 비어 있었다."}, {"s": null, "t": "갈매는 대장간 안에 서 있었다. 쇠불은 마침 자리에 없었다. 갈매는 벽에 걸린 두 동강 난 칼을 올려다보고 있었다. 낮게 지펴 둔 화덕이 웅웅거렸다. 칼자루의 닳은 문장이 화덕 불빛에 희미하게 드러났다."}, {"s": null, "t": "나는 문간에서 갈매를 불렀다. 갈매가 돌아보지 않고 손짓만 했다. 들어와서 곁에 서라는 뜻이었다."}, {"s": "southern_remnant:galmae", "t": "그사이 네가 갖다 준 거, 내가 다 세어 봤거든? 주괴가 열넷, 식칼이 다섯, 창이 넷, 수리 도구가 아홉. 낫은 이제 세지도 못하겠어. 마을 낫의 절반이 네 쇠야."}, {"s": "southern_remnant:galmae", "t": "저거 할배 칼이야. 남명이 망하던 밤에 부러졌대. 그 뒤로 할배는 저 칼을 다시 안 찼어."}, {"s": null, "t": "갈매가 벽의 칼에서 눈을 떼지 않은 채 제 허리춤의 칼자루를 손바닥으로 덮었다."}, {"s": "southern_remnant:galmae", "t": "난 이걸 열네 살부터 한 번도 안 풀었어. 잘 때도 머리맡에 뒀고, 마을 안에서도 차고 다녔고."}, {"s": "southern_remnant:galmae", "t": "할배는 마을 안에선 칼을 안 찼거든. 부지깽이 하나만 달랑 들고 다녔지. 근데 난 그게 안 되더라. 칼을 풀면 등 뒤가 휑한 것 같아서."}, {"s": null, "t": "나는 그럼 이제 칼을 풀 거냐고 물었다. 갈매가 바로 대답하지 않고 화덕 불만 보았다."}, {"s": "southern_remnant:galmae", "t": "풀어 보려고. 근데 그냥 풀면 분명 또 찰 거야. 걸어 둘 자리가 있어야 돼."}, {"s": null, "t": "갈매가 칼자루에서 손을 떼고 나를 보았다. 무언가 정한 얼굴이었다."}, {"s": "southern_remnant:galmae", "t": "칼걸이를 하나 만들 거야. 내 방에. 보름마다 와서 묵는 화로 뒤 작은 방 있잖아, 거기 벽에다."}, {"s": "southern_remnant:galmae", "t": "고리는 둘, 강철로. 월철은 무른 데가 있어서 칼 무게에 고리가 처지거든. 강철 주괴 두 덩이면 내가 구부려서 짤 수 있어."}, {"s": null, "t": "나는 왜 고리가 둘이냐고 물었다. 갈매가 대답 대신 화덕 쪽으로 걸어가 풀무 손잡이를 잡았다."}, {"s": "southern_remnant:galmae", "t": "그건 다 만들고 말해 줄게. 얼른 부어 와. 불은 내가 지펴 놓을 테니까."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_5', 2, '고리 둘', '강철 주괴을(를) 만든다, 강철 주괴을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "craft", "items": ["steel_ingot"], "n": 2}], "give": {"steel_ingot": 2}}'::jsonb, '[{"s": null, "t": "강철 주괴 두 덩이를 넘기자 갈매는 해 질 녘까지 대장간에서 나오지 않았다. 땅, 땅, 망치 소리가 메밀밭 너머까지 울렸다."}, {"s": null, "t": "해가 질 무렵 갈매가 나를 화로 뒤 작은 방으로 데려갔다. 방에는 이부자리 하나와 등잔 하나뿐이었다. 볕에 말린 이불 냄새와 등잔 기름 냄새가 은근하게 섞여 났다. 벽에 새 칼걸이가 박혀 있었다. 검게 담금질한 쇠에 고리 둘이 나란히 달려 있었다."}, {"s": null, "t": "갈매가 허리띠를 풀었다. 칼집째 칼을 들어 왼쪽 고리에 걸었다. 쇠고리가 칼 무게를 받아 쩡 낮게 울렸다."}, {"s": null, "t": "갈매는 칼을 건 손을 한참 고리에서 떼지 못했다. 손가락이 칼집을 두어 번 쓸었다. 갈매가 손을 거두고 깊게 숨을 내쉬었다."}, {"s": "southern_remnant:galmae", "t": "…풀었다. 진짜로."}, {"s": null, "t": "나는 비어 있는 오른쪽 고리를 보았다. 갈매가 그 고리를 손가락으로 툭 건드렸다. 고리가 달랑 흔들렸다."}, {"s": "southern_remnant:galmae", "t": "네 거야. 너 여기 오면 맨날 {직업:호위=칼을/월궁=활을/퇴마=방울을/의무=부채를/봉인=금강령을/암영=단도를/조련=활을/*=무기를} 차고 다니잖아. 여기선 좀 걸어 두고 다녀. 잔불촌에서 네 등 뒤를 노릴 놈은 없으니까."}, {"s": "southern_remnant:galmae", "t": "쇠불이가 묻더라. 고리를 하나만 달면 될 걸 왜 둘이냐고. 그래서 말해 줬지. 하나는 이 방에서 자는 사람 거, 하나는 이 방에 오는 사람 거라고."}, {"s": null, "t": "나는 내 무기를 풀어 오른쪽 고리에 걸었다. 두 무기가 나란히 매달려 달랑거렸다. 갈매가 그것을 보더니 팔짱을 꼈다."}, {"s": null, "t": "갈매가 손가락으로 내 무기 손잡이를 한 번 톡 건드렸다. 갈매는 제가 무엇을 하는지 알아챈 듯 얼른 손을 거두었다."}, {"s": "southern_remnant:galmae", "t": "잘 걸었네. 자, 이제 나가 보자."}, {"s": null, "t": "갈매가 방문을 열었다. 가을밤 바람이 문틈으로 들어와 등잔불을 흔들었다. 불씨 고개 위로 보름달이 떠오르고 있었다."}, {"s": "southern_remnant:galmae", "t": "고개에. 할배한테 가. 오늘 밤은 정찰이 아니야. 칼 없이 걷는 길이야."}, {"s": null, "t": "나는 갈매의 빈 허리춤을 내려다보았다. 갈매가 내 눈길을 알아채고 문지방에 선 채 돌아보았다."}, {"s": "southern_remnant:galmae", "t": "괜찮으려고 가는 거야."}, {"s": "southern_remnant:galmae", "t": "국경 길 말고 고갯마루로 가는 옛 길로 갈 거야. 오늘은 길을 안 일러 줄 테니까 네가 발소리를 듣고 따라와. 가다가 바위 밑이며 길섶이며 같이 한 번씩 살피자. 맨손으로 가는 길이니까 미리 봐 둬야 돼."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_galmae_5', 3, '갈매가 맡긴 등', '불씨 고개에 간다, 불씨 고개을(를) 살핀다', '{"at": ["ember_pass"], "tasks": [{"t": "travel", "r": ["ember_pass"], "n": 1}, {"t": "search", "r": ["ember_pass"], "n": 2}]}'::jsonb, '[{"s": null, "t": "보름달 아래 불씨 고개 옛 길은 하얗게 빛났다. 밤이슬에 젖은 억새가 바지 자락에 스쳐 서걱거렸고, 숨을 들이쉴 때마다 콧속이 알싸했다. 갈매가 앞장서 걸었다. 허리춤에 칼이 없었다. 갈매의 두 손이 빈 채로 몸 옆에서 흔들렸다."}, {"s": null, "t": "나는 그 뒤를 세 걸음 떨어져 따라갔다. 갈매의 등이 달빛 속에서 곧았다. 갈매는 한 번도 뒤를 돌아보지 않았다."}, {"s": null, "t": "바위 뒤에서 부엉이가 푸드덕 날아올랐다. 갈매의 어깨가 움찔했다. 갈매의 손이 허리춤 빈자리로 갔다가, 천천히 몸 옆으로 돌아왔다. 갈매는 걸음을 멈추지 않았다."}, {"s": "southern_remnant:galmae", "t": "…괜찮아, 부엉이네. 너 거기 있지?"}, {"s": null, "t": "나는 있다고 했다. 갈매가 앞을 본 채 「응」 하고 작게 대답했다."}, {"s": null, "t": "고갯마루 늙은 소나무 아래 봉분 둘이 달빛을 받고 있었다. 밤바람에 솔잎 냄새가 짙게 풍겼다. 갈매가 봉분 앞에 멈춰 섰다. 갈매는 앉지 않고 선 채로 말했다."}, {"s": "southern_remnant:galmae", "t": "할배. 나 오늘 칼을 안 찼다? 방에 걸어 놓고 왔어. 할배처럼."}, {"s": "southern_remnant:galmae", "t": "할배가 그랬잖아. 등은 서로 봐 주는 거라고. 한쪽만 봐 주는 게 아니라고. 근데 할배, 서로 봐 주려면 한 번은 맡겨 봐야 되더라."}, {"s": null, "t": "갈매가 봉분 앞에서 돌아섰다. 달빛이 갈매의 얼굴을 비추었다. 갈매가 나를 똑바로 보았다."}, {"s": "southern_remnant:galmae", "t": "{이름}. 내려가는 길도 내가 앞에 설게. 칼 없이."}, {"s": "southern_remnant:galmae", "t": "등은 네가 봐. 맡긴다."}, {"s": null, "t": "갈매가 숨을 한 번 크게 들이켰다. 갈매가 다시 돌아서서 고갯길을 내려가기 시작했다. 나는 그 뒤를 따랐다."}, {"s": null, "t": "몇 걸음 내려가다가 갈매가 앞을 본 채 덧붙였다. 목소리가 평소보다 작았다."}, {"s": "southern_remnant:galmae", "t": "갈매가 맡긴 등이다? 대충 보지 말고, 끝까지 봐."}, {"s": null, "t": "나는 끝까지 보겠다고 했다. 갈매는 대답하지 않았다. 갈매의 귀 끝이 달빛 아래에서도 빨갰다."}, {"s": null, "t": "고개 아래로 잔불촌 화로 불빛이 보였고, 바람에 실려 온 숯내가 코끝에 닿았다. 갈매의 빈 손이 걸음에 맞춰 흔들렸다. 나는 그 등에서 눈을 떼지 않고 마을까지 내려갔다."}, {"s": null, "t": "화로 뒤 작은 방 벽에서 칼 두 자루가 나란히 우리를 기다리고 있었다."}]'::jsonb, '{"gil": 205, "title": "rg_galmae", "items": {"hf_rg_galmae_rack": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_haram_1', 'side', '연담·서하람', '손으로 읽는 눈금', '갈매가 보름마다 잔불촌에 가 있는 동안, 서하람은 관성대 지붕에서 제가 어느 쪽을 보고 있는지조차 모른다. 서하람은 손끝으로 눈금을 읽는 나침반을 주인공에게 주문한다. 서하람은 주인공을 숨소리로 알아본다.', 'star_observatory', 50, '{mde_haram_2}'::text[], null, 1645, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_haram_1';
delete from public.world_quest_steps where quest_id = 'rg_haram_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_1', 1, '숨 열여덟', '숨 열여덟', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "봄밤이었다. 산꼭대기라 바람이 아직 찼고, 관성대 돌계단에는 밤이슬이 내려 발밑이 미끈거렸다. 무극 관성대 계단 아래에서 수직 운해가 창을 벽에 기대 세우고 꾸벅 인사했다."}, {"s": "q:bl_unhae", "t": "관측관님은 지붕에 계십니다. 갈매 님이 잔불촌에 가셔서 오늘은 혼자 오르셨지요. 제가 부축해 드리겠다니까 마다하시더군요."}, {"s": null, "t": "나는 계단을 올랐다. 지붕 위 혼천의 곁에 서하람이 앉아 있었다. 혼천의의 놋쇠 고리가 바람을 받아 끼익 낮게 울었다. 무릎 위에 손바닥만 한 나침반 하나가 놓여 있었다."}, {"s": null, "t": "서하람은 나침반 판을 손끝으로 더듬고 있었다. 하얗게 바랜 두 눈은 엉뚱하게 혼천의 쪽을 향해 있었다."}, {"s": null, "t": "내가 마지막 계단에 올라서자 서하람의 손끝이 멈췄다. 서하람이 고개를 갸웃했다."}, {"s": "q:r71_seoharam", "t": "계단 하나에 숨 한 번 반. 다 올라와서는 열여덟 번… 아, {이름} 님이죠?"}, {"s": null, "t": "나는 어떻게 알았느냐고 물었다. 서하람이 배시시 웃었다."}, {"s": "q:r71_seoharam", "t": "숨소리로 알죠. 갈매 씨는 계단에선 숨을 참았다가 다 올라와서 한꺼번에 몰아쉬거든요. 할머니는 계단마다 「아이고」 하시고요, 운해 씨는 창 끝이 벽을 긁어요. {이름} 님은요, 숨이 고르고 조금 느려요."}, {"s": null, "t": "나는 서하람 곁에 앉아 무릎 위의 나침반을 보았다. 관성대에서 쓰는 나침반이었다. 판에 금빛 칠로 방위가 그려져 있었다."}, {"s": "q:r71_seoharam", "t": "이거요, 칠로 그린 눈금이라서 손으로는 하나도 안 읽혀요. 어딜 만져도 다 매끈해요."}, {"s": "q:r71_seoharam", "t": "갈매 씨가 있을 땐 「북쪽은 네 왼손 쪽」 하고 일러 주거든요. 근데 보름마다 잔불촌에 가 버리면, 저는 지붕에 앉아서 제가 어딜 보고 있는지도 몰라요."}, {"s": null, "t": "서하람이 나침반을 두 손으로 감쌌다. 손끝이 판 가장자리를 빙글빙글 돌았다."}, {"s": "q:r71_seoharam", "t": "손끝으로 읽는 눈금이 있으면 좋겠어요. 홈을 파서요. 북쪽은 제일 깊게, 동쪽 서쪽은 조금 얕게, 그렇게요."}, {"s": null, "t": "나는 관성대 법구장에게 부탁해 보라고 했다. 서하람이 손을 내저었다."}, {"s": "q:r71_seoharam", "t": "법구장 어르신들은 죄다 눈 밝은 사람만 생각하고 만드시거든요. 손으로 읽는 건 아무도 안 만들어 봤대요. 그리고 이건요… 갈매 씨한테는 비밀로 하고 싶어요."}, {"s": "q:r71_seoharam", "t": "다음 보름에 돌아오면, 제가 먼저 「북쪽은 저기예요」 하고 가리켜서 놀래 주고 싶거든요."}, {"s": "q:r71_seoharam", "t": "눈금 바늘은 성진사로 갈아야 별 쪽을 잘 가리킨대요. 구름 위 회랑에 성진사가 반짝반짝 깔려 있다고 들었어요. 거기서 좀 주워다 주실래요? 값은 천명원에서 드릴게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_1', 2, '별 가루 소리', '구름 위 회랑에서 성진사을(를) 모은다', '{"at": ["star_observatory"], "tasks": [{"t": "gather", "items": ["star_sand"], "r": ["cloud_corridor"], "n": 4}]}'::jsonb, '[{"s": null, "t": "성진사 주머니를 내밀자 서하람이 두 손을 오므려 받았다. 서하람은 주머니를 귀에 대고 살살 흔들었다. 사르륵사르륵 고운 모래 소리가 났다."}, {"s": "q:r71_seoharam", "t": "와, 별 가루 소리다. 처음 들어 봐요. 이렇게 고운 줄 몰랐어요."}, {"s": null, "t": "서하람이 주머니 끈을 풀어 성진사를 손바닥에 조금 덜었다. 차갑고 까끌까끌한 알갱이를 손끝으로 굴리다가 고개를 들었다."}, {"s": "q:r71_seoharam", "t": "{이름} 님 소매에서도 이 가루 냄새가 나요. 회랑 바람 냄새도요. 바람이 셌죠?"}, {"s": null, "t": "나는 바람에 모자가 날아갈 뻔했다고 했다. 서하람이 쿡쿡 웃으며 성진사를 주머니에 도로 털어 넣었다."}, {"s": null, "t": "서하람이 손바닥의 성진사 가루를 털고 무릎을 세웠다."}, {"s": "q:r71_seoharam", "t": "자, 이제 홈 이야기를 할게요. 잘 들어 주셔야 돼요? 제가 손으로 읽을 거니까요."}, {"s": "q:r71_seoharam", "t": "북쪽 홈은 손톱이 반쯤 들어갈 만큼이요. 남쪽은 그 반만큼이요. 동쪽 서쪽은 홈 말고 점으로 찍어 주세요. 동쪽은 점 하나, 서쪽은 점 둘. 그래야 안 헷갈려요."}, {"s": null, "t": "나는 왜 동쪽이 점 하나냐고 물었다. 서하람이 손가락 하나를 들어 보였다."}, {"s": "q:r71_seoharam", "t": "동쪽에선 해가 하나 뜨니까요. 서쪽은 해도 지고 달도 뜨니까 둘이고요. …방금 제가 정했어요."}, {"s": null, "t": "서하람은 제 말이 마음에 드는지 혼자 흐뭇하게 웃었다."}, {"s": null, "t": "나는 웃음을 참고 그대로 하겠다고 했다. 서하람이 손바닥으로 지붕 기와를 쓸었다."}, {"s": "q:r71_seoharam", "t": "그리고 바늘 끝에도 작은 홈을 하나 파 주세요. 바늘이 어디를 가리키는지 손으로 만져서 알게요."}, {"s": "q:r71_seoharam", "t": "하나면 돼요. 두 개를 만들면 할머니가 하나 달라고 하실 거예요. 할머니 눈도 요즘 침침하시니까요. …그건 다음에 따로 부탁할게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_1', 3, '북쪽은 저기', '별자리 나침반을(를) 만든다, 별자리 나침반을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["lt_compass_4"], "n": 1}], "give": {"lt_compass_4": 1}}'::jsonb, '[{"s": null, "t": "나침반을 넘기자 서하람이 그것을 두 손으로 받쳐 들었다. 밤하늘이 맑아 별이 시리도록 또렷했다. 서하람의 손끝이 판 위를 천천히 더듬었다."}, {"s": "q:r71_seoharam", "t": "깊은 홈… 얕은 홈… 점 하나, 점 둘."}, {"s": null, "t": "서하람이 숨을 고르고 바늘 끝의 홈을 찾아 손가락을 얹었다. 서하람이 그 자리에서 몸을 천천히 돌렸다. 바늘이 판 위에서 파르르 떨다가 멈췄다."}, {"s": "q:r71_seoharam", "t": "…북쪽은, 저기예요."}, {"s": null, "t": "서하람의 손가락이 하늘을 가리켰다. 손가락 끝에 국자별 손잡이가 걸려 있었다. 나는 맞다고 했다."}, {"s": null, "t": "서하람의 얼굴에 웃음이 번졌다. 서하람이 나침반을 품에 꼭 끌어안고 두 발을 동동 굴렀다."}, {"s": "q:r71_seoharam", "t": "맞아요? 진짜로요? 저 혼자 찾은 거예요! 갈매 씨가 안 일러 줬는데!"}, {"s": "q:r71_seoharam", "t": "다음 보름엔 계단 꼭대기에서 기다렸다가 제가 먼저 말할 거예요. 「북쪽은 저기예요.」 하고요. 갈매 씨가 뭐라고 할까요? 벌써 궁금해요."}, {"s": null, "t": "나는 갈매가 「누가 일러 줬어」 하고 따질 것 같다고 했다. 서하람이 웃음을 터뜨렸다."}, {"s": "q:r71_seoharam", "t": "맞아요, 꼭 그럴 거예요. 그럼 제가 「{이름} 님이 바늘에 홈을 파 줬어요」 하면 되죠. 그건 비밀이 아니어도 돼요."}, {"s": null, "t": "서하람이 나침반을 무릎에 내려놓고 한참 손끝으로 홈을 쓸었다. 손끝의 움직임이 조금 느려졌다."}, {"s": "q:r71_seoharam", "t": "{이름} 님. 관성대 법구가 다 눈으로 읽게 생겼다고 했잖아요. 혼천의 고리도, 물시계 눈금도, 별 기록 판도요."}, {"s": "q:r71_seoharam", "t": "그걸 하나씩 손으로 읽게 바꾸고 싶어요. 한꺼번에는 못 하니까 조금씩요. …앞으로도 부탁드려도 돼요?"}, {"s": null, "t": "나는 그러겠다고 했다. 서하람이 안심한 듯 나침반 바늘 끝 홈에 손가락을 올렸다."}, {"s": "q:r71_seoharam", "t": "그럼 오실 때마다 숨을 세어 둘게요. 계단에서 몇 번 쉬셨는지요. 그게 제 첫 관측이에요. 예언은 안 하고요, 관측만 해요."}, {"s": null, "t": "내려갈 때가 되자 서하람이 계단 첫 칸까지 나를 배웅했다. 계단 아래에서 운해의 창 끝이 벽을 긁는 소리가 올라왔다. 나는 갈매가 하던 대로 다섯, 쉬고, 다시 다섯 하고 계단 수를 세어 주었다."}, {"s": "q:r71_seoharam", "t": "{이름} 님은 갈매 씨보다 느리게 세시네요. 그래도 제 숨이랑은 딱 맞아요. 다음에도 그 박자로 세 주세요."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_haram_2', 'side', '연담·서하람', '담요 하나', '초여름 밤, 서하람이 혼자서도 차를 따를 수 있는 다기를 주문하고, 별바라기 언덕 이슬로 찻물을 끓인다. 관성대 지붕에 담요는 하나뿐이다. 「오늘은 별 대신 {이름} 님 숨을 셀게요.」', 'star_observatory', 50, '{rg_haram_1}'::text[], null, 1646, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "haram", "stage": 2}'::jsonb where quest_id = 'rg_haram_2';
delete from public.world_quest_steps where quest_id = 'rg_haram_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_2', 1, '깨진 찻잔', '깨진 찻잔', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "초여름이었다. 해 진 산자락에서 밤꽃 냄새가 실려 왔고, 돌계단은 아직 낮의 온기를 품고 있었다. 관성대 계단을 다 오르자 서하람이 계단 꼭대기에 앉아 있다가 손가락을 하나씩 접었다."}, {"s": "q:r71_seoharam", "t": "열일곱! 지난번보다 한 번 적어요. 조금 서둘러 오셨나 봐요."}, {"s": "q:r71_seoharam", "t": "할머니 나침반 말이에요, 할머니가 아침마다 북쪽 눈금부터 만져 보세요. 서고 등잔은 손잡이에 홈이 있어서, 운해 씨가 밤에 더듬어 잡아도 안 엎는대요."}, {"s": null, "t": "서하람이 품에서 무명에 싼 것을 꺼냈다. 무명을 펼치자 이가 빠진 찻잔 두 개가 나왔다. 잔 바닥에 마른 찻물 자국이 갈색으로 눌어붙어 있었다."}, {"s": "q:r71_seoharam", "t": "오늘은 이거 때문에요. 어젯밤에 혼자 차를 따르다가, 넘치는 줄도 몰랐어요. 뜨거운 물이 손등에 쏟아져서 잔을 놓쳐 버렸어요."}, {"s": null, "t": "서하람의 왼손 등이 빨갛게 부어 있었다. 나는 그 손을 잡아 들여다보았다. 서하람이 얼른 손을 빼서 소매 속에 감췄다."}, {"s": "q:r71_seoharam", "t": "괜찮아요, 괜찮아요. 할머니가 고약을 발라 주셨어요. 할머니한테는 잔이 미끄러졌다고만 했고요."}, {"s": null, "t": "나는 갈매는 알고 있느냐고 물었다. 서하람이 고개를 저었다."}, {"s": "q:r71_seoharam", "t": "우리 정찰대장님이 아시면 저 이제 혼자서는 차를 못 마셔요. 주전자를 어디다 숨겨 버릴걸요."}, {"s": "q:r71_seoharam", "t": "저 혼자서 차를 따르고 싶어요. 아무도 없는 밤에도요. 따를 때마다 누굴 부르면, 그 사람이 제 손 노릇을 해야 하잖아요."}, {"s": null, "t": "서하람이 손가락으로 허공에 찻주전자 모양을 그렸다."}, {"s": "q:r71_seoharam", "t": "주전자 주둥이에 작은 턱을 하나 붙여 주세요. 물이 나올 때 「졸졸」이 아니라 「똑똑」 소리가 나게요. 잔 안쪽엔 가는 줄을 하나 둘러 주세요. 물이 줄에 닿으면 손끝에 느껴지게요."}, {"s": "q:r71_seoharam", "t": "그리고 찻물은요, 별바라기 언덕 풀잎에 맺힌 이슬로 끓이면 단맛이 난대요. 할머니가 젊을 때 그랬대요. 언덕에서 풀이랑 이슬을 좀 가져다주실래요?"}, {"s": null, "t": "나는 이슬을 받을 단지를 챙겨 가겠다고 했다. 서하람이 부은 손등을 문지르며 웃었다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_2', 2, '똑똑', '별바라기 언덕에서 채집한다', '{"at": ["star_observatory"], "tasks": [{"t": "gather", "r": ["star_hill"], "n": 3}]}'::jsonb, '[{"s": null, "t": "이슬 단지와 풀잎 꾸러미를 내려놓자 서하람이 단지 뚜껑을 열고 코를 가까이 댔다. 단지 겉에 송골송골 맺힌 물방울에 서하람의 손바닥이 젖었다. 서하람의 콧등이 찡긋했다."}, {"s": "q:r71_seoharam", "t": "풀 냄새가 나요. 언덕에 풀벌레가 많았죠? 예전엔 그 언덕에만 가면 꼭 잠들어 버렸거든요. 풀벌레 소리를 한 번도 끝까지 못 들어 봤어요."}, {"s": null, "t": "나는 풀벌레가 내 발목까지 뛰어올랐다고 했다. 서하람이 키득거리며 단지를 품에 안았다."}, {"s": "q:r71_seoharam", "t": "언덕에 반딧불 넋도 있다던데, 보셨어요?"}, {"s": null, "t": "나는 반딧불 넋 여럿이 이슬 단지 둘레를 맴돌았다고 했다. 서하람이 아쉬운 듯 입술을 비죽였다."}, {"s": "q:r71_seoharam", "t": "저는 이제 그런 건 못 보니까요, 오실 때마다 하나씩 말해 주세요."}, {"s": "q:r71_seoharam", "t": "이제 다기만 있으면 돼요. 주둥이 턱이랑 잔 안쪽 줄이요. 잊지 않으셨죠?"}, {"s": null, "t": "나는 잊지 않았다고 했다. 서하람이 계단 아래쪽으로 고개를 돌렸다. 아래층에서 찻잔 부딪는 소리가 달그락 올라왔다."}, {"s": "q:r71_seoharam", "t": "할머니가 또 차를 드시나 봐요. 할머니도 요즘 잔을 자주 엎으세요. 눈이 침침하셔서요."}, {"s": null, "t": "나는 할머니 것도 하나 만들어 오겠다고 했다. 서하람이 잠깐 생각에 잠겼다가 빙그레 웃었다."}, {"s": "q:r71_seoharam", "t": "다기는 하나만 만들어 주세요. 할머니한테 드리고 싶지만, 할머니는 저한테 차를 따라 주시는 게 낙이시거든요. 제가 혼자 따르면 서운해하실 거예요."}, {"s": null, "t": "서하람이 손가락으로 하늘을 가리켰다."}, {"s": "q:r71_seoharam", "t": "제 다기는 지붕에서 쓸 거예요, 오늘 밤에. 할머니 몰래 지붕에서 마시는 차예요. 그건 제가 따를 거예요."}, {"s": null, "t": "서하람이 입술에 손가락을 댔다. 아래층에서 찻잔 소리가 다시 달그락 울렸다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_2', 3, '별 대신', '다기 세트을(를) 만든다, 다기 세트을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["hf_surf_teaset"], "n": 1}], "give": {"hf_surf_teaset": 1}}'::jsonb, '[{"s": null, "t": "밤이 깊었다. 관성대 지붕 위에 작은 화로가 놓였고, 이슬 물이 주전자 속에서 보글보글 끓었다. 풀잎 향이 김에 섞여 은은하게 퍼졌다."}, {"s": null, "t": "서하람이 주전자 손잡이를 쥐고 잔 위로 기울였다. 주둥이 턱에서 물방울이 똑, 똑 떨어졌다. 서하람은 고개를 기울이고 그 소리를 들었다. 잔 안쪽 줄에 물이 닿자 서하람의 손이 멈췄다."}, {"s": "q:r71_seoharam", "t": "…됐다. 안 넘쳤죠?"}, {"s": null, "t": "나는 딱 맞게 따랐다고 했다. 서하람이 두 번째 잔에도 똑같이 따라서 내 쪽으로 밀었다."}, {"s": null, "t": "지붕 위로 밤바람이 불었다. 초여름 바람이 생각보다 쌀쌀해서 팔뚝에 소름이 돋았다. 서하람이 등 뒤에서 담요 한 장을 끌어왔다. 서하람은 담요를 제 어깨에 두르려다 멈추고 손으로 바닥을 더듬었다."}, {"s": "q:r71_seoharam", "t": "어, 담요가 하나밖에 없네요. 운해 씨가 하나 더 갖다준다더니 깜빡했나 봐요."}, {"s": null, "t": "서하람이 담요 한쪽을 끌어 내 어깨에 덮었다. 남은 한쪽은 제 어깨에 둘렀다. 우리는 담요 하나를 둘러쓰고 나란히 앉았다."}, {"s": null, "t": "서하람이 찻잔을 두 손으로 감싸 쥐고 하늘 쪽으로 얼굴을 들었다. 하얗게 바랜 눈에 별빛이 비쳤지만, 그 눈은 별을 보지 못했다."}, {"s": "q:r71_seoharam", "t": "예전엔 이 시간이면 별을 셌어요. 하나, 둘, 꾸벅꾸벅 졸면서요. 이제는 별이 안 보이는데… 그래도 손이 심심하네요."}, {"s": "q:r71_seoharam", "t": "오늘은 별 대신 {이름} 님 숨을 셀게요. 괜찮죠?"}, {"s": null, "t": "나는 괜찮다고 했다. 서하람이 담요 속에서 내 손목을 찾아 두 손가락을 얹었다. 손가락 끝이 따뜻했다."}, {"s": "q:r71_seoharam", "t": "하나. 둘. 셋…"}, {"s": null, "t": "서하람은 소리를 낮추어 내 숨을 셌다. 화로의 숯이 작게 탁 튀었다. 아래층 찻잔 소리가 멎었다. 관성대가 조용해졌다."}, {"s": "q:r71_seoharam", "t": "열여섯이에요. 아까 계단을 오르실 땐 열일곱이었는데. 느려졌네요. 편하신가 봐요."}, {"s": null, "t": "나는 담요가 따뜻해서 그렇다고 했다. 서하람은 손가락을 거두지 않았다."}, {"s": "q:r71_seoharam", "t": "별은 세면 셀수록 많아져서 끝이 없었어요. 숨은 세면 셀수록 편해지네요. 이게 더 좋아요."}, {"s": "q:r71_seoharam", "t": "이 담요요, 제가 스무 해 동안 지붕에서 덮고 잔 거예요. 하나뿐이라서 다행이에요. 둘이었으면 따로따로 덮었을 거 아니에요."}, {"s": null, "t": "서하람은 그 말을 하고 찻잔에 얼굴을 묻었다. 나는 아무 말 없이 차를 마셨다. 이슬로 끓인 차가 정말로 달았다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_haram_3', 'side', '연담·서하람', '오늘 온 사람', '서하람의 관측 일지에 「오늘 온 사람」 칸이 생긴다. 손끝으로 쓴 글씨는 비뚤배뚤해서 서하람이 주인공에게 대신 적어 달라고 한다. 밤새 일지를 옮겨 적고 나니 그 칸에는 한 사람 이름뿐이다.', 'star_observatory', 50, '{rg_haram_2}'::text[], null, 1647, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "haram", "stage": 3}'::jsonb where quest_id = 'rg_haram_3';
delete from public.world_quest_steps where quest_id = 'rg_haram_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_3', 1, '비뚤배뚤한 칸', '비뚤배뚤한 칸', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "한여름 밤이었다. 바람 한 점 없이 후텁지근해서 계단을 오르는 동안 등에 땀이 배었다. 관성대 지붕에 올라서자 서하람이 두꺼운 공책 한 권을 무릎에 펴 놓고 있었다."}, {"s": "q:r71_seoharam", "t": "오셨어요? 오늘 이렇게 더운데, 계단을 쉬지도 않고 올라오셨네요."}, {"s": "q:r71_seoharam", "t": "다기는 지붕 기와 밑에 숨겨 놨어요. 할머니는 아직 모르세요."}, {"s": null, "t": "나는 서하람의 무릎 위에 펼쳐진 공책을 들여다보았다. 서하람이 공책을 들어 보였다. 표지에 「관측 일지」라는 글씨가 반듯하게 적혀 있었다."}, {"s": "q:r71_seoharam", "t": "제 관측 일지예요. 별 칸은 갈매 씨가 잔불촌에 가기 전에 적어 줘요. 「빈, 국자 손잡이 끝에서 두 마디, 오늘도 있음.」 이렇게요. 맨날 똑같아요."}, {"s": "q:r71_seoharam", "t": "근데 제가 칸을 하나 새로 만들었어요. 이거요."}, {"s": null, "t": "서하람이 공책을 펼쳐 한쪽 가장자리를 손끝으로 짚었다. 세로로 길게 칸이 그어져 있었다. 칸 머리에 비뚤배뚤한 글씨로 「오늘 온 사람」이라고 적혀 있었다."}, {"s": null, "t": "칸 안에는 글씨가 몇 줄 있었다. 글자들이 서로 겹치고, 줄을 넘어 옆 칸까지 삐져나가 있었다. 송곳으로 찍은 점들이 글씨 옆에 나란히 박혀 있었다. 종이가 손때와 더위에 눅눅하게 부풀어 있었다."}, {"s": "q:r71_seoharam", "t": "손끝으로 더듬어서 쓴 거예요. 점은 제가 읽을 거고, 글씨는 남이 읽을 거예요. 근데 남이 제 글씨를 못 읽어요. 할머니가 보시고는 「이게 무슨 지렁이냐」 하셨어요."}, {"s": "q:r71_seoharam", "t": "{이름} 님이 대신 적어 주실래요? 제가 불러 드리면요."}, {"s": null, "t": "나는 그러겠다고 했다. 서하람이 지붕 한구석을 손으로 더듬어 붓과 벼루를 찾아 내밀었다. 하늘엔 달이 없었다. 산 아래 논에서 개구리 우는 소리만 올라왔다."}, {"s": "q:r71_seoharam", "t": "아, 등이 없네요. 저는 등이 없어도 되는데, {이름} 님은 등이 있어야 쓰잖아요."}, {"s": "q:r71_seoharam", "t": "등잔을 하나 만들어 주세요. 바닥이 넓어서 지붕 기와 위에서도 안 넘어지는 걸로요. 제가 손을 뻗다가 쳐도 안 엎어지게요."}, {"s": null, "t": "나는 바닥 넓은 등잔이라면 금방 만들 수 있다고 했다. 서하람이 다행이라는 듯 손뼉을 짝 쳤다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_3', 2, '숨 열여덟, 맥 일흔둘', '사기 등잔을(를) 만든다, 사기 등잔을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["hf_surf_lamp"], "n": 1}], "give": {"hf_surf_lamp": 1}}'::jsonb, '[{"s": null, "t": "바닥 넓은 등잔에 불을 켜자 지붕 위가 노랗게 밝아졌다. 기름 타는 냄새를 따라 날벌레 몇 마리가 불빛으로 모여들었다. 서하람이 등잔 쪽으로 손바닥을 펴서 온기를 재어 보았다."}, {"s": "q:r71_seoharam", "t": "따뜻한 쪽이 등이고, 그 옆이 {이름} 님이에요. 그럼 시작할게요. 첫 줄이요."}, {"s": null, "t": "내가 먹을 갈자 서늘한 먹 냄새가 더운 공기 속으로 퍼졌다. 서하람이 점 찍힌 자리를 손끝으로 읽으며 불렀다. 나는 그대로 받아 적었다."}, {"s": "q:r71_seoharam", "t": "봄, 보름. {이름} 님. 계단 숨 열여덟. 소매에 성진사 가루. 회랑 바람 냄새."}, {"s": "q:r71_seoharam", "t": "초여름, 보름 사흘 뒤. {이름} 님. 숨 열일곱. 맥 일흔둘. 풀벌레가 발목에 붙어 옴. 그거 제가 떼 드렸잖아요. 그것도 적어 주세요."}, {"s": null, "t": "나는 웃음을 참으며 적었다. 서하람이 손끝을 다음 점으로 옮겼다."}, {"s": "q:r71_seoharam", "t": "그다음 날. {이름} 님. 숨 열아홉. 맥 여든. 서두름. …이날 왜 서두르셨어요?"}, {"s": null, "t": "나는 그날 비가 올 것 같아서 서둘렀다고 했다. 서하람이 「아아」 하더니 점 옆에 송곳으로 작은 점 하나를 더 찍었다."}, {"s": "q:r71_seoharam", "t": "「비 올 것 같아서」… 아, 이유 칸도 만들어야겠다."}, {"s": null, "t": "나는 그 이유도 그대로 적었다. 서하람이 내 붓 소리가 멎기를 기다렸다가 다음 점으로 손끝을 옮겼다."}, {"s": null, "t": "나는 받아 적다가 붓을 멈췄다. 일지를 앞장부터 넘겨 보았다. 봄부터 한여름까지, 그 칸에 적힌 이름은 모두 같은 이름이었다."}, {"s": null, "t": "나는 갈매나 할머니나 운해는 왜 없느냐고 물었다. 서하람이 손끝을 공책 위에 얹은 채 잠깐 말이 없었다."}, {"s": "q:r71_seoharam", "t": "그분들은 늘 있는 사람이잖아요. 오늘 온 사람이 아니라요. 오늘 와야 「오늘 온 사람」이죠."}, {"s": "q:r71_seoharam", "t": "그리고 아직 남은 점이 많아요. 지붕 일지 말고 서고 쪽 일지에도 찍어 놨거든요. 오늘 밤에 다 옮겨 적으려면 아침까지 걸려요. 같이 해 주실 거죠? 저는 이제 밤새도 안 졸려요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_3', 3, '한 사람만 적힌 칸', '자율 활동을 끝까지 마친다', '{"at": ["star_observatory"], "tasks": [{"t": "idle", "n": 1, "k": "research"}]}'::jsonb, '[{"s": null, "t": "동이 틀 무렵 마지막 점을 옮겨 적었다. 등잔 기름이 바닥에 조금 남아 있었다. 손가락에 먹물이 까맣게 배어 있었다. 새벽이 되어서야 공기가 식어, 땀 밴 옷이 등에 차갑게 달라붙었다."}, {"s": null, "t": "서하람이 공책을 넘겨받아 「오늘 온 사람」 칸을 손끝으로 처음부터 끝까지 쓸었다. 내 글씨는 손끝으로 읽히지 않았다. 서하람은 송곳 점만 하나하나 짚어 내려갔다."}, {"s": "q:r71_seoharam", "t": "스물셋이요. 봄부터 스물세 번 오셨어요."}, {"s": "q:r71_seoharam", "t": "이 칸엔 다른 이름이 하나도 없네요. 만들 땐 몰랐는데, 다 적고 나니까 알겠어요."}, {"s": null, "t": "서하람이 웃었다. 웃다가 공책을 덮어 품에 끌어안았다."}, {"s": "q:r71_seoharam", "t": "별 칸은 매일 똑같은데, 이 칸은 매번 달라요. 숨도 다르고, 맥도 다르고, 소매에 묻어 오는 것도 달라요."}, {"s": "q:r71_seoharam", "t": "저는 이 칸이 더 재밌어요. 별 칸을 쓸 땐 갈매 씨가 「또 똑같아」 하고 투덜거리는데, 이 칸은 제가 불러 주는 걸 {이름} 님이 웃으면서 적잖아요."}, {"s": null, "t": "나는 웃은 적 없다고 했다. 서하람이 검지를 들어 좌우로 흔들었다."}, {"s": "q:r71_seoharam", "t": "웃으셨어요. 숨이 두 번 끊겼거든요. 풀벌레 줄에서 한 번, 이유 칸에서 한 번. 숨은 거짓말을 못 해요."}, {"s": null, "t": "나는 졌다고 했다. 서하람이 공책을 다시 펴서 맨 끝 빈 줄을 손끝으로 짚었다."}, {"s": "q:r71_seoharam", "t": "오늘 것도 적어 주세요. 한여름 그믐. {이름} 님. 계단 숨 열여섯. 밤새 일지를 적어 줌. 웃음 두 번."}, {"s": null, "t": "나는 그대로 적었다. 서하람이 송곳으로 그 줄 옆에 점을 찍었다. 점 하나를 찍고 나서 그 옆에 조금 큰 점을 하나 더 찍었다."}, {"s": null, "t": "나는 큰 점은 무엇이냐고 물었다. 서하람이 송곳을 내려놓고 공책을 덮었다."}, {"s": "q:r71_seoharam", "t": "그건 제 칸이에요. 「오늘 기다린 사람」. 아직 이름은 안 붙였어요."}, {"s": null, "t": "해가 혼천의 고리 사이로 들어와 지붕을 비추었다. 서하람의 바랜 눈이 그 빛을 받아 하얗게 빛났다. 서하람은 그 빛을 보지 못하면서도 해가 뜬 쪽으로 얼굴을 돌렸다."}, {"s": "q:r71_seoharam", "t": "따뜻해요. 해 떴죠? 밤을 다 새웠네요. 예전 같으면 지금쯤 이 지붕에서 코를 골고 있었을 텐데요."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_haram_4', 'side', '연담·서하람', '졸리지 않은 밤', '늦여름, 스무 해 동안 밤마다 졸던 서하람에게 밤이 너무 길다. 서하람은 별이 떨어진 자리를 손으로 만져 보고 싶다며 혜성 낙하지에 가자고 한다. 서하람은 밤새 말을 하다가 새벽에 주인공의 어깨에 기대 잠든다.', 'star_observatory', 50, '{rg_haram_3}'::text[], null, 1648, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "haram", "stage": 4}'::jsonb where quest_id = 'rg_haram_4';
delete from public.world_quest_steps where quest_id = 'rg_haram_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_4', 1, '스무 해치 밤', '스무 해치 밤', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "늦여름 밤이었다. 귀뚜라미 소리가 산자락을 메웠고, 바람에서 벌써 마른 잎 냄새가 조금 묻어났다. 계단 꼭대기에 서하람이 앉아 있었다. 서하람은 무릎을 끌어안고 고개를 숙이고 있다가, 내 숨소리를 듣고 고개를 들었다."}, {"s": "q:r71_seoharam", "t": "…오셨어요. 그 바닥 넓은 등잔, 요즘은 매일 밤 지붕에 켜 둬요. 저는 못 보는데, 운해 씨는 그 불을 보고 제가 지붕에 있는 줄 안대요."}, {"s": null, "t": "서하람의 눈 아래가 거뭇했다. 나는 잠을 못 잤느냐고 물었다. 서하람이 무릎 위에서 손가락을 꼼지락거렸다."}, {"s": "q:r71_seoharam", "t": "졸리지가 않아요. 벌써 사흘째예요. 별이 탄 뒤로는 밤에 졸린 적이 없어요."}, {"s": "q:r71_seoharam", "t": "할머니는 이제 「람아, 자거라」 소리를 안 하셔도 돼서 좋으신가 봐요. 그래서 못 자겠다는 말을 못 했어요."}, {"s": "q:r71_seoharam", "t": "처음엔 좋았어요. 밤이 다 제 거니까요. 근데 요즘은 밤이 너무 길어요. 해가 언제 뜨나 숨을 세다 보면 숨이 천 번을 넘어가요."}, {"s": null, "t": "서하람이 무릎을 더 꼭 끌어안았다. 서하람의 목소리가 조금 낮아졌다."}, {"s": "q:r71_seoharam", "t": "스무 해 동안 밤마다 잤어요. 그러니까 저는 스무 해치 밤을 한 번도 안 살아 본 거예요. 밤에 뭘 해야 하는지 몰라요. 다른 사람들은 밤에 뭐 해요?"}, {"s": null, "t": "나는 잠이 안 오는 밤엔 걷기도 하고 누구랑 이야기를 하기도 한다고 했다. 서하람이 고개를 번쩍 들었다."}, {"s": "q:r71_seoharam", "t": "그럼 걸어요, 우리. 오늘 밤에요. 가 보고 싶은 데가 있거든요."}, {"s": "q:r71_seoharam", "t": "혜성 낙하지요. 별이 떨어진 자리요. 별 기록에는 수백 번 적었는데, 만져 본 적은 없어요. 떨어진 별이 무슨 느낌인지 손으로 알고 싶어요."}, {"s": null, "t": "나는 밤길이 험하다고 했다. 서하람이 손가락으로 제 바랜 눈을 가리켰다."}, {"s": "q:r71_seoharam", "t": "저는 밤이나 낮이나 똑같아요. 깜깜해서 곤란한 건 {이름} 님이죠. 등을 하나 들고 가요. 바람에 안 꺼지는 걸로요. 어유를 먹이는 등이 바람에 세대요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_4', 2, '떨어진 별', '어유 등을(를) 만든다, 어유 등을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["lt_lantern_3"], "n": 1}], "give": {"lt_lantern_3": 1}}'::jsonb, '[{"s": null, "t": "어유 등에 불을 붙이자 서하람이 내 허리띠 끝을 쥐었다. 갈매가 하던 대로였다. 나는 계단을 세며 앞장서 내려갔다."}, {"s": null, "t": "혜성 낙하지까지는 밤길로 한참이었다. 서하람은 걷는 내내 말을 했다. 길섶 풀이 발목을 스치는 소리, 멀리서 부엉이가 우는 소리, 등잔 기름이 타는 냄새를 하나하나 짚었다."}, {"s": "q:r71_seoharam", "t": "밤엔 소리가 멀리 가네요. 낮엔 몰랐어요. 낮엔 다들 떠드니까요."}, {"s": null, "t": "길이 비탈로 바뀌자 발밑에서 자갈이 자그락거렸다. 서하람의 걸음이 느려졌다. 나는 걸음을 늦추고 돌이 있는 자리마다 발 앞을 일러 주었다."}, {"s": "q:r71_seoharam", "t": "「여기 돌」, 그 한마디면 되네요. 짧아서 좋아요. 발이 먼저 알아들어요."}, {"s": null, "t": "혜성 낙하지 가장자리에 이르자 땅이 움푹 꺼져 들어가 있었다. 구덩이 비탈에 유리처럼 굳은 모래가 등불을 받아 반짝였다. 구덩이 안쪽에서 오래 그을린 돌 냄새가 희미하게 올라왔다."}, {"s": null, "t": "서하람이 비탈에 무릎을 꿇고 앉아 손바닥으로 땅을 쓸었다. 손바닥 아래에서 매끈한 유리 모래가 바스락거렸다."}, {"s": "q:r71_seoharam", "t": "…매끄러워요. 녹았다가 굳은 거예요. 별이 떨어질 때 이 땅이 다 녹았나 봐요. 뜨거웠겠다."}, {"s": null, "t": "서하람이 손바닥에 모래 한 줌을 떠서 귀에 대고 흔들었다. 사르륵 소리가 성진사보다 거칠었다."}, {"s": "q:r71_seoharam", "t": "별 가루보다 굵어요. 떨어진 별은 부서지면서 이렇게 굵어지나 봐요."}, {"s": null, "t": "그때 구덩이 바닥에서 딸깍딸깍 무언가 부딪는 소리가 올라왔다. 별쇠 딱정벌레 여럿이 등불을 보고 비탈을 기어오르고 있었다."}, {"s": null, "t": "서하람이 등 곁으로 몸을 웅크렸다. 나는 서하람의 손에 어유 등 손잡이를 쥐여 주었다."}, {"s": "q:r71_seoharam", "t": "저 소리요. 쇠끼리 부딪는 소리예요. 딱정벌레죠? 비탈에서 저것들한테 발목을 물리면 저는 굴러떨어져요."}, {"s": "q:r71_seoharam", "t": "{이름} 님, 저것들 좀 쫓아 주세요. 저는 여기 등 곁에 가만히 있을게요. 그다음엔 여기서 밤새 있고 싶어요. 해 뜰 때까지요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_4', 3, '어깨', '혜성 낙하지의 요괴를 물리친다, 혜성 낙하지에서 쉰다', '{"at": ["comet_crater"], "tasks": [{"t": "win", "r": ["comet_crater"], "n": 5}, {"t": "rest", "r": ["comet_crater"], "n": 1}]}'::jsonb, '[{"s": null, "t": "딱정벌레들이 물러가자 구덩이가 조용해졌다. 나는 서하람 곁에 앉았다. 구덩이 바닥에 고인 밤공기가 차서 무릎이 시렸다. 어유 등이 우리 발치에서 흔들림 없이 탔다."}, {"s": null, "t": "서하람은 그 밤 내내 말을 했다. 할머니가 「람아」 하고 부르던 목소리, 관성대 지붕에서 두루마리를 덮고 자던 버릇, 갈매가 처음 저를 업고 계단을 오르던 날의 이야기였다."}, {"s": "q:r71_seoharam", "t": "갈매 씨가 저를 업었을 때요, 등이 엄청 딱딱했어요. 칼을 차는 사람은 등도 칼 같은가 봐요. 근데 따뜻했어요."}, {"s": null, "t": "서하람은 웃다가 문득 말을 멈췄다. 손바닥으로 유리 모래를 천천히 쓸었다."}, {"s": "q:r71_seoharam", "t": "진을 풀던 밤이요. 제 별이 탈 때, 저는 제가 거둬질 줄 알았어요. 알고 있었어요. 그런데도 할머니한테는 그 말을 안 하고 갔어요."}, {"s": "q:r71_seoharam", "t": "별이 타는 게 뜨거웠어요. 눈이 뜨거웠어요. 그때 다들 제 이름을 불렀잖아요. {이름} 님 목소리도 들렸어요. 갈매 씨 목소리가 제일 컸고요."}, {"s": null, "t": "나는 그 밤 일을 다 기억한다고 했다. 서하람이 유리 모래를 쥔 손에 힘을 주었다."}, {"s": "q:r71_seoharam", "t": "그래서 지금 여기 있는 거예요. 거둬지지 않고요. 그런데 가끔 무서워요. 이렇게 밤이 길면, 다들 자는 동안 저 혼자 남은 것 같아서요."}, {"s": null, "t": "서하람의 목소리가 떨렸다. 나는 대답 대신 서하람의 손을 잡았다. 차가운 손이었다. 나는 「하람」 하고 이름을 불렀다. 금빛 입김이 가늘게 맺혀 서하람의 가슴께에 닿았다."}, {"s": "q:r71_seoharam", "t": "…따뜻해요. 혼자가 아니네요."}, {"s": null, "t": "동쪽 하늘이 희부옇게 밝아 오기 시작했다. 어디선가 새벽 새가 짧게 울었다. 서하람의 말이 차츰 느려졌다. 말과 말 사이가 길어졌다."}, {"s": "q:r71_seoharam", "t": "이상해요. 졸린 거랑은 달라요. 별이 끌어당기던 그런 졸음이 아니에요. 그냥… 몸이 무거워요."}, {"s": "q:r71_seoharam", "t": "밤새 말을 하니까 그런가 봐요. 이런 건 처음이에요. 피곤해서 잠이 오는 거요."}, {"s": null, "t": "서하람의 머리가 천천히 기울어 내 어깨에 닿았다. 서하람은 머리를 떼려다 말고 그대로 두었다."}, {"s": "q:r71_seoharam", "t": "잠깐만요. 잠깐만 이러고 있을게요. 숨은… {이름} 님이 세 주세요."}, {"s": null, "t": "서하람의 숨이 고르게 길어졌다. 나는 서하람이 하던 대로 하나, 둘, 셋 그 숨을 세었다. 스물을 넘기기 전에 서하람이 잠들었다."}, {"s": null, "t": "해가 혜성 낙하지 비탈 위로 떠올랐다. 유리 모래가 아침 햇빛에 반짝였다. 내 어깨 위에서 서하람이 스무 해 만에 처음으로, 별에 끌려가지 않는 잠을 잤다."}, {"s": null, "t": "나는 어깨를 움직이지 않았다. 어유 등의 불이 아침 빛 속에서 하얗게 바래 갔다. 나는 등을 끄지 않았다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_haram_5', 'side', '연담·서하람', '관측 대상', '가을, 서하람이 천명원 관측 대상 명부를 들고 온다. 첫 줄은 새 별 「빈」, 둘째 줄은 비어 있다. 서하람은 표식으로 쓸 청동 호신패 두 개에 점을 찍고, 지붕의 낡은 관측 의자에 담요를 덮어 주인공을 앉힌다. 「예언은 안 해요. 관측만.」', 'star_observatory', 50, '{rg_haram_4}'::text[], null, 1649, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "haram", "stage": 5}'::jsonb where quest_id = 'rg_haram_5';
delete from public.world_quest_steps where quest_id = 'rg_haram_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_5', 1, '둘째 줄', '둘째 줄', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "가을밤이었다. 산 위 바람이 맑고 차서 숨을 들이쉴 때마다 코끝이 쨍했고, 마른 잎이 기와 위를 바스락거리며 굴렀다. 관성대 지붕에 서하람이 낡은 나무 의자 곁에 서 있었다. 등받이가 높고 팔걸이 끝이 반들반들 닳은 의자였다."}, {"s": "q:r71_seoharam", "t": "열여섯이요. 요즘은 계속 열여섯이에요. 계단이 익숙해지셨나 봐요."}, {"s": "q:r71_seoharam", "t": "그사이 갖다주신 것들이요, 어유 등은 그 뒤로 안 꺼트렸어요. 저울도 별 판도 손으로 읽게 고쳐서 서고에 들였어요. 관성대 법구가 반은 손으로 읽을 수 있게 됐어요. 할머니가 이제 저보고 법구 감독을 하래요."}, {"s": null, "t": "나는 처음 보는 의자 쪽으로 다가갔다. 서하람이 내 발소리를 듣고 의자 팔걸이를 손바닥으로 쓸었다."}, {"s": "q:r71_seoharam", "t": "관측 의자예요. 제가 밤마다 여기서 별을 보다가 잠들었어요. 할머니가 몇 번이나 버리자고 하셨는데, 끝까지 안 버렸어요."}, {"s": null, "t": "나는 팔걸이를 손으로 쓸어 보았다. 손때가 묻어 반들반들했고, 묵은 나무에서 오래된 기름 냄새가 났다. 팔걸이 한쪽 끝에 송곳 점 몇 개가 찍혀 있었다."}, {"s": "q:r71_seoharam", "t": "그건 잠들기 전에 마지막으로 센 별 수예요. 잠결에 찍어서 다 엉망이에요."}, {"s": null, "t": "서하람이 품에서 얇은 책 한 권을 꺼냈다. 표지에 「관측 대상 명부」라고 적혀 있었다."}, {"s": "q:r71_seoharam", "t": "이건 천명원 관측관마다 하나씩 가진 명부예요. 한 해 동안 무엇을 지켜볼지 적어 두는 거예요. 별이든, 혜성이든, 구름이든요."}, {"s": null, "t": "서하람이 명부를 펼쳐 첫 줄을 손끝으로 짚었다. 첫 줄에는 갈매의 투박한 글씨로 「빈 · 국자 손잡이 끝에서 두 마디」가 적혀 있었다. 그 옆에 송곳 점이 하나 찍혀 있었다."}, {"s": "q:r71_seoharam", "t": "첫 줄은 「빈」이에요. 근데 둘째 줄은 아직 비어 있어요."}, {"s": "q:r71_seoharam", "t": "관측 대상을 적으면 그 줄마다 표식을 하나씩 둬요. 별이면 동판에 점을 찍고요. 근데 둘째 줄은 별이 아니라서, 동판 말고 다른 표식이 필요해요."}, {"s": null, "t": "나는 둘째 줄에 무엇을 적을 거냐고 물었다. 서하람이 명부를 덮으며 입꼬리를 올렸다."}, {"s": "q:r71_seoharam", "t": "그건 다 하고 말할게요. 표식부터요. 청동 호신패를 두 개 만들어 주세요. 손바닥에 쏙 들어가는 걸로요. 거기에 제가 점을 찍을 거예요. 하나는 명부에 끼워 두고, 하나는… 그것도 다 하고 말할게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_5', 2, '열여덟 개의 점', '청동 호신패을(를) 만든다, 청동 호신패을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["bronze_charm"], "n": 2}], "give": {"bronze_charm": 2}}'::jsonb, '[{"s": null, "t": "청동 호신패 두 개를 넘기자 서하람이 그것을 관측 의자 팔걸이에 나란히 올려놓았다. 서하람은 송곳을 쥐고 패 하나를 손바닥에 눕혔다."}, {"s": null, "t": "서하람이 송곳 끝을 청동에 대고 톡, 톡 두드렸다. 점이 하나씩 패에 박힐 때마다 청동 부스러기에서 쇳내가 살짝 풍겼다. 서하람은 입술을 달싹이며 점을 셌다."}, {"s": null, "t": "점이 열여덟이 되자 서하람이 송곳을 멈췄다. 서하람은 두 번째 패에도 똑같이 열여덟 개의 점을 찍었다."}, {"s": null, "t": "나는 왜 열여덟이냐고 물었다. 서하람이 패를 손끝으로 쓸어 점을 확인했다."}, {"s": "q:r71_seoharam", "t": "봄에 제가 처음 나침반을 부탁드린 날이요. 계단을 다 올라와서 숨을 열여덟 번 쉬셨어요. 일지 첫 줄이에요."}, {"s": "q:r71_seoharam", "t": "별은 어디 있는지가 표식이에요. 사람은 숨이 표식이에요. 이 점을 만지면 그날 숨소리가 생각나요."}, {"s": null, "t": "나는 그날 계단 끝에서 숨이 찼던 것이 떠올라 웃었다. 서하람이 내 웃음소리 쪽으로 고개를 돌렸다."}, {"s": null, "t": "서하람이 패 하나를 내 손바닥에 올려놓고 손가락을 오므려 주었다. 청동이 서하람 손의 온기를 머금고 있었다."}, {"s": "q:r71_seoharam", "t": "이건 {이름} 님 거예요. 하나는 명부에, 하나는 {이름} 님한테요. 같은 점이 찍힌 걸 둘이 하나씩 가지는 거예요. 별 기록이랑 같아요. 하늘에 하나, 기록에 하나요."}, {"s": null, "t": "나는 패를 품에 넣었다. 서하람이 의자 등받이에 걸쳐 둔 담요를 끌어내려 의자에 반듯하게 깔았다. 지붕 위로 가을바람이 서늘하게 불었다."}, {"s": null, "t": "나는 둘째 줄 이야기를 다시 꺼냈다. 서하람이 웃으며 손가락 하나를 입술에 댔다."}, {"s": "q:r71_seoharam", "t": "아직이요. 해 뜨기 전에 말할게요."}, {"s": "q:r71_seoharam", "t": "오늘 밤은 여기서 같이 있어 주세요. 명부에 둘째 줄을 적기 전에 한 번 더 지켜보고 싶어요. 밤새요."}, {"s": "q:r71_seoharam", "t": "의자에는 {이름} 님이 앉으세요. 저는 바닥이 좋아요. 기와가 낮의 볕을 품고 있어서 따뜻해요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_haram_5', 3, '하람의 관측 대상', '무극 관성대에서 쉰다', '{"at": ["star_observatory"], "tasks": [{"t": "rest", "r": ["star_observatory"], "n": 1}]}'::jsonb, '[{"s": null, "t": "나는 담요가 깔린 관측 의자에 앉았다. 서하람은 의자 발치 기와에 등을 기대고 앉았다. 서하람의 손가락 두 개가 내 손목에 얹혀 있었다."}, {"s": null, "t": "밤이 깊어 가는 동안 서하람은 내 숨을 세었다. 가끔 「열다섯」 「열여섯」 하고 작게 중얼거렸다. 그 소리 말고는 바람 소리뿐이었다. 산 아래에서 개 짖는 소리가 한 번 올라왔다가 사라졌다."}, {"s": null, "t": "새벽이 가까워지자 서하람이 손가락을 거두고 명부를 무릎에 펼쳤다. 서하람이 붓을 쥐고 손끝으로 둘째 줄의 위치를 더듬었다."}, {"s": null, "t": "나는 대신 적어 주겠다고 했다. 서하람이 붓을 쥔 손을 제 쪽으로 끌어당겼다."}, {"s": "q:r71_seoharam", "t": "이건 제가 쓸래요. 비뚤어져도요. 「오늘 온 사람」 칸은 {이름} 님이 적어 줬지만, 이 줄은 제가 적어야 해요. 관측관이 직접 정하는 거라서요."}, {"s": null, "t": "서하람이 붓을 천천히 움직였다. 글씨가 비뚤배뚤 줄을 넘었다. 서하람은 한 글자를 쓸 때마다 왼손 손끝으로 붓 자리를 짚어 가며 다음 글자를 썼다."}, {"s": null, "t": "둘째 줄에 내 이름이 적혔다. 서하람이 명부 사이에 청동 호신패 하나를 끼우고 책을 덮었다."}, {"s": "q:r71_seoharam", "t": "「관측 대상 · {이름}」. 적었어요. 올해 내내 지켜볼 거예요. 내년에도 적을 거고요."}, {"s": null, "t": "나는 무엇을 관측할 거냐고 물었다. 서하람이 명부를 가슴에 안고 고개를 들었다."}, {"s": "q:r71_seoharam", "t": "언제 오시는지요. 계단에서 몇 번 쉬시는지요. 소매에 뭐가 묻어 오는지, 숨이 몇 번인지요."}, {"s": "q:r71_seoharam", "t": "예언은 안 해요. 다음에 언제 오실지, 오래오래 오실지, 그런 건 안 맞혀요. 예언하는 사람은 별을 바꾸고 싶어지거든요. 저는 안 바꿀래요."}, {"s": "q:r71_seoharam", "t": "관측만 해요. 오시면, 관측할게요. 그거면 돼요."}, {"s": null, "t": "서하람이 의자 쪽으로 손을 뻗어 담요 끝을 찾았다. 서하람이 그 끝을 내 무릎 위로 반듯하게 끌어 덮었다."}, {"s": "q:r71_seoharam", "t": "이 의자는 이제 관측 대상 자리예요. 담요도요. 다른 사람이 앉으면 안 돼요. 갈매 씨도요. 그 칼잡이 대장님이 오면 제가 바닥에 앉힐 거예요."}, {"s": "q:r71_seoharam", "t": "{이름} 님은 이제 하람의 관측 대상이에요. 천명원 명부에 그렇게 적혔으니까 못 물러요."}, {"s": null, "t": "동쪽 하늘이 밝아 왔다. 새벽 서리가 기와 끝에 하얗게 앉아 있었다. 서하람이 해 뜨는 쪽으로 얼굴을 돌리고 손가락을 다시 내 손목에 얹었다."}, {"s": "q:r71_seoharam", "t": "열다섯이요. 처음보다 세 번 적어요. {이름} 님은 여기 오시면 숨이 편해지세요."}, {"s": null, "t": "나는 품속의 청동 호신패를 꺼내 손끝으로 점을 쓸어 보았다. 열여덟 개의 점이 손끝에 하나하나 걸렸다."}]'::jsonb, '{"gil": 205, "title": "rg_haram", "items": {"hf_rg_haram_chair": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_munsu_1', 'side', '연담·문수', '선착 책상', '명등청이 등도로 드나드는 배와 짐을 적을 출납 서리로 문수를 남문 수로 선착에 내려보냈다. 선착에는 책상 하나 없어 짐 궤짝에 앉아 쓴 장부 글씨가 다 삐진다. 혼자 있으면 물소리가 무서운 문수가 조사원에게 서안을 주문하고, 서안을 짜는 동안 쉬지 않고 떠든다.', 'deungdo_landing', 50, '{mdq_17}'::text[], null, 1650, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = null where quest_id = 'rg_munsu_1';
delete from public.world_quest_steps where quest_id = 'rg_munsu_1' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_1', 1, '삐진 획', '삐진 획', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "남문 수로 선착 돌계단 아래, 짐 궤짝 하나에 서리 문수가 걸터앉아 있었다. 문수는 무릎 위에 장부를 펴 놓고 붓을 쥐고 있었다. 궤짝이 기우뚱할 때마다 붓끝이 종이에서 미끄러졌다. 수로에서 물이끼와 젖은 돌 냄새가 올라왔고, 계단 위 등 기둥에서 등 기름 냄새가 바람결에 섞여 내려왔다."}, {"s": "q:dh_munsu", "t": "아이참, 또 삐졌어! 또!"}, {"s": null, "t": "문수가 삐져나간 획을 내려다보며 울상을 지었다. 그러다 나를 보고 붓을 든 채 벌떡 일어났다. 궤짝이 쿵 하고 넘어졌다."}, {"s": "q:dh_munsu", "t": "조사원님! 오셨어요? 아, 아니, 반가워서 일어난 거예요. 이 궤짝이 원래 잘 넘어지거든요."}, {"s": null, "t": "나는 궤짝을 바로 세워 주며 선착에는 무슨 일로 왔느냐고 물었다. 문수가 장부를 가슴에 끌어안고 숨도 쉬지 않고 말을 쏟아 냈다."}, {"s": "q:dh_munsu", "t": "명등청에서 보냈어요. 등도로 드나드는 배가 요즘 엄청 늘었대요. 짐도 사람도요. 그걸 장부에 적을 서리가 하나 있어야 한대서 제가 왔죠. 베끼는 건 제가 제일 잘하니까요."}, {"s": "q:dh_munsu", "t": "근데 와 보니까 책상이 없는 거예요. 걸상도 없고요! 쉼막에서 빌린 궤짝은 귀퉁이가 다 깨져서 자꾸 기울고, 장부를 무릎에 놓고 쓰니까 글씨가 다 이 모양이에요."}, {"s": null, "t": "문수가 장부를 펼쳐 보였다. 반듯하게 쓰인 줄 사이사이로 삐져나간 획이 개구리 다리처럼 튀어나와 있었다."}, {"s": "q:dh_munsu", "t": "제 원래 글씨는 진짜 잘 쓰거든요? 감찰관님도 「글씨 하나는 됐다」고 하셨다니까요. ……하나는요."}, {"s": null, "t": "계단 위 등 기둥에서 등지기 차랑이 사다리를 타고 내려왔다. 차랑은 넘어졌다 일어선 궤짝을 한 번 보고, 웃음을 참으며 고개를 꾸벅 숙였다."}, {"s": "q:ug_charang", "t": "서리님, 그 궤짝은 쉼막 살림이니까 아껴 주세요. 함박 님이 하나하나 세어 보신대요."}, {"s": null, "t": "차랑이 쉼막 쪽으로 걸어갔다. 문수가 그 뒷모습을 보다 나를 돌아보며 입을 삐죽였다."}, {"s": "q:dh_munsu", "t": "보셨죠? 다들 웃는다니까요. ……근데요, 조사원님. 책상이 없어서만 그런 게 아니라요."}, {"s": null, "t": "문수가 목소리를 낮추고 수로 쪽을 흘끔거렸다. 돌계단 아래로 검푸른 물이 출렁이며 계단 모서리를 핥고 있었다."}, {"s": "q:dh_munsu", "t": "여기 혼자 있으면 무섭거든요. 물소리가 계속 나요. 책상이라도 있으면 그 앞에 딱 앉아서 일만 할 텐데, 궤짝에 앉아 있으면 자꾸 물 쪽을 보게 돼요."}, {"s": "q:dh_munsu", "t": "그래서 말인데요, 서안 하나만 짜 주실 수 있어요? 나무는 옛 나루 저자에 부적목이 있대요. 차랑 님 말로는 오래 묵어서 결이 곧고 안 비틀린대요."}, {"s": "q:dh_munsu", "t": "값은 명등청 출납으로 드릴게요. 제가 적는 거니까 틀림없어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_1', 2, '듣고만 계시면', '옛 나루 저자에서 부적목을(를) 모은다', '{"at": ["deungdo_landing"], "tasks": [{"t": "gather", "items": ["wood"], "r": ["old_ferry_market"], "n": 4}]}'::jsonb, '[{"s": null, "t": "옛 나루 저자에서 부적목을 지고 돌아오니 문수가 궤짝 대신 돌계단에 앉아 있었다. 궤짝은 아예 옆으로 누워 있었다."}, {"s": "q:dh_munsu", "t": "오셨다! 궤짝은 포기했어요. 계단이 차라리 안 흔들리더라고요. 엉덩이가 좀 차갑긴 한데요."}, {"s": null, "t": "나는 부적목을 내려놓고 대패와 톱을 꺼냈다. 문수가 계단에서 내려와 내 곁에 쪼그려 앉았다."}, {"s": "q:dh_munsu", "t": "여기서 짜시는 거예요? 저도 봐도 돼요? 저는 목공을 하나도 몰라요. 정청에선 나무 만질 일이 없었으니까요. 아, 딱 한 번 있긴 있었는데."}, {"s": null, "t": "문수의 말은 끝날 줄을 몰랐다. 대패질 소리 위로 문수의 목소리가 쉬지 않고 이어졌다. 대팻밥이 돌돌 말려 문수의 무릎 위로 떨어졌다."}, {"s": "q:dh_munsu", "t": "서고 서가 다리가 부러진 적이 있거든요. 제가 고친다고 못을 박았는데, 글쎄 못이 서가를 뚫고 나가서 옆 칸 장부에 구멍이 났지 뭐예요. 기록관님은 그 장부를 보시고 배를 잡고 웃으셨어요. 감찰관님은 안 웃으셨고요."}, {"s": "q:dh_munsu", "t": "그리고요, 정청 서리방 걸상은 다 다리가 짝짝이예요. 서리가 편하면 존다고 일부러 그렇게 둔대요. 진짜인지는 모르겠어요. 제 생각엔 그냥 아무도 안 고친 거거든요."}, {"s": null, "t": "나는 대답하지 않고 대패질을 했다. 문수가 이따금 숨을 고르며 내 얼굴을 살폈다."}, {"s": "q:dh_munsu", "t": "대답은 안 하셔도 돼요. 듣고 계시죠? 듣고만 계시면 돼요. 그럼 덜 무섭거든요."}, {"s": null, "t": "나는 대패를 멈추지 않고 듣고 있다고 했다. 문수의 어깨에서 힘이 조금 빠졌다. 문수는 다시 말을 이었고, 수로의 물소리는 그 말소리에 묻혀 거의 들리지 않았다."}, {"s": null, "t": "해가 기울 무렵 서안 판자가 매끈하게 다듬어졌다. 문수가 판자를 쓰다듬다 손바닥을 코에 대고 냄새를 맡았다."}, {"s": "q:dh_munsu", "t": "나무 냄새가 나요. 정청 냄새랑 완전 달라요. 정청은 먹 냄새밖에 안 나요."}, {"s": null, "t": "문수가 판자 위에 장부를 올려 보았다. 장부가 판자 한가운데에 흔들림 없이 놓였다. 문수는 손바닥으로 장부를 꾹 눌러 보고 흡족한 듯 콧소리를 냈다."}, {"s": "q:dh_munsu", "t": "이제 다리만 붙이면 되죠? 다 짜시면 저한테 넘겨 주세요. 제가 처마 밑 제일 안 젖는 데로 옮길게요. 자리는 벌써 봐 뒀다니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_1', 3, '선착 장부 첫 줄', '서안을(를) 만든다, 서안을(를) 넘긴다', '{"at": ["deungdo_landing"], "tasks": [{"t": "craft", "items": ["hf_seoan"], "n": 1}], "give": {"hf_seoan": 1}}'::jsonb, '[{"s": null, "t": "다 짠 서안을 넘겨주자 문수가 끙끙거리며 혼자 들어 옮기려 했다. 서안 한쪽 다리가 계단 모서리에 걸렸다. 나는 반대편을 들어 주었다."}, {"s": null, "t": "우리는 서안을 돌계단 옆 쉼막 처마 아래에 내려놓았다. 문수가 미리 봐 뒀다는 자리였다. 수로가 바로 내려다보이면서도 비가 들이치지 않는 곳이었다. 새 판자는 손바닥에 닿는 감촉이 매끄럽고 차갑게 만져졌다."}, {"s": "q:dh_munsu", "t": "여기요, 여기! 여기 앉으면 배가 들어오는 게 다 보여요. 근데 물은 좀 덜 보이고요. 그게 중요하거든요."}, {"s": null, "t": "문수가 서안 앞에 궤짝을 끌어다 놓고 앉았다. 장부를 펴고 벼루를 놓았다. 붓은 서안 모서리에 가지런히 눕혔다."}, {"s": null, "t": "문수가 붓을 들어 첫 줄을 적었다. 획이 하나도 삐지지 않았다. 문수가 장부를 들어 하늘에 비춰 보더니 입이 귀에 걸렸다."}, {"s": "q:dh_munsu", "t": "봐요! 이게 제 글씨예요! 이제야 제 글씨가 나온다니까요!"}, {"s": null, "t": "문수가 장부 맨 첫 줄을 손가락으로 짚었다. 「등도 남문 수로 선착 출납 — 서안 한 개, 조사원님 납품」이라고 적혀 있었다."}, {"s": "q:dh_munsu", "t": "첫 줄은 이걸로 하려고 아껴 뒀거든요. 선착 장부 첫 줄이요."}, {"s": null, "t": "문수가 붓을 내려놓고 서안 가장자리를 두 손으로 꼭 잡았다. 그러고는 나를 올려다보았다."}, {"s": "q:dh_munsu", "t": "근데요, 조사원님. 오늘 제가 얼마나 떠들었는지 아세요? 쉼막 함박 님은 반 식경만 들어도 귀를 막으세요."}, {"s": "q:dh_munsu", "t": "근데 조사원님은 끝까지 들어 주셨잖아요. 대패질하시면서 한 번도 말을 안 막으셨어요."}, {"s": null, "t": "나는 재미있었다고 했다. 문수가 눈을 동그랗게 떴다가 서안에 이마를 쿵 박았다. 아프다는 소리 대신 웃음소리가 새어 나왔다."}, {"s": "q:dh_munsu", "t": "그럼요, 앞으로도 부탁드려도 돼요? 선착엔 나무 물건이 하나도 없어요. 걸상이며 장부 궤며, 붓꽂이며요. 명등청 출납으로 꼬박꼬박 적을게요."}, {"s": null, "t": "나는 그러겠다고 했다. 문수가 장부에 둘째 줄을 적었다. 「조사원님 — 앞으로도 납품. 틀림없음」이라는 줄이었다. 이번에도 획이 하나도 삐지지 않았다."}, {"s": null, "t": "해가 수로 너머로 넘어가자 물 위로 저녁 빛이 기름처럼 번졌다. 계단의 등 기둥에 하나둘 불이 들어왔다. 문수가 서안 앞에 앉은 채 수로 쪽을 슬쩍 보았다가 얼른 장부로 눈을 돌렸다."}, {"s": "q:dh_munsu", "t": "오늘은 물소리가 하나도 안 무서웠어요. 서안 덕인지, 누구 덕인지는 모르겠지만요."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_munsu_2', 'side', '연담·문수', '맞장구', '바람에 살이 부러진 등 기둥 등롱 둘을 고치는 일이 출납 서리 문수에게 떨어진다. 목공을 모르는 문수를 대신해 조사원이 살을 깎는 동안 문수는 쉬지 않고 떠든다. 조사원이 처음으로 맞장구를 치자 문수가 말을 멈춘다.', 'deungdo_landing', 50, '{rg_munsu_1}'::text[], null, 1651, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "munsu", "stage": 2}'::jsonb where quest_id = 'rg_munsu_2';
delete from public.world_quest_steps where quest_id = 'rg_munsu_2' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_2', 1, '부러진 살', '부러진 살', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "선착 처마 아래 서안 옆에 낯선 걸상이 하나 놓여 있었다. 문수는 그 걸상 위에 장부 궤를 올려 두고, 자기는 여전히 궤짝에 앉아 있었다. 처마 끝에서 빗방울이 아직 똑똑 떨어졌고, 젖은 돌계단이 거무스름하게 번들거렸다."}, {"s": "q:dh_munsu", "t": "조사원님! 마침 잘 오셨어요. 비가 이틀이나 왔는데 장부 궤에 넣어 둔 장부가 하나도 안 젖었어요!"}, {"s": "q:dh_munsu", "t": "이 걸상은 함박 님이 쉼막 걸 빌려주신 거예요. 빌린 거라 아껴 써야죠. 그래서 저는 아직 궤짝에 앉아요."}, {"s": null, "t": "문수가 한숨을 쉬며 계단 위 등 기둥을 올려다보았다. 등 기둥마다 등롱이 걸려 있었는데, 그중 둘은 나무 살이 부러져 등갓이 한쪽으로 기울어 있었다."}, {"s": "q:dh_munsu", "t": "저거 보이세요? 차랑 님이 저보고 고쳐 달래요. 등 기둥 손질도 출납이래요. 기름이며 종이며 다 장부에 적으니까 서리 일이라나요."}, {"s": "q:dh_munsu", "t": "근데 제가 손대면 또 장부에 구멍이 날 거예요. 제가 바로 정청에서 소문난 그 「장부 뚫은 서리」라고요."}, {"s": null, "t": "문수가 제 손바닥을 내려다보았다. 손끝에 먹물이 배어 거뭇했다. 나무 가시 하나 박혀 본 적 없는 손이었다."}, {"s": "q:dh_munsu", "t": "이 손은 붓만 쥐어 봤어요. 망치를 쥐면 손이 먼저 놀란다니까요."}, {"s": null, "t": "나는 같이 고치자고 했다. 문수의 얼굴이 환해졌다가 금세 다시 시무룩해졌다."}, {"s": "q:dh_munsu", "t": "근데 등갓 종이도 다 해졌어요. 차랑 님 말로는 꺼진 관아 터에 바랜 등롱 종이가 많대요. 거기 종이는 결이 질겨서 밤바람에도 안 찢어진대요."}, {"s": null, "t": "문수가 꺼진 관아 터 쪽을 바라보다 어깨를 움츠렸다. 관아 터로 가는 길은 무너진 담장 사이로 어둡게 뚫려 있었다. 그쪽에서 불어온 바람에 축축한 재 냄새가 묻어 있었다."}, {"s": "q:dh_munsu", "t": "근데 꺼진 관아 터는…… 거기 현판 아래에 뭐가 산대요."}, {"s": null, "t": "나는 혼자 다녀오겠다고 했다. 문수가 미안한 얼굴로 두 손을 모았다."}, {"s": "q:dh_munsu", "t": "저는 여기서 살이 몇 개 부러졌는지 세어 놓을게요. 세는 건 잘하거든요. 종이는 세 장이면 될 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_2', 2, '대답이 오니까', '꺼진 관아 터에서 바랜 등롱 종이을(를) 모은다', '{"at": ["deungdo_landing"], "tasks": [{"t": "gather", "items": ["bleached_lantern_paper"], "r": ["dark_yamen"], "n": 3}]}'::jsonb, '[{"s": null, "t": "바랜 등롱 종이를 들고 돌아오니 문수가 등롱 둘을 내려 서안 위에 올려 두고 있었다. 부러진 살마다 숯으로 작은 표시가 되어 있었다. 관아 터에서 주워 온 종이는 만질 때마다 바스락거렸고, 손끝에 묵은 먼지 냄새를 남겼다."}, {"s": "q:dh_munsu", "t": "부러진 살이 열한 개예요. 왼쪽 등롱이 일곱, 오른쪽이 넷이요. 다 세어 놨어요."}, {"s": null, "t": "나는 부러진 살을 빼내고 새 살 자리를 재었다. 문수가 내 옆에서 등롱 틀을 붙잡아 주며 쉬지 않고 떠들었다."}, {"s": "q:dh_munsu", "t": "근데요, 등도 등롱은 정청 등롱이랑 살 모양이 달라요. 정청 건 살이 여덟 개인데 여긴 열두 개예요. 처음엔 제가 잘못 센 줄 알고 세 번을 셌어요."}, {"s": "q:dh_munsu", "t": "차랑 님 말로는 흰 밤엔 바람이 안 불었는데 이제 밤마다 분대요. 그래서 살이 버티다 버티다 부러진 거래요. 바람이 부는 건 좋은 건데 살은 부러지니까, 좋은 건지 나쁜 건지 모르겠어요."}, {"s": null, "t": "나는 살을 깎다 말고 바람이 부는 쪽이 더 좋겠다고 맞장구를 쳤다. 바람이 불어야 등불도 흔들리고, 흔들려야 살아 있는 불 같다고 했다."}, {"s": null, "t": "문수의 입이 한 마디를 하다 만 채 멈췄다. 등롱 틀을 붙잡은 손도 멈췄다. 문수가 나를 빤히 보았다."}, {"s": "q:dh_munsu", "t": "……방금요. 제 말에 대답하신 거죠?"}, {"s": null, "t": "나는 그렇다고 했다. 문수가 등롱 틀을 놓칠 뻔하다가 얼른 다시 붙잡았다."}, {"s": "q:dh_munsu", "t": "제 얘기에 맞장구쳐 준 사람, 처음이에요. 다들 「그래서 요점이 뭔데」 하거든요."}, {"s": "q:dh_munsu", "t": "대답이 오니까요… 그다음에 무슨 말을 해야 할지 모르겠어요. 이상하죠? 말은 원래 제가 제일 많은데."}, {"s": null, "t": "문수가 얼굴을 붉히고 등롱 틀만 내려다보았다. 내가 살을 두어 개 더 깎고 나서야 문수가 작은 목소리로 말을 이었다. 아까보다 훨씬 느렸다."}, {"s": "q:dh_munsu", "t": "……그럼, 살은요. 새로 깎은 걸 그냥 끼우면 비가 올 때 썩어요. 칠을 해야 돼요."}, {"s": "q:dh_munsu", "t": "칠액 두 통만 만들어 주시면 제가 바를게요. 바르는 건 할 수 있어요. 붓질이니까요."}, {"s": null, "t": "문수가 내 얼굴을 살폈다. 무언가를 기다리는 눈이었다. 나는 붓질이라면 문수를 따를 사람이 없겠다고 했다. 문수의 귀가 빨개졌다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_2', 3, '맞장구 둘', '칠액을(를) 만든다, 칠액을(를) 넘긴다', '{"at": ["deungdo_landing"], "tasks": [{"t": "craft", "items": ["lacquer"], "n": 2}], "give": {"lacquer": 2}}'::jsonb, '[{"s": null, "t": "칠액 두 통을 건네자 문수가 붓을 들고 새 살에 칠을 먹였다. 붓질은 정말로 반듯했다. 살마다 칠이 고르게 먹어 윤이 반지르르 돌았다. 칠에서 들큼하고 매캐한 냄새가 피어올랐다."}, {"s": "q:dh_munsu", "t": "보세요. 붓질은 잘한다니까요."}, {"s": null, "t": "칠이 마르는 동안 나는 바랜 등롱 종이를 오려 등갓에 발랐다. 바랜 종이에 등불을 비추자 우윳빛이 은은하게 번졌다."}, {"s": null, "t": "해가 지고 우리는 등롱 둘을 등 기둥에 다시 걸었다. 차랑이 사다리 위에서 심지에 불을 붙였다."}, {"s": "q:ug_charang", "t": "하나도 안 기우네요. 고맙습니다, 조사원님. 서리님도요."}, {"s": null, "t": "차랑이 고개를 꾸벅 숙이고 쉼막으로 내려갔다. 바람이 한 줄기 불어와 새 등롱이 흔들렸다. 열두 개의 살이 하나도 부러지지 않고 버텼다. 문수가 그 흔들림을 올려다보았다."}, {"s": "q:dh_munsu", "t": "흔들리니까 꼭 살아 있는 불 같네요. 조사원님 말씀대로요."}, {"s": null, "t": "문수가 서안 앞에 앉아 장부를 펼쳤다. 붓을 든 채 무언가를 망설이다 나를 힐끔 보았다."}, {"s": "q:dh_munsu", "t": "근데요. 아까 그거, 한 번만 더 해 주실 수 있어요? 맞장구요."}, {"s": "q:dh_munsu", "t": "오늘 등롱을 고친 거, 잘된 것 같지 않아요?"}, {"s": null, "t": "나는 아주 잘됐다고 맞장구를 쳤다. 문수가 붓을 쥔 채 어깨를 들썩이며 웃었다. 웃음소리가 수로를 따라 멀리 퍼져 나갔다."}, {"s": "q:dh_munsu", "t": "이거 이상하게 좋네요. 말하면 대답이 오는 거요. 혼자 떠들 때랑 완전 달라요."}, {"s": null, "t": "문수가 장부에 「등롱 둘 고침. 살 열한 개, 칠 두 통 — 조사원님 납품」이라고 적었다. 그 줄 끝에 작은 글씨로 「맞장구 둘」이라는 넉 자를 덧붙였다."}, {"s": null, "t": "나는 그것도 장부에 적느냐고 물었다. 문수가 붓을 내려놓고 진지한 얼굴로 대답했다."}, {"s": "q:dh_munsu", "t": "출납이니까요. 들어온 거니까 적어야죠. 받은 건 다 적는 게 서리 일이거든요."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_munsu_3', 'side', '연담·문수', '밤 물소리', '밤배가 늘어 문수가 밤에도 선착을 지키게 된다. 밤 물소리가 무서운 문수 곁에서 조사원이 불침번을 함께 선다. 문수는 무서움을 덮으려고 밤새 떠들다가 말하는 도중에 처음으로 잠이 든다.', 'deungdo_landing', 50, '{rg_munsu_2}'::text[], null, 1652, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "munsu", "stage": 3}'::jsonb where quest_id = 'rg_munsu_3';
delete from public.world_quest_steps where quest_id = 'rg_munsu_3' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_3', 1, '등잔 셋', '등잔 셋', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "해 질 녘 선착에 가 보니 문수가 서안 옆에 등잔을 셋이나 켜 놓고 앉아 있었다. 등잔 불빛이 서안을 둘러싸고 동그랗게 번져 있었다. 심지 타는 소리가 지지직 작게 이어졌다."}, {"s": "q:dh_munsu", "t": "조사원님! 보세요, 칠액 남은 걸로 장부 궤 모서리까지 칠했어요. 반들반들하죠?"}, {"s": null, "t": "나는 등잔을 왜 셋이나 켰느냐고 물었다. 문수가 등잔 하나를 서안 가운데로 끌어당겼다."}, {"s": "q:dh_munsu", "t": "명등청에서 밤배 출납도 보래요. 요즘 밤에 들어오는 배가 늘었대요. 그래서 오늘부터 밤에도 여기 있어야 돼요. 불침번처럼요."}, {"s": "q:dh_munsu", "t": "근데 밤엔 물소리가 커지거든요. 낮엔 사람 소리에 묻히는데 밤엔 물소리밖에 없어요. 그게 꼭 누가 계단을 올라오는 소리 같단 말이에요."}, {"s": null, "t": "문수가 그 말을 하며 저도 모르게 계단 쪽을 돌아보았다. 계단 아래 물이 어둠 속에서 철썩철썩 출렁였다."}, {"s": "q:dh_munsu", "t": "정리소 도랑을 지킬 때도 그랬어요. 그때도 등잔을 셋씩 켜 놨어요."}, {"s": null, "t": "문수가 등잔 셋을 손가락으로 하나씩 짚었다."}, {"s": "q:dh_munsu", "t": "하나는 장부를 보는 거, 하나는 계단을 보는 거, 하나는…… 그냥 무서워서 켠 거예요."}, {"s": null, "t": "나는 오늘 밤 같이 있겠다고 했다. 문수가 붓을 떨어뜨렸다가 허둥지둥 주웠다."}, {"s": "q:dh_munsu", "t": "진짜요? 진짜로요? 그럼, 그럼요……"}, {"s": null, "t": "문수가 붓을 쥔 채 처마 옆 빈 곳을 가리켰다. 처마와 쉼막 벽 사이로 수로 바람이 숭숭 들이쳤다. 등잔 셋의 불꽃이 한꺼번에 한쪽으로 쏠렸다."}, {"s": "q:dh_munsu", "t": "밤바람이 저기로 서안까지 들이쳐요. 등잔이 자꾸 꺼질 뻔해요. 꺼지면 깜깜해지고, 깜깜해지면 물소리가 더 커지고요."}, {"s": "q:dh_munsu", "t": "저기를 덧창으로 막으면 바람도 덜 들고 물소리도 덜 들릴 것 같아요. 널 덧창 하나만 짜 주실 수 있어요? 밤 되기 전에요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_3', 2, '노 소리', '널 덧창을(를) 만든다, 널 덧창을(를) 넘긴다', '{"at": ["deungdo_landing"], "tasks": [{"t": "craft", "items": ["hf_window_shutter"], "n": 1}], "give": {"hf_window_shutter": 1}}'::jsonb, '[{"s": null, "t": "널 덧창을 처마 옆에 달자 수로 쪽에서 불어오던 바람이 뚝 끊겼다. 물소리도 한 겹 낮아졌다. 문수가 덧창을 두드려 보며 고개를 끄덕였다."}, {"s": "q:dh_munsu", "t": "확실히 덜 들려요. 반쯤요. 나머지 반은… 들리긴 하지만요."}, {"s": null, "t": "밤이 깊어 갈수록 눅눅한 냉기가 소매 속까지 스며들었고, 문수의 말도 빨라졌다. 배 한 척이 들어와 짐을 내리고 떠날 때마다 문수는 장부에 적었다. 적고 나서는 다시 떠들었다."}, {"s": "q:dh_munsu", "t": "근데요, 흰 밤일 땐 소리가 세 걸음 밖으로 안 나갔대요. 차랑 님이 그러는데, 바로 옆 사람 목소리도 잘 안 들렸대요. 그때 여기 있었으면 저는 무서워서 기절했을 거예요."}, {"s": "q:dh_munsu", "t": "근데 이제 밤이 돌아와서 저 끝 물소리까지 여기로 와요. 그것도 무섭거든요. 소리가 안 들려도 무섭고 들려도 무서우면 저는 어쩌라는 거냐고요."}, {"s": null, "t": "문수가 스스로 한 말에 웃음을 터뜨렸다. 그 순간 계단 아래에서 철썩, 하고 큰 물소리가 났다. 문수가 펄쩍 뛰어 내 팔을 붙잡았다."}, {"s": "q:dh_munsu", "t": "방금요! 방금 그 소리 들으셨죠? 들으셨잖아요!"}, {"s": null, "t": "계단 아래로 거룻배 한 척이 스르르 들어오고 있었다. 노를 젓던 사람이 쿨럭쿨럭 쇳소리 섞인 기침을 하며 이쪽으로 손을 들어 보였다. 청파였다."}, {"s": null, "t": "청파는 빈 배를 말뚝에 매고 쉼막 쪽으로 올라갔다. 기침 소리가 쉼막 문 안으로 사라졌다."}, {"s": "q:dh_munsu", "t": "……청파 님 배였네요. 노 소리였구나. 제가 지금 팔을 너무 세게 잡았죠. 죄송해요."}, {"s": null, "t": "문수가 손을 놓으려다 말고 내 소매 끝만 살짝 쥐었다. 나는 그대로 두었다."}, {"s": null, "t": "그때 문수의 배에서 꼬르륵 소리가 났다. 문수가 배를 움켜쥐고 얼굴을 붉혔다."}, {"s": "q:dh_munsu", "t": "……쉼막 살림 맡으신 함박 님이 밤참은 손수 잡아 먹으래요. 쉼막 쌀이 모자라대요. 계단 아래 물에 고기가 많다고요."}, {"s": "q:dh_munsu", "t": "같이 잡아요. 아니, 조사원님이 잡으세요. 저는 옆에서 등잔을 들고 있을게요."}, {"s": "q:dh_munsu", "t": "먹고 나서는 번갈아 눈을 좀 붙여요. 날 새려면 아직 멀었어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_3', 3, '말하다 든 잠', '남문 수로 선착에서 낚시를 한다, 남문 수로 선착에서 쉰다', '{"at": ["deungdo_landing"], "tasks": [{"t": "fish", "r": ["deungdo_landing"], "n": 2}, {"t": "rest", "r": ["deungdo_landing"], "n": 1}]}'::jsonb, '[{"s": null, "t": "잡은 고기를 등잔불에 구울 때 기름이 불에 떨어져 치익 소리를 냈다. 노릇하게 탄 껍질에서 고소한 냄새가 퍼졌다. 고기를 나눠 먹고 나자 밤이 한결 짧아졌다. 우리는 번갈아 눈을 붙이기로 했다. 먼저 자기로 한 것은 문수였다. 문수는 눕고 나서도 쉬지 않고 떠들었다."}, {"s": null, "t": "문수의 말이 점점 느려졌다. 정청 먹 냄새 이야기가 서고 책벌레 이야기로 넘어갔다. 그 이야기가 문장 한가운데서 뚝 끊겼다. 문수는 서안에 볼을 대고 잠들어 있었다."}, {"s": null, "t": "나는 덧창 옆에 앉아 수로를 지켰다. 물소리가 고르게 철썩거렸다. 밤배 두 척이 더 들어왔고, 나는 문수가 깨지 않게 장부에 짐 수를 적어 두었다."}, {"s": null, "t": "동이 틀 무렵 수로 위로 물안개가 낮게 깔렸다. 문수가 화들짝 놀라며 고개를 들었다. 볼에 서안 나뭇결 자국이 빨갛게 찍혀 있었다."}, {"s": "q:dh_munsu", "t": "제가 잤어요? 말하다가요? 아이고, 어디까지 했더라?"}, {"s": null, "t": "나는 책벌레가 서고 장부 겉장만 골라 먹는다는 데까지 했다고 대답했다. 문수가 입을 떡 벌렸다."}, {"s": "q:dh_munsu", "t": "……그걸 기억하세요? 제가 말하다 잠든 데까지요?"}, {"s": null, "t": "나는 그 뒷이야기가 궁금했다고 했다. 문수가 볼의 나뭇결 자국을 문지르며 나를 물끄러미 보았다."}, {"s": "q:dh_munsu", "t": "정리소 도랑을 지킬 땐 사흘을 꼬박 샌 적도 있어요. 무서워서요. 근데 오늘은 말하다가 잤네요."}, {"s": "q:dh_munsu", "t": "들어 주는 사람이 있으니까 물소리가 안 들렸나 봐요."}, {"s": null, "t": "문수가 장부를 펼쳤다가 내가 적어 둔 줄을 보았다. 「밤배 둘 — 소금 넷, 장작 일곱」이라는 줄이었다. 문수가 그 줄을 손가락으로 쓸었다."}, {"s": "q:dh_munsu", "t": "글씨가… 저보다는 좀 못하시네요."}, {"s": null, "t": "문수가 웃음을 참지 못하고 웃었다. 웃다가 그 줄 옆에 제 글씨로 반듯하게 한 번 더 옮겨 적었다. 옮겨 적고 나서도 내 글씨는 지우지 않았다."}, {"s": "q:dh_munsu", "t": "이건 안 지울래요. 오늘 밤 몫이니까요."}, {"s": "q:dh_munsu", "t": "그리고요, 아까 그 책벌레 얘기요. 뒷얘기가 엄청 길거든요. 다음에 꼭 해 드릴게요. 그러니까 또 오셔야 돼요, 꼭이요."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_munsu_4', 'side', '연담·문수', '말 없는 날', '늘 떠들던 문수가 처음으로 말이 없다. 짐 정리를 하다 보따리에서 도제조 백운서의 붓이 나온 날이다. 조사원이 먼저 말을 걸자 문수는 그 방에서 날마다 벼루와 붓을 차려 드리던 일을 털어놓고, 둘은 꺼진 관아 터 느티나무 아래로 붓을 돌려 드리러 간다.', 'deungdo_landing', 50, '{rg_munsu_3}'::text[], null, 1653, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "munsu", "stage": 4}'::jsonb where quest_id = 'rg_munsu_4';
delete from public.world_quest_steps where quest_id = 'rg_munsu_4' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_4', 1, '「거든요」 없는 글', '「거든요」 없는 글', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "바람 한 점 없는 흐린 낮이었다. 선착 처마 아래가 이상하게 조용해서 수로 물소리만 유난히 또렷했다. 문수가 서안 앞에 앉아 있었지만 아무 말이 없었다. 붓을 쥔 손만 장부 위를 오갔다."}, {"s": null, "t": "내가 다가가자 문수가 고개를 들어 꾸벅 숙였다. 입을 열려다 다시 다물었다. 문수는 서안 한쪽에 놓인 종이 한 장을 내 쪽으로 밀었다."}, {"s": null, "t": "종이에는 반듯한 글씨가 적혀 있었다. 「조사원님. 조사원님이 짜 주신 덧창 덕에 밤바람이 안 듭니다. 걸상도 새로 받았고 장부 궤도 둘이 되었습니다. 고맙습니다.」 말하듯이 쓴 글이었는데 「거든요」가 하나도 없었다."}, {"s": null, "t": "그 아래 한 줄이 더 있었다. 「서가 다리 하나 부러짐. 강화 부적목이 있어야 고칠 수 있음.」이라는 줄이었다."}, {"s": null, "t": "계단 위에서 차랑이 사다리를 내려오다 나를 보고 다가왔다. 차랑은 목소리를 낮춰 내 귀에 대고 말했다."}, {"s": "q:ug_charang", "t": "서리님이 아침부터 한마디도 안 하셨어요. 무슨 일인지 여쭤봐도 고개만 저으시고요. 평소엔 우리 수다쟁이 서리님 때문에 제가 귀를 막을 지경인데요."}, {"s": null, "t": "차랑이 걱정스러운 얼굴로 쉼막 쪽으로 돌아갔다. 나는 문수에게 무슨 일이 있느냐고 물었다. 문수가 고개를 저었다."}, {"s": null, "t": "문수는 붓끝으로 종이의 마지막 줄을 톡톡 짚었다. 서안 옆에 지난번에 들인 서가가 한쪽 다리가 꺾인 채 비스듬히 서 있었다. 칸마다 장부가 쏟아질 듯 기울어 있었다."}, {"s": null, "t": "서가 발치에 풀어 헤친 보따리 하나가 놓여 있었다. 짐을 정리하던 참이었는지, 옷가지와 낡은 장부 몇 권이 보따리 밖으로 비어져 나와 있었다."}, {"s": null, "t": "보따리 맨 위에 붓 한 자루가 얹혀 있었다. 문수의 눈길이 자꾸 그 붓으로 갔다가 돌아왔다."}, {"s": null, "t": "나는 붓을 가리키려다 손을 거두었다. 문수가 먼저 그 붓을 집어 품에 넣었다."}, {"s": null, "t": "나는 강화 부적목을 지어 오겠다고 했다. 서가를 고치면 장부가 쏟아지지 않을 터였다. 문수가 턱을 아주 조금 끄덕이다가 처음으로 입을 열었다. 목소리가 갈라져 있었다."}, {"s": "q:dh_munsu", "t": "……네. 고맙습니다."}, {"s": null, "t": "「거든요」가 붙지 않은 대답이었다. 문수는 그 말만 하고 다시 장부로 고개를 숙였다. 붓을 쥔 손이 오래 움직이지 않았다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_4', 2, '차려 둔 자리', '강화 부적목을(를) 만든다, 강화 부적목을(를) 넘긴다', '{"at": ["deungdo_landing"], "tasks": [{"t": "craft", "items": ["reinforced_lumber"], "n": 2}], "give": {"reinforced_lumber": 2}}'::jsonb, '[{"s": null, "t": "강화 부적목을 건네고 서가 다리를 고쳐 세웠을 때는 해가 기울고 있었다. 문수는 그동안에도 말이 없었다. 다만 내가 서가를 세울 때 반대편을 꼭 붙잡아 주었다."}, {"s": null, "t": "서가를 다 고치고 돌아보니 문수가 서안 앞에 앉아 무언가를 차리고 있었다. 문수는 벼루를 놓고 먹을 갈았다. 사륵사륵 먹 가는 소리가 처마 아래를 채웠다. 그 곁에 종이 한 묶음을 가지런히 놓았다."}, {"s": null, "t": "문수는 다 차려 놓고도 붓을 들지 않았다. 빈 종이 앞에 두 손을 무릎에 얹고 가만히 앉아 있었다."}, {"s": null, "t": "나는 문수 곁에 앉았다. 해가 다 질 때까지 그렇게 있다가 내가 먼저 그 자리를 누구에게 차려 준 것이냐고 물었다."}, {"s": null, "t": "문수의 어깨가 움찔했다. 문수는 빈 종이를 내려다보며 입을 열었다. 목소리가 아주 작았다."}, {"s": "q:dh_munsu", "t": "……도제조님이요."}, {"s": "q:dh_munsu", "t": "그 방에 계실 때 날마다 이렇게 차려 드렸어요. 심지가 밝아지는 때가 해 질 녘이면 해 질 녘에, 한밤이면 한밤에요. 벼루, 먹, 붓, 종이 한 묶음이요."}, {"s": "q:dh_munsu", "t": "아침에 짐을 정리하다가 보따리에서 붓 한 자루가 나왔어요. 그분 손에서 제가 빼 드린 붓이요."}, {"s": "q:dh_munsu", "t": "심지가 낮아지면 붓 쥔 손이 그대로 굳으셨어요. 그럼 제가 붓을 빼 드리고, 손을 무릎에 내려 드렸고요. 그 붓을 돌려 드리려고 챙겼는데… 돌려 드릴 데가 없어져서, 그냥 들고 다녔나 봐요."}, {"s": null, "t": "문수가 품에서 붓 한 자루를 꺼내 종이 옆에 눕혔다. 붓털 끝이 하얗게 말라 있었다."}, {"s": "q:dh_munsu", "t": "제가 왜 이렇게 떠드는지 아세요? 그 방에서는요, 숨소리도 크게 못 냈어요. 하루에 한 번, 몇 마디요. 그 몇 마디를 놓칠까 봐 다들 숨을 참았어요."}, {"s": "q:dh_munsu", "t": "그러다 나오면 말이 막 쏟아져요. 참았던 게 한꺼번에요. 근데 오늘은… 붓을 보니까 다시 그 방에 있는 것 같아서요. 말이 안 나왔어요."}, {"s": null, "t": "문수의 목소리가 떨렸다. 나는 문수의 등을 천천히 두드렸다. 문수가 코를 훌쩍이며 붓을 내려다보았다."}, {"s": "q:dh_munsu", "t": "조사원님. 꺼진 관아 터 뒤뜰 느티나무요. 그분 계신 데요. 이 붓을 거기 갖다 드리고 싶어요."}, {"s": "q:dh_munsu", "t": "혼자서는 못 가겠어요. 같이 가 주실래요? 가서 그냥… 좀 앉아 있다 와요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_4', 3, '「됐네」', '꺼진 관아 터에 간다, 꺼진 관아 터에서 쉰다', '{"at": ["dark_yamen"], "tasks": [{"t": "travel", "r": ["dark_yamen"], "n": 1}, {"t": "rest", "r": ["dark_yamen"], "n": 1}]}'::jsonb, '[{"s": null, "t": "꺼진 관아 터 뒤뜰 느티나무 아래에 작은 봉분 하나가 있었다. 봉분 앞에 누군가 놓고 간 찻잔이 이슬에 젖어 있었다. 느티나무 그늘은 축축했고, 발밑 흙에서 비 갠 뒤 같은 눅진한 흙내가 풍겼다."}, {"s": null, "t": "문수가 봉분 앞에 쪼그려 앉아 붓을 내려놓았다. 붓 옆에 벼루와 먹을 놓았다. 날마다 하던 일처럼 손놀림이 익숙했다."}, {"s": null, "t": "우리는 느티나무 뿌리에 나란히 걸터앉았다. 등도에 밤이 내려와 처마 등롱들이 하나둘 켜졌다. 문수는 오래 말이 없었다. 나도 말하지 않았다."}, {"s": null, "t": "바람이 불어 느티나무 잎이 사르르 흔들렸다. 나는 그 소리를 듣다가 먼저 말을 걸었다. 그분이 문수가 차려 둔 붓을 쓴 적이 있었느냐고 물었다."}, {"s": "q:dh_munsu", "t": "……네. 날마다요. 처음엔 제가 먹을 너무 진하게 갈아서 붓이 뻑뻑했어요. 그랬더니 종이에 「물을 더」라고 쓰셨어요. 그날 하루치 말을 그걸로 다 쓰신 거예요."}, {"s": null, "t": "문수가 그 말을 하고 나서 피식 웃었다. 웃고 나니 말이 조금씩 이어졌다."}, {"s": "q:dh_munsu", "t": "그다음 날부터는 먹을 묽게 갈았거든요. 그랬더니 「됐네」 하시더라고요. 입으로요. 그게 저한테 하신 처음이자 마지막 칭찬이었어요."}, {"s": "q:dh_munsu", "t": "감찰관님은 제 글씨를 칭찬하셨지만, 도제조님은 제 먹을 칭찬하셨거든요. 그건 아무한테도 말을 안 했어요. 자랑하면 안 될 것 같아서요."}, {"s": null, "t": "문수의 말끝에 「거든요」가 하나씩 돌아오고 있었다. 나는 먹을 잘 간 덕에 그분이 귀한 말 한마디를 문수에게 쓰셨을 거라고 맞장구를 쳤다."}, {"s": null, "t": "문수가 소매로 눈가를 꾹 눌렀다. 문수는 봉분 앞에 놓인 붓을 다시 보았다."}, {"s": "q:dh_munsu", "t": "붓은 여기 두고 갈게요. 이제 돌려 드렸으니까요."}, {"s": "q:dh_munsu", "t": "조사원님. 오늘 제가 말을 안 하니까 먼저 말을 걸어 주셨잖아요. 선착에서도, 지금도요."}, {"s": "q:dh_munsu", "t": "저는 맨날 제가 먼저 말하는 사람이거든요. 누가 먼저 말을 걸어 준 건 처음이에요. 이상하네요, 말이 다시 나와요."}, {"s": null, "t": "문수가 일어나 봉분 앞에 고개를 깊이 숙였다. 문수는 내 쪽으로 돌아서서 등잔을 들어 올렸다."}, {"s": "q:dh_munsu", "t": "돌아가는 길엔 제가 떠들게요. 책벌레 뒷얘기를 아직 안 했잖아요."}, {"s": null, "t": "선착으로 돌아오는 길 내내 문수는 책벌레 이야기를 했다. 이야기는 선착 계단에 닿을 때까지 끝나지 않았다. 나는 굽이마다 맞장구를 치고 웃어 주었다."}]'::jsonb, '{"gil": 205}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('rg_munsu_5', 'side', '연담·문수', '수다 상대', '문수가 무엇에 쓸지 묻지 말아 달라며 물 먹은 뱃판과 칠액을 주문한다. 쉼막 뒤에서 망치 소리가 하루 종일 울리고, 해 질 녘 문수가 다리가 짝짝이인 걸상 하나를 끌고 나온다. 서안 맞은편, 조사원이 앉을 자리다.', 'deungdo_landing', 50, '{rg_munsu_4}'::text[], null, 1654, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
update public.world_quests set open_req = '{"regular": "munsu", "stage": 5}'::jsonb where quest_id = 'rg_munsu_5';
delete from public.world_quest_steps where quest_id = 'rg_munsu_5' and step > 3;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_5', 1, '묻지 말아 주세요', '묻지 말아 주세요', '{"at": ["deungdo_landing"]}'::jsonb, '[{"s": null, "t": "선착 처마 아래 서안 앞에 문수가 없었다. 장부만 펼쳐진 채 바람에 넘어가고 있었다. 쉼막 뒤편에서 쿵, 쿵 망치질 소리가 들려왔다. 볕 좋은 오후였고, 바람에 생나무 쪼갠 냄새가 실려 왔다."}, {"s": null, "t": "소리를 따라가 보니 문수가 쉼막 뒤 짐 궤짝 그늘에 쪼그려 앉아 있었다. 무언가를 망치로 두드리던 문수가 나를 보고 화들짝 놀라 그것을 등 뒤로 감췄다. 미처 감추지 못한 나무 조각이 발치에 굴러다녔다."}, {"s": "q:dh_munsu", "t": "조, 조사원님! 언제 오셨어요? 아무것도 아니에요! 그냥 망치질 연습이거든요!"}, {"s": null, "t": "문수가 엄지손가락을 입에 물었다가 얼른 뺐다. 엄지 끝이 빨갛게 부어 있었다."}, {"s": "q:dh_munsu", "t": "어제 선착 장부를 처음부터 넘겨 봤는데요. 서안 하나, 걸상 둘, 붓꽂이 둘, 장부 궤 셋, 소반 하나, 덧창 하나, 등롱 살 열한 개요. 서가는 다리까지 고쳐 주셨고요."}, {"s": "q:dh_munsu", "t": "선착 장부 첫 장부터 끝 장까지 조사원님 줄이 서른 줄이 넘어요. 명등청에서 장부 보신 분이, 이 조사원은 선착에 사느냐고 물으셨대요."}, {"s": "q:dh_munsu", "t": "근데요, 오늘 부탁은 좀 이상해요. 뭐에 쓸 건지는 안 여쭤봐 주셨으면 좋겠어요."}, {"s": null, "t": "나는 묻지 않겠다고 했다. 문수가 안도의 숨을 길게 내쉬었다."}, {"s": "q:dh_munsu", "t": "다행이다. 조사원님은 약속하면 꼭 지키시잖아요."}, {"s": "q:dh_munsu", "t": "옛 나루 저자에 물 먹은 뱃판이 굴러다니거든요. 옛날 나룻배 판자요. 일흔 해를 물에 잠겨 있다가 마른 거라 엄청 단단하대요. 삿대 님이 그랬어요. 앉아도 안 부서진대요."}, {"s": null, "t": "문수가 「앉아도」라는 말을 하고 나서 얼른 입을 틀어막았다."}, {"s": "q:dh_munsu", "t": "아, 아니, 그러니까… 세 장만요. 세 장이면 돼요."}, {"s": null, "t": "문수가 등 뒤의 것을 더 깊이 감추며 뒷걸음질 쳤다. 궤짝에 발꿈치가 걸려 하마터면 넘어질 뻔했다."}, {"s": "q:dh_munsu", "t": "진짜 안 여쭤보실 거죠? 약속하신 거예요?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_5', 2, '쉼막 뒤 망치 소리', '옛 나루 저자에서 물 먹은 뱃판을(를) 모은다', '{"at": ["deungdo_landing"], "tasks": [{"t": "gather", "items": ["waterlogged_plank"], "r": ["old_ferry_market"], "n": 3}]}'::jsonb, '[{"s": null, "t": "물 먹은 뱃판 세 장을 건네자 문수가 판자를 받아 들고 쉼막 뒤로 달려갔다. 망치 소리가 다시 쿵쿵 울렸다. 이따금 아야, 하는 소리가 섞였다."}, {"s": null, "t": "나는 서안 앞 궤짝에 앉아 기다렸다. 처마 끝 등롱이 바람에 흔들렸다. 지난번에 고친 살은 하나도 부러지지 않았다. 볕에 데워진 궤짝 뚜껑이 엉덩이 밑에서 뜨끈했다."}, {"s": null, "t": "망치 소리가 그칠 때마다 쉼막 뒤에서 무언가를 재는 혼잣말이 들렸다. 한 뼘, 반 뼘 하는 소리였다."}, {"s": null, "t": "쉼막 문이 열리고 쉼막 맏이 함박이 주먹밥 두 개를 들고 나왔다. 아직 따끈한 주먹밥에서 참기름 냄새가 고소하게 번졌다. 함박은 하나를 내 손에 쥐여 주고, 쉼막 뒤를 턱으로 가리키며 고개를 절레절레 저었다. 함박은 나머지 하나를 들고 망치 소리 나는 쪽으로 사라졌다."}, {"s": null, "t": "해가 서쪽으로 한 뼘쯤 기울었을 때 문수가 쉼막 모퉁이에서 고개만 내밀었다. 이마에 땀이 송골송골 맺혀 있었고, 입가에 밥알이 하나 붙어 있었다."}, {"s": "q:dh_munsu", "t": "조사원님, 칠액이요. 칠을 안 하면 비를 맞고 금방 썩어요. 근데 저는 칠액 만드는 법을 몰라서요. 한 통만 만들어 주실래요?"}, {"s": null, "t": "나는 무엇에 칠할 거냐고 물으려다 아까 한 약속이 떠올라 입을 다물었다. 문수가 그걸 알아챘는지 키득 웃었다."}, {"s": "q:dh_munsu", "t": "안 물어보시네요. 진짜 안 물어보시네. 그게 제일 고마워요."}, {"s": null, "t": "나는 입가에 밥알이 붙었다고 손짓했다. 문수가 손등으로 입가를 문지르다 엉뚱한 쪽만 닦았다. 나는 웃음을 참고 반대쪽이라고 다시 손짓했다."}, {"s": "q:dh_munsu", "t": "아… 함박 님이 일하면서 먹으라고 쥐여 주셨거든요. 근데 손이 망치를 안 놓으니까요."}, {"s": null, "t": "나는 쉬어 가며 하라고 했다. 문수가 고개를 세차게 저었다."}, {"s": "q:dh_munsu", "t": "쉬면 해 지기 전에 못 끝내요. 오늘 끝내야 오늘 보여 드릴 수 있으니까요."}, {"s": "q:dh_munsu", "t": "다 되면 보여 드릴게요. 해 지기 전에요. 그동안 저는 다리를 맞춰야 돼요. 다리가 자꾸 짝짝이가 되거든요. 정청 서리방 걸상처럼요."}, {"s": null, "t": "문수가 아차 하는 얼굴이 되었다. 문수의 고개가 모퉁이 뒤로 쏙 들어갔다. 곧이어 망치 소리가 아까보다 더 세게 울렸다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('rg_munsu_5', 3, '수다 상대 자리', '칠액을(를) 만든다, 칠액을(를) 넘긴다', '{"at": ["deungdo_landing"], "tasks": [{"t": "craft", "items": ["lacquer"], "n": 1}], "give": {"lacquer": 1}}'::jsonb, '[{"s": null, "t": "칠액을 건네고 해가 기울 무렵, 문수가 쉼막 모퉁이에서 무언가를 끙끙거리며 끌고 나왔다. 물 먹은 뱃판으로 짠 걸상이었다."}, {"s": null, "t": "걸상 다리 네 개는 저마다 길이가 조금씩 달랐다. 칠은 고르게 먹어 반들반들했고, 덜 마른 칠 냄새가 코를 톡 쏘았다. 문수가 걸상을 서안 앞에 내려놓자 걸상이 한쪽으로 살짝 기우뚱했다."}, {"s": null, "t": "문수가 걸상을 서안 맞은편, 자기 궤짝과 마주 보는 자리에 놓았다. 그러고는 짧은 다리 밑에 얇은 나무 조각을 끼워 받쳤다. 걸상이 반듯하게 섰다."}, {"s": "q:dh_munsu", "t": "됐다! 이제 안 흔들려요."}, {"s": null, "t": "문수가 걸상 앞에 서서 두 손을 모았다. 무슨 말을 하려다 몇 번이나 입을 다물었다."}, {"s": "q:dh_munsu", "t": "그동안 조사원님이 오시면 늘 궤짝에 앉으시거나 서 계셨잖아요. 손님 자리가 없었어요. 선착 걸상은 다 장부를 놓는 데라서요."}, {"s": "q:dh_munsu", "t": "그래서 하나 더 짰어요. 제 손으로요. 다리는 좀 짝짝이지만, 받쳐 놨으니까 괜찮아요."}, {"s": null, "t": "문수가 걸상의 앉는 판을 손바닥으로 툭툭 쳤다. 판 가장자리에 칼로 홈을 파고 먹을 먹인 반듯한 글씨가 새겨져 있었다. 「문수의 수다 상대 자리」라는 글씨였다."}, {"s": "q:dh_munsu", "t": "여기 앉으세요. 수다 상대 자리거든요."}, {"s": "q:dh_munsu", "t": "제가 떠들면 들어 주시고요, 맞장구도 쳐 주시고요, 제가 말을 안 하는 날엔 먼저 말을 걸어 주시고요. 그런 사람 자리예요. 다른 사람은 못 앉아요."}, {"s": null, "t": "나는 걸상에 앉았다. 걸상이 삐걱 소리를 냈지만 흔들리지 않았다. 문수가 맞은편 궤짝에 앉았다. 서안 하나를 사이에 두고 우리 눈높이가 맞았다."}, {"s": "q:dh_munsu", "t": "어때요? 높이가 딱 맞죠? 그거 맞추느라 다리를 세 번이나 잘랐거든요. 그래서 짝짝이가 된 거예요."}, {"s": null, "t": "나는 딱 맞는다고 했다. 문수가 엄지를 치켜들다가 부은 엄지를 보고 얼굴을 찡그렸다. 우리는 동시에 웃음을 터뜨렸다."}, {"s": null, "t": "수로 쪽에서 밤배 노 젓는 소리가 들려왔다. 계단 아래 물이 철썩였다. 문수는 그쪽을 돌아보지 않았다."}, {"s": "q:dh_munsu", "t": "근데요, 조사원님. 책벌레 뒷얘기가 아직 남았어요. 오늘은 그거 끝까지 해 드릴게요. 엄청 길거든요?"}, {"s": null, "t": "문수가 서안에 팔꿈치를 괴고 이야기를 시작했다. 나는 수다 상대 자리에 앉아 끝까지 들었다. 그날 밤 선착 처마 아래 등잔은 늦게까지 꺼지지 않았다."}]'::jsonb, '{"gil": 205, "title": "rg_munsu", "items": {"hf_rg_munsu_stools": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;


